INSERT INTO songs (song_number, title, category, song_text, tune, count, created_at) VALUES 
(2, 'О Отче наш на небесах', NULL, 'Куплет 1 \nО, Отче наш, на небесах \nпочуй моління Ти моє! \nНехай у наших всіх ділах \nсвятиться ім''я ввік Твоє.\n\nКуплет 2.\nТи бачиш все, - Ти наш Отець,  \nтремтить перед Тобою все; \nТи неба і землі Творець, \nхай прийде Царство вже Твоє.\n\nКуплет 3.\nО, Боже, як премудрий Ти!  \nІ ціль життя мого одна: \nВ часи безрадісні й тяжкі: \nхай буде воля ввік Твоя.\n\nКуплет 4.\nТи - Цар і Бог наш Всеблагий,  \nжиття даєш усім єствам. \nТебе благаєм, Всесвятий, \nдай хліб щоденний нині нам!\n\nКуплет 5.\nТи милосердний Боже наш,  \nпрости провини наші нам, \nЯк ми прощаєм в кожен час \nзлі вчинки нашим ворогам.\n\nКуплет 6.\nХто без Тебе спастися б міг?  \nВ спокусу, Боже не введи, \nНас, немічних дітей Твоїх, \nВід злого духа збережи.\n\nКуплет 7.\nПремудрі всі Твої діла,  \nТвоє і Царство, Боже сил! \nТобі і слава, і хвала \nповіки вічнії. Амінь.', '', NULL, NULL),
(3, 'Свят Свят Свят Господь наш', NULL, 'Куплет 1 \nСвят, Свят, Свят Господь наш, \nБог Всемогутній! \nВранці лину вгору, \nбо Він моя мета; \nСвят, Свят, Свят Господь наш, \nвсюди Він присутній, \nБог в трьох особах, \nТрійце Пресвята!\n\nКуплет 2.\nСвят, Свят, Свят Господь наш!  \nВ небі спів лунає; \nАнгели з святими \nЙому честь віддають. \nВін є, Він і буде; \nВін в руках тримає \nцей світ і зорям \nвказує Він путь!\n\nКуплет 3.\nСвят, Свят, Свят Господь наш!  \nХоч і закрила \nтемрява гріховна \nнам Бога від людей. \nВсесвіт обгорнула \nЙого мудрість, сила \nй правда Його є \nсвітлом для очей.\n\nКуплет 4.\nСвят, Свят, Свят Господь наш,  \nБог Всемогутній! \nЙого діло славить \nвесь світ у всі літа; \nСвят, Свят, Свят в минулім, \nнині та в майбутнім \nБог в трьох Особах, \nТрійця Пресвята!', '', NULL, NULL),
(4, 'Віддаймо хвалу Ісусу Христу', NULL, 'Куплет 1 \nВіддаймо хвалу Ісусу Христу, \nСпіваймо Йому всі пісню нову!\nМогутній і вічний, і любить Він нас, \nУ велич одягнений наш любий Спас.\n\nКуплет 2.\nНе можна в словах любов описать,  \nНе можна в піснях її оспівать; \nУ сонці, у хмарах вона і в дощі, \nУ темряві ночі, в ранковій зорі.\n\nКуплет 3.\nГосподня любов безмежна, свята,  \nГосподня любов у наших серцях; \nВона нам відкрила джерела добра, \nСпасіння і вічне життя нам дала.\n\nКуплет 4.\nВіддаймо хвалу Ісусу Христу,  \nСпіваймо Йому всі пісню нову! \nМогутній і вічний, і любить Він нас, \nУ велич одягнений наш любий Спас.', '', NULL, NULL),
(5, 'Прославте Господа всі люди на землі', NULL, 'Куплет 1 \nПрославте Господа всі люди на землі; \nВгорі у небесах всі ангели святі, \nХваліте Господа всі небеса небес, \nБо Він велично так створив все у красі...\n\nКуплет 2.\nТебе, о, Господи, хай славить і мій дух,  \nБо Ти мій любий Відкупитель і Творець; \nСпасіння вічне Ти даєш для Своїх слуг, - \nНехай Тобі хвала бринить з усіх сердець!\n\nКуплет 3.\nЯ бачу край новий спокою і добра,  \nДе кожен від гріхів навіки вільним є; \nДля Тебе, Творче, там звучить повік хвала, \nНехай святиться й серед нас Ім''я Твоє!\n\nКуплет 4.\nХор ангелів Йому невпинно все співа:  \nСвятий! Святий! Святий! Творець, \nТобі хвала і той небесний спів підхоплює душа: \nСвятий Господь, Владика Всесвіту, Отець!', '', NULL, NULL),
(6, 'Хай буде Творцю Всеблагому хвала', NULL, 'Куплет 1 \nХай буде Творцю Всеблагому хвала! \nГосподня любов нас від смерти спасла!\n\nПрипев: \nАлилуя, честь і слава!\nАлилуя повік!\nАлилуя, честь і слава!\nАлилуя повік!\nБог з нами! Амінь.\n\nКуплет 2.\nСпасителю наш, Тобі слава навік,  \nБо в Тобі лиш спасіння знайшов чоловік!\n\nКуплет 3.\nНаш Отче небесний, у Дусі Святім  \nНавчай і веди нас у вічний Свій дім!', '', NULL, NULL),
(7, 'Хвалу небесному Отцю', NULL, 'Куплет 1 \nХвалу небесному Отцю \nспішіть всі принести; \nНа землю Сина Він послав, \nщоб грішників спасти.\n\nПрипев: \nБудь благословен, \nбудь благословен, \nБудь благословен, \nБоже наш!\nБудь благословен, \nбудь благословен, \nБудь благословен, \nБоже наш!\n\nКуплет 2.\nХристос - Спаситель, вірний Друг;  \nнадія і мета; \nТерпів ганьбу й багато мук, \nщоб дати нам життя.\n\nКуплет 3.\nХристос прославлений Отцем,  \nтепер на троні Він; \nХвалу від Ангелів святих \nприймає Божий Син.\n\nКуплет 4.\nПорадник, Дивний, світу Князь,  \nВолодар Він всього; \nНастав і нам той славний час \nпрославити Його.', '', NULL, NULL),
(8, 'Радісно ми прославляєм', NULL, 'Куплет 1 \nРадісно ми прославляєм \nБога слави і чудес, \nСерце перед Ним схиляєм, \nпросим милости з небес. \nРозжени невір''я хмари, \nвіддали сумнівів тьму, \nПриведи у вічну славу,\nмир дай серцю нашому.\n\nКуплет 2.\nНебо і земля велично  \nсповіщають міць Твою, \nЗорі з ангелами гучно \nвіддають хвалу Творцю; \nЛуки, поле, ліс і гори, \nусі ріки та моря, \nСпів пташок і хмар узори \nвеличають всі Творця.\n\nКуплет 3.\nБраття, пісню величаву,  \nщо з світанком почалась, \nВідкупителю на славу віддамо, \nбо Він нас спас. \nДружнім співом величайте \nПереможця над гріхом, \nПро життя усім звіщайте \nнам дароване Христом.', '', NULL, NULL),
(9, 'Прославте Спаса люди всі', NULL, 'Куплет 1 \nПрославте Спаса, люди всі, \nЙому віддайте честь. \nЙого навік проголосіть \nнад людством всім Царем!\nЙого навік проголосіть \nнад людством всім Царем!\n\nКуплет 2.\nБрати за Нього полягли  \nпогублені мечем; \nВсе ж Він є скрізь об''явлений, \nнад людством всім Царем!\nВсе ж Він є скрізь об''явлений, \nнад людством всім Царем!\n\nКуплет 3.\nНароде, що живеш в гріхах –  \nу темряві помреш. \nСхилися ти до ніг Христа, \nтвоїм Він є Царем!\nСхилися ти до ніг Христа, \nтвоїм Він є Царем!', '', NULL, NULL),
(10, 'Ти задля мене Спасе', NULL, 'Куплет 1 \nТи задля мене, Спасе, \nзійшов з святих небес, \nі залишив оселі, \nповні святих чудес.\n\nПрипев: \nЗа мене Ти, о, Спасителю мій, \nприйняв Голгофський хрест, \nхвала Тобі, Відкупителю мій, \nхвала Тобі і честь.\n\nКуплет 2.\nУ яслах мій Спаситель,  \nмісце Собі знайшов. \nСин Божий, Примиритель \nз любов''ю в світ прийшов.\n\nКуплет 3.\nЛюбов''ю і красою  \nмене Ти полонив, \nсвітлом добра й спокою\nдушу мою зігрів.\n\nКуплет 4.\nБажаю відпочити  \nлише в Тобі Однім, \nдай свято, чисто жити \nв моїм житті земнім.\n\nКуплет 5.\nТобі співати хочу,  \nТи добрий Пастир мій, \nТобі служити хочу, \nСпасителю, я Твій.', '', NULL, NULL),
(11, 'Ісусу Відкупителю', NULL, 'Куплет 1 \nІсусу Відкупителю \nіз роду в рід хвала! \nСлаву і честь Спасителю \nвіддайте всі серця.\n\nПрипев: \nСпівайте щиро всі \nСпівайте щиро всі  \nПро вістку радісну, святу, \nБожу ласку й доброту, \nспівайте щиро всі.\nспівайте щиро всі.\n\nКуплет 2.\nХристос Свою кров проливав,  \nсмерть смертю переміг, \nСпасіння нам подарував, \nі рай відкрив для всіх.\n\nКуплет 3.\nУсі до Господа прийдіть,  \nВін ніжно любить вас, \nЖиття щасливе ви прийміть, \nйого дає вам Спас.\n\nКуплет 4.\nЯк серце ваше заболить,  \nдо Спаса йдіть мерщій, \nВін душу вашу оживить \nі свій пошле спокій.', '', NULL, NULL),
(12, 'Христа хай величають всі', NULL, 'Куплет 1 \nХриста хай величають всі \nі ангели в красі, \nі ангели в красі \nХвалу Йому хай принесуть!\n\nПрипев: \nПрославте, прославте!\nПрославте, прославте! \nПрославте Бога сил!\n\nКуплет 2.\nТи, Богом вибраний народ,  \nстомився від скорбот, \nстомився від скорбот. \nПрослав, і Він тебе спасе.\n\nКуплет 3.\nНароди, люди, племена,  \nнемов сім''я одна, \nнемов сім''я одна, \nХриста прославте любов.', '', NULL, NULL),
(13, 'Слав душе Творця і Бога', NULL, 'Куплет 1 \nСлав, душе, Творця і Бога \nВін нас любить без кінця, \nподає нам допомогу, \nмиром сповнює серця! \nАлілуя! Алілуя! \nСлав премудрого Творця!\n\nКуплет 2.\nСлав за всі благодіяння,  \nщо в житті являє Бог, \nЗа полегшення страждання \nпід час горя і тривог! \nАлілуя! Алілуя! \nСлав, бо вічно славен Бог!\n\nКуплет 3.\nСлав, душе, Того, Хто любить  \nНас без міри, без кінця. \nВін прощає і приймає, і\n дає нам дар життя! \nАлілуя! Алілуя! \nСлав небесного Творця!', '', NULL, NULL),
(14, 'О Спасе наш Тобі хвала', NULL, 'Куплет 1 \n О, Спасе наш, Тобі хвала! \nТвоя любов нас всіх спасла. \nЗа нас Ти на хресті страждав, \nжиття нам вічне дарував. \nАлилуя! Амінь.\n\nКуплет 2.\nЄдинородний Божий Син, \nза тяжкий гніт людських провин \nземне прийнявши тіло й кров, \nСвою до нас явив любов. \nАлилуя! Амінь.\n\nКуплет 3.\nХто Всесвіт Словом сотворив,  \nпрестол небесний залишив, \nі душі від гріхів звільнив, \nв любові жити нас навчив. \nАлилуя! Амінь.', '', NULL, NULL),
(15, 'Прославмо Бога всі словами та ділами', NULL, 'Куплет 1 \n Прославмо Бога всі словами та ділами \nЗа те, що Він в красі колись з''явивсь між нами. \nТакож Він і тепер є тут посеред нас: \nХоч на хресті помер, та в третій день воскрес.\n\nКуплет 2.\nБез Тебе на землі були ми дуже грішні,  \nВ темряві та в імлі блукали духом бідні. \nНаш Отче, з нами Ти тут завжди пробувай, \nТвоїх дарів святих нам з неба посилай.\n\nКуплет 3.\nНесім хвалу святу Небесному Отцеві,  \nІ Синові Христу, що вмер за грішний цей світ; \nІ Духові хвала у Трійці пресвятій \nЗа дивні ті діла, що об''явились в Нім!', '', NULL, NULL),
(16, 'Слав душе Царя небес', NULL, 'Куплет 1 \nСлав, душе, Царя небес, \nпоклонись до ніг Отця; \nСпас Господь мене навіки, \nспівом славлю Його я. \nАлилуя, Алилуя! \nСлава вічному Царю!\n\nКуплет 2.\nСлава Богу благодаті,  \nнам Він поміч у біді; \nСлава Богу милосердя, \nнас благословляє Він. \nАлилуя, Алилуя! \nСлава вірності Його!\n\nКуплет 3.\nАнгели радіють в небі,  \nбачать Господа лице; \nВ святості складають славу, \nбо достойний наш Отець. \nАлилуя! Алилуя! \nСлавте, люди, Господа!', '', NULL, NULL),
(17, 'Отче люблю і прославляю твоє Імя', NULL, 'Куплет 1 \nОтче, люблю і прославляю твоє Ім''я! \nБоже, Ти спасіння моє!\n\nПрипев: \nСлава Тобі, слава Тобі, \nслава, наш Господи, Тобі!\n\nКуплет 2.\nІсусе, славимо Тебе за Твою любов,  \nТи гріхи всі наші простив.', '', NULL, NULL),
(18, 'Угорі під небесами', NULL, 'Куплет 1 \nУгорі під небесами \nангели співають, Бога прославляють, \nІ лунає вже віками \nлюдям дивна новина.\n\nПрипев: "Слава Богу в небі!" – \nПрославляймо гідно Господа свого! \n"Слава Богу в небі!" – \nВеличаймо всі Його!\n\nКуплет 2.\nМилосердя сповіщаймо:  \nБог Себе являє, де Його не знають; \nНа Голгофу споглядаймо: \nтам помер за нас Христос.\n\nКуплет 3.\nТо за беззаконня наші  \nу вінку терновім голова Христова; \nУ Його спасіння чаші \nдар прощення данний нам.\n\nКуплет 4.\nО, який же Бог ласкавий –  \nнам приніс спасіння й віру в воскресіння; \nВсі співаймо пісню слави – \nгідний Бог її від нас!', '', NULL, NULL),
(19, 'Всі люди на землі прийдіть', NULL, 'Куплет 1 \nВсі люди на землі, прийдіть, \nпрославте Господа в цю мить; \nХай лине пісня до небес: \nхвала Творцеві всіх чудес!\n\nКуплет 2.\nБог нас для Себе всіх створив,  \nаби для Нього кожен жив, \nВін - Батько наш: Його любім,\nза Ним ідемо в вічний дім.\n\nКуплет 3.\nПолиньмо духом в височінь,  \nде неба світла голубінь, \nКуди ввійдуть лиш ті серця, \nщо прославлятимуть Творця.\n\nКуплет 4.\nПрославмо нашого Отця,  \nза Його ласку без кінця. \nУ Слові Божому глибінь \nповіки вічнії! Амінь.', '', NULL, NULL),
(20, 'Уста мої хвалу Тобі', NULL, 'Куплет 1 \nУста мої хвалу Тобі \nспівають, Спасе мій! \nПрийшов кінець моїй журбі, \nв душі настав спокій.\n\nПрипев: \nХвала Христу, \nхвала Христу, \nхвала Христу повік!\nХвала Христу, \nхвала Христу, \nхвала Христу повік!\n\nКуплет 2.\nКоли Христос мій  \nна хресті мене від смерти спас, \nТоді уста Його святі \nмолилися за нас.\n\nКуплет 3.\nХоч сльози, горе та біду  \nзустріну в світі цім, \nВід Нього я не відійду \nі завжди буду з Ним.\n\nКуплет 4.\nСпасіння вістку сповіщай  \nти людям кожну мить, \nЩоб від загибелі спасти \nй щасливими зробить.', '', NULL, NULL),
(21, 'Прославляємо Царя царів', NULL, 'Куплет 1 \nПрославляємо Царя царів, \nпрославляємо Творця, \nПрославляємо ми Господа \nІ Спасителя Христа.\n\nКуплет 2.\nПоклоняємось Йому тепер,  \nВін є Богом всіх віків, \nПеред троном ласки станемо, \nхай до Нього лине спів.\n\nКуплет 3.\nВін Володар Всесвіту всього,  \nВін Творець усіх людей, \nВін Господь на небі й на землі,\nгідний Він хвали від нас.\n\nКуплет 4.\nАлилуя Богові Отцю!  \nАлилуя і Христу! \nАлилуя Трійці Пресвятій! \nМи приносимо хвалу.', '', NULL, NULL),
(22, 'Господи Отче небесний', NULL, 'Куплет 1 \nГосподи, Отче небесний, \nвислухай пісню хвали; \nМи нашу жертву сердечну \nспільно Тобі принесли.\n\nПрипев: \nСлава Тобі, Отче святий, \nЗа дар спасіння, за дар дорогий; \nЛаску до нас віковічну \nТи у Христі проявив!\n\nКуплет 2.\nНас у дорозі до неба  \nТи від гріха бережеш,\nблагословіння від Себе \nкожному з нас подаєш.\n\nКуплет 3.\nВірою, Боже, сягаєм  \nв небо, у Царство Твоє; \nСкоро візьмеш нас, ми знаєм; \nтак каже Слово святе.', '', NULL, NULL),
(23, 'Хвала хвала Ісусу', NULL, 'Куплет 1 \nХвала, хвала Ісусу! \nВін душу спас мою, \nЗа всі мої провини \nпролив Він кров Свою. \nХвала, хвала Ісусу! \nВін на хресті вмирав, \nІз темряви страшної \nВін Сам мене підняв.\n\nКуплет 2.\nХвала, хвала Ісусу!  \nВтішає Він мене; \nУ край, де вічна радість, \nВін Сам мене введе. \nПрославлю я Ісуса \nза всі Його діла, \nПрославлю милість Божу, - \nвона мене спасла.\n\nКуплет 3.\nХвала, хвала Ісусу \nв долині цій земній, \nІ вірю: буду жити, \nде Вікупитель мій. \nТам, в царстві всіх спасенних, \nя буду прославлять \nСпасителя Святого \nбезмірну благодать.', '', NULL, NULL),
(24, 'Христу хвала за те що час минув', NULL, 'Куплет 1 \nХристу хвала за те, що час минув, \nКоли я в темряві гріховній був, \nСпокою в світі цім я не знайшов, \nГосподь мій спас мене через Свою любов.\n\nПрипев: \nЗ Христом я буду в небесах \nЗ гілками дивних пальм в руках. \nВ красі небесного вінця \nспіватиму: "Христом спасенний я!"\n\nКуплет 2.\nСумніви й страх Спаситель віддалив,  \nВін силу смерти смертю покорив. \nЯ грішний був - але Він полюбив, \nМене пречистою Він кров''ю убілив.\n\nКуплет 3.\nХвала Спасителю, тепер Він мій,  \nВін збудував у серці храм святий; \nЯ не боюсь: Господь зі мною є \nІ завжди від біди мене Він Сам спасе.', '', NULL, NULL),
(25, 'О як блажен щасливий я', NULL, 'Куплет 1 \nО, як блажен, щасливий я, \nХристос - Спаситель мій. \nМені Він дім приготував \nв небесній стороні.\n\nПрипев: \nСлавлю Агнця! За мій гріх \nстраждав на Голгофі Він, \nАлилуя! Алилуя! \nАлилуя! Амінь.\n\nКуплет 2.\nНе порівняю я ні з чим  \nте місто золоте, \nПовіки буду жити в нім \nу славі я з Творцем.\n\nКуплет 3.\nТам ночі зовсім вже нема,  \nа сонцем сяє Бог, \nЗ сердець завжди звучить хвала, \nнема плачу й тривог.\n\nКуплет 4.\nО, браття й сестри, радість нам  \nдав Бог вже в світі цім, \nТут бачим світло, \nщо і там світитиме святим.', '', NULL, NULL),
(26, 'Христа славте Він наш великий Спаситель', NULL, 'Куплет 1 \nХриста славте! Він наш великий Спаситель! \nПрославляйте Божу любов святу. \nСлавте, славте Його всі ангели Божі, \nчесть віддайте ви за любов Йому. \nНемов діток, нас Він безмірно любить, \nі тримає всіх у руках Своїх.\n\nПрипев:\nАлилуя! Радійте нині всі вірні – \nНам Спаситель двері життя відкрив!\n\nКуплет 2.\nХриста славте! Він наш Великий Спаситель,  \nВін за гріх наш рзп''ятий на хресті; \nВін за нас всіх терпів тяжкії страждання, \nГріхів тягар душу Йому гнітив. \nВін є наша пісня життя й спасіння, \nславте, славте Господа, всі святі.\n\nКуплет 3.\nХриста славте! Він наш Великий Спаситель,  \n"О, Осанна!" - дивний лунає спів. \nНаш Спаситель царює в славі повіки, \nЦар, Пророк і Первосвященник Він. \nАлилуя! Сталося славне чудо: \nпута смерті Божий Син разірвав!', '', NULL, NULL),
(27, 'Вірність Твоя до нас вічна о Боже', NULL, 'Куплет 1 \nВірність Твоя до нас вічна, о, Боже, \nІ тіні зміни в Тобі не знайдеш. \nТи Той самий у безмежній любові, \nвсім життя в цьому світі даєш.\n\nПрипев: \nВірність Твоя до нас вічна, о, Боже наш. \nЩоденно ласку Твою бачу я. \nВсе, що потрібно, мені посилаєш. \nНезмінна, Боже мій, вірність Твоя.\n\nКуплет 2.\nОсінь, зима й весна, літо щороку,  \nСонце і місяць та зорі вгорі, \nПрирода вся повсякчас нам свідкує \nПро Твою вірність у кожній порі.\n\nКуплет 3.\nМир Твій і прощення гріхів триває.  \nТи завжди з нами й нам радість даєш, \nБлагословіння Свої посилаєш, \nУ вічну славу Ти нас приведеш.', '', NULL, NULL),
(28, 'Великий Боже Як на світ погляну', NULL, 'Куплет 1 \nВеликий Боже! Як на світ погляну, \nНа все, на все, що Ти створив в красі, \nЯк кожний твір Тобі складає шану, \nІ як обняв любов''ю Ти усіх;\n\nПрипев: \nТоді, Господь, \nмій дух співа Тобі: \nВеликий Ти! Великий Ти!\nТоді, Господь, \nмій дух співа Тобі: \nВеликий Ти! Великий Ти!\n\nКуплет 2.\nКоли дивлюсь на мерехтливі зорі,  \nТам, де незнані нам горять світи, \nДе сонце й місяць у небес просторі \nПливуть у тиші, наче кораблі;\n\nКуплет 3.\nЯк навесні природа розквітає  \nІ чую я в діброві солов''я, \nІ весняні я пахощі вдихаю, \nІ шумом рік дзвінким милуюсь я;\n\nКуплет 4.\nКоли із хмар навислих грім лунає,  \nІ в пітьмі ночі блискавка іскрить, \nЯк під дощем природа оживає, \nВеселка в небі барвами горить;\n\nКуплет 5.\nКоли беру я книгу Заповітів  \nІ в Ній читаю про Твої діла, \nЯк полюбив Ти нас, людей на світі, \nІ Свого Сина з неба нам послав;\n\nКуплет 6.\nКоли любов Його й покору бачу,  \nЯк Він терпів і всім слугою був, \nРозп''ятий був, страшний злочинець наче,\nПомер, пролив Свою невинну Кров;\n\nКуплет 7.\nКоли спокуси серце огортають,  \nІ дух мій тужить у важкій журбі, \nІ Ти пречисті руки простягаєш, \nІ ніжно зміцнюєш у боротьбі!\n\nКуплет 8.\nКоли Господь мене Сам закликає,  \nІ світить промінь сяєва Його, \nТоді мій дух в покорі замовкає, \nПризнавши велич Господа свого.', '', NULL, NULL),
(29, 'Як Славний наш Господь в Сіоні –', NULL, 'Куплет 1 \nЯк Славний наш Господь в Сіоні – \nне можуть розказать уста! \nВеликий в небі Він на троні \nі на землі в малих квітках; \nІ скрізь Господь велично дивний, \nвночі і вдень сіянням рівний.\n\nКуплет 2.\nТебе, Твій Агнець златорунний  \nвідображає завжди нам, \nІ ми на арфі дзвінкострунній \nТобі приносим фіміам. \nПрийми з глибин сердець хваління, \nподяку, славу й поклоніння.\n\nКуплет 3.\nТи сонцем всіх нас зігріваєш,  \nТи любиш, любиш, Боже нас. \nТи хліб щодня нам посилаєш, \nі з нами всюди кожний час; \nти грішний світ не забуваєш, \nсвятою ласкою тримаєш.\n\nКуплет 4.\nГосподь, хвала хай наша лине  \nв Твої чудові небеса, \nІ співи наші беззупинно \nхай ллються чисті, як роса. \nТобі в серцях вівтар поставим, \nТебе, великий Боже, славим.', '', NULL, NULL),
(30, 'Всевишньому слава Він нас оправдав', NULL, 'Куплет 1 \nВсевишньому слава! Він нас оправдав. \nТак світ полюбив Він, що Сина віддав, \nЗа наші гріхи на хресті Він вмирав \nІ вірним Своїм там спасіння придбав.\n\nПрипев: \nСлав Христа, слав Христа, Хай лунає хвала, \nвеличаймо Його, Славмо подвиг Христа. \nХодімо до Нього, бо любить всіх нас, \nВід загибелі вічної кров''ю Він спас.\n\nКуплет 2.\nСпасіння для нас на хресті Він купив,  \nІ кров''ю Своєю за нас заплатив. \nТепер кожен може до Нього прийти, \nСпасіння в Ісусі для себе знайти.\n\nКуплет 3.\nВеликі й чудові є Божі шляхи,  \nВін визволив людство із рук сатани. \nКоли ж ми ввійдемо у славу Його, \nТам більше пізнаємо Спаса свого.', '', NULL, NULL),
(31, 'Подивись на берег річки', NULL, 'Куплет 1 \nПодивись на берег річки, \nде багато є роси; \nТам, поміж квіток барвистих \nлілія цвіте в красі.\n\nПрипев: \nЯк Бог лілію так любить, \nдбає про її красу, \nТо невже ж тебе забуде? \nБачить Він твою тугу.\n\nКуплет 2.\nКорінці її водою  \nпідкріпляються щодня; \nКвітка скроплена росою, \nсвітить рання їй зоря.\n\nКуплет 3.\nДобре лілії на волі,  \nбо над нею небеса; \nБджілку, що літає в полі, \nвабить лілії краса.\n\nКуплет 4.\nАромат і вид красивий  \nлілія дає щодня; \nХто на світі є вродливий \nі багатий, як вона?\n\nКуплет 5.\nОсь яка краса творіння,  \nяк про неї Бог подбав; \nЗа життя вона спокійна, \nчого ж ти в журбу упав?', '', NULL, NULL),
(32, 'Владико неба Боже наш', NULL, 'Куплет 1 \nВладико неба, Боже наш, \nхвалитиму Тебе щодня \nІ прославлятиму всякчас \nТвої діла, Твоє Ім''я.\n\nКуплет 2.\nО, Боже, - Ти Творець світів, \nТи в ангельській живеш хвалі, \nІ рівного нема Тобі \nні в небесах, ні на землі.\n\nКуплет 3.\nВсі океани і земля,  \nусі народи з роду в рід \nЗвеличують Твоє Ім''я, \nТобі співає весь цей світ.\n\nКуплет 4.\nПро ласку та Твою красу,  \nусім, мій Боже, розповім; \nТакож я вістку понесу, \nщо Ти прощаєш людям всім.\n\nКуплет 5.\nКоли б народ Тебе пізнав,  \nприйняв Твою пролиту кров; \nТоді б хвалу Тобі віддав \nза ласку, милість і любов.', '', NULL, NULL),
(33, 'Гляньте браття вгору в сині небеса', NULL, 'Куплет 1 \nГляньте, браття, вгору, в сині небеса, \nНа путі небесні, на Молочний Шлях: \nСонце, місяць, зорі - хто їх засвітив? \nТу красу Всесильний наш Господь створив.\n\nКуплет 2.\nГляньте, браття, в море, в темний океан,  \nЩо хвилює води, мов пшеничний лан; \nХто життям глибини водні заселив? \nТі дива Всесильний наш Господь створив.\n\nКуплет 3.\nГляньте, любі браття, в піднебесний світ:  \nВесело літає там пташиний рід; \nХто орлам, соколам крила дарував? \nТі дива Всесильний наш Господь створив.\n\nКуплет 4.\nГляньте кругом себе, на луги й поля,  \nПишно вбрана в квіти наша вся земля; \nХто в ліси і гори звірів поселив? \nВсе те Всемогутній наш Господь створив.\n\nКуплет 5.\nГляньте всі на себе, гляньте на братів:  \nХто серденька ваші до життя збудив? \nДо науки й віри хто нас нахилив? \nПевно, все це Бог дав, Він це все створив.\n\nКуплет 6.\nВсесвіт Він тримає у Своїх руках;  \nЯк про сонце дбає, так і про комах, \nА ще більше дбає про дітей Своїх, \nЩедро наділяє Він добром усіх.', '', NULL, NULL),
(34, 'Любов Господня дивна є', NULL, 'Куплет 1 \nЛюбов Господня дивна є, \nне можем ми розповісти; \nСпасіння всім вона дає \nі хоче в небо привести. \nВона сягає до небес \nта глибша всіх морів, \nВона славніша від чудес, \nясніша від зорі.\n\nПрипев: \nО, Боже, як любов Твоя \nдля нас чудова є! \nУ ній спасіння, й лиш вона \nУсім життя дає.\n\nКуплет 2.\nМинає в світі цім життя,  \nмогутність, славу нищить час, \nЙдуть царські трони в забуття, \nприйде пора - не стане й нас. \nЛюбов же Божа не мине, \nнемеркнуча вона, \nЗавжди окрилює мене, \nі смутку в ній нема.\n\nКуплет 3.\nКоли б чорнилом всі моря,  \nа небозвід папером став, \nГілки, - як пера писарям, \nі весь народ писать почав, \nЩоб описать любов Отця; \nзабракло б всяких мір: \nСписали б пера до кінця, \nчорнило й весь папір.', '', NULL, NULL),
(35, 'На землі не все нам видно', NULL, 'Куплет 1 \nНа землі не все нам видно, \nале гляньмо в небеса: \nПеред нашими очима \nвідкривається краса. \nЗірки, місяць, ясне сонце, \nщо Господь їх сотворив, \nВиповняють Божу волю, \nяку Він їм доручив.\n\nПрипев: \nБог нам дав безсмертну душу, \nжиття вічне обіцяв. \nВін простив нам всі провини, \nБожий Син за це страждав. \nО, скажи, мій милий друже, \nщо Йому за це Ти дав?\n\nКуплет 2.\nПташки знають свою пору,  \nнапрямок, куди летіть. \nКвіточки, й дерева знають, \nколи їм зазеленіть. \nВсе творіння славить Бога \nтак, як Він кому звелів. \nДруже, що ти для Ісуса \nв житті доброго зробив?\n\nКуплет 3.\nБог дає все, що потрібне  \nнам для тіла і душі, \nЙого очі всюди бачать, \nщо ми творимо в тиші. \nЧас прийде, Господь спитає\nкожного, хто що робив, \nІ розплатиться по правді, \nяк хто в Нього заробив.', '', NULL, NULL),
(36, 'Приходьте дружно з піснею', NULL, 'Куплет 1 \nПриходьте дружно з піснею: \nБог любить нас! \nВін нам відкрив небесний дім: \nБог любить нас! \nПроснутись грішникам пора, \nшукайте вічного добра \nПроходить ніч, зійшла зоря: \nБог любить нас!\n\nПрипев: \nБог любить нас! Бог любить нас! \nПриходьте дружно з піснею: \nБог любить нас!\n\nКуплет 2.\nСкажіть ви близьким і чужим:  \nБог любить нас! \nЗійшов з небес і з нами жив: \nБог любить нас! \nПогляньте, знову Він гряде, \nХто муки прийняв за людей; \nСпасіння славу Він несе: \nБог любить нас!\n\nКуплет 3.\nРадійте вірнії завжди:  \nБог любить нас! \nЖиття і мир Він всім дає: \nБог любить нас! \nВін - наше сонце і наш щит \nв любові й правді утвердить; \nІ дух і тіло збереже: \nБог любить нас!', '', NULL, NULL),
(37, 'Правда любить Бог мене', NULL, 'Куплет 1 \nПравда, любить Бог мене, \nВін за мене постраждав, \nВ темну ніч і в світлий день \nбуть зі мною обіцяв.\n\nПрипев: \nПравда любить, любить Бог мене; \nПравда любить, любить Бог мене, \nВін за мене постраждав.\n\nКуплет 2.\nПравда, любить Бог мене,  \nколи в горі я скорблю, \nВін, я вірю, подає \nруку сильную Свою.\n\nКуплет 3.\nПравда, любить Бог мене  \nі в життєвій боротьбі\nЗлі нападки подолать \nпосилає сил мені.\n\nКуплет 4.\nПравда, любить Бог мене,  \nучить Він добру без слів; \nВчитись в Нього буду я \nвсе життя, до вічних днів.', '', NULL, NULL),
(38, 'Бог є любов о велике щастя', NULL, 'Куплет 1 \nБог є любов, о, велике щастя! \nБог є любов, любить Він і нас.\n\nПрипев: \nХай кожний радісно співає, й славить, \nЙого хай славить, Бог є любов.\n\nКуплет 2.\nБог є любов, ми Його не знали,  \nБог є любов, світло Він послав.\n\nКуплет 3.\nБог є любов, ми гріху служили,  \nБог є любов, нам гріхи простив.\n\nКуплет 4.\nІсус Спаситель помер за грішних,  \nІсус Спаситель спасіння дав.', '', NULL, NULL),
(39, 'Чудова ласка що знайшла', NULL, 'Куплет 1 \nЧудова ласка, що знайшла \nмене у прірві зла, \nДо ніг Ісуса привела, \nжиття нове дала.\n\nКуплет 2.\nІсус мене так полюбив,  \nщо всі гріхи простив, \nЗ Отцем навіки примирив \nі небо відчинив.\n\nКуплет 3.\nГосподню ласку я ціню  \nі щиро так люблю; \nНавік Ісусу віддаю \nя волю всю свою.', '', NULL, NULL),
(40, 'Царює в небі наш Господь', NULL, 'Куплет 1 \nЦарює в небі наш Господь, \nвсе слухає Його. \nТам серафимів славний хор \nспіває для Нього.\n\nПрипев: \nСпівай, співай, Творцеві всіх світів.\nНехай Йому лунає слави спів. \nХай звуків тих краса наповнить небеса. \nСпівай, співай! Творця Ти прославляй \n(співай).\n\nКуплет 2.\nМоря і гори перед Ним  \nнесуть хвалу щомить. \nПідемо ми вслід за Христом, \nдля Нього будем жить.\n\nКуплет 3.\nВ Його руках є Всесвіт весь, \n Він охорона нам. В\nвійдемо з Ним у край небес, - \nспівати будем там.', '', NULL, NULL),
(41, 'Любить нас Христос безмірно', NULL, 'Куплет 1 \nЛюбить нас Христос безмірно, \nяк любить Він! \nЗавжди ніжно, завжди вірно, \nяк любить Він!\nЩастя світу проминає, \nкращий друг нас забуває, \nСпас же ні, не залишає, \nяк любить Він!\n\nКуплет 2.\nНа хресті Ісус в стражданнях...  \nЯк любить Він! \nГрішним дав Він оправдання, \nяк любить Він! \nВін минуле все прощає, \nрадість дивну посилає, \nХто Йому лиш довіряє, \nяк любить Він!\n\nКуплет 3.\nХто пізнать Його бажає,  \nяк любить Він! \nСпокій, щастя той пізнає, \nяк любить Він! \nВічним Словом підкріпляє\nІ нове життя дарує, \nПідкріпляє Своїм Словом, \nяк любить Він!\n\nКуплет 4.\nВсіх до Себе закликає,  \nяк любить Він! \nВ Своє царство Він приймає, \nяк любить Він! \nВін блаженство обіцяє, \nв горі завжди помагає,\nДоведе Він нас до раю, \nяк любить Він!', '', NULL, NULL),
(42, 'О ласкавий Боже з неба', NULL, 'Куплет 1 \nО, ласкавий Боже, з неба \nТи до нас тепер зійди, \nМи в молитві йдем до Тебе, \nТи в нас віру пробуди. \nПоселися в душах наших, \nСвятим Духом їх сповняй, \nПідкріпляй всіх підупавших \nі нове життя їм дай.\n\nКуплет 2.\nБоже наш, подай нам сили,  \nнас очисти й освяти, \nІ до самої могили \nбудь надією нам Ти. \nЛиш Тебе ми величаєм \nза любов Твою святу, \nБо в Тобі Одному маєм \nнашого життя мету.\n\nКуплет 3.\nПоможи нам жити свято,  \nТвій виконувать наказ \nІ боротися завзято \nпроти зла у всякий час; \nА в кінці путі-дороги, \nяк до неба вже прийдем, \nВсі забудемо тривоги, \nвідпочинок там знайдем.', '', NULL, NULL),
(43, 'Минула ніч і день настав', NULL, 'Куплет 1 \nМинула ніч, і день настав, \nхвала, мій Бог, Тобі! \nТи тихий, мирний сон послав, \nбув захистом мені, \nбув захистом мені.\n\nКуплет 2.\nСьогодні, Боже, помагай  \nз Тобою свято жить; \nЛюбити, вірити навчай, \nдобро усім робить, \nдобро усім робить.\n\nКуплет 3.\nЩо жде мене - не знаю я,  \nта вірю: приймеш Ти \nМене в край вічного життя \nдля здійснення мети, \nдля здійснення мети.', '', NULL, NULL),
(44, 'О Боже дай життя душі', NULL, 'Куплет 1 \nО, Боже, дай життя душі, \nприйми її, як жертву любу! \nНа порятунок поспіши, \nколи загрожує їй згуба, \nЙ нехай, утверджена в Тобі, \nвстоїть в жорстокій боротьбі.\n\nКуплет 2.\nО, Боже, дай життя душі,  \nочисти серце від провини. \nЗа це Тобі, Христе, в тиші \nхай завжди щира вдячність лине. \nХоч немічний, безсилий я, \nТи - сила й поміч вся моя!\n\nКуплет 3.\nО, Боже, дай життя душі,  \nзмилосердися наді мною; \nДо Книги вічної впиши, \nщоб в вічності я був з Тобою. \nДля Тебе тут і в небесах \nне змовкне пісня на устах!', '', NULL, NULL),
(45, 'Милосердний Спасе', NULL, 'Куплет 1 \nМилосердний Спасе, \nвічно з нами будь, \nЩоб небесний голос \nТвій могли ми чуть; \nО, яка то радість, \nяк Ти, Спасе, з нами! \nТи нас підкріпляєш \nвічними словами в скорботах всіх.\n\nКуплет 2.\nЩоб спасти загиблих,  \nТи з небес зійшов, \nУ цей світ скорботний \nв тілі прийшов; \nЗа нас, о, Спаситель, \nТи терпів страждання, \nЩоб нам, грішним, дати \nз Тобою Єднання в крові святій.\n\nКуплет 3.\nТи не залишаєш нас,  \nТвоїх овець, \nТи покірних любиш, \nяк дітей отець; \nДай нам більше віри, \nвтішай Святим Духом \nІ для нас постійно \nбудь незмінним Другом. \nНас Ти навчай!', '', NULL, NULL),
(46, 'Дай святість нам Боже дай мир і Твій страх', NULL, 'Куплет 1 \nДай святість нам, Боже, дай мир і Твій страх, \nДай плач покаяння у наших гріхах. \nПримнож Ти нам віру, чуття обнови, \nІ радість в молитві й служінні пошли.\n\nКуплет 2.\nДай вдячними бути за ласку святу;  \nДай вірити в Слово й в Твою доброту. \nУ горі, стражданнях дай силу на все, \nУ спробах покірно хвалити Тебе.\n\nКуплет 3.\nДай чистеє серце і дух оживи,  \nДо Тебе стремлінням святим наділи. \nУ праці й спокої дай жити щодня, \nТебе прославляти у всі дні життя.', '', NULL, NULL),
(47, 'О Боже поклик мій почуй в цю мить', NULL, 'Куплет 1 \nО, Боже, поклик мій почуй в цю мить: \nВ любові я Твоїй ввік хочу жить. \nВ любові я Твоїй, в любові я Твоїй \nввік хочу жить, ввік хочу жить.\n\nКуплет 2.\nВсім серцем хочу я любить Христа,  \nБо в Ньому ціль моя й одна мета. \nБо в Ньому ціль моя, бо в Ньому \nціль моя й одна мета, й одна мета.\n\nКуплет 3.\nБлукав я в марноті, до смерти йшов,  \nАле знайшов в Христі життя й любов. \nАле знайшоі в Христі, але знайшов я у Христі \nЖиття й любов, життя й любов.\n\nКуплет 4.\nУ вічний край піду я від землі,  \nХриста побачу там в Його красі!\nХриста побачу там, Христа побачу там \nВ Його красі, в Його красі!', '', NULL, NULL),
(48, 'Боже милосердний з неба з висоти', NULL, 'Куплет 1 \nБоже милосердний, з неба, з висоти \nГлянь на нас на землю, ясно освіти; \nМир всели небесний людям у серця, \nХай вони зазнають щастя без кінця!\n\nКуплет 2.\nВічне Слово правди в людях Ти посій,  \nБлагодатним Духом душі розігрій; \nВсіх непримиримих, Боже, примири, \nДо всіма забутих ласку прояви!\n\nКуплет 3.\nВсюди милосердя між людьми будуй  \nІ за нашим Краєм, Господи, пильнуй; \nМи благаєм, Боже, завжди з нами будь, \nХай Твої щедроти нас не проминуть!', '', NULL, NULL),
(49, 'Боже милостивий', NULL, 'Куплет 1 \nБоже милостивий, \nвчуй мої благання \nНа землі журливій \nв дні мого скитання.\n\nПрипев: \nВірному бути дай завжди, мій Боже, \nдушу ворог лютий хай не переможе.\n\nКуплет 2.\nЙду я долом смерті  \nвсюди за Тобою, \nО, не дай померти \nз ворогом в двобою.\n\nКуплет 3.\nХай не підступають  \nгрізні перешкоди \nЙ віри не зламають \nзлі вітри незгоди.\n\nКуплет 4.\nВийду переможно,  \nБоже мій, з Тобою, \nХоч душа тривожна, \nсповнена журбою.', '', NULL, NULL),
(50, 'О Боже мій дай мені сили', NULL, 'Куплет 1 \nО, Боже мій, дай мені сили\nЖиття за ближніх покладать,\nІ в серці тихім до могили\nВсі кривди ворогам прощать.\nІ в серці тихім до могили\nВсі кривди ворогам прощать.\n\nКуплет 2.\nНе дай з гріхами примиритись \nВ тяжкій життєвій боротьбі,\nТи Сам навчи мене молитись,\nМолитись гaряче Тобі.\nТи Сам навчи мене молитись,\nМолитись гaряче Тобі.\n\nКуплет 3.\nО, Боже, Боже, зневажають \nМене і рідні і чужі,\nА я від серця всім прощаю,\nЯк в Слові Ти звелів мені.\nА я від серця всім прощаю,\nЯк в Слові Ти звелів мені.\n\nКуплет 4.\nО, Боже мій, дай мені сили \nВсіх слів Твоїх не забувать,\nУсім прощати до могили\nЙ життя за ближніх покладать.\nУсім прощати до могили\nЙ життя за ближніх покладать.', '', NULL, NULL),
(51, 'Любий Спасе будь зі мною', NULL, 'Куплет 1 \nЛюбий Спасе, будь зі мною, \nЧи покриє тьма мене, \nЧи піднімуться злі хвилі – \nВсе ж любитиму Тебе.\n\nПрипев: \nСпасе мій, Тебе люблю я \nІ любитиму все більш; \nЯк ввійду я в вічну славу, \nПолюблю Тебе сильніш.\n\nКуплет 2.\nСпасе мій, Тебе люблю я  \nБо всім серцем я відчув: \nЯ не маю тут нікого, \nХто б завжди зі мною був.\n\nКуплет 3.\nБуду я Тебе любити  \nВ час моєї праці тут, \nБо як буду Тобі вірний, - \nУ небесний дім ввійду.', '', NULL, NULL),
(52, 'Боже Ти над світом ласку', NULL, 'Куплет 1 \nБоже, Ти над світом ласку \nрозливаєш, як дощі, \nХай же хоч одна краплина \nз того припаде й мені. \nІ мені, і мені \nз того припаде й мені.\nІ мені, і мені \nз того припаде й мені.\n\nКуплет 2.\nНе покинь мене, мій Боже,  \nласк Твоїх не відніми – \nЯк свою дитину, Отче, \nТи до Себе пригорни. \nПригорни, пригорни, \nТи до Себе пригорни.\nПригорни, пригорни, \nТи до Себе пригорни.\n\nКуплет 3.\nДовго я з гріхами знався,  \nТвого Духа ображав, \nТа нарешті спам''ятався \nі нове життя почав. \nЯ почав, я почав, \nя нове життя почав.\nЯ почав, я почав, \nя нове життя почав.\n\nКуплет 4.\nНе покинь мене, мій Боже,  \nа любови вчи мене; \nЯк чинити все, що гоже, \nяк прославити Тебе. \nВчи мене, вчи мене, \nяк прославити Тебе.\nВчи мене, вчи мене, \nяк прославити Тебе.', '', NULL, NULL),
(53, 'Я утомлений безсилий', NULL, 'Куплет 1 \nЯ, утомлений, безсилий, \nБоже мій, до Тебе йду, \nЛиш в Тобі нові я сили\nі спокій душі знайду.\n\nПрипев: \nБоже мій, до Тебе йду я, \nоживи мене, молю, \nПідкріпляй постійно Духом, \nсерцю дай любов Твою!\n\nКуплет 2.\nЯ, безрадісний, бажаю  \nрадість вічную знайти, \nЛиш в Тобі її шукаю, \nмоє щастя - тільки Ти.\n\nКуплет 3.\nУтішай мій дух журливий,  \nу Тобі дай відпочить, \nУкріплятись в Твоїй силі, \nшлях тернистий завершить.\n\nКуплет 4.\nА коли я йти втомлюся  \nсеред горя на землі, \nТобі, Боже, помолюся, \nпоможи тоді мені.', '', NULL, NULL),
(54, 'Щиро я люблю Ісуса', NULL, 'Куплет 1 \nЩиро я люблю Ісуса, \nЙого слухаю слова; \nО, як любо, як приємно \nМені вчитись у Христа.\nО, як любо, як приємно \nМені вчитись у Христа.\n\nКуплет 2.\nЩиро я люблю Ісуса,  \nНа минуле дивлюсь я, \nЙого милості святої \nНе збагне душа моя.\nЙого милості святої \nНе збагне душа моя.\n\nКуплет 3.\nЩиро я люблю Ісуса,  \nВін мене благословив, \nІ Гріхи мої простив всі, \nІ спокоєм наділив.\nІ Гріхи мої простив всі, \nІ спокоєм наділив.\n\nКуплет 4.\nО, Благослови, мій Спасе,  \nбіля ніг Твоїх мене, \nГлянь на мене Ти з любов''ю \nІ яви Своє лице.\nГлянь на мене Ти з любов''ю \nІ яви Своє лице.\n\nКуплет 5.\nДухом нас Святим наповни  \nі любовію Христа, \nЩоб могли ми свято жити, \nсерцем линуть в небеса.\nЩоб могли ми свято жити, \nсерцем линуть в небеса.', '', NULL, NULL),
(55, 'О я грішник бідний справді я такий', NULL, 'Куплет 1 \nО я грішник бідний, справді я такий. \nКоли б Бог безсмертний не послав спокій, \nНе сповив любов''ю і не врятував, \nТо у цьому світі я б давно пропав.\n\nКуплет 2.\nБуду на Ісуса в вірі споглядать,  \nБожого спокою над усе бажать. \nТож, як вчую Слово Господа мого, \nБуду прославляти й величать Його.\n\nКуплет 3.\nВ роздумі солодкім, що Ти - Пастир мій,  \nВ мить одну зникають гріх і страх людський. \nЗ радістю для Тебе прагну працювать, \nЩоб з Тобою жити, в Тобі пробувать.\n\nКуплет 4.\nБоже! Ти є дивний Цар дарів святих,  \nСлово правди вічне і душі Жених. \nХай убогим духом, буду, Отче мій, \nЩоб Тебе шукати й слухать голос Твій.', '', NULL, NULL),
(56, 'Спасителю ласкавий мій приклад вічний Ти', NULL, 'Куплет 1 \nСпасителю ласкавий, мій приклад вічний Ти, \nСмиренний Царю світу, страждав Ти на хресті! \nЧоло в вінку терновім не можу я забуть; \nЯк Ти, в ділах і слові, зразком я хочу буть.\n\nКуплет 2.\nТвоє бажаю Слово з життям моїм з''єднать,  \nУчитися у Тебе, як ворогам прощать. \nЯ хочу так молитись, як Ти моливсь за них, \nІ серцем всім смиритись поміж синів земних.\n\nКуплет 3.\nО, Господи, я прагну в Тобі перебувать,  \nТакож Тебе благаю мене завжди навчать! \nМій розум проясніє, як будеш Ти в мені, \nІ я, Твоє творіння, радітиму в Тобі!\n\nКуплет 4.\nІ сповниться свідомість лиш образом Твоїм,  \nІ я зіллюсь з Тобою усім єством своїм. \nНебесним вічним світлом засяєш в серці Ти, \nІ все тілесне зблідне у променях святих.', '', NULL, NULL),
(57, 'За все Тобі я дякую', NULL, 'Куплет 1 \nЗа все Тобі я дякую, \nІсусе, Спасе мій, \nЗа Кров святу, пролитую, \nза дар любови Твій.\n\nПрипев: \nЯ дякую за все, \nза те, що спас мене, \nЗа те, що небо дав, \nмене Своїм назвав. \nО, Господи святий, \nживи в душі моїй, \nЗавжди мене навчай, \nведи в небесний край.\n\nКуплет 2.\nЗа все Тобі я дякую, \nщо Ти у світ прийшов \nІ душу змучену мою \nдля вічності знайшов.\n\nКуплет 3.\nЗа все Тобі я дякую,  \nза мир і Дух Святий, \nКотрий у пору всякую \nживе в душі моїй.\n\nКуплет 4.\nЗа все Тобі я дякую,  \nТи небо дав мені, \nЯ з вічною подякою \nслужитиму Тобі.', '', NULL, NULL),
(58, 'Я люблю Тебе Боже люблю всім єством', NULL, 'Куплет 1 \nЯ люблю Тебе, Боже, люблю всім єством, \nАле в серці так мало вогню... \nІ мій дух вже знеміг під життєвим ярмом, \nЯ втомився вести боротьбу.\n\nПрипев: \nСили вже нема; \nБоже мій, я молю, \nПідкріпи Ти мене; \nВся надія на Тебе моя.\n\nКуплет 2.\nТвій священний вогонь запали у душі,  \nСпокій, радість і щастя дай знов. \nДай мені, щоб вірним завжди був Тобі \nІ до ближніх дай, Боже, любов.\n\nКуплет 3.\nІ лукавий бентежить і мучить щодня  \nХоче душу в оману ввести, \nАле, Боже, ти скеля й твердиня моя, \nТільки Ти мене можеш спасти.\n\nКуплет 4.\nІ коли Ти прийдеш, щоб судити цей світ,  \nСвіт гріховний, порочний і злий, \nДай мені увійти на весільний обід \nВ Твій прекрасний чертог золотий.', '', NULL, NULL),
(59, 'Коли страх мене огорне', NULL, 'Куплет 1 \nКоли страх мене огорне, \nо, Спасе, тримай, \nІ коли ослабне віра, \nТи мене тримай.\n\nПрипев: \nЗа руку тримай, тримай, \nза руку тримай, тримай, \nО, Спасителю могутній, \nСам мене тримай!\n\nКуплет 2.\nЯ не можу сам триматись,  \nо, Спасе, тримай, \nДай на Тебе покладатись, \nТи мене тримай.\n\nКуплет 3.\nВ ясний час, чи в час нещастя,  \nо, Спасе, тримай, \nВ дні недолі чи у щасті, \nТи мене тримай.\n\nКуплет 4.\nСтережи Сам мою душу,  \nо, Спасе, тримай. \nТи купив мене ціною, \nТи мене тримай.', '', NULL, NULL),
(60, 'О потіш моє серце Спасителю мій', NULL, 'Куплет 1 \nО, потіш моє серце, Спасителю мій, \nТвоїм словом любові і правди; \nХочу голос Твій чути в темряві нічній, \nНад розбурханим морем неправди.\n\nКуплет 2.\nПідніми знов правицю над морем земним,  \nЩо грозить мене вмить затопити, \nДай веління і вітру, і хвилям лихим \nЗамовчати навік, не грозити.\n\nКуплет 3.\nДай, щоб човен слабкий мій щасливо доплив  \nДо небесного тихого стану, \nДе не буде вже грізних, тривожних часів, \nДе вже бажана вічність настане.\n\nКуплет 4.\nБудь зі мною Спасителю, не залишай  \nОдного у бурхливому морі; \nЗавжди Духом Святим Ти в мені пробувай, \nКоли гаснуть і сонце, і зорі.', '', NULL, NULL),
(61, 'Усі мої провини', NULL, 'Куплет 1 \nУсі мої провини \nнесу до ніг Христа, \nСтікає кров невинна \nз Голгофського хреста. \nВона мене обмиє, \nгріхи всі убілить, \nВину мою покриє \nі рани всі зцілить, \nі рани всі зцілить.\n\nКуплет 2.\nВідкрив перед Тобою  \nубоге серце я, \nІ Ти безсмертним \nСловом змінив моє життя. \nУсі душі страждання \nпоніс Ти на Собі; \nКінець сумним зітханням \nзнайшов я лиш в Тобі, \nзнайшов я лиш в Тобі.\n\nКуплет 3.\nНа віковічній Скелі  \nстоїть моя душа; \nХристом в святій оселі \nпоселена вона. \nЙого я ім''я славлю, \nмені Він дорогий, \nВін перший і останній – \nХристос, Спаситель мій, \nХристос, Спаситель мій.', '', NULL, NULL),
(62, 'О Господи будь з нами', NULL, 'Куплет 1 \nО, Господи, будь з нами, \nвсіх нас охороняй, \nПремудрими шляхами \nдо світла направляй.\n\nКуплет 2.\nВ дітей Твоїх усюди  \nєднання сотвори, \nХай спокій Твій пробуде \nі мир в серцях святий.\n\nКуплет 3.\nДумки нам дай єдині,  \nТвою даруй любов, \nДух тихий незлобивий \nпошли в серця нам знов.\n\nКуплет 4.\nСпасителю ласкавий,  \nТи нас благослови, \nНавчи нас Словом Правди, \nщоб вірними були.', '', NULL, NULL),
(63, 'В серце моє Спасителю ввійди', NULL, 'Куплет 1 \nВ серце моє, Спасителю, ввійди, \nЗвільни його від смутку й марноти; \nМожливо, ще панує зло в мені, \nОчисти Сам і все прости вповні.\n\nКуплет 2.\nСлавлю Тебе, а Ти допоможи,  \nПісню хвали в уста мої вклади; \nВ серці моїм створи духовний храм \nІ запануй у нім любов''ю Сам!\n\nКуплет 3.\nБоже, візьми мене і Сам веди,  \nЯ хочу завжди за Тобою йти; \nВолю мою і все моє життя \nВізьми й веди до вічного буття.\n\nКуплет 4.\nРадість і спокій лиш в Тобі однім,  \nНе залишай мене у світі цім; \nТи обіцяв завжди Своїх вести, \nТо ж і мені до неба дай ввійти!', '', NULL, NULL),
(64, 'Ти знаєш Боже моє бажання', NULL, 'Куплет 1 \nТи знаєш, Боже, моє бажання, \nМолитву чуєш Ти мою, \nІ знаєш серця мого страждання, \nКоли я гіркі сльози ллю.\n\nКуплет 2.\nТи знаєш, Боже, що я бажаю,  \nНе слави, скарбів на землі, \nЯ щирим серцем Тебе кохаю \nЗ моїх весняних юних днів.\n\nКуплет 3.\nСумує серце моє порою,  \nВ устах моїх немає слів \nІ я, самотній, скорблю душею, \nЗмовкає мій весняний спів.\n\nКуплет 4.\nНіхто не знає, усім байдуже,  \nКуди душею лину я, \nІ хто спитає, і хто потішить, \nКоли сумна душа моя?\n\nКуплет 5.\nЦей світ чужий вже мені зробився,  \nО, Боже мій, зі мною будь, \nБо слабнуть сили і я втомився, \nА ще далека моя путь.\n\nКуплет 6.\nАле я й далі йду за Тобою;  \nХай вітер стогне, буревій, \nНехай сердито шумить порою, \nЯ не боюсь, бо Ти - Бог мій.', '', NULL, NULL),
(65, 'Обізвись мій милий Боже', NULL, 'Куплет 1 \nОбізвись, мій милий Боже, \nБоже - Правдо Ти моя! \nОбізвись в тяжку годину, \nЯк подам свій голос я.\n\nКуплет 2.\nМені тісно було, Боже,  \nА Ти дав мені простір, \nІ тепер мене помилуй, \nТа пошли душі Твій мир!\n\nКуплет 3.\nМайте страх і віру в Бога  \nУсі люди на землі, \nПомишляйте в вашім серці, \nПро діла Його святі.\n\nКуплет 4.\nО, засяй над нами, Боже,  \nСвітлом Ти Свого лиця, \nТим святим небесним світлом, \nЩо сіяє без кінця!', '', NULL, NULL),
(66, 'В хвилини горя у цьому світі', NULL, 'Куплет 1 \nВ хвилини горя у цьому світі, \nКоли страждання вкривають путь, \nТоді до Тебе я лину, Боже, \nО милосердний, зі мною будь.\n\nПрипев: \nДуша шукає моя спокою, \nБо вже втомився я в борьбі. \nДо Тебе лину у час страждання, \nБудь Ти зі мною, о, Боже мій.\n\nКуплет 2.\nЗлоба, напруга і лицемірство,  \nЗловісний відблиск вогнів гріха,\nЗло скрізь бушує й одне невірство \nУ час приходу страшного дня.\n\nКуплет 3.\nЯ знаю, Спасе, що Ти вже скоро  \nПрийдеш, й настане всьому кінець, \nА в нагороду Своїм всім вірним \nДаруєш славний життя вінець.', '', NULL, NULL),
(67, 'Вже не раз в молитві щирій', NULL, 'Куплет 1 \nВже не раз в молитві щирій, \nБоже, я Тебе благав. \nТа чому ж, мій Спасе милий, \nВідповіді Ти не давав?\n\nКуплет 2.\nЧи в мені так віри мало,  \nЧи то гріх я затаїв? \nЧи любові вже не стало, \nЧи я брату не простив?\n\nКуплет 3.\nО, скажи, мій милий Боже,  \nЩоб я певно зрозумів, \nЩо є в серці ще негоже, \nЧим Тобі не послужив?\n\nКуплет 4.\nО, скажи скоріше, Боже,  \nЖду, щоб Ти вже відповів, \nЩоб я в вірі став сильнішим \nЩоб душею я радів.', '', NULL, NULL),
(68, 'Ось настав молитви час', NULL, 'Куплет 1 \nОсь настав молитви час, \nми до Спаса ідем, \nГріх і страх, що мучить нас, \nперед Ним покладем. \nНам дано давно пізнать: \nнас Він хоче прийнять \nІ Своє благословіння \nв повноті всім нам дать.\n\nПрипев: \nО, молитви час, \nо, молитви час! \nБути з Богом у єднанні \nдивна радість для нас!\n\nКуплет 2.\nОсь настав молитви час,  \nБоже, молимо ми: \nДухом Ти повій на нас, \nТвій народ освяти, \nПісню нам в уста вдихни, \nдуші в нас запали, \nСам любов''ю і спокоєм \nв нас серця осіни.\n\nКуплет 3.\nОсь настав молитви час,  \nтихий скромний наш дім, \nБуде згода поміж нас \nу єднанні святім, \nспокій дай усім серцям, \nспокій дай з неба нам, \nУ душі подобу неба  \nсотвори, Боже, Сам.', '', NULL, NULL),
(69, 'Вчуй Спасителю благання', NULL, 'Куплет 1 \nВчуй, Спасителю, благання, \nхочу свято завжди жить. \nІ в безсиллі, і в стражданнях \nпоможи Тебе любить.\n\nКуплет 2.\nБачиш: слабнуть віри крила,  \nі надія покида, \nХай Твоя могутня сила\nу падінні підніма.\n\nКуплет 3.\nДай, щоб стихло грізне море,  \nі щоб вітер перестав, \nЩоб всміхнулись в небі зорі, \nщоб Тебе я прославляв.\n\nКуплет 4.\nВчуй, Спасителю, благання,  \nпоможи Тебе любить, \nНа пісні зміни ридання, \nдай для Тебе тільки жить.', '', NULL, NULL),
(70, 'Не минай мене Ісусе', NULL, 'Куплет 1 \nНе минай мене, Ісусе, \nсерцю світло дай, \nЧуєш, молять Тебе всюди: \n"Боже, не минай!"\n\nПрипев:\nБоже, Боже! О, почуй мене. \nЧуєш, молять Тебе всюди: \n"Боже, не минай!"\n\nКуплет 2.\nЯ утомлений душею,  \nпоможи мені. \nБудь в часи тяжкі зі мною \nі в найкращі дні.\n\nКуплет 3.\nЯ на Тебе покладаюсь  \nсеред бід моїх, \nОживи мій дух, благаю, \nсил подай Твоїх.\n\nКуплет 4.\nТи Один лиш утішаєш,  \nрадість подаєш, \nВід нещастя захищаєш, \nв небо приведеш.', '', NULL, NULL),
(71, 'Ісусе мій прости мені', NULL, 'Куплет 1 \nІсусе мій, прости мені, \nпрости провини всі мої. \nОбмий мене в крові Своїй, \nдай вічний мир душі моїй.\n\nКуплет 2.\nБагато є гріхів моїх,  \nвони є чорні і страшні; \nЛюбов Твоя сильніша їх, \nвона дає спокій мені.\n\nКуплет 3.\nДарів моїх не хочеш Ти,  \nприношу серце лиш Тобі; \nТаким, як є, мене прийми, \nочисти у крові святій.\n\nКуплет 4.\nПрости, помилуй і спаси,  \nмоя надія лиш в Тобі. \nКоли прийдуть тяжкі часи, \nдай сил мені для боротьби.', '', NULL, NULL),
(72, 'Святий Боже Всемогутній', NULL, 'Куплет 1 \nСвятий Боже Всемогутній, \nбудь Ти серед нас в цей час. \nМи Тебе від серця просим, \nпрости і помилуй нас.\n\nКуплет 2.\nБоже, глянь, Твої ми діти,  \nпросимо Тебе в цей час, \nДай нам в вірі всім прожити, \nпрости і помилуй нас.\n\nКуплет 3.\nСвятий Боже Неосяжний,  \nнас не кинь в непевний час, \nНе відмов нам в благодаті, \nпочуй і помилуй нас.', '', NULL, NULL),
(73, 'Боже почуй мої моління', NULL, 'Куплет 1 \nБоже, почуй мої моління, \nТебе, Тебе благаю я, \nУтри мої скорботні сльози; \nв Тобі надія вся моя!\n\nКуплет 2.\nНехай моя молитва лине  \nдо Тебе, ніби фіміам, \nІ серце прагне безупинно \nв чудовий Твій небесний храм.\n\nКуплет 3.\nТебе всім серцем я благаю,  \nпрости за те, що я згрішив. \nПрости, що знов в земному краї \nТебе ділами прогнівив.\n\nКуплет 4.\nДай повсякчасно за Тобою  \nшляхами правди йти мені. \nМій Боже, я Тебе благаю, \nпочуй мої моління всі!', '', NULL, NULL),
(74, 'Я чую голос Твій', NULL, 'Куплет 1 \nЯ чую голос Твій, \nвін кличе у тиші, \nОбмитись у крові святій, \nпролитій на хресті.\n\nПрипев: \nМій Спасителю, \nйду до Тебе я, \nВірю, змиє гріх тяжкий \nпречиста кров Твоя!\n\nКуплет 2.\nСлабкий і грішний я,  \nта сила є в Тобі; \nКріплюсь Тобою завжди я \nв життєвій боротьбі.\n\nКуплет 3.\nТи всім життя даєш,  \nхто за Тобою йде, \nІ в Царство вічне тих ведеш, \nв любові хто живе.\n\nКуплет 4.\nСпасителю, хвала,  \nхвала крові Твоїй! \nДуша моя в Тобі знайшла \nтой спокій дорогий.', '', NULL, NULL),
(75, 'Боже мій з Тобою хочу завжди жить', NULL, 'Куплет 1 \nБоже мій, з Тобою хочу завжди жить \nІ Тобі постійно на землі служить. \nТи ж мене за руку в світі цім тримай, \nНа земній дорозі впасти не давай.\n\nКуплет 2.\nЯк слабіють сили і томлюся я,  \nХай мене зміцняє сила лиш Твоя. \nХай надія, віра в серці пломенять, \nЩоб Тебе, мій Спасе, щиро прославлять.\n\nКуплет 3.\nБоже, лиш з Тобою хочу я іти,  \nІ в небесне Царство прагну увійти. \nТи ж мене на світі, Боже, не лишай, \nУ земній недолі Духом утішай.', '', NULL, NULL),
(76, 'Боже мій моє вагання', NULL, 'Куплет 1 \nБоже мій, моє вагання \nвіддали з мого життя. \nУ час горя, чи страждання, \nчи в хвилини забуття.\n\nКуплет 2.\nХочу я не сумніватись  \nні на мить, що я син Твій, \nБо я маю сповіщати \nдар спасіння дорогий.\n\nКуплет 3.\nВіддали від мене сумнів,  \nначе я без сил Твоїх; \nДай щоб я був скрізь розумним \nі з Тобою переміг.\n\nКуплет 4.\nПоможи, щоб я душею  \nв грішний світ не відступав, \nЩоб спокусою своєю \nмене ворог не здолав.', '', NULL, NULL),
(77, 'Молитви час приємний час', NULL, 'Куплет 1 \nМолитви час приємний час, \nколи Сам Бог чекає нас; \nХодім до Нього у журбі, \nколи наш дух у боротьбі; \nНа наш молитви фіміам \nГосподь зливає Свій бальзам. \nЗавжди в житті молився Спас, - \nлюбім і ми молитви час.\n\nКуплет 2.\nУсі до Господа прийдім,  \nпотреби всі Йому несім; \nВін хоче нам допомогти \nнападки зла перемогти. \nПриємно й радісно завжди, \nяк ми збираємось сюди, \nІ Дух Святий навчає нас \nлюбити наш молитви час.\n\nКуплет 3.\nДає молитви час нам Бог,  \nяк запоруку перемог; \nКоли ми молимось усі, - \nчерпаєм силу для душі. \nТак завжди і Христос робив, \nколи на світі цьому жив; \nХристос є прикладом для нас, - \nлюбімо й ми молитви час!', '', NULL, NULL),
(78, 'В хвилину тяжкую в житті', NULL, 'Куплет 1 \nВ хвилину тяжкую в житті, \nяк сонце сум гнітить – \nОдну молитву в тишині \nповторюю щомить.\n\nКуплет 2.\nІ силу благодатную  \nвідчую з слів живих, \nІ дихає відрадою \nкраса небесна в них.\n\nКуплет 3.\nЗ душі тягар здіймається,  \nвсі сумніви пройшли \nІ віриться, і плачеться, \nі легко на душі.', '', NULL, NULL),
(79, 'Боже навчай мене Боже навчай', NULL, 'Куплет 1 \nБоже, навчай мене, Боже навчай, \nВолю Твою сповнять допомагай; \nСлово Твоє любить, правду й добро чинить, \nВірно Тобі служить, Боже, навчай.\n\nКуплет 2.\nМудрість Твою даруй, Боже навчай,  \nЩоб не здолав мене сум і відчай; \nЩоб у спокуси час віри вогонь не згас, \nБоже, навчай мене, Боже, навчай.\n\nКуплет 3.\nКоли скінчу свій шлях тут на землі,  \nЗустрінуть в небесах мене святі. \nСеред земних тривог свято свій шлях пройти, \nУ вічний рай ввійти, Боже, навчай.', '', NULL, NULL),
(80, 'О Спасе відвічний Осново буття', NULL, 'Куплет 1 \nО, Спасе відвічний, Осново буття, \nБез Тебе не можу я мати життя; \nОбтяжений горем, до Тебе я йду \nІ перед Тобою гріхи визнаю.\n\nПрипев: \nСпаси мене, спаси мене, \nСпасителю світу, спаси і мене!\n\nКуплет 2.\nО, Спасе ласкавий, почуй голос мій,  \nБо тільки в Тобі спокій маю я свій; \nГріхів тягарі Ти зніми, тоді я \nВідчую, що чиста душа вже моя.\n\nКуплет 3.\nЯ вірю: можливе Тобі тільки все,  \nБо цілого світу тягар Ти несеш; \nНадіюсь: Ти чуєш молитву мою, \nТому своє серце Тобі віддаю.', '', NULL, NULL),
(81, 'О Боже наш Тебе ми благаєм', NULL, 'Куплет 1 \nО, Боже наш, Тебе ми благаєм: \nБлагослови і силу пролий; \nПеред Тобою серце схиляєм, \nПрийди і нас любов''ю зігрій.\n\nПрипев: \nГосподи, Боже наш Всемогутній, \nДухом Святим повій Ти на нас; \nТи знаєш все, Ти всюди присутній, \nБлагослови всіх нас у цей час!\n\nКуплет 2.\nДухом Святим Ти все наповняєш,  \nЩастя і радість душам даєш; \nСеред темряви шлях прокладаєш \nІ в Дім Отця до неба ведеш.\n\nКуплет 3.\nДухом Святим, як світлом небесним,  \nШлях на Голгофу нам освітив; \nТам Ти, наш Спасе, подвигом хресним \nДвері спасіння грішним відкрив!', '', NULL, NULL),
(82, 'У цей молитви час', NULL, 'Куплет 1 \nУ цей молитви час \nми з нуждами прийшли; \nО, Триєдиний Боже наш, \nнам відповідь пошли.\n\nКуплет 2.\nДай глибше пізнавать  \nТвою премудрість слів, \nТвій голос, Боже, відрізнять \nвід інших голосів.\n\nКуплет 3.\nДай щастя відчувать  \nу праці й боротьбі; \nДопоможи себе віддать \nлиш Одному Тобі.\n\nКуплет 4.\nО, Трійце Пресвята,  \nбудь з нами кожен час, \nУ вічне, світле майбуття \nТи супроводжуй нас.', '', NULL, NULL),
(83, 'Мій Ісусе будь зі мною', NULL, 'Куплет 1 \nМій Ісусе, будь зі мною, \nдо грудей Ти пригорни \nІ Всесильною рукою \nмене в світі бережи.\n\nПрипев: \nЯ Тобі лиш довіряюсь, \nя Тобі лиш віддаюсь, \nЗавжди бачити бажаю \nлиш Тебе, о мій Ісус!\n\nКуплет 2.\nБережи мене в дорозі,  \nщоб я міг шлях закінчить, \nУвійти у край небесний \nі навік там відпочить.\n\nКуплет 3.\nПомочі нема ні в кого,  \nтільки в Тебе Одного, \nНе залиш мене самого \nсеред моря грізного!\n\nКуплет 4.\nЛаска, спокій і спасіння  \nтільки в Тебе, Спасе мій; \nДай духовного натхнення, \nя вже вічно буду Твій.', '', NULL, NULL),
(84, 'Не в словах щоденних молитов', NULL, 'Куплет 1 \nНе в словах щоденних молитов \nЯ блаженство для душі знайшов; \nО, мій Боже, я кажу в душі:\nВічне джерело моє в Тобі.\n\nКуплет 2.\nНе в спокої щастя я шукав  \nІ не в марноті життєвих справ; \nНасолоду маю в боротьбі: \nВічне джерело моє в Тобі.\n\nКуплет 3.\nБачиш Ти: я завжди, в кожну мить  \nУ Твоїй свободі хочу жить. \nЦі бажання я несу Тобі – \nВічне джерело моє в Тобі.\n\nКуплет 4.\nТи відкрив мені любов Свою:  \nБуду я з Тобою у раю; \nЗ радощів тремтить душа в мені – \nВічне джерело моє в Тобі.\n\nКуплет 5.\nТи для мене захист, віра, щит,  \nХоч би проти мене став весь світ: \nСилу Ти даєш у боротьбі, \nВічне джерело моє в Тобі.\n\nКуплет 6.\nХоч навколо небезпека жде,  \nСкрізь рука Твоя мене веде, \nПеремогу Ти даєш мені, \nВічне джерело моє в Тобі.\n\nКуплет 7.\nПісля довгих, нещасливих днів  \nНа землі одне я зрозумів: \nВсе блаженство у Твоїй красі, \nВічне джерело моє в Тобі.', '', NULL, NULL),
(85, 'Отче я Тебе благаю', NULL, 'Куплет 1 \nОтче, я Тебе благаю: \nне забудь мене, почуй; \nВ моїм серці ніч відчаю, - \nБоже любий, порятуй! \nТи - любов. З палким молінням \nгрішний я, до Тебе йду; \nЗаспокоєння й спасіння \nлиш у Тебе я знайду.\n\nКуплет 2.\nПрихилися, Отче вічний,  \nі мене не залишай; \nЯ нещасний, безутішний, \nТи ж мені Свій спокій дай.\nНе пригадуй, що минуло, \nвсе прости, що зле робив, \nв серці радости не було, \nкращі дні в гріхах прожив\n\nКуплет 3.\nМій Спасителю ласкавий,  \nмій Ісусе, захист мій: \nО, прости, прости благаю, \nщастя дай душі моїй. \nЯ одного лиш бажаю, \nщоб навіки був Ти мій; \nТи даси спасіння, знаю, \nі введеш у спокій Свій.', '', NULL, NULL),
(86, 'Підніми мене Ісусе', NULL, 'Куплет 1 \nПідніми мене, Ісусе, \nз цього світу марноти, \nВ ту країну, де з святими \nпробуваєш вічно Ти.\n\nКуплет 2.\nЯ стомився в цій мандрівці,  \nв небеса спочити йду. \nЛиш в Тобі я нові сили \nі спокій душі знайду.\n\nКуплет 3.\nПідніми мене, Ісусе,  \nв край небесний, край святий, \nДе минуться всі спокуси, \nсмуток і тягар людський.\n\nКуплет 4.\nТи почуй мої благання,  \nвласний гріх я визнаю, \nСкороти мої страждання, \nдушу обнови мою.', '', NULL, NULL),
(87, 'Отче небесний Боже могутній', NULL, 'Куплет 1 \nОтче небесний, Боже могутній, \nТи Утішитель, Дух правди Ти; \nВсюди присутній і Всевидючий, \nБудь поміж нами, нас освяти!\n\nКуплет 2.\nОтче небесний, в земній дорозі  \nНас, Твоїх діток не забувай; \nПрийди, вселися в серця убогі. \nБлагослови і спокій нам дай!\n\nКуплет 3.\nОтче небесний, змий всі провини  \nІ чистотою душі вкраси; \nХай Твоя ласка з неба полине. \nЗа це Ти слався у всі часи!', '', NULL, NULL),
(88, 'О Спасе мій благаю я', NULL, 'Куплет 1 \nО, Спасе мій, благаю я, \nпрости провини всі мої! \nВ журбі моїй приходжу я \nй гріхи всі визнаю Тобі.\n\nКуплет 2.\nОсь боротьбу з гріхом веду,  \nі сам не маю сили я;\n\nКуплет 3\nмолитвою до Тебе йду,  \nбезмірна є любов Твоя.\n\nКуплет 3.\nВід всіх гріхів мене обмий,  \nдух підкріпи, пошли спокій. \nПрости мені, о, Спасе мій, \nі буду вже навік я твій.\n\nКуплет 4.\nМене, о, Боже, не суди,  \nперед Тобою я стою. \nПо милості Твоїй прости, \nпрости, Спасителю, молю!', '', NULL, NULL),
(89, 'О навчи мене Боже молитись', NULL, 'Куплет 1 \nО, навчи мене, Боже, молитись, \nТвій священний закон зберігать, \nТа навчи гордим серцем скоритись, \nТвою волю в житті виповнять, \nТвою волю в житті виповнять.\n\nКуплет 2.\nЩоб ти жив у мені неподільно,  \nДух святий щоб в мені пробував, \nЩоб служив я Тобі добровільно \nІ Твоє лиш ім''я прославляв, \nІ Твоє лиш ім''я прославляв.\n\nКуплет 3.\nЩоб, Твоєю освячений кров''ю,  \nЧистим серце своє схоронив, \nЩоб святою Ісуса любов''ю, \nЯ завжди своїх ближніх любив, \nЯ завжди своїх ближніх любив.', '', NULL, NULL),
(90, 'Отче наш що єси на небесах', NULL, 'Куплет 1 \nОтче наш, що єси на небесах! \nНехай святиться ім''я Твоє, \nнехай прийде Царство Твоє. \nНехай буде воля Твоя \nяк на небі, так і на землі;\n\nКуплет 2.\nХліб наш насущний дай нам сьогодні.  \nІ прости, нам провини наші, \nяк і ми прощаєм винуватцям нашим;\n\nКуплет 3.\nІ не введи нас у спокусу,  \nале визволи нас від лукавого. \n(Амінь).', '', NULL, NULL),
(90, 'Отче наш що єси на небі', NULL, 'Куплет 1 \nОтче наш, що єси на небі! \nНехай святиться ім''я Твоє, \nнехай прийде Царство Твоє, \nНехай буде воля Твоя \nІ на землі, як на небі, як на небі.\n\nКуплет 2.\nХліб наш щоденний дай нам,  \nдай нам, дай нам на цей день, \nІ прости нам, і прости нам, \nі прости нам провини наші, \nяк і ми прощаєм винуватцям нашим,\n\nКуплет 3.\nІ не введи нас у спокусу,  \nале визволи, але визволи нас \nВід лукавого, \nБо Твоє є царство, і сила, \nі слава навіки. Амінь.', '', NULL, NULL),
(91, 'Будьте пильні і завжди моліться', NULL, 'Куплет 1 \nБудьте пильні і завжди моліться, \nСкоро наш Господь прийде; \nВін лиш тих візьме у край небесний, \nХто Його в молитві жде.\n\nПрипев: \nВір, молись, уже не довго, \nВір, молись, Господь велить; \nСкоро Він прийде у славі, \nНас візьме, з Ним будем жить.\n\nКуплет 2.\nБудьте пильні і завжди моліться,  \nВорог правди все не спить; \nВ броню праведності зодягніться \nТакож віри щит візьміть.\n\nКуплет 3.\nБудьте пильні і завжди моліться,  \nБог спасе від всіх гріхів; \nВ силі Духом Божим укріпіться, \nСтійте твердо в боротьбі.\n\nКуплет 4.\nБудьте пильні і завжди моліться,  \nБог ласкавий чує вас; \nНа Ісуса вірою дивіться, \nВін поможе в кожний час.', '', NULL, NULL),
(92, 'Молись в день радости і щастя', NULL, 'Куплет 1 \nМолись в день радости і щастя, \nВ турботах й боротьбі молись, \nМолись в загрозі від нещастя, \nКоли тривожишся - молись!\n\nКуплет 2.\nМолись, коли ти кривду терпиш;  \nУ небезпеці ти молись! \nМолись, коли за милих просиш, \nЗа злого ворога молись.', '', NULL, NULL),
(93, 'На горі Оливній там', NULL, 'Куплет 1 \nНа горі Оливній, там, \nСпас молився всю ніч Сам, \nДля молитви приклад всім Спас нам дав; \nІ як ми також щодня \nпроведем в молитві час, \nТо зазнаєм, любо як насамоті.\n\nПрипев: \nО, як любо так мені \nу молитві бути з Ним, \nРозказати все Йому насамоті.\n\nКуплет 2.\nЄ також щасливі дні,  \nколи любо так мені \nБути з Спасом моїм насамоті; \nБог мій душу там мою \nнаповнює радістю. \nО, як любо бути з Ним насамоті.\n\nКуплет 3.\nЯк надія пропаде,  \nсмуток душу обів''є, \nДо Христа прийди ти насамоті; \nІ Він смуток віджене, \nв серце радість вмить пошле. \nЯк прийдеш до Нього ти насамоті.', '', NULL, NULL),
(94, 'Такий як є тепер я йду', NULL, 'Куплет 1 \nТакий, як є, тепер я йду \nДо Тебе, мій Спасителю. \nТобі все серце віддаю, \nО, Спасе, я до Тебе йду!\n\nКуплет 2.\nТакий, як є, в безодні  \nзла Не маю сили для добра, \nЛиш Ти мій щит, моя скала, \nО, Спасе, я до Тебе йду.\n\nКуплет 3.\nТакий, як є, мене прийми,  \nТягар гріха з душі зніми, \nЗ любов''ю ніжно обніми, \nО, Спасе, я до Тебе йду.\n\nКуплет 4.\nТакий, як є, побачив я,  \nБезмежна є любов Твоя. \nВ Тобі лиш радість для життя, \nО, Спасе, я до Тебе йду.', '', NULL, NULL),
(95, 'Пильнуй у всякий час мій брате на землі', NULL, 'Куплет 1 \nПильнуй у всякий час, мій брате, на землі, \nЩоб твій маяк не згас у темряві нічній. \nВ служінні пильним будь для Бога і людей!\nСвій поклик не забудь: в темряву нести день.\n\nПрипев: \nПильнуй, молись, \nпильнуй, молись. \nПильнуй і вночі, \nбудь готовий і вдень, \nВсякий час пильнуй.\n\nКуплет 2.\nНа варті не дрімай, у боротьбі з гріхом;  \nЗавіт святий тримай, даний Самим Отцем. \nБадьорим будь й молись всі дні твої земні! \nДодолу не хились, світи ясні вогні.\n\nКуплет 3.\nВ суворий час змагань на Бога покладайсь,  \nВперед йди без вагань, Творця ти прославляй. \nПильнуй, бо Спас іде, судити грішний світ, \nА як Господь прийде, - готуйся дати звіт.', '', NULL, NULL),
(96, 'Отче мій благослови', NULL, 'Куплет 1 \nОтче мій, благослови \nТи мене, ось я стою; \nЗнаєш всю печаль мою – \nскорбну душу оживи!\n\nПрипев: \nОтче, благослови, \nСам мене благослови!\n\nКуплет 2.\nОсь, сьогодні в тихий час,  \nчую я, що Ти - мій Спас; \nЛаску знову прояви \nі мене благослови!\n\nКуплет 3.\nЩоб сіяла чистота –  \nтемне все з душі розвій, \nСпокій дай душі моїй \nради Господа Христа.\n\nКуплет 4.\nЯ ніколи ще в житті  \nтак Христа не шанував, \nТільки зараз розпочав, \nбо пізнав діла святі.', '', NULL, NULL),
(97, 'Боже хай буде воля Твоя', NULL, 'Куплет 1 \nБоже, хай буде воля Твоя \nЗавжди моєю! – Молюся я; \nБо ж я, як глина, в Твоїй руці, \nЗ мене роби, що хочеш Собі.\n\nКуплет 2.\nБоже, хай буде воля Твоя, \nХай чистотою сяє душа; \nКров''ю святою мене обмий, \nЩоб я був здібний на труд святий.\n\nКуплет 3.\nБоже, хай буде воля Твоя,  \nТільки на Тебе надіюсь я; \nТи моя сила, Ти міцний спокій, \nТи моя радість, Спаситель мій.\n\nКуплет 4.\nБоже, хай буде воля Твоя,  \nТи Святим Духом мене сповняй, \nЩоб могли бачить люди усі, \nЩо Ти, Ісусе, живеш в мені.', '', NULL, NULL),
(98, 'О Боже Отче наш благий', NULL, 'Куплет 1 \nО, Боже, Отче наш благий, \nхвала, хвала Тобі, \nЗа кожний дар Твій дорогий \nй потіху у журбі.\n\nКуплет 2.\nПрестол Твій, Боже, в небесах,  \nу неземній красі; \nТримаєш все в Своїх руках, \nТобі там служать всі.\n\nКуплет 3.\nТвоя любов мене кріпить,  \nжиття мені дає. \nЗа те бажаю я хвалить \nсвяте ім''я Твоє.\n\nКуплет 4.\nЯк пташка з клітки виліта  \nна волю - в поле, в гай, \nОтак лети, душе моя, \nв небесний світлий край.\n\nКуплет 5.\nХвала, наш Відкупителю,  \nза ласку й доброту! \nХвала Тобі, Спасителю, \nза Кров Твою святу!', '', NULL, NULL),
(99, 'Тихий час вечірній праці день погас', NULL, 'Куплет 1 \nТихий час вечірній, праці день погас... \nБоже вічний, вірний, о, почуй Ти нас. \nМи до Тебе, Отче, зморені прийшли, \nТо зміцни нас словом, сил нових пошли.\n\nКуплет 2.\nВсе Тобі відомо в нашому житті,  \nСерця біль і втому ми несем Тобі. \nРуки простягаєм в цей вечірній час, \nСилу дай, благаєм, о, почуй Ти нас!\n\nКуплет 3.\nДай нам, Спасе любий, благодать серцям,  \nТим, хто скаже Слово, також співакам. \nНаших душ бажання, Боже освяти, \nБо й до днів останніх поміч - тільки Ти!', '', NULL, NULL),
(100, 'Брате знову нагадай про святу любов', NULL, 'Куплет 1 \nБрате, знову нагадай про святу любов; \nПро Ісусові слова розкажи нам знов. \nСпів любови ллється, дух до неба рветься.\n\nПрипев: \nСлавте Христа, \nславте Христа, \nСлавте любов Христа!\nСлавте Христа, \nславте Христа, \nСлавте любов Христа!\n\nКуплет 2.\nЛюдям всім Христос приніс вічну цю любов;  \nТішить нас в годину сліз вічна ця любов. \nНас Христос навчає; грішних Бог прощає.\n\nКуплет 3.\nБрате, знову нагадай про святу любов;  \nЗникне з серця сум, відчай, буде радість знов.\nКличе спів любови на дорогу нову.', '', NULL, NULL),
(101, 'О наш Спасе благодать', NULL, 'Куплет 1 \nО, наш Спасе, благодать \nна святі слова пролий, \nДай нам всім перебувать \nв вічній милості Твоїй.\n\nПрипев: \nДух єднання дай серцям, \nв святості охороняй, \nІ засяй, як Сонце, нам, \nТвоїм Словом нас навчай!\n\nКуплет 2.\nТи відкрий всім нам сердця  \nі посій слова святі; \nЗлине хай на них роса \nласки й миру в повноті.\n\nКуплет 3.\nХай наповнить Божий Дух  \nнаше серце і наш слух; \nНас усіх благослови, \nоживи і укріпи.', '', NULL, NULL),
(102, 'Боже наш благослови ласкою дітей Своїх', NULL, 'Куплет 1 \nБоже наш, благослови ласкою дітей Своїх. \nВ наші душі Ти пошли Дух Святий з небес Твоїх.\n\nПрипев: \nТи - надія, Ти - спокій, \nТи - спасіння для душі. \nХай лютує буревій, \nБоже, ми в руці Твоїй.\n\nКуплет 2.\nСеред горя та спокус,  \nСпасе наш, будь з нами Ти. \nСам веди нас о, Ісус, \nаж до вічної мети.\n\nКуплет 3.\nНезабаром вічний край,  \nде зберуться всі святі. \nВ вірі, Господи, зміцняй, \nпроведи нас у житті.', '', NULL, NULL),
(103, 'О Спасе говори нам', NULL, 'Куплет 1 \nО, Спасе, говори нам \nсьогодні і всякчас \nСлова любови й сили: \n"Я не залишу вас!" \nПошли нам серця спрагу \nдо слів Твоїх живих, \nі запали наснагу \nв нас до пісень святих.\n\nПрипев: \nО, Спасе, говори нам слова Твої святі, \nНадії та любови, що сила наша - Ти! \nСвятої віри промінь, щоб в душах не погас, \nТебе дай чути завжди: "Я не залишу вас!"\n\nКуплет 2.\nО, Спасе, говори нам  \nз ранкової пори, \nВідкрий у нас джерела \nмолитви і хвали. \nНавчи віднині стати \nТвоїми вже цілком, \nІти на добре діло \nрадісно із псалмом.\n\nКуплет 3.\nО, Спасе, говори нам,  \nвідкрий Твій Заповіт;\nІ близьким, і далеким \nдай сили послужить. \nДля нас найкраща доля, \nщоб віру зберегти, - \nТвою творити волю, \nу спокій Твій ввійти.', '', NULL, NULL),
(104, 'Неділю день спокою дає нам Бог в житті', NULL, 'Куплет 1 \nНеділю, день спокою дає нам Бог в житті; \nДень молитов, відради і зміцнення душі.\n\nКуплет 2.\nВ неділю ми в родину збираємось одну,  \nСпіваємо Творцеві псалми, хвалу святу.\n\nКуплет 3.\nВ день перший, у неділю Бог світло нам створив; \nВ неділю Спас із гробу у величі ожив.\n\nКуплет 4.\nАпостолам в неділю Бог Духа з неба дав,  \nВідвагу в них збудивши, на проповідь послав.\n\nКуплет 5.\nВ неділю день Господній зміцняється душа, \nЩоб краще ми сповняли Господнії діла.\n\nКуплет 6.\nХвала Отцеві в небі, і Синові Його,  \nІ Духові Святому за радіть для цього.', '', NULL, NULL),
(105, 'Ось зібрались знову ми Тебе Отче прославлять', NULL, 'Куплет 1 \nОсь зібрались знову ми Тебе, Отче, прославлять; \nБоже наш, хвалу прийми і примнож нам благодать. \nДух наш в вірі підкріпляй, щоб Тобою ми жили \nІ земний, дочасний край Свято, радісно пройшли.\n\nКуплет 2.\nО, Спасителю, навчай мудро жити в світі цім,  \nСилу Духа посилай, щоб любов являти всім. \nПоможи, щоб ми жили в згоді, як одна сім''я, \nБули вірними Тобі до кінця свого життя.\n\nКуплет 3.\nБудем з радістю в серцях Господа Отця молить;  \nВіджене Він горе й жах, щедро нас благословить. \nВсю забудемо журбу, будем Господу співать \nі Спасителю Христу славу і хвалу складать.', '', NULL, NULL),
(106, 'Буде дощ благословіння', NULL, 'Куплет 1 \nБуде дощ благословіння, \nщо Господь нам обіцяв; \nГрішні знайдуть в Нім спасіння, \nКров''ю Його Спас придбав.\n\nПрипев: \nБлагословіння нині нам, Боже, зішли; \nми всі Тебе щиро просим: \nнам силу Духа пошли!\n\nКуплет 2.\nБуде дощ благословіння  \nз Божих скарбниць неземних; \nБуде духовне натхнення \nв слові та співі святих.\n\nКуплет 3.\nБуде дощ благословіння, \nБоже, його нам пошли, \nЩоб люди мали спасіння \nі в Царство неба ввійшли.\n\nКуплет 4.\nБуде дощ благословіння,  \nбо нам Господь обіцяв; \nШлемо до Нього моління, \nщоб ласку цю Він нам дав.', '', NULL, NULL),
(107, 'Боже наш благослови', NULL, 'Куплет 1 \nБоже наш, благослови \nТи слова святі для нас,\nДух і душу обнови, \nщоб з любов''ю в кожний час \nСлухались ми слів Твоїх \nі виконували їх.\n\nКуплет 2.\nБоже, молим, освяти  \nнаше серце, волю, дух; \nПовнотою ласки Ти \nпереповни Твоїх слуг. \nРуку нам Свою подай \nІ веди у вічний край.', '', NULL, NULL),
(108, 'Слухайте вістку в любові святій', NULL, 'Куплет 1 \nСлухайте вістку в любові святій, \nПоки ще маєте час: \nБог нас навіки простив у Христі \nІ від загибелі спас.\n\nПрипев: \nБог від загибелі спас; \nБог від загибелі спас! \nТак, Бог нас навіки простив у Христі \nІ від загибелі спас.\n\nКуплет 2.\nМоже, неправда загублених днів  \nМучить непевністю вас? \nВірте всім серцем: вас Бог полюбив \nІ від загибелі спас.\n\nКуплет 3.\nМоже, в життєвих стражданнях тяжких  \nПромінь надії погас? \nО, пригадайте в думках ви своїх: \nБог від загибелі спас.\n\nКуплет 4.\nМоже, в життєвій спокусі земній  \nДрузі всі зрадили вас? \nСлово хай чується в мові простій: \nБог від загибелі спас.', '', NULL, NULL),
(109, 'Дозволь Спасителю мені', NULL, 'Куплет 1 \nДозволь, Спасителю, мені \nз Тобою жити у всі дні;\nНавчи мене, як маю я \nсвоє проводити життя.\n\nКуплет 2.\nМене в журбі Ти утішай,  \nвід зла й гріха охороняй, \nПобожно жити вчи мене, \nщоб завжди славив я Тебе.\n\nКуплет 3.\nЖивої віри, Боже, дай,  \nтерпінню й вірності навчай, \nЩоб за Тобою йшов услід \nі зберігав Твій заповіт.', '', NULL, NULL),
(110, 'Боже Боже ми благаєм', NULL, 'Куплет 1 \nБоже, Боже, ми благаєм: \nпоможи у світі йти; \nЧасом тяжко нам буває, \nале поміч наша - Ти.\nЧасом тяжко нам буває, \nале поміч наша - Ти.\n\nКуплет 2.\nПосилай нам Своє Слово  \nі безсилим силу дай, \nДари Духа і любови \nв серця щедро проливай.\nДари Духа і любови \nв серця щедро проливай.\n\nКуплет 3.\nВ цьому світі небагато  \nнам боротись і страждать, \nПоможи прожити свято, \nщоб Ти міг нас в небо взять.\nПоможи прожити свято, \nщоб Ти міг нас в небо взять.', '', NULL, NULL),
(111, 'Скажи священне слово', NULL, 'Куплет 1 \nСкажи священне слово, \nскажи, о, Спасе, знов \nПро дар життя чудовий \nі про Твою любов. \nСкажи і про спасіння, \nвсім нам, як діточкам; \nБо змучені блуканням, \nслужили лиш гріхам.\n\nПрипев: \nСкажи слова із Біблії, \nСкажи мені їх знов; \nСкажи пори потрібної \nВсе про Твою любов.\n\nКуплет 2.\nСкажи святі глаголи,  \nщоб я в душі своїй \nЗбагнув і смерти горе, \nі дар спасіння Твій. \nУ слові своєчаснім \nЧастіше сповіщай, \nЩо нам, таким нещасним, \nвідкрив Ти вічний рай.\n\nКуплет 3.\nСкажи слова бадьорі  \nколи побачиш Ти, \nЩо дух мій дуже хворий, \nя гину в марноті. \nІ, як прийде година \nскінчити шлях земний, \nДай довіряти слову, \nщо Ти Спаситель мій.', '', NULL, NULL),
(112, 'Як олень спрагнений', NULL, 'Куплет 1 \nЯк олень спрагнений \nв степу біжить до джерела, \nТебе так прагне, Боже мій, \nмоя сумна душа.\n\nКуплет 2.\nТи і цілюще джерело,  \nТи і жива вода, \nЩо підбадьорює нам дух \nі спрагнені серця.\n\nКуплет 3.\nО, Спасе, спрагненим серцям  \nживої дай води \nІ нас, знеможених, зміцняй, \nшляхом життя веди!', '', NULL, NULL),
(113, 'Хліб життя нам Спас дає', NULL, 'Куплет 1 \nХліб життя нам Спас дає, \nСлово вічнеє Своє; \nВін усіх до Себе ніжно кличе нас. \nПодає Він ласку всім \nдітям вибраним Своїм. \nЯк з Христом приємно бути в кожний час!\n\nПрипев: \nХліб життя усім наш добрий Спас дає. \nСлово вічне, Слово дивнеє Своє. \nДушу нашу Він кріпить, \nспокій серцю Він дарить; \nО, який Ісус наш величний є.\n\nКуплет 2.\nМанну з неба посилав  \nй хліб небесний подавав \nДобрий Бог наш в ту далеку давнину. \nЧи ж не дасть Він Духа нам, \nЙого дочкам і синам, \nЩо так щиро ми тут молимось Йому?\n\nКуплет 3.\nСкоро знову Він прийде  \nй від землі Своїх візьме, \nІ всі в небі будемо радіти з Ним: \nХліб небесний споживать \nта Ісуса прославлять \nЙ вічно жити з любим Господом своїм!', '', NULL, NULL),
(114, 'Боже чути Слово', NULL, 'Куплет 1 \nБоже, чути Слово \nТи дозволив знову; \nНам яви Твоє лице, \nОсвіти таємне все!\n\nКуплет 2.\nЖдем Тебе з дарами  \nМиру поміж нами; \nДай нам Духа благодать, \nСерцем дай Тебе прийнять!\n\nКуплет 3.\nВихваляйте знову  \nвсі Христа живого; \nВін дає життя вінець, \nВін наш Пастир і Отець!', '', NULL, NULL),
(115, 'О Слово Боже вірне', NULL, 'Куплет 1 \nО, Слово Боже вірне! \nВ нім наше все життя. \nБагатство в нім нетлінне – \nнаука це Христа. \nХристос в любові втішить, \nВін душу оживля, \nЗ сумніву визволяють \nЙого святі слова:\n\nПрипев: \nПрийди до Христа: \nв Нім твоє життя; \nДруже безутішний, \nне вагайсь, іди!\n\nКуплет 2.\nО, серце, не вагайся,  \nСпасителю повір, \nНавік Йому віддайся, \nпроси у Нього сил. \nНещасний, хто блукає \nдалеко від Христа, - \nЩасливий, хто приймає \nБожественні слова.\n\nКуплет 3.\nО, Боже, будь Ти з нами  \nі вдень, і уночі, \nЩоб світлими путями \nдо Тебе йшли хутчій; \nМогутньою рукою \nведи нас всіх вперед \nДорогою вузькою \nвсе за собою вслід.', '', NULL, NULL),
(116, 'Дивіться як радіють', NULL, 'Куплет 1 \nДивіться, як радіють \nсьогодні небеса, \nТак само розквітає \nі християн краса.\n\nПрипев: \nДає нам спокій дорогий \nв недільний день Отець Святий. \nТіштеся, тіштеся, \nдав спокій Бог Святий!\n\nКуплет 2.\nПанує всюди свято  \nі спокій у серцях; \nГолубить нас, як мати, \nсвята любов Отця.\n\nКуплет 3.\nСерця палають миром  \nв дорослих і малих, \nІ Бог утіху щиру \nпримножує для всіх.\n\nКуплет 4.\nДо неба нас підносять  \nслова Христа святі, \nІ в душі нам приносять \nвідраду у Христі.\n\nКуплет 5.\nЯкщо ці дні неділі  \nтакі приємні тут – \nЯкі ж то будуть милі \nдні вічні, що прийдуть?..', '', NULL, NULL),
(117, 'Ніколи не залишу', NULL, 'Куплет 1 \nНіколи не залишу \nсвятої Біблії, \nВона шлях до спасіння \nпоказує мені.\n\nПрипев: \nНе залишу ніколи \nБіблії не залишу, \nНе залишу ніколи Книги Божої.\n\nКуплет 2.\nКоли я у спокусі  \nбуваю, чи в журбі, - \nВона мене навчає, \nпідтримує тоді.\n\nКуплет 3.\nКоли в життєвім морі  \nзла буря надійде – \nДо пристані Голгофи \nвона мене веде.\n\nКуплет 4.\nЯ їй лиш довіряю,  \nзнаходжу в ній Христа; \nВ Нім світло правди сяє \nй любові повнота.', '', NULL, NULL),
(118, 'Книгу Божу маю я', NULL, 'Куплет 1 \nКнигу Божу маю я, \nхоч старенька вже вона, \nДні пригадую минулі, наче дзвін; \nМоя мама в ній знайшла \nдар спасіння від Христа; \nНе забуду я щасливих тих хвилин.\n\nПрипев: \nО, чудова, найдорожча \nКнига Божа, Я люблю, люблю тебе! \nТи звернути не даєш, \nв царство Боже нас ведеш, \nВ край, куди прийме \nГосподь вас і мене.\n\nКуплет 2.\nПам''ятаю про Христа  \nвсе читала мама там, \nЯк любив, страждав, \nвмирав Він на хресті; \nЯ уважно слухав все: \n"Пам''ятай, за тебе це, - \nговорила мама, - ти Його люби!"\n\nКуплет 3.\nТе давно-давно я чув,  \nале слів тих не забув \nІ мені ця Книга світлом є в житті; \nЯ слова Христа люблю, \nвсе вперед за Ним іду, \nБо до щастя хочу вічного прийти.', '', NULL, NULL),
(119, 'Твоє Слово Господи благословляє нас', NULL, 'Куплет 1 \nТвоє Слово, Господи, благословляє нас; \nСлава хай буде Тобі, Слава, Господи. \nТвоє Слово, Господи, благословляє нас. \nІ славу Тобі дає. О, наш Господь і Цар, \nСлава хай буде Тобі, Слава, Господи. \nТвоє Слово, Господи, благословляє нас.', '', NULL, NULL),
(120, 'Святая Біблія одна', NULL, 'Куплет 1 \nСвятая Біблія одна. \nДуховним світлом є вона: \nМи з неї знаєм, що за нас \nпомер у муках любий Спас.\n\nПрипев: \nО, Слово Боже - світло ти \nв житті постійно нам світи. \nО, Слово Боже - ясно сяй, \nі нас веди в небесний край.\n\nКуплет 2.\nВідомо з Біблії і те,  \nщо Бог життя нове дає \nУсім, хто серце та уста \nпоклали на вівтар Христа.\n\nКуплет 3.\nГосподня Біблія свята  \nзвіщає про любов Христа, \nЩо смертю смерть Він подолав, \nщоб грішник в Бозі спокій мав.\n\nКуплет 4.\nХто любить Біблію читать,  \nтому не страшно умирать. \nУсіх, кого вона веде,\nжиття на небі вічне жде.', '', NULL, NULL),
(121, 'Слово Боже сила Божа –', NULL, 'Куплет 1 \nСлово Боже, сила Божа – \nнаша це надія, \nЦе - любов, що наші душі \nповсякчасно гріє.\n\nКуплет 2.\nВ час журби, або тривоги,  \nколи сил немає – \nМи із Біблії словами \nдуші утішаєм.\n\nКуплет 3.\nБоже, дякуєм за Слово,  \nщо сьогодні чули; \nПоможи, щоб ми з Твоєї \nстежки не звернули.', '', NULL, NULL),
(122, 'Біблія світло Боже засвітила', NULL, 'Куплет 1 \nБіблія світло Боже засвітила \nШлях нам відкрила у незнаний світ; \nВірити Богу нас навчила, \nІ до святих небес відкрила вхід.\n\nПрипев: \nГосподи, дай нам знати Святе Слово \nІ його правду сповіщати всім, \nЩоб, як настане Царство вже Христове, \nВоно відкритим стало нам і їм.\n\nКуплет 2.\nБіблії слово все майбутнє знає,  \nЩо час наступний людям принесе; \nЩо відбулося, та що бути має, \nБіблія вчить нас розуміти все.\n\nКуплет 3.\nБіблія путь правдиву відкриває,  \nВсіх направляє на стежки святі; \nХто вказівки священні забуває, \nТой відійде від вірної путі.\n\nКуплет 4.\nО, християни, Біблію читайте,  \nСловом її перемагайте гріх; \nБожої правди всіх людей навчайте \nІ їх приводьте до Христових ніг.', '', NULL, NULL),
(123, 'О предвічний Цар Єгова', NULL, 'Куплет 1 \nО, предвічний Цар Єгова! \nПуть в пустині освіти, \nВтомленого і слабкого \nподорожнього веди.\n\nПрипев: \nХліб небесний, хліб небесний \nдай нам, Боже, душу підкріпляй \nДай нам, хліб небесний, \nдай нам хліб небесний\nДай нам, хліб небесний, \nдай нам хліб небесний \nХліб небесний і Ним душу підкріпляй.\n\nКуплет 2.\nСтрумінь хай води живої  \nз скелі потече для всіх; \nХай горить пори нічної \nсвітло слів Твоїх живих.\n\nКуплет 3.\nПодолав Христос тьми силу,  \nтож за це Йому хвала. \nДай, щоб шлях душа звершила, \nв край завітній увійшла.\n\nКуплет 4.\nТут вождя я все чекаю,  \nнезабаром Він прийде, \nІ в небесну вічну славу \nСам мене Він приведе.', '', NULL, NULL),
(124, 'Як стежиною лісною', NULL, 'Куплет 1 \nЯк стежиною лісною \nдо струмка біжить олень, \nтак і я стремлюсь душею \nдо Господніх слів щодень. \nВ день сумний утіху завжди \nя знаходжу в Книзі книг, \nВ день щасливий Слово Правди \nя беру в віршах святих.\n\nКуплет 2.\nСлово Боже визволяє  \nдушу від тяжких недуг, \nСлово серце звеселяє, \nнасолоджує мій дух. \nСловом тим перемагаю \nвсі спокуси зла й гріха, \nСловом тим Христа звіщаю, \nяк спасенний Ним слуга.\n\nКуплет 3.\nСлово шлях мій освітляє  \nсеред темряви й марнот, \nЗ ним я горе забуваю \nі звільняюсь від турбот.\n \nДля душі Господнє слово – \nвісник вічного добра, \nКраще скарбу золотого \nй скарбу чистого срібла.', '', NULL, NULL),
(125, 'Глибше хочу правду пізнавати', NULL, 'Куплет 1 \nГлибше хочу правду пізнавати, \nщо в Святім Письмі; \nБуду завжди Біблію читати \nй слухати її.\n\nПрипев: \nВсе більше я молюсь, \nщодня я більш учусь \nІ все зростаю в Нім, \nБожім Слові дорогім.\n\nКуплет 2.\nГлибше серцем хочу відчувати  \nя любов Христа; \nВ ній я можу з Богом долю мати, \nце - моя мета.\n\nКуплет 3.\nГлибше серцем хочу підкоритись,  \nяк Ісус учив; \nХочу щиро Спасові молитись, \nщоб і я так жив.\n\nКуплет 4.\nГлибше я зміцнятись хочу в Бозі,  \nв істині Христа; \nВірним бути тільки волі Божій \nвсе своє життя.', '', NULL, NULL),
(126, 'Ми зібрання закінчили', NULL, 'Куплет 1 \nМи зібрання закінчили \nі додому йдем; \nВсе, чого ми научились, \nу серця візьмем.\n\nПрипев: \nМирно, тихо і спокійно \nдодому підем, \nСлово Боже, що почули, \nв серці понесем.\n\nКуплет 2.\nОтож будемо ми завжди,  \nна зібрання йти \nІ навчатися тут правди, \nяк життя вести.\n\nКуплет 3.\nДасть Бог жити, ми зійдемось  \nна зібрання знов, \nЧи то в будень, чи в неділю, \nпрославлять Його.', '', NULL, NULL),
(127, 'Благодать Господа Ісуса Христа', NULL, 'Куплет 1 \nБлагодать Господа Ісуса Христа \nі любов Бога-Отця, \nТа єднання Святого Духа \nхай буде з нами, буде з нами. \nАмінь. \nАмінь. Амінь.\nАмінь. Амінь.', '', NULL, NULL),
(128, 'Візьми мене мій Спасе за руку Сам', NULL, 'Куплет 1 \nВізьми мене, мій Спасе, за руку Сам, \nІ поведи до щастя в Твій вічний храм. \nТи знаєш: я не можу без Тебе йти, \nМене в дорозі, Боже, підтримуй Ти!\n\nКуплет 2.\nДай серцю радість неба в Твоїх словах, \n Щоб линути до Тебе, в сумних часах. \nСвяту і тверду віру збуди в мені, \nА гордість і невіру Ти віджени.\n\nКуплет 3.\nКоли у смертнім тілі нема надій –  \nНаправ мене до цілі, о, Боже мій! \nВізьми мене, мій Спасе, за руку Сам, \nІ поведи до щастя в Твій вічний храм.', '', NULL, NULL),
(129, 'О Єгово через хвилі', NULL, 'Куплет 1 \nО, Єгово, через хвилі \nкрізь пустелі нас веди; \nМи без Тебе всі безсилі, \nперед нами завжди йди;\nМанну з неба, манну з неба \nнам, безсилим, посилай!\n\nКуплет 2.\nО, відкрий Свої потоки  \nдорогих дарів святих; \nТвій вогненний стовп високий \nхай веде дітей Твоїх. \nО, наш Спасе, о наш Спасе, \nбудь для наших душ щитом.\n\nКуплет 3.\nСтоїмо біля Йордану:  \nнам дорогу проклади \nІ в країну Ханаану, \nБоже, Твій народ веди. \nСпів хваління, спів хваління \nзалунає там Тобі.', '', NULL, NULL),
(130, 'Тихая ніч дивная ніч', NULL, 'Куплет 1 \nТихая ніч, дивная ніч, \nВсе дріма... Лиш не спить, \nБлагоговіє подружжя святе: \nДивного Сина послав Бог-Отець, \nРадістю серце горить, \nрадістю серце горить!\n\nКуплет 2.\nТихая ніч, дивная ніч,  \nГолос з неба звістив: \n"Тіштеся, нині Христос народивсь, \nМир і спасіння для всіх Він приніс, \nСвітло святе нам явив! \nСвітло святе нам явив!"\n\nКуплет 3.\nТихая ніч, дивная ніч,  \nВ небо нас Бог позвав. \nХай же відкриються наші серця, \nІ хай прославлять Його всі уста: \nВін нам Спасителя дав! \nВін нам Спасителя дав!', '', NULL, NULL),
(131, 'Повний благости щастя й радости', NULL, 'Куплет 1 \nПовний благости, щастя й радости \nБлагодатний цей день Різдва. \nСвіт в гріхах томився, \nСпас нам народився \nВіруючим всім день торжества!\n\nКуплет 2.\nПовний благости, щастя й радости  \nБлагодатний цей день Різдва. \nАнгели небесні і пісні чудесні \nСповіщають нам день торжества!\n\nКуплет 3.\nПовний благости, щастя й радости  \nБлагодатний цей день Різдва. \nЩоб спаслась людина, \nБог послав нам Сина. \nРадуйтесь, настав день торжества!', '', NULL, NULL),
(132, 'Земле радій  Христос прийшов', NULL, 'Куплет 1 \nЗемле радій - Христос прийшов! \nПрийми Царя царів! \nЩоб в серці твоїм, Він місце знайшов, \nщоб став життям твоїм, \nЩоб став життям твоїм, \nщоб став життям твоїм.\n\nКуплет 2.\nНам Він приніс спасіння всім,  \nЙого прославте всі \nза радість, любов, Пролитую кров, \nщо змила гріх з душі; \nЩо змила гріх з душі; \nщо змила гріх з душі.\n\nКуплет 3.\nЛюди, радійте, Спас царить!  \nСпівайте Йому всі! \nВсім людям Христос Спасіння дає \nі щастя для душі, \nІ щастя для душі, \nі щастя для душі.', '', NULL, NULL),
(133, 'З неба ангели летять', NULL, 'Куплет 1 \nЗ неба ангели летять, \nДобру Новину несуть; \nЗірка сяє в небесах, \nв яслах Спас у пеленках. \nВсі народи перед Ним, \nзаспіваймо слави гімн: \nХай радіє вся земля, \nнародилось Немовля! \nЗаспіваймо слави гімн, \nнародився Божий Син.\n\nКуплет 2.\nПастухи розносять вість,  \nщо з''явивсь небесний Гість; \nМудреці зі Сходу йдуть \nі дари Йому дають. \nВід Святого Духа нам \nнародився Божий Син, \nВін зійшов у грішний світ, \nщоб здійснився Заповіт. \nЗаспіваймо слави гімн, \nНародився Божий Син.\n\nКуплет 3.\nМиру князь родився нам,  \nлюдським дочкам і синам; \nВсім вода із Джерела \nжиттєдайна протекла! \nУмалився ради нас \nі від смерти людство спас: \nНародився, щоб у Нім \nнам згори родитись всім. \nЗаспіваймо слави гімн, \nнародився Божий Син.', '', NULL, NULL),
(134, 'Вночі з вітанням Ангел появивсь', NULL, 'Куплет 1 \nВночі з вітанням Ангел появивсь: \n"Пастирі, встаньте, Спас вам народивсь; \nТо ж, тепер часу не гайте, \nв Віфлеєм всі поспішайте \nБогу на поклін!"\n\nКуплет 2.\nПрийшли та й бачуть в яслях Немовля,  \nЯк Ангел Божий з неба промовляв; \nПеред Ним вони смирились, \nЙому щиро помолились \nв радості сердець.\n\nКуплет 3.\n"Ласкавий Спасе, Бажаний здавен,  \nУ кожнім часі будь благословен! \nБо Тебе царі, й пророки \nтак чекали довгі роки; \nТи ж нам об''явивсь!"', '', NULL, NULL),
(135, 'Прийдіте всі вірні', NULL, 'Куплет 1 \nПрийдіте, всі вірні, \nз радісним хвалінням, \nПрийдіте, не гайтеся, у Вифлеєм. \nЦар народився, Цар всього творіння.\n\nПрипев: \nПрийдіть і поклоніться. \nПрийдіть і поклоніться, \nПрийдіть і поклоніться Господу!\n\nКуплет 2.\nНебеснії хори,  \nрадісно співайте, \nНаповніть хвалою простори небес, \n"Слава навіки, слава в вишніх Богу!"\n\nКуплет 3.\nІсусе, в молитві  \nми йдемо до Тебе \nПрославити щиро бажаєм Тебе, \nСлово предвічне нам явилось в тілі:', '', NULL, NULL),
(136, 'Хори ангелів вістять', NULL, 'Куплет 1 \nХори ангелів вістять: \n"В небі й на землі спокій." \nГори й доли гомонять, \nПро цей "дар", так дорогий.\n\nПрипев: \nСлава, Богові на небі.\n\nКуплет 2.\nПастухи питають їх:  \n"Новина яка у вас? \nЩо спонукало всіх \nЗемлю навістить в цей час."\n\nКуплет 3.\n"В Вифлеєм скоріш спішіть,  \nТам знайдете Немовля. \nВ яслах там Ісус лежить, \nНим спасеться вся земля."', '', NULL, NULL),
(137, 'Слава Богові хай буде', NULL, 'Куплет 1 \nСлава Богові хай буде \nв небі, спокій на землі, \nволя добра буде в людях! \nСпас з''явивсь до нас в хвалі.\n\nПрипев: \nАлилуя! Алилуя! \nВже минула ночі тінь! \nАлилуя! Алилуя! \nСлава Богові повік! Амінь.\n\nКуплет 2.\nТой, Хто Всесвітом керує  \nй має в небі Свій престол, \nзалишив небесну славу, \nяк людина в світ прийшов.\n\nКуплет 3.\nВ яслах бідних народився,  \nвигляд Він слуги прийняв, \nДобровільно умалився, \nщоб спасіння кожен мав.\n\nКуплет 4.\nГрішні всі, Він двері раю  \nвідчинив широко вам; \nХто ввійти туди бажає, \nприйме тих Спаситель Сам.\n\nКуплет 5.\nО, приходьте всі до Спаса  \nви, що змучились в гріхах! \nВ Ньому душі ті спасуться, \nяк народиться в серцях.', '', NULL, NULL),
(138, 'Бог Предвічний народився', NULL, 'Куплет 1 \nБог Предвічний народився, \nВін прийшов із небес, \nЩоб спасти люд Свій весь І світ втішився.\n\nКуплет 2.\nВ Вифлеємі народився  \nІсус Спас, Пастир наш. \nПравди Цар із небес Нам об''явився.\n\nКуплет 3.\nЩо за чудо нам з''явилось,  \nДе Марія Христа повила, \nтам Зоря Світлая прийшла.\n\nКуплет 4.\nСлава Богу! Заспіваймо  \nІ Народженому пресвятому \nЦарю поклін віддаймо!', '', NULL, NULL),
(139, 'Ось Спаситель на землю зійшов', NULL, 'Куплет 1 \nОсь Спаситель на землю зійшов, \nЛюдське тіло на Себе прийняв, \nЗа оселю Він ясла обрав, \nЩоб явити нам ласку й любов.\n\nПрипев: \nСлава Христу! Слава, слава, слава Христу, \nМир і радість для нас Він приніс!\n\nКуплет 2.\nСам Син Божий на землю прийшов  \nНе в пошані, не в царськім вінці, \nНе в палаті, але в простоті, \nВ бідних яслях Він місце знайшов.\n\nКуплет 3.\nСвій надзоряний трон залишив  \nВсього Всесвіту Бог і Творець; \nІ як Пастир за бідних овець, \nЗа людей Він життя положив.', '', NULL, NULL),
(140, 'Нині радість стала', NULL, 'Куплет 1 \nНині радість стала, \nЯка не бувала, \nНад вертепом зоря ясна \nСвітові засяла!\n\nКуплет 2.\nТам Христос родився,  \nЗ Діви воплотився, \nЯк людина пеленками \nВбогими вповився.\n\nКуплет 3.\nАнгели співають  \nХриста величають, \nВсім народам цю чудову \nНовину звіщають.\n\nКуплет 4.\nМи також співаймо,  \nХриста прославляймо. \nВід Марії Рожденому \nХвалу й честь віддаймо!', '', NULL, NULL),
(141, 'Ангельськії співи в небесах звучать', NULL, 'Куплет 1 \nАнгельськії співи в небесах звучать; \nРадість, утішіння, мир вони дарять. \nНам родивсь Спаситель, дивне Немовля. \nВсіх Він Відкупитель, грішників, як я.\n\nПрипев: \nАнгельськії співи в небесах звучать. \nВ них для всіх спасіння, мир і благодать. \nСлава Богу в небі і мир на землі, \nслава Богу в небі і мир на землі. \nАмінь, амінь.\n\nКуплет 2.\nУ висотах неба слава й честь Тому,  \nХто страждав за грішних, що любили тьму. \nІз глибин сердечних до небес ясних \nспіви ллються щирі від Його святих.\n\nКуплет 3.\nБудемо любов''ю за любов платить  \nТому, Хто нас кров''ю спас; щоб вічно жить. \nБратові, що гине, руку подамо. \nНе за користь й плату вічність маємо.', '', NULL, NULL),
(142, 'Слава слава Богу в небі', NULL, 'Куплет 1 \nСлава, слава Богу в небі, \nна землі мир, благодать; \nЗакликайте, браття, ближніх, \nбудем Бога прославлять!\n\nПрипев: \nАлилуя, алилуя, \nСлава Богу в небі! \nАлилуя, алилуя, \nАлилуя! Амінь!\nАлилуя, алилуя, \nАлилуя! Амінь!\n\nКуплет 2.\nТой, хто Всесвітом керує,  \nмає в небі Свій престол – \nЗалишив небесну славу, \nяк людина в світ прийшов.\n\nКуплет 3.\nБог прощення і спасіння  \nу Христі нам хоче дать, \nЦе святе благословіння \nпоспішайте всі прийнять.\n\nКуплет 4.\nВ Вифлиємі Спас родився,  \nв бідних яслах Він лежав; \nТо для нас Христос смирився \nі всім нам за приклад став.\n\nКуплет 5.\nЛюди, слухайте, не гайтесь,  \nдо Ісуса поспішіть, \nУ гріхах своїх покайтесь, \nв серце всі Христа прийміть!', '', NULL, NULL),
(143, 'Небо і земля небо і земля', NULL, 'Куплет 1 \nНебо і земля, небо і земля \nнині торжествують, \nАнгели й люди, ангели й люди \nвесело святкують.\n\nПрипев: \nХристос родився, Бог воплотився, \nАнголи співають, славу звіщають, \nПастухи вітають, поклін складають, \n"Чудо!" - повідають. \n"Чудо, чудо!" - повідають.\n\nКуплет 2.\nУ Вифлеємі, у Вифлеємі  \nвесела новина: \nПречиста Діва, Пречиста Діва \nнародила Сина.\n\nКуплет 3.\nОтцівське слово, Отцівське слово  \nзодяглося в тіло, \nВ земній темряві, В земній темряві \nсонце засвітило.\n\nКуплет 4.\nАнголи служать, анголи служать  \nГосподу своєму, \nСпівають: "Слава!", співають: "Слава!" \nНовородженому.\n\nКуплет 5.\nТри володарі, три володарі  \nзі сходу приходять,\nЛадан і миро, ладан і миро \nй золото приносять.\n\nКуплет 6.\nСпасу святому, Спасу святому  \nті дари складають, \nПастирі людям, пастирі людям \nновину звіщають.\n\nКуплет 7.\nЙого ми нині, Його ми нині  \nтакож величаймо, \nСлава на небі й на землі спокій! – \nЙому заспіваймо.', '', NULL, NULL),
(144, 'Ой зійшла зійшла правда на землю', NULL, 'Куплет 1 \nОй, зійшла, зійшла правда на землю, \nта й поселилась поміж людьми. \nВсім розказала, як треба людям, \nяк треба жити, як Бог велить.\nВсім розказала, як треба людям, \nяк треба жити, як Бог велить.\n\nКуплет 2.\nДе ж тая правда, звідки з''явилась,  \nде вона нині на світі є? \nТам в Вифлеємі в яслях родилась, \nа тепер в вірних серцях живе.\nТам в Вифлеємі в яслях родилась, \nа тепер в вірних серцях живе.\n\nКуплет 3.\nХристос є правда, Христос є світло,  \nХристос - любов, життя Він для нас. \nО, якби люди зі всього світу \nпришли до Нього, Він би їх спас.\nО, якби люди зі всього світу \nпришли до Нього, Він би їх спас.\n\nКуплет 4.\nІ Дух Святий, і правда із неба  \nнині шукають в серцях ясел, \nщоб поселився, щоби родився \nХристос Спаситель в серцях людей.\nщоб поселився, щоби родився \nХристос Спаситель в серцях людей.\n\nКуплет 5.\nІ в кому знайде місце для Себе,  \nтам запанує радість свята, \nтому дарує місце на небі, \nі допоможе нести хреста.\nтому дарує місце на небі, \nі допоможе нести хреста.', '', NULL, NULL),
(145, 'Нині всі вірні Христа прославляють', NULL, 'Куплет 1 \nНині всі вірні Христа прославляють, \nСили небесні Ісуса вітають; \n"Спас народився!" - звіщають в хвалі, \n"Слава Богу в небі, мир на землі!"\n\nПрипев: \nСлава, слава, Слава Богу в небі, \nмир на землі! \nСлава, слава, Цар народився \nХристос!\n\nКуплет 2.\nХристос родився, радійте душею,  \nПсалми хваління, летіть над землею, \nВірні, співайте Творцеві в хвалі: \n"Слава Богу в небі, мир на землі!"\n\nКуплет 3.\nЗірка небесна вказала дорогу  \nТрьом мудрецям, що вклонилися Богу, \nПодарували коштовних дарів, \nЗнали: в дитині Господь, Цар царів.\n\nКуплет 4.\nІрод почув, що Христос народився,  \nСерцем жорстоким своїм розлютився, \nТайно Дитятко убити рішив, \nДе Спас родився шукати звелів.\n\nКуплет 5.\nЗ вісткою Йосипу Ангел з''явився:  \n"Ірод Ісуса убити рішився; \nВранці візьми Ти Марію й Дитя, \nАж у Єгипті спасай їм життя!"\n\nКуплет 6.\nІрод з військами діток убиває,  \nМати з Ісусом від нього втікає; \nДивно спаслося Господнє Дитя, \nЩоб дарувати всім людям життя.', '', NULL, NULL),
(146, 'Всесильний Царю світу', NULL, 'Куплет 1 \nВсесильний Царю світу, \nТи ясла вибрав Сам \nІ так Себе смирив Ти, \nщо став за приклад нам. \nЯ був звичайний житель \nі всім розповідав, \nЩо в яслах був Спаситель, \nа сам Тебе не знав.\n\nКуплет 2.\nПочув тоді я голос:  \n"Я в яслах бідних був. \nТерпів печери холод, \nтепер до тебе йду. \nБажаю народитись \nу серці Я твоїм \nІ так відобразитись, \nяк в дзеркалі живім."\n\nКуплет 3.\nІ Ти мені з''явився,  \nлюбов''ю освітив, \nЯ духом відродився \nі став дитям Твоїм. \nТа чудо: Ти родився \nу твориві Своїм, \nВ мені Ти оселився \nі став навік моїм.', '', NULL, NULL),
(147, 'Ой у Вифлеємі', NULL, 'Куплет 1 \nОй, у Вифлеємі \nвесела новина, \nрадуйся!\n\nПрипев: \nОй, радуйся, земле, \nБожий Син народився!\n\nКуплет 2.\nТам Діва Марія  \nнародила Сина: \nрадуйся!\n\nКуплет 3.\nІ Отцівське слово  \nзодяглося в Тіло: \nрадуйся!\n\nКуплет 4.\nВ мороці земному  \nСонце засвітило: \nрадуйся!\n\nКуплет 5.\nАнгели співають  \nГосподу свойому: \nрадуйся!\n\nКуплет 6.\nСлаву, честь складають  \nНовородженому: \nрадуйся!\n\nКуплет 7.\nІ ми Рожденого  \nХриста прославляймо: \nрадуйся!\n\nКуплет 8.\nГосподеві Спасу  \nвсі поклін віддаймо: \nрадуйся!', '', NULL, NULL),
(148, 'По всьому світу стала новина', NULL, 'Куплет 1 \nПо всьому світу стала новина: \nДіва Марія Сина родила; \nСіном притрусила, в яслах положила \nГосподнього Сина.\n\nКуплет 2.\nРадісну пісню чути в тишині,  \nАнгели славлять Бога в вишині; \nБо спасіння світу, згідно Заповіту, \nВ Дитині убогій!\n\nКуплет 3.\nОсь появилась на небі зоря,  \nШлях освітила до Христа Царя; \nМудреці приходять і дари приносять \nГосподньому Сину.\n\nКуплет 4.\nДо Вифлеєму пастухи ідуть,  \nРадість велику у серцях несуть; \nНа коліна впали й разом привітали \nГосподнього Сина!', '', NULL, NULL),
(149, 'З вишин небесних уночі', NULL, 'Куплет 1 \nЗ вишин небесних уночі \nвсім грішникам землі \nХор ангелів благовістив: \nРодився Божий Син: \n"Хай добра воля між людьми \nй мир буде на землі!" \nПриймали вістку люди всі, \nВеликі та малі.\n\nКуплет 2.\nЦя вістка й досі любо нам  \nбринить в різдвяний час, \nі всім, хто змучений життям, \nдарує радість Спас. \nМіста, і села, й хутори, \nпалаци та хати! – \nУ ці Різдвяні вечори \nдля всіх цей спів святий.', '', NULL, NULL),
(150, 'Дитя нам вічний Бог послав', NULL, 'Куплет 1 \nДитя нам вічний Бог послав, \nСин народивсь Його, \nМогутню владу Бог поклав \nНа рамена Його.\nМогутню владу Бог поклав \nНа рамена Його.\n\nКуплет 2.\n"Чудовий, сильний, Бог Творець" –  \nНазве Його весь світ, \nПорадник, Вічности Отець, \nКнязь миру з роду в рід.\nПорадник, Вічности Отець, \nКнязь миру з роду в рід.\n\nКуплет 3.\nВін Царство вічне встановив  \nІ мир приніс у світ, \nНавіки правдою зміцнив \nПрестол і Заповіт.\nНавіки правдою зміцнив \nПрестол і Заповіт.', '', NULL, NULL),
(151, 'Вістку дивну всі приймайте', NULL, 'Куплет 1 \nВістку дивну всі приймайте: \nБог зійшов в долину сліз! \nВсім народам сповіщайте: \nБог спасіння їм приніс.\n\nПрипев: \nСлава, слава Богу лине \nІз землі аж до небес; \nВічний Бог послав нам Сина, \nВ Ньому джерело чудес.\n\nКуплет 2.\nОсь над темною землею  \nЗірка нам ясна зійшла; \nНебеса співають з нею: \nЛюдям мир, Христу хвала!\n\nКуплет 3.\nВгору очі підіймайте  \nВід журби, світських турбот, \nСпівом ви Царя вітайте, \nЩо з небесних йде висот.\n\nКуплет 4.\nБог ввесь світ спасти бажає  \nВід темряви, від гріха; \nвсіх до Себе закликає: \nЗемле! Ти не будь глуха!', '', NULL, NULL),
(152, 'Нині в місті Вифлеємі', NULL, 'Куплет 1 \nНині в місті Вифлеємі \nлюдям народився Спас; \nНе у царській діадемі, \nв бідноті з''явивсь до нас. \nВін в приниженні й покорі, \nяк людина, в світ прийшов, \nСпівчував усім, хто в горі; \nв муках смерть свою знайшов.\n\nПрипев: \nХвала Христу за ніч святу! \nСпасе, ти для нас прийшов! \nАмінь.\n\nКуплет 2.\nНад полями Вифлеєму  \nпастухи почули спів; \nВістку дивну і приємну \nАнгел з неба сповістив. \nПастухи пішли до міста \nі знайшли там Немовля, \nхор небесний урочисто \nславив Господа Царя.\n\nКуплет 3.\nНе в палаці, не в хатині,  \nяк було родитись слід, \nА в вертепі тій Дитині \nдовелось прийти в цей світ. \nУ печері темній, вбогій \nВін створив Собі вівтар; \nОсь таку земну дорогу \nвибрав був Всесвіту Цар.', '', NULL, NULL),
(153, 'Ясна на небі зірка засяла', NULL, 'Куплет 1 \nЯсна на небі зірка засяла, \nдивну новину всім несе, \nХвиля спасіння в світ завітала, \nБог від гріхів людей спасе. \nВін полюбив світ, це всі ви знайте, \nСпас народився, радуйтесь! \nСпас народився, радуйтесь!\n\nКуплет 2.\nУ Вифлеємі, в яслах на сіні  \nСпас спочиває - Цар людей! \nВсі поспішайте до Нього нині, \nВін нас чекає, як дітей. \nВсі милосердя в Нього шукайте, \nСпас народився, радуйтесь! \nСпас народився, радуйтесь!', '', NULL, NULL),
(154, 'Спас народився від діви Марії', NULL, 'Куплет 1 \nСпас народився від діви Марії, \nУ Вифлеємі у яслах на сіні.\n\nПрипев: \nАнгели співають там, \nдобру вість звіщають нам; \nЗ пастухами разом впадім перед Спасом: \nБог нам в Ньому всім спасіння дав.\n\nКуплет 2.\nМарія - мати Сина сповиває,  \nНевинним серцем Бога прославляє.\n\nКуплет 3.\nЙосип й Марія дбають про Дитятко,  \nСпівають: Люлі, любе Немовлятко.\n\nКуплет 4.\nТри володарі з дарами приходять,  \nЛадан і миро, золото приносять.\n\nКуплет 5.\nЙого Різдво ми нині пригадаймо:  \nСлава на небі! - Йому заспіваймо.', '', NULL, NULL),
(155, 'У Вифлеємі нині новина', NULL, 'Куплет 1 \nУ Вифлеємі нині новина: \nПречиста Діва вродила Сина. \nВ яслах на сіні Його поклала \nПісню тихенько Йому співала.\nВ яслах на сіні Його поклала \nПісню тихенько Йому співала.\n\nКуплет 2.\nПастухам ангел вістку звіщає:  \n"Радість і спокій Бог посилає; \nДо Вифлеєму всі поспішайте, \nВ бідній Дитині Спаса вітайте!"\n\nКуплет 3.\nТам херувими з неба злітають,  \nАнгельські хори Спаса вітають, \nПастух убогий несе, що може, \nЩоб привітати Дитятко Боже.\n\nКуплет 4.\nА за зорею здалеку, з Сходу  \nЙдуть мудреці з чужого народу. \nЗолото щире, ладан та миро, \nНесуть дарунки та серця віру.\n\nКуплет 5.\nЛюбий наш Спасе, ми не багаті,  \nДарів коштовних не можем дати, \nТож в подарунок несем від себе \nВіру та щиру любов до Тебе.', '', NULL, NULL),
(156, 'Божий світе веселися', NULL, 'Куплет 1 \nБожий світе, веселися! \nНині Спас твій народився \nУ вертепі для отари \nБо в гостиниці не стало \nДля Нього, для Нього кімнати.\n\nКуплет 2.\nВ небі ангели співають,  \nПро Христів прихід звіщають: \n"На землі мир, в небі слава!" \nБожа правда завітала \nДо грішних, до грішних людей всіх.\n\nКуплет 3.\nПастухи поприбігали  \nСвого Спаса привітали. \nЯк дізнались, що Месія \nНародився від Марії \nсвятої, Від Діви святої.\n\nКуплет 4.\nІ ми Спаса звеличаймо,  \nЯк Владику прославляймо! \nБожій правді покорімось, \nІ від Духа народімось, \nЙ живімо, живімо в любові!', '', NULL, NULL),
(157, 'Ангели в небі пісню співають', NULL, 'Куплет 1 \nАнгели в небі пісню співають, \nщо Христос родився всім возвіщають.\n\nПрипев: \nСлава в вишніх Богу, \nі на землі мир.\n\nКуплет 2.\nПречиста Діва дитятко сповила.  \nБожого Сина в яслах положила.\n\nКуплет 3.\nЙосип і Марія Богу помолились,  \nпастухи ягняток Христу поклонились.\n\nКуплет 4.\nІ ми нині вірні Христа величаймо,  \nангельську пісню Йому заспіваймо.', '', NULL, NULL),
(158, 'Чи ви чуєте як дзвони скрізь дзвенять', NULL, 'Куплет 1 \nЧи ви чуєте, як дзвони скрізь дзвенять? \nХай вони і в душах наших забринять, \nБо на землю задля нас Ісус прийшов \nІ приніс спасіння, радість і любов.\n\nПрипев: \nДзвеніть, дзвеніть, дзвони пречудесні, \nНесіть, несіть вісті нам небесні! \nСлава, слава в небесах, \nМир і радість всім серцям! \nЛюди, слухайте, як дзвони \nскрізь дзвенять.\n\nКуплет 2.\nМи в побожності сприймаєм дивний дзвін,  \nДухом бачим: народився Божий Син; \nВін дитиною в убогих яслах спить, \nІ хор ангелів з небес благовістить.\n\nКуплет 3.\nТі чудові співи згадуєм і ми,  \nПро любов Господню кажуть нам вони; \nСлаву Богу люди піднести спішать, \nРадістю і щастям в них серця горять.', '', NULL, NULL),
(159, 'О дітки ідіть же скоріше ідіть', NULL, 'Куплет 1 \nО, дітки, ідіть же, скоріше ідіть, \nВ печері у яслах Спаситель лежить; \nЗоря освітила ніч темну з небес, \nДала знак про дивнеє чудо з чудес.\n\nКуплет 2.\nПогляньте: у яслах лежить Немовля,  \nНебесною святістю ніжно сія; \nТо Боже дитятко родилось у світ, \nВсі ангельські хори Йому шлють привіт.\n\nКуплет 3.\nО, дітки, для вас Він у яслах лежав,  \nЩоб кожен із вас Його в серце прийняв;\nПочувши ту ангельську вістку святу, \nПриходьте і ви поклонитись Христу!', '', NULL, NULL),
(160, 'Про Різдво Христове Ангел сповіщав', NULL, 'Куплет 1 \nПро Різдво Христове Ангел сповіщав, \nРадісну і нову пісню заспівав: \n"Слава в небі Богу і на землі спокій" \n- День Різдва святий!\n\nКуплет 2.\nЯ лечу від Бога радість дати вам:  \nУ вертепі вбогім Спас родився нам;\n Швидко поспішайте, Дитятко вітайте, \nСпокій на землі!\n\nКуплет 3.\nПастухи вітати швидше всіх прийшли,  \nВ яслах, а не в хаті Господа знайшли; \nСтояли, співали, Христа прославляли \nЗа любов святу.\n\nКуплет 4.\nМудреці теж знали, де ясна зоря,  \nПрийшли, привітали Бога і Царя; \nБогові співали, дар Цареві склали, \nСлавили Христа.\n\nКуплет 5.\nІрод, злом сповитий, як про це узнав,  \nВін Дитятко вбити воїнів послав; \nТі дітей побили, мечі потупили, \nА Христос живе.\n\nКуплет 6.\nЛюди досі жили у гріхах своїх,  \nЗ ними до могили переходів гріх; \nХай Різдво Христове дасть життя всім нове \nІ радісних днів!', '', NULL, NULL),
(161, 'Хто там в бідних яслах спить', NULL, 'Куплет 1 \nХто там в бідних яслах спить? \nЧий в печері Син лежить? \nТо Христос в цей світ прийшов \nі приніс свою любов.\n\nПрипев: \nДо Ісуса всі ходім; \nВін введе нас в вічний дім!\n\nКуплет 2.\nХто народ там науча?  \nТо чиї слова звучать? \nДо Кого слабих несуть \nта сліпих, кривих ведуть?\n\nКуплет 3.\nХто там, плачучи, стоїть,  \nде сном смерти Лазар спить? \nВ честь Кого лунає спів? \nДо Кого спішать з домів?\n\nКуплет 4.\nХто в саду припав лицем,  \nмолиться перед Отцем? \nХто на хрест поніс наш гріх! \nХто смерть смертю переміг?\n\nКуплет 5.\nХто воскрес, щоб оживлять, \nмертвих з гробу підіймать? \nХто найкращий Друг є твій? \nТо Ісус наш дорогий!\n\nКуплет 6.\nЦе - Христос, Учитель наш,  \nВідкупитель Він і Спас; \nце Любов, що в світ прийшла \nй Добру Вістку принесла.', '', NULL, NULL),
(162, 'Повість скажи про Ісуса', NULL, 'Куплет 1 \nПовість скажи про Ісуса, \nвсе нам про Нього звісти; \nДивна й велична та вістка \nсерце втішає завжди. \nАнгелів пісню повторюй, \nпісню святого Різдва: \n"Мир і любов у народі, \nБогові в небі хвала."\n\nПрипев: \nПовість скажи про Ісуса, \nвсе нам про Нього звісти; \nДивна й велична та вістка \nсерце втішає завжди.\n\nКуплет 2.\nЯк Він в пустелі постився,  \nяк у спокусі Він був, \nЯк він боровся, повідай, \nяк перемогу здобув. \nЯк безпритульний, голодний, \nвсім помагав у житті, \nВін збагатив всі народи, \nСам пробував у нужді.\n\nКуплет 3.\nЯк на хресті розіп''яли,  \nяк Він в стражданнях вмирав; \nЯк в домовину поклали \nі як із мертвих Він встав. \nДивную повість скажи нам, \nяк Він людей полюбив, \nСлава навіки Ісусу: \nнаші гріхи Він простив.', '', NULL, NULL),
(163, 'Ісусове святе Імя', NULL, 'Куплет 1 \nІсусове святе Ім''я, \nПонад усе кохаю я; \nВоно дорожче за життя – \nСвяте Ім''я Ісуса!\n\nПрипев: \nО, Ісус, Твоє Ім''я \nЛюбить так душа моя! \nСлавте, славте всі уста \nСвяте Ім''я Ісуса!\n\nКуплет 2.\nЛюблю я чути це Ім''я,  \nВ нім насолода вся моя, \nЙого оспівую щодня – \nСвяте Ім''я Ісуса!\n\nКуплет 3.\nЧудове те Ім''я - Ісус,  \nЙому Одному я молюсь, \nНічого в світі не боюсь \nз Святим Ім''ям Ісуса!\n\nКуплет 4.\nНе в силі оспівать уста  \nКраси величної Христа, \nЙого лиш славлять небеса – \nСвяте Ім''я Ісуса!', '', NULL, NULL),
(164, 'О як імя Ісуса нам', NULL, 'Куплет 1 \nО, як ім''я Ісуса нам \nПриємне й дороге; \nСпасіння щастя всім серцям \nВоно для нас дає.\n\nКуплет 2.\nУ Ньому зцілення від ран  \nДля кожної душі; \nУ ньому втіха християн, \nКоли тяжкі часи.\n\nКуплет 3.\nУ Ньому вірний мій маяк,  \nДо Нього я пливу; \nУ ньому від вітрів і бур \nЯ затишок знайду.\n\nКуплет 4.\nВ Ісусі вся моя мета,  \nВін Друг і Пастир мій, \nПокров і вічнеє життя, \nІ здійснення надій.', '', NULL, NULL),
(165, 'Небесний спокій я знайшов', NULL, 'Куплет 1 \nНебесний спокій я знайшов, \nяк до Христа прийшов; \nМоє життя Він відродив, \nгріхи мені простив. \nТам, де криниця Сихаря, \nя був з Христом моїм, \nНе раз була душа моя \nтам в Галилеї з Ним.\n\nПрипев: \nТам в Галилеї з Ним, \nТам в Галилеї з Ним; \nТак часто бачу я себе \nтам в Галилеї з Ним.\n\nКуплет 2.\nГосподь відкрив для мене вхід  \nв небесний, вічний край, \nТож за Христом іду услід \nу славний Божий рай. \nХриста одного я люблю \nі лиш Йому служу, \nТепер іду до ніг Його \nтягар душі зложить.\n\nКуплет 3.\nЯ бачу той тернистий шлях,  \nна нім Христову кров; \nМи всі страждали у гріхах – \nХристос нам дав любов. \nЛюбов Його нас підняла \nз безодні марноти; \nУсюди так багато зла, - \nжиття й добро в Христі.', '', NULL, NULL),
(166, 'Самарянка та не знала', NULL, 'Куплет 1 \nСамарянка та не знала, \nщо Христос її шукав, \nЩо вона з Ним розмовляла, \nпити Він прохав. \nАле Він їй відкриває, \nв світі як вона жила, \nЦі слова її вражають, \nвсім сказать пішла.\n\nПрипев: \nО, довірся, милий друже, \nТвій Спаситель тебе жде. \nСерцем ти не будь байдужий, \nБо Ісус піде.\n\nКуплет 2.\nУ краю, де похилились  \nтихо пальми й мир дрімав, \nЛюди йшли і дивувались, \nїх Ісус чекав. \nСамарянка розказала: \n"Дивний там пророк стоїть, \nЧи прийшов то не Месія? \nСвітло Боже в Нім..."\n\nКуплет 3.\nІ тепер вода ще ллється  \nдля слабих усіх людей. \nТим, хто плаче, Бог втирає \nсльози із очей. \nГосподь грішників прощає, \nВін відкрив всім благодать. \nДруже, Він тебе шукає, \nщоб спасіння дать.', '', NULL, NULL),
(167, 'В дивному озері Генісаретському', NULL, 'Куплет 1 \nВ дивному озері Генісаретському, \nв чистій, криштальній воді \nОбраз Ісуса Христа Назаретського \nвідображався святий.\nОбраз Ісуса Христа Назаретського \nвідображався святий.\n\nКуплет 2.\nНині Він Духом Своїм поселяється  \nв нашій щасливій душі, \nЧом невиразно Він в нас відбивається, \nяк відбивався в воді.\nЧом невиразно Він в нас відбивається, \nяк відбивався в воді.\n\nКуплет 3.\nМоже, серця вкрились сумнівів храмами,  \nМоже, гнітить марнота, \nДух наш схвильований світу примарами, \nтак, що й не видно Христа?\nДух наш схвильований світу примарами, \nтак, що й не видно Христа?\n\nКуплет 4.\nБудем, як озеро Генісаретськеє,  \nчисті і світлі в душі, \nІ відіб''ється Христа Назаретського \nв нас Його образ святий.\nІ відіб''ється Христа Назаретського \nв нас Його образ святий.', '', NULL, NULL),
(168, 'Я Друга дивного знайшов', NULL, 'Куплет 1 \nЯ Друга дивного знайшов, \nнайкращий Він на світі, \nЗнайшов Його святу любов \nв Новому Заповіті. \nЛюблю Спасителя свого \nбезмежною любов''ю, \nВін мій тепер і я Його, \nЙого обмитий кров''ю.\n\nКуплет 2.\nЯ Друга вірного пізнав,  \nнемає більш такого, \nМене до Себе Він прийняв \nнужденного й слабкого. \nВін Провідник мій на путі \nі йде завжди зі мною, \nВеде мене Він у житті \nвсесильною рукою.\n\nКуплет 3.\nСвятого Друга маю я,  \nВін добрий мій Учитель, \nУ Нім надія вся моя, \nбо Він є мій Спаситель. \nІ хто мене розлучить з Ним, \nжиття чи смерть, чи горе? \nЯ скрізь іду з Христом моїм \nчерез життєве море.', '', NULL, NULL),
(169, 'Оживляє сила Божа', NULL, 'Куплет 1 \nОживляє сила Божа \nтого, хто знеміг. \nНаш Ісус незмінний вчора, \nнині і повік.\nЛюбить грішних і спасає, \nпроганяє тьму.\n\nПрипев: \nНаш Ісус є вчора, нині і повік без змін. \nВсе пройде, любов Господня не старіє, ні! \nО, хвала Йому, о, хвала Йому: \nВсе пройде - Ісус є вічний, о, хвала Йому.\n\nКуплет 2.\nДруг знедолених і грішних –  \nлюбить Він тебе. \nЙди до Нього, засудивши \nу гріхах себе. \nВін таких прощає й каже: \n"Більше не гріши!"\n\nКуплет 3.\nВін вздоровлював недужих,  \nвсім давав спокій. \nВін зітре всі наші сльози \nв радості святій: \nХто йшов з вірою до Бога – \nмилість той пізнав.\n\nКуплет 4.\nЗ учнями, що були в горі,  \nйшов Він в Емаус, \nТак іде незримо з нами \nнаш Господь Ісус; \nА коли життю земному \nвже прийде кінець -', '', NULL, NULL),
(170, 'У Христі ми Друга маєм', NULL, 'Куплет 1 \nУ Христі ми Друга маєм, \nВін життя в нас пробудив, \nЩастям нас благословляє, \nджерело Він вічних сил. 2р.\n\nКуплет 2\nЯк же часто ми страждали, \nтерплячи даремно там, \nде просити забували, \nщоб давав Він поміч нам. 2р.\n\nКуплет 3\nЧи спокуса нас турбує,  \nчи у світі тяжко жить – \nВірмо всі, що Він нас чує \nі в час горя поспішить. \n\nКуплет 4\nВін Один у всьому світі \nзрозуміти може нас; \nТільки Він, душі Спаситель, \nдопомогу вчасно дасть. 2р.\n\nКуплет 5\nУ зневіру не впадаймо,  \nяк прийде тривоги час; \nСерце все Йому віддаймо – \nі Він спокій з неба дасть. \n\nКуплет 6\nМоже, нас забули друзі – \nвсе відкриймо перед Ним; \nЛиш Христос в земній дорозі \nвірний Друг усім святим. 2р.', '', NULL, NULL),
(171, 'Єдиний лікар є для нас –', NULL, 'Куплет 1 \nЄдиний лікар є для нас – \nласкавий наш Спаситель; \nЗ гріха й загибелі нас \nспас Син Божий, Відкупитель.\n\nПрипев: \nКращий скарб мені Ти дав, \nдушу і тіло врятував, \nщоб Тебе я прославляв: \n"Ти - мій Бог, Спаситель!"\n\nКуплет 2.\nУсі гріхи мої простив  \nєдиний мій Спаситель, \nІ дім Отця мені відкрив \nСин Божий, Примиритель.\n\nКуплет 3.\nЛюбити серцем прагну я  \nТебе, мій Відкупитель;\nУ Тебе вічний дар життя, \nМій Цар, мій Бог, Спаситель!\n\nКуплет 4.\nГріху і злу нас не зламать,  \nТи сильний Повелитель; \nДля серця радісно звучать \nслова: Ісус, Спаситель.\n\nКуплет 5.\nЯ славлю радісно Христа,  \nлюбов Його безмірну; \nХай величають всі уста \nГосподню ласку дивну.', '', NULL, NULL),
(172, 'Закінчивсь тривожний день', NULL, 'Куплет 1 \nЗакінчивсь тривожний день, \nстихло все, не чуть пісень; \nСонця промінь тихо згас, \nнаступив спочинку час. \nНіч покрила, все мовчить; \nІсус молиться, не спить.\n\nКуплет 2.\nОсь Христос в тяжкій журбі  \nзнемагає в боротьбі; \nТихо молить Він Отця: \nХай минула б чаша ця!\nВ небі вже зоря горить. \nВін же молиться, не спить.\n\nКуплет 3.\nКров у Нього на чолі.  \nВін припав аж до землі. \nЙому важко, бо Один \nзалишився Людський Син. \nЖурно, тихо, все мовчить. \nВін же молиться, не спить.\n\nКуплет 4.\nЗакінчився скорбний шлях, \nВін вже в славі в небесах, \nБачить все і любить нас, \nі поможе в кожен час. \nБуде вічно нас любить \nЙ помагати в кожну мить, Він не спить.', '', NULL, NULL),
(173, 'О ласкавий ласкавий Спаситель', NULL, 'Куплет 1 \nО, ласкавий, ласкавий Спаситель! \nНа хресті Він за мене вмирав, \nВін єдиний є наш Примиритель, \nВін всім вірним життя вічне дав.\n\nПрипев: \nВін за мене на хресті постраждав, \nВін за мене на хресті постраждав, \nна хресті постраждав, за мене вмирав,\nВін за мене на хресті постраждав.\n\nКуплет 2.\nГрішні Праведника осудили,  \nНа Голгофі Його розп''яли, \nІ одежу Його поділили, - \nТак немудрі Творця прийняли.\n\nКуплет 3.\nДав життя Своє в жертву Син Божий, \nЩоб від смерті людей врятувать; \nПереміг темні сили ворожі,\nВірним дав Він Свою благодать.', '', NULL, NULL),
(174, 'Ночі пізня вже година', NULL, 'Куплет 1 \nНочі пізня вже година, \nвсюди тиша і все спить; \nа Ісус на самотині \nТихо став Отця молить: \n"Отче Мій Святий, чи може\nпроминути чаша ця?\nТільки хай же буде, Отче, \nволя праведна Твоя!"\n\nКуплет 2.\nМолить Він Отця, благає  \nтак у другий, третій раз, - \nПіт кривавий виступає \nна чолі в скорботний час. \nВ тиші молиться Спаситель, \nучнів сон здолав усіх; \nУ тяжкій борні Учитель,\nдрузів кличе Він Своїх.\n\nКуплет 3.\n"Годі, годі вам дрімати, -  \nлюбим учням Він сказав, - \nОсь Мене ідуть узяти, \nчас страждань моїх настав. \nІ проллю Я кров святую \nза світ грішний, за всіх вас..." \nТишу розбудив нічную \nшум народу в пізній час.\n\nКуплет 4.\nБув з народом Юда-зрадник,  \nвін Христа поцілував; \nКого мали вони взяти – \nцілуванням показав. \nРуки Господу зв''язали, \nдо Пилата повели, \nНаглумились, насміялись \nі судити почали.\n\nКуплет 5.\nПокарати Його мали,  \n"Розіпни!" - народ кричав; \nНа Голгофі розіп''яли – \nтам Спаситель смерть прийняв. \nТоді скелі розпадались, \nсонце смеркло серед дня, \nІ завіса розірвалась, \nяк звершилось розп''яття.', '', NULL, NULL),
(175, 'Христос розпятий на хресті', NULL, 'Куплет 1 \nХристос, розп''ятий на хресті, \nза світ страждав; \nВін повний ласки й доброти \nусім прощав.\n\nКуплет 2.\nХристос вмирав, а світ над Ним  \nв той час глумивсь; \nВ нестерпних муках Божий Син \nза люд моливсь.\n\nКуплет 3.\nЛюбов Небесного Отця  \nсвіт не пізнав; \nГріхами лютими серця \nсвої скував.\n\nКуплет 4.\nХристос, розп''ятий на хресті,  \nза нас вмирав; \nЩоб від загибелі спасти, \nВін смерть прийняв.', '', NULL, NULL),
(176, 'Був ти друже на Голгофі', NULL, 'Куплет 1 \nБув ти, друже, на Голгофі, \nде Христос страждав? \nЯкі муки там жорстокі \nВін за нас прийняв! \nБачив ти вінок терновий \nна чолі Його? \nБачив ти, як кров стікала \nз святих ран Його?\n\nКуплет 2.\nЧи ти чув розлуки слово:  \n"Боже, Боже Мій! \nЧом лишив Мене Самого \nв боротьбі тяжкій?! \nЯ прийшов до них з любов''ю, \nпрагну їх спасти, \nА вони не зрозуміли... \nБоже, їм прости!\n\nКуплет 3.\nОсь звершилось! - й до Твоїх я,  \nОтче, рук святих \nВіддаю Мій дух покірно, \nТи його прийми!" \nДруже, знай, що ради моїх \nі твоїх провин \nмусив тяжко так стаждати \nСвятий Божий Син.\n\nКуплет 4.\nТому, друже, не вагайся,  \nна Голгофу йди, \nбіля ніг Христа Ісуса \nвесь свій гріх склади.\nА із уст Його почуєш \nті слова святі: \n"У раю зі Мною нині \nй вічно будеш ти."', '', NULL, NULL),
(177, 'Гірко плакав Христос на скорботній землі', NULL, 'Куплет 1 \nГірко плакав Христос на скорботній землі, \nСльози чисті лилися з очей; \nне даремно Він плакав: Він бачив у злі \nМарно гинучих бідних людей.\n\nПрипев: \nНі, Я плачу за вас; \nЯ ллю Свої сльози і кров; \nЯ приніс вам на землю небесну любов, \nви ж за це розіпнете Мене.\n\nКуплет 2.\nЧерез що, наш Спасителю, ти у сльозах?  \nМоже, храми Твої не блищать? \nЧи ж не Твій віковічний престол в небесах? \nЧи страждання тебе тяготять?\n\nКуплет 3.\nЯ дивлюся в журбі на людей - на братів:  \nВони гинуть в гріхах на землі, \nБо забули про кров, що за них Я пролив, \nІ забули про муки Мої.\n\nКуплет 4.\nЯ молюся за вас, Мною куплені ви,  \nо, прийміть Святу жертву Мою! \nЯ даю вам спасіння в пролитій крові, \nЯ віддав за вас душу Свою.', '', NULL, NULL),
(178, 'Сад Гефсиманський темрявою вкрився', NULL, 'Куплет 1 \nСад Гефсиманський темрявою вкрився, \nМов перед бурею вмить занімів, \nслухав уважно, як Хтось там молився, \nСльози кривавії лив.\n\nКуплет 2.\nСад Гефсиманський пізнав свого Друга,  \nЛюди ж пізнать не хотіли Його, \nДико кричали, ревіли навкруги, \nБога розп''яли свого.\n\nКуплет 3.\nО, схаменися, невірний народе,  \nЧорні заслони з очей своїх скинь! \nВсі залишили свої смертні походи,\nКров проливати покинь.\n\nКуплет 4.\nЗнай, що настане остання година,  \nБог для невірних відкриє Свій суд; \nТам не покається жодна людина, \nБо вже не буде спокут.', '', NULL, NULL),
(179, 'Пригадаймо муки Христову любов', NULL, 'Куплет 1 \nПригадаймо муки, Христову любов, \nЯк страждав Син Божий, як лив за нас кров; \nОсь у Гефсиманськім темному саду \nчути шум і гомін - вороги ідуть.\n\nКуплет 2.\nЙдуть вони з вогнями, тихо гомонять, \nЗ кіллям і з мечами - Спаса хочуть взять. \nЯк вже близько стала ворогів юрба, \nТихо і ласкаво Він їх запитав:\n\nКуплет 3.\n"Вам кого тут треба в пору цю нічну?  \nЯкщо лиш Ісуса? - Ось Я, тут стою!" \nВороги змовчали від тих слів святих, \nЗлякано упали на місцях своїх.\n\nКуплет 4.\nРаптом зрадник Юда перед Спасом став  \nІ лице Господнє він поцілував. \n"Радуйся, Учитель!" - Юда так сказав, \nА Його Спаситель тихо запитав:\n\nКуплет 5.\n"Чого з ворогами, друже, ти прийшов?  \nНащо залишаєш ти Мою любов?" \nВ той час народ лютий на Христа напав \nІ святії руки Господу зв''язав...', '', NULL, NULL),
(180, 'В багряниці Син Божий в терновім вінці', NULL, 'Куплет 1 \nВ багряниці Син Божий, в терновім вінці, \nМіцно зв''язані зморені руки. \nСкільки втоми, страждання на світлім лиці, \nСкільки жалю до всіх, скільки муки...\nСкільки втоми, страждання на світлім лиці, \nСкільки жалю до всіх, скільки муки...\n\nКуплет 2.\nТа не тілом лиш терпить Спаситель за нас,  \nХоч ганебні й жахливі знущання; \nСтрашні муки душі - знати в той скорбний час, \nЩо не всі приймуть Боже спасіння.\nСтрашні муки душі - знати в той скорбний час, \nЩо не всі приймуть Боже спасіння.\n\nКуплет 3.\nПогляд Сина любов''ю до грішних горів,  \nСерце ніжно усіх пригортало, \nТа лиш дехто цю Божу любов зрозумів, \nГрішні люди Ісуса розп''яли.\nТа лиш дехто цю Божу любов зрозумів, \nГрішні люди Ісуса розп''яли.\n\nКуплет 4.\nТак томився Спаситель і тяжко терпів,  \nБеззаконний світ з Бога сміявся. \nТо за тебе, мій друже, Він вмерти схотів, \nВін за тебе на муки віддався.\nТо за тебе, мій друже, Він вмерти схотів, \nВін за тебе на муки віддався.\n\nКуплет 5.\nДруже мій, не відкинь ти любови Христа,  \nНе забудь Його щире бажання. \nО, прийми ти спасіння, яке Він придбав, \nОціни Його муки й страждання.\nО, прийми ти спасіння, яке Він придбав, \nОціни Його муки й страждання.', '', NULL, NULL),
(181, 'Вже північ навкруги все спить', NULL, 'Куплет 1 \nВже північ... навкруги все спить, \nЧорні хмари по небу пливуть; \nтемний Гефсиманський сад мовчить, \nНіби молиться хтось, - в тиші чуть.\n\nКуплет 2.\nВже північ... Ісус в боротьбі  \nчисті руки в молитві підняв, \nЙого серце в смертельній журбі, \nЙого дух жах і морок обняв.\n\nКуплет 3.\nВже північ... Христос без вини  \nГоспода почав тихо благать, \nЧує - час наблизився сумний. \nЙого мучити візьмуть, розпнуть.\n\nКуплет 4.\nВже північ... Сад прокинувся,  \nТо Ісуса взяти вже прийшли, \nпоцілунок Юди - то зрада. \nБула північ... Ісуса взяли.', '', NULL, NULL),
(182, 'Сам хреста тяжкого', NULL, 'Куплет 1 \nСам хреста тяжкого, \nСам хреста тяжкого \nСвятий Божий Син \nвиніс на Голгофу, \nвиніс на Голгофу \nі помер там Він.\n\nКуплет 2.\nПо Господній волі,  \nпо Господній волі \nє хрест мій земний, \nЩоб я зносив болі, \nщоб я зносив болі \nу душі своїй.\n\nКуплет 3.\nЗмучений в дорозі,  \nзмучений в дорозі \nтягарем хреста, \nУ тяжкій знемозі, \nу тяжкій знемозі \nСпас мій постраждав.\n\nКуплет 4.\nКоли розмишляю,  \nколи розмишляю \nпро Ісуса я, \nЛегшим відчуваю, \nлегшим відчуваю \nсвій тягар хреста.\n\nКуплет 5.\nТоді мені сили,  \nтоді мені сили \nдодає Спас мій, \nЩоб аж до могили, \nщоб аж до могили, \nніс тягар я свій.\n\nКуплет 6.\nХочу свято жити,  \nхочу свято жити \nІ хреста нести, \nБогу догодити, \nБогу догодити \nв небеса ввійти.', '', NULL, NULL),
(183, 'Чоло в вінку терновім похилене униз', NULL, 'Куплет 1 \nЧоло в вінку терновім похилене униз. \nКолючки гострі в Нього до крові уп''ялись. \nТи залишив всю славу, розп''ясти дав Себе. \nЗа муки і зневагу, люблю я лиш Тебе.\n\nКуплет 2.\nТерпів Ти тяжко, Спасе, страждав за нас усіх.  \nГаньбу та зле знущання завдав Тобі мій гріх. \nЯ заслужив ці муки, мої гріхи ти взяв, \nСпоглянь в цей час на мене, щоб ласку я прийняв.\n\nКуплет 3.\nВіддячити не можу, таких не маю слів.  \nЗа всі Твої страждання, що Ти перетерпів. \nО, дай же вірним бути, всі дні на цій землі, \nТвій подвиг не забути допоможи мені.', '', NULL, NULL),
(184, 'Чи тихо навколо чи стогне реве', NULL, 'Куплет 1 \nЧи тихо навколо, чи стогне, реве \nЛюдського життя океан, \nВ душі моїй стомленій завжди живе \nЛюбов до Спасителя ран.\n\nКуплет 2.\nНі горе, ні сльози, ні глум ворогів  \nНе змусять забути повік \nПро те, що ласкавий Господь захотів \nПочути благальний мій крик.\n\nКуплет 3.\nПішов на Голгофу понести мій гріх  \nІ в муках страждать за людей, \nІ душу мою убілив Він, як сніг, \nУ крові пречистій Своїй.\n\nКуплет 4.\nО, Боже мій любий, коли Ти прийдеш \nУ силі та славі Своїй – \nі стомлені душі Ти наші візьмеш \nВ обійми Свої дорогі?', '', NULL, NULL),
(185, 'Прийдіть та погляньте на страшні знущання', NULL, 'Куплет 1 \nПрийдіть та погляньте на страшні знущання... \nНаш гріх приготовив Христові страждання; \nОсь руки, і ноги, і серце пробили, \nЗ тернини вінка на чоло положили.\n\nПрипев: \nВсі співайте: Алилуя! \nСлавте Господа!\n\nКуплет 2.\nНе слухають люди про муки Христові,  \nЧому ж їх не цінять? Не мають любови? \nО, люди, відкиньте свої мудрування! \nПрийміть усім серцем Христові страждання.\n\nКуплет 3.\nХто прагне спасіння - іди до Ісуса; \nЙого кров рятує тебе від спокуси. \nЗа гріх хто самого себе докоряє, \nТому двері раю вже Бог відчиняє.\n\nКуплет 4.\nЗа наші гріхи ми всі мали страждати,  \nХристос постраждав, щоб рятунок нам дати. \nВіддаймо ж Йому славу, честь поклоніння \nЗа те, що нам, грішним придбав Він спасіння.', '', NULL, NULL),
(186, 'За тебе Я страждав', NULL, 'Куплет 1 \nЗа тебе Я страждав \nі кров Свою пролив; \nІ смертю на хресті \nтебе Я відкупив. \nЖиття віддав тобі, \nа що ти дав Мені?\n\nКуплет 2.\nЯ на землі прожив  \nв скорботах та журбі, \nЩоб ти у небі жив \nщастя мав собі. \nЯ радість дав тобі, \nа що ти дав Мені?\n\nКуплет 3.\nЯ небо залишав,  \nйого красу й любов, \nЯ грішних полюбив, \nтебе знайти прийшов. \nЯ все віддав тобі,\nа що ти дав Мені?\n\nКуплет 4.\nО, друже дорогий,  \nХристу життя віддай; \nлиш Він - Спаситель твій, \nЙому хвалу складай. \nВін - Пастир, Він - любов, \nпролив за тебе кров.', '', NULL, NULL),
(187, 'Там на Голгофі Спас тяжко страждав', NULL, 'Куплет 1 \nТам, на Голгофі Спас тяжко страждав, \nна Себе всі мої гріхи Він взяв. \nСвятую кров пролив і нею гріх мій змив, \nСпасіння Він звершив й мене прийняв.\n\nКуплет 2.\nТам, на Голгофі Спас тяжко вмирав,  \nСин Божий за людей життя віддав, \nЩоб нас усіх спасти й до неба довести, \nМир дати для душі - Христос вмирав.\n\nКуплет 3.\nО, любі друзі, поки ще є час,  \nПрийдіть до Нього всі, Він прийме вас. \nВам всі гріхи простить, і спокій дасть в ту мить \nВсім, хто лиш поспішить, наш любий Спас.', '', NULL, NULL),
(188, 'Що вину мою простить', NULL, 'Куплет 1 \nЩо вину мою простить? \nО, ніщо, лиш кров Ісуса! \nЩо мене знов оживить? \nО, ніщо, лиш кров Ісуса!\n\nПрипев: \nСтрумок той цінний є, \nзмиває гріх з мене, \nВін є сильніш морів, - \nО, ніщо, лиш кров Ісуса!\n\nКуплет 2.\nЩо з''єднає з Богом нас?  \nО, ніщо, лиш кров Ісуса! \nЩо спокій для серця дасть? \nО, ніщо, лиш кров Ісуса!\n\nКуплет 3.\nЩо спасе з гріхів мій дух?  \nО, ніщо, лиш кров Ісуса! \nНі добро моїх заслуг, - \nО, ніщо, лиш кров Ісуса!\n\nКуплет 4.\nЩо знов підкріпить мене?  \nО, ніщо, лиш кров Ісуса! \nЩо знов душу підійме? \nО, ніщо, лиш кров Ісуса!', '', NULL, NULL),
(189, 'Хто підносить свій зір', NULL, 'Куплет 1 \nХто підносить свій зір \nна Христа на хресті, \nТой одержує спокій душі, \nДруже мій, ось поглянь, \nяк Він світ полюбив, \nНа хресті і за тебе терпів.\n\nПрипев: \nГлянь, глянь, друже, глянь. \nГлянь на рани Христа, \nна терновий вінок \nІ пізнаєш любови зразок.\n\nКуплет 2.\nВід загроз і від суду  \nтебе Він звільнив, \nІ від смерти тебе відкупив; \nСмерть, де жало і влада \nтвоя на буття? \nПекло, де перемога твоя?\n\nКуплет 3.\nЯк туманом, тобі  \nсмуток душу сповив, \nІ стражданнями серце стомив, \nАле глянь на Христа, \nВін промінням сія, \nВічна правда у Нім і життя.\n\nКуплет 4.\nО, чому ж у твоїх  \nтаємничих очах \nІ байдужість буває, і страх? \nДруже, глянь на Христа \nти в надії живій – \nІ отримаєш дар дорогий.', '', NULL, NULL),
(190, 'Христос як учням всім своїм', NULL, 'Куплет 1 \nХристос, як учням всім своїм \nпро хресну смерть відкрив, \nДля друзів Він перед Отцем \nвзяв хліб, благословив.\n\nКуплет 2.\nІ розламавши, їм подав,  \nй до них слова сказав: \n"Прийміть і споживайте всі, \nце тіло є Моє."\n\nКуплет 3.\nЗ вином також Він чашу взяв,  \nза неї помоливсь: \n"Оце є кров Моя, - сказав, - \nви з неї пийте всі.\n\nКуплет 4.\nНовий Мій Заповіт в крові  \nЯ вам тепер даю. \nОтож, робіть це завжди ви,\nсмерть згадуйте Мою."\n\nКуплет 5.\nО, Господи, дозволь в цей час  \nТвою згадати кров, \nПролиту на хресті за нас, \nстраждання і любов.', '', NULL, NULL),
(191, 'Зійдім на Голгофу брати', NULL, 'Куплет 1 \nЗійдім на Голгофу, брати! \nМесію небесного там розп''яли. \nВін правди святої слова сповіщав, \nНедужих зціляв, а тепер постраждав... \nСклонімось перед Ним.\n\nКуплет 2.\nЗійдім на Голгофу, брати!  \nВ стражданнях обличчя, немов у вогні. \nВін прагне, і оцет Тому подають, І\nз уст Чиїх води живії течуть.\nСклонімось перед Ним...\n\nКуплет 3.\nЗійдім на Голгофу, брати!  \n"Не знають, що чинять, їм Отче, прости!" – \nВін молить... Зійдім також ми, щоб за нас \nМолитва Христова у вись піднялась. \nСклонімось перед Ним...\n\nКуплет 4.\nЗійдім на Голгофу, брати!  \nЗнов погляд підносить Ісус догори: \n"Мій Отче! Чому Ти залишив Мене?" \nО, брате, щоб нас прийнять в Царство Своє! \nСклонімось перед Ним...\n\nКуплет 5.\nЗійдім на Голгофу, брати!  \nСтраждальця молитва остання звучить: \n"Звершилось! Я дух Мій Тобі віддаю." \nЗа нас Він пожертвував душу Свою. \nСклонімось перед Ним...\n\nКуплет 6.\nЗійдім на Голгофу, брати!  \nГіркою отрутою наші гріхи \nХристові страждання і смерть завдали. \nЧи є що дорожче тієї ціни? \nСклонімось перед Ним.', '', NULL, NULL),
(192, 'Коли б Тебе Христе в стражданнях', NULL, 'Куплет 1 \nКоли б Тебе, Христе, в стражданнях \nв душі постійно споглядав, \nЯ б рвався в небо без вагання \nй Тебе сильніше все кохав. \nКоли б завжди перед собою \nя бачив образ Твій в крові, \nто б знав, якою Ти ціною \nспасіння вічне дав мені.\n\nКуплет 2.\nКоли б чоло в вінку терновім  \nдовіку я не забував, \nя там би вдячний був Христові: \n"Я не достойний, - Ти ж страждав!" \nКоли б частіш насамотині \nТебе я, Господи, благав, \nТо для служіння правди нині \nТи більше б сил мені давав.', '', NULL, NULL),
(193, 'Слава тобі о Спасе мій', NULL, 'Куплет 1 \nСлава тобі, о Спасе мій, \nза хресну смерть і рай; \nЩоб не забув я подвиг Твій, \nГолгофу нагадай.\n\nПрипев: \nЩоб не забув мольбу Твою, \nщоб не забув любов Твою, \nщоб не забув я кров Твою, - \nГолгофу нагадай.\n\nКуплет 2.\nБачу печеру, там, де Ти  \nзамучений лежав \nІ ангела, що з висоти \nз''явився сторожам.\n\nКуплет 3.\nВіри проміннями згори  \nдушу мою осяй; \nЩоб зріли в ній святі плоди, \nГолгофу нагадай.\n\nКуплет 4.\nХочу подібним буть Тобі,  \nв покорі хрест нести. \nХвилини горя у житті \nприйняти так, як Ти.', '', NULL, NULL),
(194, 'Прийми подяку і хваління', NULL, 'Куплет 1 \nПрийми подяку і хваління, \nІсусе, за Твою любов; \nЗа гріх наш Ти страждав невинно, \nЗа нас пролив святую кров.\n\nКуплет 2.\nПрийняв приниження й наруги,  \nпобої, глум і розп''яття, \nПішов за нас на хресні муки, \nщоб дати вічне нам життя.\n\nКуплет 3.\nЗ сльозами радості спасіння  \nприйму від Тебе, Спасе, я; \nІ вірю, з Богом мир безцінний \nдарує жертва нам Твоя.\n\nКуплет 4.\nТвої священні заповіти  \nвиконувати хочу я, \nТвоєю правдою зігрітий, \nприйду я до кінця життя.', '', NULL, NULL),
(195, 'Я дізнавсь про любов Христа', NULL, 'Куплет 1 \nЯ дізнавсь про любов Христа, \nяк ходив Він колись по землі, \nЯк робив Він великі діла, \nяк страждав і помер на хресті, хресті, \nЯк страждав і помер на хресті.\n\nПрипев: \nТак, так за людей, людей; \nТак, так за людей: \nСпаситель з небес, \nПовний слави чудес, \nУмирав, щоб спасти всіх людей.\n\nКуплет 2.\nЯ дізнавсь, як Ісус страждав,  \nяк томився Він у муках і вмер. \nЗ Книги Божої я дізнавсь, \nщо Христос умирав за людей, людей, \nЩо Христос умирав за людей.\n\nКуплет 3.\nЯ дізнавсь про небесний край,  \nде святі будуть славить Христа. \nО, чи буде там, у тім краю, \nприготовлено місце мені, мені, \nПриготовлено місце мені.\n\nКуплет 4.\nТа я знаю Господні слова:  \n"Я життя вічне вірним даю". \nТак, я вірю і люблю Христа, знаю, \nдасть мені місце в раю, в раю, \nЗнаю, дасть мені місце в раю.', '', NULL, NULL),
(196, 'Я співаю як Спаситель', NULL, 'Куплет 1 \nЯ співаю, як Спаситель \nмене дивно полюбив, \nЯк страждав мій Відкупитель, \nі мене навік простив.\n\nПрипев: \nПісня ллється про Ісуса, \nсмертю Він мене купив, \nКров пролив Свою святую \nі гріхи навік простив!\n\nКуплет 2.\nЯ співаю, линуть звуки:  \nщоб мене від мук спасти, \nВін прийняв за мене муки, \nдав Себе Він розп''ясти.\n\nКуплет 3.\nЯ співаю, як Спаситель  \nв небі чистому сія, \nЯк Він любить всіх, Хранитель, \nвічно з Ним там буду я.', '', NULL, NULL),
(197, 'На хресті Христова кров', NULL, 'Куплет 1 \nНа хресті Христова кров \nза мій гріх пролита,\nТам спасіння знайшов \nі почав знов жити.\n\nПрипев: \nУ Христі, у Христі \nє могутня сила, \nВсі гріхи мої тяжкі \nКров Твоя обмила.\n\nКуплет 2.\nВ хресній смерті, Спасе мій,  \nВсім даєш прощення. \nХто повірить в подвиг Твій – \nТи даєш спасіння.\n\nКуплет 3.\nЧерез хресну смерть Твою  \nв небо доступ маю, \nІ там радощам моїм \nвже не буде краю.', '', NULL, NULL),
(198, 'Там далеко колись на узгірї стояв', NULL, 'Куплет 1 \nТам далеко, колись, на узгір''ї стояв \nХрест зневаги ганебних провин. \nУ хресті я придбав вічний прощення дар, \nбо на нім помирав Божий Син.\n\nПрипев: \nЯ повік не забуду той хрест, \nбо лиш в ньому спасіння моє. \nНайцінніший скарб мого життя, - \nКров пролита Ісуса свята.\n\nКуплет 2.\nТворить нове життя і святі почуття  \nу душі моїй давній той хрест; \nЯ туди все дивлюсь, там Спаситель Ісус... \nДля Голгофи прийшов Він з небес.\n\nКуплет 3.\nКоли згадую я, як за мене мій Спас,  \nна хресті тому тяжко страждав, \nперед Ним визнаю я вину всю мою, \nбо отримав там прощення дар.', '', NULL, NULL),
(199, 'Такий як є заради крови', NULL, 'Куплет 1 \nТакий, як є, заради крови, \nза нас пролитої з хреста. \nНа поклик Божої любови, \nмій Спасе, йду до Тебе я.\n\nКуплет 2.\nТакий, як є - сліпий і бідний,  \nнема добра зовсім в мені. \nХоч прощення Твого не гідний, \nмій Спасе, йду до Тебе я.\n\nКуплет 3.\nТакий, як є; мене Ти приймеш,  \nдаруєш спокій і життя, \nСвоєю ласкою обіймеш, \nмій Спасе, йду до Тебе я.\n\nКуплет 4.\nТакий, як є, в Твоїй любові  \nздолаю всі спокуси я: \nВіднині і назавжди в Тобі, \nмій Спасе, йду до Тебе я.', '', NULL, NULL),
(200, 'Кров Свою Син Божий пролив', NULL, 'Куплет 1 \nКров Свою Син Божий пролив, \nвід гріхів очистив всіх нас, \nВід гріховних пут нас звільнив \nі Своєю жертвою спас. \nЯк вівця я довго блудив, \nВ серці панував тільки гріх; \nТа мене Спас кров''ю обмив, \nі став я біліший, ніж сніг.\n\nПрипев: \nБілий, як сніг, \nБілий, як сніг. \nКров''ю Ісуса обмий, \nІ буду я білий, мов сніг.\n\nКуплет 2.\nВін вінок терновий носив,  \nна хресті розп''ятий Він був; \nВін за грішних Бога просив \nі для всіх спасіння здобув. \nЯ прийшов також до Христа, \nвід гріхів обмився моїх; \nЦе зробила кров пресвята, \nі став я біліший, ніж сніг.\n\nКуплет 3.\nБоже, всю безодню гріхів  \nі вину свою визнаю, \nЯ не маю добрих плодів; \nТи Сам бачиш неміч мою. \nТи, однак, мене все ж прийняв \nі звільнив від гріхів тяжких \nІ з душі тягар всякий зняв, \nі став я біліший, ніж сніг.', '', NULL, NULL),
(201, 'Мій дух радіє в кожну мить', NULL, 'Куплет 1 \nМій дух радіє в кожну мить, \nпро Господа мій спів бринить, \nСмерть переніс Христос за нас \nй Своїх від смерти спас.\n\nПрипев: \nО, Христе мій любий, \nТи вмер за нас; \nВід вічної смерти \nТи всіх Своїх спас.\n\nКуплет 2.\nХристос на грішній цій землі  \nшукав загиблих у пітьмі, \nСпасіння вічне дав Він їм, \nулюбленим Своїм.\n\nКуплет 3.\nЛюблю Спасителя Христа,  \nв Нім світло, щастя повнота. \nЯке ж блаженство ми знайдем, \nколи туди прийдем!\n\nКуплет 4.\nСпівають ангели Христу  \nу небі пісню пресвяту. \nО, що за радість без кінця \nчекає нас в Отця.', '', NULL, NULL),
(202, 'Я є вівця Ісуса', NULL, 'Куплет 1 \nЯ є вівця Ісуса, \nВін Пастир добрий мій, \nЯ всюди Ним хвалюся, \nВін дав душі спокій.\n \nСебе віддав на муки,\nза мене постраждав,\nВід вічної розлуки \nМене Він врятував, \nмене Він врятував.\n\nКуплет 2.\nЯ є вівця Ісуса,  \nВін Пастир добрий мій, \nЯ з Ним вже не боюся \nстраждань в душі моїй.\n \nПречистою Він кров''ю \nмене з гріхів омив, \nНебесною любов''ю \nВін дивно оживив, \nВін дивно оживив.\n\nКуплет 3.\nЯ є вівця Ісуса,  \nВін Пастир добрий мій, \nВ знак вічного союзу \nдав Заповіт Новий. \nІ Хліб переломив Він, \nміж учнями ділив, \nІ з чаші з ними пив Він, \n"Чиніть це й ви!" - звелів, \n"Чиніть це й ви!" - звелів.\n\nКуплет 4.\nЯ є вівця Ісуса,  \nВін Пастир добрий мій, \nЯ Ним Одним кріплюся \nв долині цій земній; \nМене Він за Собою \nпровадить, як дитя, \nДо щастя і спокою, \nдо вічного життя, \nДо вічного життя.', '', NULL, NULL),
(203, 'Чи пізнав ти силу крові о скажи', NULL, 'Куплет 1 \nЧи пізнав ти силу крові, о скажи! \nЧи звільнився ти від тягарів? \nЧи приніс ти до Христа свої гріхи,\nЩоб Він кров''ю святою обмив?\n\nПрипев: \nЧи ти вже чистий є? \nМоже змити твій гріх кров Христа; \nМоже убілити, наче сніг, тебе. \nЧи обмитий ти кров''ю Христа?\n\nКуплет 2.\nЧи ти маєш в серці віру у Христа,  \nЧи ти жертву Голгофську прийняв? \nВсі гріхи змиває тільки кров свята; \nЧи в підніжжя хреста ти їх склав?\n\nКуплет 3.\nЧи готовий ти Ісуса зустрічать?  \nЧи очистився вже від гріхів? \nМоже Спас у край небесний, вічний взять \nТільки тих, кого кров''ю обмив.\n\nКуплет 4.\nТож прийди до Спаса, відступи від зла,  \nІ покайся в провинах скоріш, \nбо за тебе із Голгофи кров текла; \nНею гріх свій навіки обмий.', '', NULL, NULL),
(204, 'Хочеш ти друже спастись від гріха –', NULL, 'Куплет 1 \nХочеш ти, друже, спастись від гріха? – \nЄ сила в крові, в крові Христа. \nХочеш ввійти в царство вічне Христа? – \nЄ сила в Його крові.\n\nПрипев: \nСила Божа чудотворна є \nВ крові Христа; \nСила Божа чудотворна є \nУ пречистій крові Христа.\n\nКуплет 2.\nХочеш покинути гордість і страх? –  \nЄ сила в крові, в крові Христа. \nТи не загинеш у власних гріхах – \nЄ сила в Його крові.\n\nКуплет 3.\nХочеш ти бути білішим за сніг? –  \nЄ сила в крові, в крові Христа. \nКров''ю Він може обмить з тебе гріх – \nЄ сила в Його крові.\n\nКуплет 4.\nГосподу хочеш ти вірно служить? –  \nЄ сила в крові, в крові Христа. \nХочеш життям ти Ісуса хвалить? – \nЄ сила в Його крові.', '', NULL, NULL),
(205, 'Коли погляну в вірі я на хрест', NULL, 'Куплет 1 \nКоли погляну в вірі я на хрест, \nде Божий Син страждав, \nТремтить тоді душа моя, \nсоромлюсь, що Його не знав.\n\nКуплет 2.\nО, Спасе любий, дай, щоб я  \nу світі слави не шукав, \nЩоб Твої муки, смерть Твоя \nбули вінцем моїх похвал.\n\nКуплет 3.\nВ палкій любові, Спасе мій,  \nза нас пролив Ти Свою кров, \nТерпів зневагу від людей \nі ради нас на смерть пішов.\n\nКуплет 4.\nКоли б я все Тобі віддав,  \nТебе б я тим не вшанував; \nЩо ж за любов Тобі я дам? \nВізьми мене, Твій весь я сам.', '', NULL, NULL),
(206, 'Блаженні серця що Христа прийняли', NULL, 'Куплет 1 \nБлаженні серця, що Христа прийняли, \nСпасіння і мир на Голгофі знайшли; \nПростив Ти й мене, я Тобі не чужий, \nТи дав мені спокій, навіки я Твій.\n\nПрипев: \nПрославте любов Христа \nДивну, Божественну! \nСпасає грішників Любов Христа.\n\nКуплет 2.\nЯ довго в гріхах без Христа пробував,  \nСпасіння, спокою у серці не мав; \nТепер я співаю: "Спасителю мій, \nЗцілив Ти мене у любові Своїй!"\n\nКуплет 3.\nБлаженні відкуплені смертю Христа,  \nСпаситель відкрив їм нове майбуття, \nУтер їхні сльози, своїми назвав, \nМені також сили безсилому дав.\n\nКуплет 4.\nО, Спасе мій милий, Ти радість моя,  \nНавчай же, щоб вірно служив Тобі я. \nПролив Ти за мене пречистую кров – \nпрославлю я милість Твою і любов!', '', NULL, NULL),
(207, 'Знаєш друже ти той струмок', NULL, 'Куплет 1 \nЗнаєш, друже, ти той струмок, \nщо з Голгофи тихо біжить? \nЗнаєш, Хто всім радість дає \nі навчає Бога любить?\n\nПрипев: \nХоч мій гріх великий, тяжкий, \nта прощення Спас мені дав; \nСтав я серцем чистий, святий, \nяк любов Христову прийняв.\n\nКуплет 2.\nНа хресті в терновім вінку  \nнаш Спаситель в муках вмирав, \nПив Голгофську чашу гірку: \nто за нас Він тяжко страждав.\n\nКуплет 3.\nДовго я без Господа жив,  \nв людях думав правду знайти; \nЛаску Бог мені дарував, \nсили дав до Нього прийти.\n\nКуплет 4.\nВідійшли вагання мої:  \nВін позвав - я встав і пішов \nІ велику радість душі \nя навіки в Ньому знайшов.\n\nКуплет 5.\nЯ думками лину туди,  \nде Христова кров пролилась; \nНею з мене змиті гріхи, \nв душу ласка Божа влилась.', '', NULL, NULL),
(208, 'Муж скорбот  таке імя', NULL, 'Куплет 1 \n"Муж скорбот", - таке ім''я, \nдане Синові Царя, \nНим спасається душа, \nАлилуя, наш Спаситель.\n\nКуплет 2.\nГлум й зневагу потерпів,  \nі на хресну смерть пішов,\nКров''ю Він мене купив, \nАлилуя, наш Спаситель.\n\nКуплет 3.\nВсі ми грішними були,  \nа відвічний Божий Син, \nПрощення купив нам всім, \nАлилуя, наш Спаситель.\n\nКуплет 4.\nНа хресті Ісус вмирав,  \nтам "Звершилось!" - Він сказав, \nВ славі перед Богом став, \nАлилуя, наш Спаситель.', '', NULL, NULL),
(209, 'Із ран Спасителя текла', NULL, 'Куплет 1 \nІз ран Спасителя текла \nструмком пречиста кров; \nПрощення всім вона дала, \nдо Нього хто прийшов.\n\nКуплет 2.\nКоли розбійник на хресті,  \nрозп''ятий умирав, \nХристос, у милості святій, \nЙому прощення дав.\n\nКуплет 3.\nЯ без Христа життя не знав  \nі гинув в марноті; \nМені Христос спасіння дав \nв Своїй крові святій.\n\nКуплет 4.\nЯке блаженство я знайшов  \nв Ісусовій крові, \nПізнав Христа святу любов \nі неземний спокій.\n\nКуплет 5.\nМожливо, в немочі десь я  \nв моїм житті згрішу – \nВ крові Спасителя Христа \nпрощення я знайду.', '', NULL, NULL),
(210, 'О Господи Боже благаю Тебе', NULL, 'Куплет 1 \nО, Господи, Боже, благаю Тебе: \nВізьми Ти, як жертву, життя все моє; \nОчисть моє серце і дух обнови, \nОбмий всі провини в пречистій крові.\n\nПрипев: \nКров''ю обмий, \nкров''ю обмий, \nпошли в моє серце \nспокій Твій святий.\n\nКуплет 2.\nО, Господи, Боже, почуй Ти мене:  \nНавчи прославляти ім''я лиш Твоє; \nПролий в моє серце святу благодать, \nДай радість спасіння душею прийнять.\n\nКуплет 3.\nОбмий мою душу в пречистій крові  \nІ стану білішим від снігу тоді; \nБлагаю: дай твердість у вірі мені, \nЗроби мене, Боже, приємним Тобі.', '', NULL, NULL),
(211, 'Там де Один постраждав за всіх', NULL, 'Куплет 1 \nТам, де Один постраждав за всіх, \nТам Де розбійник обмив свій гріх, \nТам Він спасіння й моє звершив. \nО, хвала Христу! \nО, хвала Христу! \nО, хвала Христу!\nТам Він спасіння й моє звершив. \nО, хвала Христу! \nО, хвала Христу! \nО, хвала Христу!\n\nКуплет 2.\nДушу мою кров''ю Спас обмив,  \nСловом Своїм мене відродив, \nДуха Святого на мене злив, \nО, хвала Христу! \nО, хвала Христу! \nО, хвала Христу!\nДуха Святого на мене злив, \nО, хвала Христу! \nО, хвала Христу! \nО, хвала Христу!\n\nКуплет 3.\nДрузі мої, ще приємний час,  \nБог милостивий чекає вас, \nТож поспішіть, щоб і вас Він спас, \nО, хвала Христу! \nО, хвала Христу! \nО, хвала Христу!\nТож поспішіть, щоб і вас Він спас, \nО, хвала Христу! \nО, хвала Христу! \nО, хвала Христу!', '', NULL, NULL),
(212, 'Ісуса люблю я бо Він спас мене', NULL, 'Куплет 1 \nІсуса люблю я, бо Він спас мене, \nДо Нього молюся і Він чує все. \nМій любий Ісусе, за мене Ти вмер, \nЛюбити Тебе буду щиро тепер.\n\nКуплет 2.\nВ житті і в час смерти любитиму  \nя Спасаючу жертву благого Христа; \nМій любий Ісусе, Ти гріх мій простив, \nСлужити я завжди бажаю Тобі.\n\nКуплет 3.\nВ небесному царстві, у славі святих  \nПолине хваління Христу з уст моїх; \nТам буду з Ісусом у вічній хвалі, \nТам горе забуду, що мав на землі.', '', NULL, NULL),
(213, 'Ти  Господь мій і Спаситель', NULL, 'Куплет 1 \nТи - Господь мій і Спаситель; \nТи за мене постраждав, \nТи - мій Пастир і Учитель, \nБо й за мене Ти вмирав.\n\nПрипев: \nТільки Ти, Спасе мій, \nМені вірний повсякчас!\n\nКуплет 2.\nЯ з Тобою хочу бути  \nВже навіки, Спасе мій, \nІ ніколи не забути, \nщо Ти дав мені спокій.\n\nКуплет 3.\nМоє серце завжди прагне  \nЖить Тобою в світі цім; \nМоя радосте й надіє, \nБудь притулком тут моїм!\n\nКуплет 4.\nХочу я перебувати  \nБіля Тебе ночі й дні \nЙ людям всім розповідати, \nЩо зробив Ти вже мені.', '', NULL, NULL),
(214, 'Честь Тобі мій Спасе слава', NULL, 'Куплет 1 \nЧесть Тобі, мій Спасе, слава! \nТяжкі муки Ти прийняв, \nНа спасіння дав нам право, \nБожими дітьми назвав.\n\nПрипев: \nЧесть Тобі, мій Спасе, слава! \nТяжкі муки Ти прийняв, \nНа спасіння дав нам право, \nБожими дітьми назвав.\n\nКуплет 2.\nДовго я блукав у світі,  \nпрагнув щастя і добра – \nМожу я тепер радіти \nчерез Господа Христа.\n\nКуплет 3.\nІ тепер моя надія  \nна святу Христову кров; \nЙого слухаю веління, \nславлю дивную любов.\n\nКуплет 4.\nЧи живу я, чи вмираю –  \nВідкупитель мій живе; \nлиш Йому хвалу складаю, \nВін у небо приведе.\n\nКуплет 5.\nВін, як Пастир, щохвилини  \nстереже мене від зла, \nЩоб до вічної країни \nувійшла душа моя.\n\nКуплет 6.\nЧесть Тобі, Ісусе, слава  \nза терпіння на хресті \nІ за поклик Твій ласкавий \nдо життя в святій красі.', '', NULL, NULL),
(215, 'Хто міг збагнути ціль Його приходу', NULL, 'Куплет 1 \nХто міг збагнути ціль Його приходу? \nСвіт про Христа одержав добру вість. \nПорвав Він пута, людям дав свободу, \nЩастя і радість грішникам приніс.\n\nКуплет 2.\nВічний Христос примирення дарує  \nЗ Богом Отцем, бо правда тільки в Нім.\nКров''ю Своєю нам приніс спасіння, \nВ серці будує Він для Себе дім.\n\nКуплет 3.\nЗнову до Тебе, Боже, я молюся,  \nХоч не збагнув ще всю Твою любов, \nДай пам''ятати подвиг цей Ісуса, \nДай не забуть Його святую кров!', '', NULL, NULL),
(216, 'О світу спасіння Любове свята', NULL, 'Куплет 1 \nО, світу спасіння, Любове свята! \nЗа наші провини лилась Кров Христа. \nВесь світ відкупив Він, і дав спокій Свій. \nХай світ весь радіє, хай світ весь радіє, \nХай світ весь радіє в любові святій.\n\nКуплет 2.\nЯ грішний був довго, був мертвий мій дух,  \nТа Божого слова торкнувся мій слух; \nІ серце скорилось, і сльози я ллю, \nГосподь мій Спаситель, Господь мій Спаситель, \nГосподь мій Спаситель спас душу мою.\n\nКуплет 3.\nРозп''ятий Син Божий вмирав на хресті,  \nРозп''ятий для світу і я у Христі. \nРозп''ятий для мене і світ разом з Ним, \nЯ з Ним умираю, я з Ним умираю, \nЯ з Ним умираю, з Ісусом моїм.\n\nКуплет 4.\nНемеркнучу славу, безсмертя вінець  \nмені дасть у небі всесильний Творець; \nЗіллються там хори землі та небес, \nДля вічної слави, для вічної слави, \nДля вічної слави в Христі я воскрес!', '', NULL, NULL),
(217, 'Тебе я славлю Спасе мій', NULL, 'Куплет 1 \nТебе я славлю, Спасе мій, \nвсім серцем і життям, \nІ пісня радости й хвали \nНаповнить хай уста!\n\nПрипев: \nО, кров Христа мене спасла,\nО, кров Христа мене спасла, \nО, кров Христа мене спасла \nІ все нове дала! \nНове все, нове все, - \nО, кров Христа мене спасла \nІ все нове дала!\n\nКуплет 2.\nТомилася душа моя,  \nКоли я жив у злі, \nТепер нехай звучить хвала, \nТобі, о, Спасе мій!\n\nКуплет 3.\nТяжке життя було в гріхах –  \nТепер спасенний я, \nОбмитий кровію Христа, \nО, як щасливий я!', '', NULL, NULL),
(218, 'Під хрестом Христовим Божий мир пливе', NULL, 'Куплет 1 \nПід хрестом Христовим Божий мир пливе, \nБлагодатне слово спокій всім дає. \nТам душа недужа гірких сліз не ллє. \nКров Христа гріхи змиває, мир дає.\n\nКуплет 2.\nЗ ран Христа стікала Заповіту кров,  \nВ ній є наша сила, Божая любов. \nСмерть нас не злякає, і не звабить гріх, \nБожий Син спасає на шляху земнім.\n\nКуплет 3.\nВірю, після смерти до Христа піду,  \nБо в житті моїм Він Розігнав пітьму. \nВ небі покладу я все до ніг Його. \nПіснею прославлю Господа мого!', '', NULL, NULL),
(219, 'Пливе над світом пісня любови', NULL, 'Куплет 1 \nПливе над світом пісня любови, \nСпів той наповнить хай людські серця, \nДля нас пора настала чудова, \nМаємо в Бозі ми вічне життя.\n\nКуплет 2.\nВ малій хатині, в кожній оселі  \nМир хай панує та щира любов, \nБо наш Спаситель там на Голгофі \nЗа гріхи світу пролив Свою кров.\n\nКуплет 3.\nО, пресвятая тайна любови,  \nПеред Тобою мудрість вся німа. \nВ кожний час спомину Тіла і Крови \nХай у серцях буде віра тверда.\n\nКуплет 4.\nХай же в нас буде і серце чисте,  \nІ сльози каяття в наших очах. \nБудь всюди з нами, Любий наш Спасе, \nСлався завжди в наших добрих ділах.', '', NULL, NULL),
(220, 'Славу відвічну в небі', NULL, 'Куплет 1 \nСлаву відвічну в небі \nСин Божий залишив, \nЗа мене і за тебе \nВін кров пролив.\n\nПрипев: \nЗа грішних нас Христос страждав, \nПолюбивши нас, Себе на хрест віддав! \nТепер і ми з Його дітьми. \nНебо нам стражданнями Христос придбав!\n\nКуплет 2.\nВільні ми і щасливі  \nчерез Христа тепер: \nВ рай двері нам відкрив Він,\nХоч Сам помер!\n\nКуплет 3.\nІдучи вслід за Спасом,  \nввійдемо в небо ми; \nТам заспіваєм разом \nхвали псалми!\n\nКуплет 4.\nДвері ще не закриті,  \nможна ввійти туди: \nГрішнику, не барись ти, \nСкоріше йди!', '', NULL, NULL),
(221, 'Бог прийшов з небес в цей світ', NULL, 'Куплет 1 \nБог прийшов з небес в цей світ, \nТяжко Він постраждав. \nГріхи мої на Себе взяв, \nЩоб я спасіння мав.\n\nКуплет 2.\nЛиш Його любов свята  \nСпасіння всім дала. \nЗвільнила нас з гріхів тяжких, \nУ небо привела.', '', NULL, NULL),
(222, 'Алилуя алилуя', NULL, 'Куплет 1 \nАлилуя, алилуя, \nмені Христос гріхи простив. \nАлилуя, алилуя, \nмене Він відкупив.', '', NULL, NULL),
(223, 'Сталось чудо із чудес', NULL, 'Куплет 1 \nСталось чудо із чудес: \nнаш Господь Ісус воскрес; \nРадощам нема кінця, \nщастям сповнені серця. \nМуки Божий Син терпів, \nКров святу за нас пролив, \nЩастя сяє нам з небес, \nбо Спаситель наш воскрес.\n\nКуплет 2.\nГріб сторожа стерегла,  \nта безсилою була, - \nНаш Христос із мертвих встав, \nперемогу вірним дав. \nСмерть і пекло подолав, \nнам надію дарував. \nВін пішов у край небес, \nповний слави і чудес.\n\nКуплет 3.\nМи повірили в Христа  \nі воскресли для життя; \nТож, за Ним услід ходім, \nВін веде нас в вічний дім. \nБраття й сестри, всі хваліть \nСпаса в цю чудову мить; \nДень почався, ніч пройшла, \nСпас воскрес, Йому хвала!', '', NULL, NULL),
(224, 'У гробі Він лежав', NULL, 'Куплет 1 \nУ гробі Він лежав, \nХристос Спаситель, \nСлавного дня чекав \nХристос Господь.\n\nПрипев: \nІз гробу Він устав, \nВсі пекельні сили подолав; \nВін воскрес і нам спасіння дарував, \nІ на царство вічне нам надію дав. \nВін воскрес! Він воскрес! \nАлилуя, Він воскрес!\n\nКуплет 2.\nДаремно стерегли  \nложе Христове, \nГріб опечатали \nз тілом Його.\n\nКуплет 3.\nСмерть переможена  \nжертвою Сина, \nГрішник спасається \nкров''ю Христа.', '', NULL, NULL),
(225, 'Христос воскрес із мертвих', NULL, 'Куплет 1 \nХристос, воскрес із мертвих, \nсмертію смерть подолав! \nІ тим, що в гробах, життя дарував! \n(3 рази)', '', NULL, NULL),
(226, 'Христос воскрес', NULL, 'Припев: \nХристос воскрес! \nО, радість, радість нам; \nХристос воскрес! \nКінець журбі, сльозам! \nХристос воскрес, \nсмерть смертю подолав \nі нам спасіння вічне дав.\n\nКуплет 1.\nЗлочинці Його тіло на древі розп''яли,  \nЙому тяжкії муки гріхом ми завдали, \nПречиста кров лилася із ран та із чола,\nЗвершилось все, Йому хвала!\n\nКуплет 2.\nЗ Аримафеї Йосип Пилата ублагав,  \nЗ хреста щоб тіло зняти, і, знявши, поховав. \nЯк почало співати, та сонце як зійшло, \nХриста вже в гробі не було.\n\nКуплет 3.\nДо гробу дуже рано Марія надійшла,  \nШукаючи старанно, Ісуса не знайшла. \nЗ''явився ангел з неба і радісно сказав: \n"Христос воскрес! Із мертвих встав!"\n\nКуплет 4.\nСхвильована Марія скорилася сльозам,  \nАж ось свята подія: Христос явився Сам. \n"Учитель мій!" - сказала і в трепеті святім \nпро чудо сповістила всім.', '', NULL, NULL),
(227, 'Христос воскрес Христос воскрес', NULL, 'Куплет 1 \nХристос воскрес! Христос воскрес! \nРадість з неба сяє ясна, \nЗавітала Пасха красна, \nВсі радіймо щиро нині, \nБог дав щастя усім вірним,\nБог дав радість нам з небес – \nХристос воскрес! Христос воскрес!\n\nКуплет 2.\nХристос воскрес! Христос воскрес!  \nСпокій нам Господь приносить, \nСпокій в небо нас підносить, \nСпокій Божий всі вітаймо, \nВоскресіння прославляймо! \nБоже чудо всіх чудес – \nХристос воскрес! Христос воскрес!\n\nКуплет 3.\nХристос воскрес! Христос воскрес!  \nВсі апостоли співають, \nСтрах і смуток забувають, \nБоже слово всім звіщають,\nВсіх до Бога закликають. \nІ спасіння йде з небес – \nХристос воскрес! Христос воскрес!\n\nКуплет 4.\nХристос воскрес! Христос воскрес!  \nВ Божій правді просвітімся, \nВ Божій правді звеселімся, \nЩезла темряви неволя, \nЗавітала краща доля, \nБожа благодать з небес – \nХристос воскрес! Христос воскрес!', '', NULL, NULL),
(228, 'Христа Творця святих чудес', NULL, 'Куплет 1 \nХриста, Творця святих чудес, \nПрославте всі сердечним співом. \nРадійте всі, звершилось диво: \nХристос воскрес! Христос воскрес!\n\nКуплет 2.\nХвала, хвала, Христос воскрес!  \nЩасливо в грудях серце б''ється, \nТепер усюди пісня ллється: \nХристос воскрес! Христос воскрес!\n\nКуплет 3.\nПо всьому світі до небес  \nХвала Творцеві щиро ллється \nІ пісня радости несеться \nХристос воскрес! Христос воскрес!\n\nКуплет 4.\nО, Спасе любий, дорогий!  \nТобі і слава, і хваління, \nПодяка, честь і поклоніння \nНа віки вічнії! Амінь.', '', NULL, NULL),
(229, 'О який нам щасливий день Бог дарував', NULL, 'Куплет 1 \nО, який нам щасливий день Бог дарував, \nСпас Христос пута смерти порвав, \nЗруйнувавши Голгофською жертвою ад, \nСобі викупив вибраних чад.\n\nПрипев: \nВ Нім Однім, радість в Нім, \nВ Нім вічне життя \nІ любови уся повнота, повнота, \nВсі серця хай прославлять \nХриста, лиш Христа, \nВсі серця хай прославлять \nХриста, лиш Христа.\n\nКуплет 2.\nНаш Спаситель три дні у пітьмі був земній,  \nз неї виніс нам дар дорогий, \nЙого сяйво світліше світила в імлі, \nТо примирення неба й землі.\n\nКуплет 3.\nВоскресіння Його - оправдання для всіх,  \nВоскресінням знесилений гріх, \nВоскресіння Його - перемога над злом, \nХай звучить Йому слави псалом!\n\nКуплет 4.\nХай живе воскресіння Христове в серцях,  \nВиганяючи сумніви й страх! \nВін воскрес і навіки гріха морок щез, \nВін воістину в славі воскрес!', '', NULL, NULL),
(230, 'Зарожевів вже схід небес', NULL, 'Куплет 1 \nЗарожевів вже схід небес, \nХристос - Спаситель наш воскрес, \nГріха темряву розігнав, \nСпасіння всім подарував.\n\nКуплет 2.\nТілом у гробі Він лежав,  \nТретього дня воскрес і встав; \nСмерть не зламала там Його, \nЦаря царів, Творця всього.\n\nКуплет 3.\nСпасе, немає сил таких,  \nНа третій день з мертвих встав; \nТи і мене Собі придбав \nІ милість я Твою пізнав.\n\nКуплет 4.\nХристос воскрес, мене простив,  \nНавіки з Богом примирив, \nВ царство вічне приведе, \nВід зла у світі збереже.\n\nКуплет 5.\nТвою любов і благодать  \nМи будем, Спасе, прославлять \nІ тут, і там, на небесах, \nДовіку в радісних піснях.', '', NULL, NULL),
(231, 'В домовині немає Христа', NULL, 'Куплет 1 \nВ домовині немає Христа, \nв домовині Христос не лежить, \nБула воля Отцева свята \nзнов Його до життя воскресить.\n\nПрипев: \nНе шукай, не шукай, \nНе шукай там, де мертві лежать! \nНе шукай, не шукай, \nБог Христос наш із мертвих воскрес.\n\nКуплет 2.\nВ домовині Христа не шукай,  \nНе шукай там, де мертві лежать; \nБог у спадщину дав Йому рай, \nБог Святому не дав зотлівать.\n\nКуплет 3.\nВ домовині немає Христа,  \nЙому служать всі сили небес. \nБула воля Отцева свята, \nдо життя щоб від смерти воскрес.', '', NULL, NULL),
(232, 'Ідіть розкажіть любим учням Христа', NULL, 'Куплет 1 \nІдіть, розкажіть любим учням Христа: \nВоскрес Він із гробу, Його там нема. \nНебесний Учитель до них прийде знов,\nПоверне їм радість, поверне любов.\n\nПрипев: \nСкажіть, що Христос наш \nіз мертвих воскрес, \nСкажіть ви всім людям: \nСин Божий воскрес!\n\nКуплет 2.\nНесіть ви цю вістку скорботним серцям,  \nПотішити хоче Спаситель їх Сам;\nУсім, хто страждає і сльози хто ллє, \nНебесную радість Спаситель дає.\n\nКуплет 3.\nУсім засвідкуйте про ласку Христа,  \nБо Він відкупив нас і дав нам життя. \nВоскрес Він із мертвих, щоб нас оправдать \nІ славу безсмертя оправданим дать.\n\nКуплет 4.\nЗа грішників нас Божий Син постраждав,  \nСтражданням Своїм нам спасіння придбав, \nВоскрес і вознісся, і знову гряде, \nУ славу небесную нас приведе.', '', NULL, NULL),
(233, 'Живий Христос  лунає скрізь', NULL, 'Куплет 1 \n"Живий Христос!" - лунає скрізь, \nЗбудився сад від сну, не спить, \nДерева, квіти і пташки \nРадіють, тішаться в цю мить.\n\nПрипев: \nМіж мертвими Христа нема, \nЙого шукати там дарма. \nХристос воскрес, Він з мертвих встав, \nСвоєю смертю смерть назавжди подолав.\n\nКуплет 2.\n"Живий Христос! " - співає все,  \nІ гори, й вітер, і поля. \nНовину радісну несе, \nРадіє, тішиться земля.\n\nКуплет 3.\n"Христа у гробі вже нема!" –  \nжінкам це ангел сповістив, \nІ вістка всюди рознеслась, \nЩо Той, що вмер, таки ожив!', '', NULL, NULL),
(234, 'У сльозах покірно біля ніг Христа', NULL, 'Куплет 1 \nУ сльозах покірно біля ніг Христа \nСлухала Марія Божії слова, \nСерцем прагнула прийнять \nвід Ісуса благодать. \nЯ також бажаю честь віддать Йому, \nразом із святими принести хвалу.\n\nКуплет 2.\nТам Марія миро дороге лила,  \nЩиро для Ісуса в жертву віддала. \nЩирий дар Ісус прийняв \nі тяжкий гріх з неї зняв. \nБіля ніг Христових, як Його слуга, \nхочу утішатись радісно і я.\n\nКуплет 3.\nПершою Марія поспішила йти,  \nщоб Ісуса Тіло у гробі знайти; \nІ ось чудо із чудес: \nз мертвих вже Христос воскрес! \nЇй Христос воскреслий об''явився Сам \nі сказав: "Іди, скажи Моїм братам!"', '', NULL, NULL),
(235, 'Арфи золотаві в небесах звучать', NULL, 'Куплет 1 \nАрфи золотаві в небесах звучать, \nАнгели у славі Господа хвалять. \nТой, Хто для народів Ласка і Закон \nУрочисто сходить на небесний трон.\n\nПрипев: \nВсе Христом звершилось, \nВсім дає свій дар. \nДжерело в Нім сили, \nВін наш Бог і Цар.\n\nКуплет 2.\nЦе Господь, Цар слави, сильний в боротьбі.  \nСлавний, величавий, гідний похвали. \nВідкривайте брами, відкривайте всі, \nСлавними піснями свято сповістить!\n\nКуплет 3.\nНа горі Голгофі був розп''ятий там,  \nЖало смерти знищив, дав спасіння нам. \nПісля воскресіння в небо повернувсь, \nЗ гробового тління в славу зодягнувсь.', '', NULL, NULL),
(236, 'Радійте всі кого Христос  Спаситель', NULL, 'Куплет 1 \nРадійте всі, кого Христос - Спаситель, \nВ Своїй любові друзями назвав; \nХристос воскрес, Господь і Вседержитель \nСвоєю смертю вам життя придбав.\n\nКуплет 2.\nЯке звання високе і пошана  \nЧекає в небі кожного із нас! \nЗа кров святу, за смерть і за страждання, \nПридбав для нас те щастя любий Спас.\n\nКуплет 3.\nМи маєм Ким хвалитись і втішатись –  \nЛише Христом, лише Христом своїм; \nІ нашим радощам не обірватись \nНі на землі, ні в небі дорогім.\n\nКуплет 4.\nО, як приємно радість відчувати,  \nнам дарував Спасителя Отець; \nВ руках Його нам добре пробувати, \nНаш Пастир знає нас, Своїх овець.\n\nКуплет 5.\nСам Бог за нас! - Хто проти виступає?  \nІди, громадо невеличка, йди; \nтобі Бог царство в небі обіцяє, \nТуди, в життя блаженне увійди!', '', NULL, NULL),
(237, 'Любив Ісуса Йосиф щиро', NULL, 'Куплет 1 \nЛюбив Ісуса Йосиф щиро, \nЗ глибоким сумом зняв з хреста \nІ, полотном обвивши тіло, \nУ гробі положив Христа.\n\nКуплет 2.\nВорожі сили не змовкали,  \nБоялись, що Він може встать; \nВони негайно приказали \nДо гробу приложить печать.\n\nКуплет 3.\nЯк тільки почало світати,  \nЖінки до гробу вже спішать, \nІ ось два мужі в білих шатах \nВже там на камені сидять.\n\nКуплет 4.\nНебесні слуги в Божій силі  \nПлиту відкинули, і враз \nВорожу ту печать розбили, - \nХристос воскрес в той дивний час!\n\nКуплет 5.\nЖінки до гробу заглядають  \nІ бачать чудо із чудес; \nІ ангели у них питають: \n"Кого шукаєте - Воскрес!"\n\nКуплет 6.\nІ в радості жінки вертають,  \nЗвістить апостолам спішать, \nПро чудо їм оповідають: \n"Христос воскрес!" - благовістять.', '', NULL, NULL),
(238, 'Як сонце в небі засіяло', NULL, 'Куплет 1 \nЯк сонце в небі засіяло, \nХристос Спаситель наш воскрес! \nХвилина дивная настала, \nзвершилось чудо із чудес! \nХристос воскрес із мертвих!\n\nКуплет 2.\nХристос воскрес! Усім спасіння  \nВін воскресінням показав. \nХристос воскрес! Гріхів прощення \nй життя нам вічне дарував. \nХристос воскрес із мертвих!\n\nКуплет 3.\nВоскресла радісна надія,  \nу серці мир: Христос воскрес! \nІду до Тебе я з хвалінням,\nМій захист, Цар, Творець чудес! \nХристос воскрес із мертвих!', '', NULL, NULL),
(239, 'Втішайтеся Христос воскрес', NULL, 'Куплет 1 \nВтішайтеся, Христос воскрес! \nСпівайте всі Творцю чудес, \nНесіть хваління до небес! \nХристос воскрес! Христос воскрес!\n\nКуплет 2.\nБратайтеся, Христос воскрес!  \nНічний туман навіки щез.\nПроснися, грішний світе весь! \nХристос воскрес! Христос воскрес!\n\nКуплет 3.\nВітайтеся, Христос воскрес!  \nСпасіння дав нам Бог з небес; \nО, радість, щастя для сердець! \nХристос воскрес! Христос воскрес!\n\nКуплет 4.\nЄднайтеся, Христос воскрес!  \nЗвершилось чудо із чудес: \nНастав великий славний день! \nХристос воскрес! Христос воскрес!', '', NULL, NULL),
(240, 'Святий Бог дав нам Свого Сина', NULL, 'Куплет 1 \nСвятий Бог дав нам Свого Сина, \nВін на хресті за всіх помер; \nІ хоч лежав Він у могилі – \nПорожнє місце свідчить, \nЩо Ісус живе.\n\nПрипев: \nО, Він живе, я надію маю; \nО, Він живе, весь страх пройде; \nІ знаю я: Він любить; \nТепер живу для Нього, \nбо Ісус живе!\n\nКуплет 2.\nТак часто це життя сумнеє,  \nЗло нам спокою не дає, \nАле Ісус допомагає, \nТож будем жити вічно з Ним, \nбо Він живе.\n\nКуплет 3.\nІ прийде час: мій день скінчиться,  \nЖиттєва боротьба пройде; \nЗ Ісусом все я переможу,\nЙого побачу в небі. \nТак, Ісус живе!', '', NULL, NULL),
(241, 'Настав день воскресіння', NULL, 'Куплет 1 \nНастав день воскресіння, \nце свідчить вся земля; \nНадія на спасіння \nпосіяна в серцях. \nТо Пасхи день Господній \nчудовий нам настав: \nСпаситель наш сьогодні \nу славі з мертвих встав!\n\nКуплет 2.\nХристос обмив нас кров''ю,  \nщоб ми за Ним ішли \nІ, сповнені любов''ю, \nдля Нього лиш жили. \nЙого слова ласкаві \nми чуємо в серцях; \nХай пісню все співає: \nСпаситель наш живий!\n\nКуплет 3.\nХай небеса радіють  \nі з ними люди всі: \nХристос воскрес! – \nСпівають в гармонії краси.\nНехай хвала з''єднає \nусіх в акорд новий, \nХай пісню все співає: \nСпаситель наш живий!', '', NULL, NULL),
(242, 'О який нам шлях відкрився', NULL, 'Куплет 1 \nО, який нам шлях відкрився \nв Царство вічне увійти! \nБожий Син з небес з''явився,\nщоб нас всіх туди ввести. \nВ світі горя Він родився, \nполюбивши люд увесь, \nДо раба упокорився, \nбув розп''ятий і воскрес!\n\nКуплет 2.\nЛюдям Божий Син являвся  \nпісля Пасхи сорок днів, \nі Хома переконався, \nщо Ісус таки ожив. \nОбіцяв їм на прощання \nДух Святий з небес послать, \nЩоб ціну Христа страждання \nлюдським душам відкривать.\n\nКуплет 3.\nА в кінці зібрав на гору  \nвсіх апостолів Своїх, \nСтав невидимий для зору, \nВін вознісся з-поміж них.\n \nЗ неба ангели звістили: \nСпас вознісся у блакить, \nАле вдруге в славі й силі \nВін прийде цей світ судить.', '', NULL, NULL),
(243, 'Христос вийшов з учнями любими з храму', NULL, 'Куплет 1 \nХристос вийшов з учнями любими з храму \nІ сів на Оливній горі; \nСвятими устами, сумними словами \nЗажурених учнів учив.\n\nКуплет 2.\n"Скажи нам, Учителю, бажане слово  \nЩе поки Ти з нами живеш; \nСкажи нам, Учителю, що тоді буде, \nКоли Ти судити світ прийдеш?"\n\nКуплет 3.\n"У світі почуєте слухи воєнні,  \nПовстане народ на народ, \nІ будуть недуги, і голод, і помір, \nкров братня і безліч скорбот.\n\nКуплет 4.\nІ зменшиться віра, погасне надія,  \nВ серцях охолоне любов; \nБагато зневіряться й видадуть ближніх, \nПроллють неповинную кров.\n\nКуплет 5.\nКоли запустіння побачите в храмі,  \nТо знайте, що суд при дверях; \nПильнуйте, щоб двері для вас не закрились, \nПоправте світильники в серцях.\n\nКуплет 6.\nВеликеє горе охопить всю землю  \nІ муки нестерпні прийдуть; \nТоді скажуть люди: "Впадіть на нас, гори!" – \nТа гори на них не впадуть.\n\nКуплет 7.\nІ сонце померкне, не дасть місяць світла,  \nІ зорі із неба впадуть, \nІ мертві воскреснуть, і всякі народи \nПрийдуть на Господній той суд.\n\nКуплет 8.\nЗ небес прийде в славі Син Божий на землю,  \nВін буде, як сонце сіять; \nТоді грішні люди підуть в вічні муки, \nА праведні з Богом царювать".', '', NULL, NULL),
(244, 'З неба Спаситель прийде ще раз', NULL, 'Куплет 1 \nЗ неба Спаситель прийде ще раз; \nчи ждеш Його в цей час? \nАле чи в вірі знайде Він нас, \nякби прийшов в цей час? \nЦеркву Свою Він забере \nі в вічну славу приведе, \nНас в мить одну усіх збере; \nчи ждеш Його в цей час?\n\nПрипев: \nСлава, слава! - Радість Він нам несе. \nСлава, слава! - Як Цар Царів прийде. \nСлава, слава! - Церкву Свою візьме. \nСлава, слава! - З неба Господь прийде.\n\nКуплет 2.\nЗло і неправду Він знищить Сам;  \nдав би те Бог в цей час! \nГоря й нещастя не буде там, \nДав би те Бог в цей час! \nВірних Христос всіх воскресить, \nВони у небі будуть жить, \nІ у славі вічній будуть всі; \nчи ждеш Його в цей час?\n\nКуплет 3.\nВірними Богу хай нас знайде,  \nякщо в цей час прийде.\nГотових в небо Він забере, \nякщо в цей час прийде. \nЗемля тремтить, шумлять моря; \nна небі вже горить зоря, \nПильнуй і жди з небес Царя: \nчи ждеш Його в цей час?', '', NULL, NULL),
(245, 'З небес Своїх у славі Господь прийде', NULL, 'Куплет 1 \nЗ небес Своїх у славі Господь прийде; \nХай пильними в молитві нас Він знайде. \nСвітильники хай сяють у нас в руках, \nЛюбов свята палає в наших серцях.\n\nПрипев: \nНове життя засяє в вічній красі, \nІ в славі освітиться Його святій.\n\nКуплет 2.\nЗабудемо всі кривди, Господь прийде;  \nНастане царство правди, Господь прийде; \nТам зникне сум, зітхання, Господь прийде; \nНе буде сліз, страждання, Господь прийде.\n\nКуплет 3.\nВін знає, як стомились в дорозі ми,  \nЯк часто ми зітхали і хрест несли. \nСкорботи наші зніме, коли прийде, \nУ славу нас Він прийме, Господь прийде.', '', NULL, NULL),
(246, 'Може зустрінемось ранком', NULL, 'Куплет 1 \nМоже, зустрінемось ранком; \nМоже, в південний час: \nАбо вночі, чи світанком \nПрийде наш любий Спас.\n\nКуплет 2.\nЗ радістю будем чекати,  \nСвято жить на землі. \nБудем завжди пильнувати, \nАж поки прийде Спас.\n\nКуплет 3.\nДрузі, пильнуймо ми ранком,  \nТакож в південний час, \nВвечері і на світанку, \nАж поки прийде Спас.\n\nКуплет 4.\nЩо за щаслива та зустріч  \nБуде з Христом для нас, \nЯк з неба в славі могутній \nПрийде нас взяти Спас!', '', NULL, NULL),
(247, 'В час коли труба Господня', NULL, 'Куплет 1 \nВ час, коли труба Господня \nнад землею прозвучить, \nІ, як вічного дня ранок засія, \nІмена усіх спасенних \nСам Ісус оголосить – \nТам, по милості Господній, буду я.\n\nПрипев: \nНа небесній перекличці, \nНа небесній перекличці, \nТам по милості Господній, буду я.\n\nКуплет 2.\nВ день блаженний воскресіння  \nвсіх померлих у Христі, \nВ день, коли введе спасенних в небеса, \nВсіх святих, обмитих кров''ю, \nщо пролита на хресті, \nВін покличе і тоді відкликнусь я.\n\nКуплет 3.\nБоже, сил дай працювати  \nі для ближніх послужить, \nЗ ранку раннього і до заходу дня; \nА коли земну нам працю \nТи дозволиш закінчить, \nТо на поклик Твій небесний стану я.', '', NULL, NULL),
(248, 'Сказав Господь Бог до Ноя', NULL, 'Куплет 1 \nСказав Господь Бог до Ноя: \n"Затоплю Я світ водою \nв близький час.\n\nКуплет 2.\nТи збудуй собі ковчега  \nДля родини і для себе, \nЩоб спастись."\n\nКуплет 3.\nНой повірив, не вагався,  \nБудувать ковчега взявся \nВ той же час.\n\nКуплет 4.\nЛюди з Ноя насміхались,  \nПравди слів не прислухались; \nГрішний люд.\n\nКуплет 5.\nПотоп хлинув, як те море,  \nЛюди бігли всі на гори, \nТам спастись.\n\nКуплет 6.\nВоди землю заливали,  \nТоді люди вже благали: \n"Де спастись?"\n\nКуплет 7.\nВсі на себе нарікали,  \nЧому правди не приймали? – \nГнів прийшов.\n\nКуплет 8.\nПтахи в небі ще літали  \nІ рятунку скрізь шукали – \nНе знайшли.\n\nКуплет 9.\nВоди землю всю покрили,  \nВсіх безбожних потопили – \nБожий суд.\n\nКуплет 10.\nЛише плавав за вітрами  \nКовчег з Ноєм і синами \nВ хвилях тих.\n\nКуплет 11.\nЯк ковчег став на вершині –  \nЗ Ноєм вийшла вся родина, \nВсі спаслись.\n\nКуплет 12.\nІ тепер не менше горя,  \nБо безбожним гірка доля \nЗнов прийде.', '', NULL, NULL),
(249, 'Я вірю прийде судний день', NULL, 'Куплет 1 \nЯ вірю: прийде судний день, \nТоді зблідніють з жаху люди, \nЗамовкне хор гучних пісень, \nІ скрізь скорботно, страшно буде.\n\nКуплет 2.\nТемрява чорна землю вкриє, \nПогасне сонце, згаснуть зорі, \nЗаграють сумно води моря \nІ вітер в темряві завиє.\n\nКуплет 3.\nВеликий жах на світ повіє,  \nЗаграють ангели у сурми \nІ тихо встануть усі люди, \nВсе замовкне раптом, заніміє.\n\nКуплет 4.\nЯ вірю, прийде судний день,  \nІ гірко плакатимуть люди; \nЗамовкне хор гучних пісень \nІ скорботно й страшно, страшно буде.', '', NULL, NULL),
(250, 'Як прийде Господь у славі –', NULL, 'Куплет 1 \nЯк прийде Господь у славі – \nЧи готовий будеш ти? \nДосі ходиш у темряві \nІ живеш у марноті.\nДосі ходиш у темряві \nІ живеш у марноті.\n\nКуплет 2.\nПодивися на Голгофу,  \nТяжко там Ісус страждав; \nТо й за тебе, милий друже, \nЩоб і ти спасіння мав.\nТо й за тебе, милий друже, \nЩоб і ти спасіння мав.\n\nКуплет 3.\nО, нещасний, ти не знаєш:  \nСкоро вже Господь прийде; \nВін і праведних, і грішних \nНеодмінно всіх знайде.\nВін і праведних, і грішних \nНеодмінно всіх знайде.\n\nКуплет 4.\nВін розгорне вічну Книгу,  \nПерегляне її Сам, \nІ довідається з неї: \nЧи записаний ти там?\nІ довідається з неї: \nЧи записаний ти там?\n\nКуплет 5.\nКоли будеш Йому вірний –  \nПрийме з радістю тебе, \nА як будеш непокірний – \nВін у Царство не прийме.\nА як будеш непокірний – \nВін у Царство не прийме.\n\nКуплет 6.\nСкаже: "Йдіть в вогонь страждати!" –  \nТам не буде каяття; \nВічно будеш там ридати, \nПроклинать своє життя.\nВічно будеш там ридати, \nПроклинать своє життя.', '', NULL, NULL),
(251, 'Я знаю що ХристосСпаситель', NULL, 'Куплет 1 \nЯ знаю, що Христос-Спаситель \nЗа мене на хресті страждав, \nЖиття відкрив для мене вічне, \nДитям Своїм мене назвав.\n\nПрипев: \nНіщо у світі цім мене \nВже від Христа не відійме. \nЖиття відкрив для мене вічне, \nДитям Своїм мене назвав.\n\nКуплет 2.\nПостійно я Його чекаю,  \nКоли за мною Він прийде, \nТоді візьме мене до Себе, \nУ дім небесний приведе.\n\nКуплет 3.\nТому всім серцем довіряюсь,  \nХто на хресті вмер за мене, \nдо Його зову прислухаюсь: \n"Скоріш прийди! Прийму тебе".\n\nКуплет 4.\nЙого любов все подолала,  \nВін так за мене постраждав \nІ кров пролив Свою невинну, - \nЖиття мені Він смертю дав.\n\nКуплет 5.\nСпаситель мій прийде вже скоро  \nІ Сам мене туди введе, \nде в Царстві правди, Царстві Божім \nМоя душа спокій знайде.', '', NULL, NULL),
(252, 'Ми ждемо Христа Спаса як прийде', NULL, 'Куплет 1 \nМи ждемо Христа Спаса, як прийде, \nМи ждемо Христа Спаса, як прийде,\nМи ждемо Христа Спаса, бо Він приготував нам \nТам вічне щастя у Царстві Своїм.\n\nКуплет 2.\nЗустрінемо Ісуса, як прийде,  \nЗустрінемо Ісуса, як прийде, \nЗустрінемо Ісуса, коли прийде у славі \nІ в небо нас візьме, як обіцяв.\n\nКуплет 3.\nПобачать Його в славі, як прийде,  \nПобачать Його в славі, як прийде, \nПобачать Його всі в славі і ті, хто розп''яли, \nІ перед Ним заплаче цілий світ.\n\nКуплет 4.\nО, друже, що ти скажеш, як прийде?  \nО, друже, що ти скажеш, як прийде? \nКоли Господь спитає: "Що вчинив з талантом, \nЧи ще один надбав, чи закопав?"\n\nКуплет 5.\nЗаплачеш тоді гірко, як прийде;  \nЗаплачеш тоді гірко, як прийде, \nТоді тобі нічого, мій друже, не поможе, - \nТаку ти долю сам собі обрав.', '', NULL, NULL),
(253, 'Так той день вже близько', NULL, 'Куплет 1 \nТак, той день вже близько, \nДень страшний, великий, \nКоли всі народи стануть перед судом.\n\nКуплет 1.\nБраття і сестри розлучаться,  \nБраття і сестри розлучаться,\nБраття і сестри розлучаться, \nНавіки, назавжди.\n\nКуплет 2.\nЖони з мужами розлучаться,  \nЖони з мужами розлучаться, \nЖони з мужами розлучаться,\nНавіки, назавжди.\n\nКуплет 3.\nДіти з батьками розлучаться,  \nДіти з батьками розлучаться, \nДіти з батьками розлучаться, \nНавіки, назавжди.\n\nКуплет 4.\nПастирі з стадом розлучаться,  \nПастирі з стадом розлучаться, \nПастирі з стадом розлучаться, \nНавіки, назавжди.\n\nКуплет 5.\nЩо тут посіяв, те там пожнеш, \nЩо тут посіяв, те там пожнеш, \nЩо тут посіяв, те там пожнеш, \nНавіки, назавжди.', '', NULL, NULL),
(254, 'О як би ти це знав', NULL, 'Куплет 1 \nО, як би ти це знав \nхоч в цей останній день, \nЩо ти за світло дня \nПрийняв лиш тільки тінь.\n\nПрипев: \nКоли б же ти пізнав \nхоч в цей останній день, \nХто може дать тобі спокій, \nХто може дать тобі спокій.\n\nКуплет 2.\nО, як би ти це знав,  \nщо шлях, яким ти йдеш, \nВеде в безодню - й там \nти пекла не минеш!\n\nКуплет 3.\nО, як би ти не знав,  \nХто повний дивних слів,\nтебе До Себе закликав! \nПрийти ж ти не хотів.\n\nКуплет 4.\nО, як би ти не знав,  \nХто про тебе скорбить, \nЩо ти у гріх упав, - \nне хочеш в правді жить.\n\nКуплет 5.\nО, як би ти пізнав,  \nХто полюбив тебе, \nХто за тебе віддав \nна смертний хрест Себе!\n\nКуплет 6.\nО, як би ти пізнав  \nХриста-Царя душі! \nУ Ньому Бог сія \nдля тебе і для всіх.\n\nКуплет 7.\nО, як би ти пізнав,  \nщо Всемогутній Він, \nЗ молитвою б ти впав \nй смирився перед Ним.', '', NULL, NULL),
(255, 'В день коли сурма Господня поскликає всіх святих', NULL, 'Куплет 1 \nВ день, коли сурма Господня поскликає всіх святих \nНад прозорою рікою, як кришталь, \nНа весільную вечерю забере Христос Своїх, \nО, яка чудова зустріч буде там!\n\nПрипев: \nО, яка ж то зустріч буде, як зберуться святі люди. \nВічну волю сурма Божа звістить нам, \nІ зустрінемо ми близьких, що пройшли шляхом тернистим. \nО, яка чудова зустріч буде там!\n\nКуплет 2.\nСповістить Господній Ангел нам зійти на висоту  \nІ підхоплені ми будем в небеса. \nПереповнить серце радість, як побачим ту красу. \nО, яка чудова зустріч буде там!\n\nКуплет 3.\nТам під звуки гуслів дивних, арф небесних золотих,  \nПереможний спів прийде на серце нам. \nПісня Агнця й Мойсея об''єднає всіх святих. \nО, яка чудова зустріч буде там!', '', NULL, NULL),
(256, 'Милий друже що буде', NULL, 'Куплет 1 \nМилий друже, що буде, \nколи наш Господь прийде \nІ байдужим Він знайде тебе; \nТи дочасне лиш кохав,\nа про вічне забував, \nЩо ж то буде, як Господь прийде.\nТи дочасне лиш кохав,\nа про вічне забував, \nЩо ж то буде, як Господь прийде.\n\nПрипев: \nЩо ж то буде, як Господь прийде? \nЩо ж то буде, як Господь прийде? \nМилий друже, що буде, \nяк Христос скоро прийде, \nІ байдужим Він знайде тебе.\n\nКуплет 2.\nТи про ближніх знаєш все,  \nале про гріхи свої, \nПро своє серденько ти не дбав. \nХто спіткнувся, хто упав, \nхто що думав, що казав, \nА не бачив, що вже сам упав.\nХто спіткнувся, хто упав, \nхто що думав, що казав, \nА не бачив, що вже сам упав.\n\nКуплет 3.\nТи судити любиш всіх,  \nколи знайдеш в кому гріх, \nА не хочеш засудить себе;\nВсіх ти знаєш, хто який: \nну, а сам ти хто такий, - \nО, пильніше, друже, подивись.\n\nКуплет 4.\nБог є праведний Суддя, \nБог є Правда і Життя, \nІ Він буде грішників судить;\nМилий друже, що буде, \nяк Христос скоро прийде, \nІ байдужим Він знайде тебе.', '', NULL, NULL),
(257, 'Небо ясне вже темніє', NULL, 'Куплет 1 \nНебо ясне вже темніє, \nсмерти вічна ніч іде: \nМоже, скоро Вседержитель \nпо твоє життя прийде.\n\nКуплет 2.\nІ тоді ти пригадаєш,  \nщо у Біблії читав; \nТоді гірко заридаєш, \nщо Христа ти не прийняв.\n\nКуплет 3.\nАле ні, вже буде пізно,  \nтам не зможеш ти придбать, \nДар, що в цім житті відкинув, \nдивну Божу благодать.\n\nКуплет 4.\nКнига Божа там відкрита,  \nперевірка всім іде; \nХто не вписаний у Книзі – \nв Царство Боже не ввійде.\n\nКуплет 5.\nДруже, стомлений гріхами,  \nу неправді не ходи, \nА почувши з неба голос, \nдо Христа скоріше йди!', '', NULL, NULL),
(258, 'Вже чую я море немов би шумить', NULL, 'Куплет 1 \nВже чую я: море немов би шумить, \nІ міниться сонце й згасає; \nОхоплений жахом світ стогне, тремтить – \nГосподній вже день наступає.\n\nПрипев: \nПрийди, мій Ісусе, прийди, дорогий, \nЯ хочу вже бути з Тобою! \nМене у крові убілив Ти Своїй, \nКупив дорогою ціною.\n\nКуплет 2.\nПроходять з гудінням страшним небеса.  \nНастала неждана хвилина; \nГотуйтесь, готуйтесь! Ось слава й краса \nВідкриється Божого Сина.\n\nКуплет 3.\nЗабудь, друже, світ та його марноту.  \nГосподній ось день наступає. \nВіддайся й будь вірний до смерти Христу, \nІ будеш в небесному краї.', '', NULL, NULL),
(259, 'Чи буде заграва ранкова світати', NULL, 'Куплет 1 \nЧи буде заграва ранкова світати, \nЧи яснеє сонце почне вже сідати – \nСпаситель із неба прийде в вічній славі \nУзяти з землі Своїх.\n\nПрипев: \nО, коли, Спасе наш, \nТобі ми співать будем гімн: \nОсь іде Він! Алилуя! \nАлилуя! Амінь. Алилуя! Амінь.\n\nКуплет 2.\nЧи буде опівдні, чи то опівночі –  \nРаптово побачать Його наші очі; \nПрийде наш Спаситель, осяяний світлом, \nУзяти з землі Своїх.\n\nКуплет 3.\nІ ангельські сили з Ним будуть сіяти,  \nВсі вірні Його будуть там зустрічати, \nІ співи хваління поллються для Нього, \nХто взяв із землі Своїх.\n\nКуплет 4.\nО, радість туди перейти без страждання,  \nБез болю, тривоги, недуги й зітхання; \nУ славу Господню на небо піднятись, \nКуди Він візьме Своїх.', '', NULL, NULL),
(260, 'Вічнавіч з Христом Ісусом', NULL, 'Куплет 1 \nВіч-на-віч з Христом Ісусом \nя зустрінусь в небесах, \nЯк іти Він буде в славі \nпри пошані і піснях.\n\nПрипев: \nВіч-на-віч з Христом Ісусом \nя зустрінусь в небесах, \nЯк Він з''явиться у славі \nз нагородами в руках.\n\nКуплет 2.\nЗараз тільки через віру  \nуявляю я Христа, \nА тоді Його побачу \nвіч-на-віч у небесах.\n\nКуплет 3.\nВічно тішитися буду  \nв славі Господа царя, \nБо все горе й зло забуду \nпо той бік ріки життя.\n\nКуплет 4.\nБуду бачити Ісуса,  \nяк Його зустріну там, \nДе одвічне "Алилуя!" \nбуде в вірних на устах.', '', NULL, NULL),
(261, 'Коли Спасителю прийдеш', NULL, 'Куплет 1 \nКоли, Спасителю, прийдеш \nсвятую церкву взяти? \nТут на землі так тяжко їй \nборотись і страждати. \nКоли назустріч їй прийдеш? \nКоли у вічний край ввійдеш? \nПрийди скоріш, о, Боже!\nПрийди скоріш, о, Боже!\n\nКуплет 2.\nУсюди чуємо ми глум  \nВід грішних над Тобою; \nУ нас в серцях і жаль, і сум – \nскрізь ллється гріх рікою. \nПрийди і перед світом знов \nяви і славу, і любов, \nПрийди скоріш, о, Боже! \nПрийди скоріш, о, Боже!\n\nКуплет 3.\nДай сили нам, щоб ми завжди  \nсіяли в цьому світі, \nІ поміж грішнимим людьми \nбули, як Божі діти. \nНіхто із нас щоб не дрімав, \nвогонь любови щоб палав, \nПрийди скоріш, о, Боже! \nПрийди скоріш, о, Боже!\n\nКуплет 4.\nПрийди, Спасителю, скоріш,  \nТебе ми вже чекаєм, \nКоли величний образ Твій \nу небесах засяє. \nНаш погляд в чистих небесах, \nбажання лиш одне в серцях: \nПрийди скоріш, о, Боже! \nПрийди скоріш, о, Боже!', '', NULL, NULL),
(262, 'О Боже Твій вогонь священний', NULL, 'Куплет 1 \nО, Боже, Твій вогонь священний, \nТвій вогонь, Твій вогонь нам пошли! \nТебе благаємо смиренно: \nТвій вогонь, Твій вогонь нам пошли! \nМоління наших душ прийми, \nСвятим нас Духом просвіти \nі благодаттю осіни, \nТвій вогонь, Твій вогонь нам пошли!\n\nКуплет 2.\nО, Господи, Тебе благаєм:  \nТвій вогонь, Твій вогонь нам пошли! \nТобі служити ми бажаєм, \nТвій вогонь, Твій вогонь нам пошли! \nСвітильник віри хай горить, \nжиттям святим бажаєм жить, \nГріховне все нехай згорить, \nТвій вогонь, Твій вогонь нам пошли!\n\nКуплет 3.\nУсім холодним і байдужим  \nТвій вогонь, Твій вогонь нам пошли! \nЛюбов''ю щоб палали душі \nТвій вогонь, Твій вогонь нам пошли! \nУ Тебе ласку щоб знайти, \nвсю силу зла перемогти, \nПрожити свято й відійти Твій вогонь,\nТвій вогонь нам пошли!\n\nКуплет 4.\nСлужіння з радістю звершати  \nТвій вогонь, Твій вогонь нам пошли! \nІ грішних від гріхів звільняти \nТвій вогонь, Твій вогонь нам пошли! \nНа вівтар Твій кладем себе, \nвсе наше сильне і слабе, \nБажаєм славить лиш Тебе, \nТвій вогонь, Твій вогонь нам пошли!', '', NULL, NULL),
(263, 'Усюди сповістіть', NULL, 'Куплет 1 \nУсюди сповістіть, \nвсім людям розкажіть, \nДе тільки є душа, \nне знаюча Христа. \nСпасені всі, ідіть \nновину цю несіть, \nЩо Дух Святий прийшов.\n\nПрипев: \nО, Дух Святий прийшов, \nО, Дух Святий прийшов, \nУтішитель з небес, \nщо обіцяв Отець. \nУсюди сповістіть, \nвсім людям розкажіть, \nЩо Дух Святий прийшов.\n\nКуплет 2.\nДуховна ніч пройшла,  \nсвята зоря зійшла, \nМіняється життя \nу селах і в містах; \nНарод лишає гріх \nі йде до Божих ніг, \nБо Дух Святий прийшов.\n\nКуплет 3.\nЛюбови глибина  \nоб''явлена для нас \nВ розп''ятому Христі, \nу правді й чистоті. \nТворцеві честь, хвала \nза всі Його діла, \nЗа Духа дар Святий!', '', NULL, NULL),
(264, 'Боже вічний і святий', NULL, 'Куплет 1 \nБоже вічний і святий, \nСам Ти Духа благодать \nНа дітей Твоїх пролий \nі до неба всіх провадь! \nНам приємно в кожну мить \nчути поклик Твій до нас: \n"Подорожні, всі прийдіть, \nповеду додому вас!"\n\nКуплет 2.\nУ Святому Дусі Ти  \nз нами будь на цій землі; \nТи нам можеш помогти \nвідшукати шлях в імлі.\nЯк зустрінем буревій, \nрозжени наш страх в той час,\nДай почути голос Твій: \n"Доведу додому вас!"\n\nКуплет 3.\nЯк пройде земне життя,  \nТи покличеш нас усіх; \nХай нам вічного буття \nне заплямить жоден гріх. \nБоже, просимо Тебе: \nу блаженний, славний час \nДай почути слово це: \n"Я привів додому вас!"', '', NULL, NULL),
(265, 'З нами Бог хто буде проти нас', NULL, 'Куплет 1 \nЗ нами Бог, хто буде проти нас? \nЗ нами Бог, хто буде проти нас? \nЗ нами Бог, хто буде проти нас? \nТак Павло-апостол нам сказав.\n\nКуплет 2.\nОсь, Я з вами буду кожен день;  \nОсь, Я з вами буду кожен день, \nОсь, Я з вами буду кожен день; \nТак Господь Спаситель обіцяв.\n\nКуплет 3.\nКров Христа змиває всякий гріх,  \nКров Христа змиває всякий гріх, \nКров Христа змиває всякий гріх; \nТак Іван-апостол запевняв.\n\nКуплет 4.\nДар Святого Духа Бог нам дав;  \nДар Святого Духа Бог нам дав; \nДар Святого Духа Бог нам дав; \nІоіль-пророк так написав.', '', NULL, NULL),
(266, 'Господь блаженство вклав і Духа дав Свого', NULL, 'Куплет 1 \nГосподь блаженство вклав і Духа дав Свого, \nКоли Йому віддав себе я усього. \nНа мене ласку злив, дав радість і спокій \nЙ любови запалив вогонь в душі моїй.\n\nПрипев: \nГорить в душі моїй,вогонь горить ясний; \nВогонь Його любови у душі моїй, \nКоли з небес зійшов до серця Дух Святий, \nГорить вогонь любови у душі моїй.\n\nКуплет 2.\nТоді Тобі віддав я все життя своє;  \nНа Твій святий вівтар, за те, що спас мене. \nІ добрий Божий Син прийняв той дар за Свій, \nЙ на жертву з неба Він вогонь послав святий.\n\nКуплет 3.\nНе за мої діла Господь це так зробив:  \nЙому лише хвала, бо Він мене любив. \nТож славлю я Його за ласку та любов, \nЩо Спаса я мого тоді в Ньому знайшов.', '', NULL, NULL),
(267, 'З неба Дух Святий до нас прийшов', NULL, 'Куплет 1 \nЗ неба Дух Святий до нас прийшов \nСповістить про святу любов, \nГрішників до Бога закликать, \nЦеркву будувать.\n\nПрипев: \nСлава, слава Богу і хвала, \nДухом творить Він святі діла; \nСильний, нас від зла Він захистить, \nНавчає свято жить, \nСлава, слава Богу і хвала за святі діла.\n\nКуплет 2.\nДух Святий нам свідчить про Христа,  \nЯк лилась Його кров свята. \nІ дає бажання нам в серця \nСлавити Творця.\n\nКуплет 3.\nДух Святий зміцняє в вірі нас  \nІ свідкує, що в славний час \nБудемо з хвалінням на вустах \nЗустрічать Христа.', '', NULL, NULL),
(268, 'Дізнавсь я про Церкву живую', NULL, 'Куплет 1 \nДізнавсь я про Церкву живую, \nВ ній радість для серця знайшов, \nНікуди вже більш не піду я, \nПрийнявши Христову любов.\n\nПрипев: \nО, друже, йди в Церкву живую, \nІ радість, і мир там знайдеш. \nПовір і віддайся Ісусу,\nУ вічне блаженство ввійдеш.\n\nКуплет 2.\nЧи знаєте Церкву живую,  \nВи браття і сестри мої? \nІдіть на дорогу святую \nДо Церкви живої усі.\n\nКуплет 3.\nО, скільки в ній душ без спокою  \nЗнайшли собі мир і спокій! \nТам ллються молитви рікою, \nЖиве в ній Христос дорогий.\n\nКуплет 4.\nХодив я усюди по світу  \nІ щастя ніде не знайшов. \nЗакінчився шлях безпросвітний, \nКоли я у Церкву ввійшов.', '', NULL, NULL),
(269, 'Тій дивній вістці твердо вірю я', NULL, 'Куплет 1 \nТій дивній вістці твердо вірю я, \nЩо в стражданнях за мене вмер Ісус; \nЗ Ним нині помер я для гріха, \nІ в знак того по вірі я хрищусь.\n\nПрипев: \nВмер я для гріха, жить щоб для Христа: \nЩоб в душі сіяв Ісуса образ, \nЩоб Дух Святий був Порадник мій!\n\nКуплет 2.\nЛилась там на хресті невинна кров,  \nЩо з душі змила гріх, мене спасла; \nВсе, все довершила та любов. \nПо милості Своїй життя дала.\n\nКуплет 3.\nНаслідувати хочу я Христа  \nІ завжди по Його слідах ходить, \nЩоб славить Ісусове ім''я; \nДля Нього я віднині хочу жить!', '', NULL, NULL),
(270, 'Люблю Твій Боже дім', NULL, 'Куплет 1 \nЛюблю Твій, Боже, дім, \nтам повнота Твоя; \nБажаю завжди бути в Нім, \nбо там любов Твоя.\n\nКуплет 2.\nЛюблю, Відвічний Бог,  \nя Церкву - храм живий; \nЇї боронить Дух Святий \nвід горя і тривог.\n\nКуплет 3.\nЗа Церкву я молю,  \nза всіх Твоїх дітей. \nЛюблю я Церкву із людей, \nулюблену Твою.\n\nКуплет 4.\nЯ радий би, брати,  \nдовіку бути в ній, \nЩоб помогти в порі сумній \nхреста її нести.\n\nКуплет 5.\nЯ знаю, що разом  \nдо Господа ми йдем; \nЯ вірю, вірю, що будем \nспівать перед Христом.', '', NULL, NULL),
(271, 'О дивний день чудовий час', NULL, 'Куплет 1 \nО, дивний день, чудовий час, \nКоли Спаситель мене Спас, \nЗі мною в заповіт вступив, \nСпокоєм серце наділив.\n\nПрипев: \nДивний день, дивний день, \nКоли Господь гріхи простив! \nТепер зі мною Сам Ісус, \nВін захищає від спокус. \nДивний день, дивний день, \nКоли Господь гріхи простив!\n\nКуплет 2.\nО, дивний день, коли наш Спас  \nЗнайшов мене в долині сліз; \nТепер Він Пастир добрий мій, \nЯ вже Його, я вже не свій.\n\nКуплет 3.\nО, дивний день, коли життя  \nМоє воскресло у Христі, \nКоли мої всі почуття \nВін Духом обновив Святим.\n\nКуплет 4.\nО, дивний день, коли пізнав  \nДушею я любов Христа, \nІ в серце Господа прийняв, \nЩасливий став на все життя.', '', NULL, NULL),
(272, 'Амінь Всі ті', NULL, 'Куплет 1 \nАмінь! Всі ті, \nщо в Христа христилися, \nУ Христа зодягнулися. \nАлилуя!', '', NULL, NULL),
(273, 'Хто хто всі ці та звідкіля прийшли', NULL, 'Куплет 1 \nХто, хто всі ці та звідкіля прийшли? \nБілу одежу де собі взяли? \nЗ їхніх уст лунає спів, \nАгнець їх кров''ю обмив.\n\nПрипев: \nАгнець нас привів у небесний вічний дім, \nКров''ю Своєю обмив, обмив; \nБудем жити вічно в небесній славі з Ним, \nАгнець нас кров''ю обмив.\n\nКуплет 2.\nЦе ті, кого Христос Собі зібрав,  \nЦе ті, за кого в муках Він вмирав, \nВін їх спас і оправдав, \nАгнець їх кров''ю обмив.\n\nКуплет 3.\nВсі, всі вони за Господом пішли,  \nЧерез велике горе перейшли, \nТа в Ісусі мир знайшли, \nАгнець їх кров''ю обмив.\n\nКуплет 4.\nШляхом тернистим їх пройшло життя,  \nЇх до мети вела рука свята, \nТо була рука Христа, \nАгнець їх кров''ю обмив.\n\nКуплет 5.\nВсіх тих, хто вірно з Господом пішов,  \nОхороняла Спасова любов; \nКожен славу вже знайшов, \nАгнець їх кров''ю обмив.\n\nКуплет 6.\nВ вічному царстві радісно живуть,  \nГоря не знають, сліз уже не ллють,\nСпів новий Христу несуть, \nАгнець їх кров''ю обмив.', '', NULL, NULL),
(274, 'Ми руки покладаєм', NULL, 'Куплет 1 \nМи руки покладаєм \nна обранця Твого, \nТебе ми всі благаєм: \nБлагослови його, \nблагослови його; \nНе в рукопокладанні \nє сила Божих слуг, - \nВ Твоїм благословінні, \nЩо підкріпляє дух, \nщо підкріпляє дух.\n\nКуплет 2.\nПрийди, як Гість чудовий,  \nСам руку поклади; \nУ праці повсякчасно \nЙому допоможи, \nйому допоможи. \nПошли йому в служінні \nвідраду і успіх, \nЩоб прикладом покори \nВін послужив для всіх, \nвін послужив для всіх.\n\nКуплет 3.\nНа нього покладаєм  \nми наш тягар нести; \nІ щиро всі благаєм, - \nТи Сам його зміцни, \nТи сам його зміцни. \nІ ми бажаєм спільно \nтягар той з ним нести, \nІ в єдності й любові \nТи нам допоможи, \nТи нам допоможи.', '', NULL, NULL),
(275, 'Ось Боже ми обрали', NULL, 'Куплет 1 \nОсь, Боже, ми обрали \nслужителя Твого, \nТебе ми всі благали \nй Ти показав його.\n\nКуплет 2.\nБлагослови в служінні  \nТи вибранця Свого, \nДаруй йому терпіння, \nуспіх в труді Його.\n\nКуплет 3.\nДаруй для нього, Боже,  \nТи мудрости згори, \nЩоб всі долав спокуси \nі вірним був завжди.\n\nКуплет 4.\nЩоб був взірцем старанним  \nпоміж Твоїх дітей, \nЩоб словом і ділами \nсвітив він для людей.', '', NULL, NULL),
(276, 'Хай люди всі слугу Христа', NULL, 'Куплет 1 \nХай люди всі слугу Христа \nзавжди в тобі знайдуть. \nЗа прикладом твого життя \nдо Господа прийдуть.\n\nКуплет 2.\nУсі в побожності прийдім  \nдо Господа Творця, \nВін Духом лагідним, святим \nНаповнить нам серця.', '', NULL, NULL),
(277, 'Відкриття молитовного дому', NULL, 'Куплет 1 \nВідкриття молитовного дому \nхай освятить сьогодні Бог Сам, \nЩоб Христова тут церква у Ньому \nвсе зростала в духовний теж храм. \nХай євангельську правду Господню \nсповіщають в нім слуги Христа; \nХай тут завжди, ось так, як сьогодні,\nвиявляється віра свята.\n\nКуплет 2.\nХай знайдуть в цьому домі спасіння  \nвсі ті душі, що блудять в гріхах \nІ щоб правди святої насіння \nрозсівалося в людських серцях. \nХай молитви святим фіміамом \nтут з відкуплених ллються сердець \nДо небесного Божого храму, \nде у славі царює Творець.\n\nКуплет 3.\nХай бринить в цьому домі хваління  \nвсе нових та духовних псалмів; \nЗа дароване Богом спасіння, \nхай подяки підноситься спів. \nХай же дім цей навіки посвятить \nСам Отець, Син і Дух Твій Святий \nХай духовно Бог церкву збагатить, \nщоб і дім, і народ був святий.', '', NULL, NULL),
(278, 'О Боже ми так радо всі', NULL, 'Куплет 1 \nО, Боже, ми так радо всі \nЦей дім присвячуєм Тобі; \nХай завжди вся Твоя сім''я \nТут Славить лиш Твоє Ім''я.\n\nКуплет 2.\nХай в ньому проповідь свята  \nЗвучить із Біблії до всіх; \nІ хай приходять до Христа \nВсі ті, кого долає гріх.\n\nКуплет 3.\nНе це лиш місце, а й нас,  \nНерукотворний Божий храм, \nБлагословляй Ти кожен час, \nДоки прийдем до вічних брам.\n\nКуплет 4.\nЩоб у серцях Ти пробував,  \nІ Дух Святий всіх нас навчав, \nЩоб кожен завжди відчував \nТвою присутність, силу, вплив.', '', NULL, NULL),
(279, 'Боже великий єдиний Нашу Вкраїну храни', NULL, 'Куплет 1 \nБоже, великий, єдиний! Нашу Вкраїну храни, \nВолі і світу промінням Ти її осіни \nСвітлом науки і знання Ти її просвіти; \nВ чистій любові до краю Ти нас, Боже, зміцни!\n\nКуплет 2.\nМолимось, Боже єдиний, Нашу Вкраїну храни.  \nВсі свої ласки, щедроти Ти на люд наш зверни! \nДай йому волю, дай йому долю, Дай доброго світу. \nЩастя дай, Боже, народу На многая, многая літа!', '', NULL, NULL),
(280, 'Вірую В Єдиного Бога', NULL, 'Куплет 1 \nВірую! В Єдиного Бога \nОтця, Всемогутнього;\n\nКуплет 2.\nТворця неба і землі,  \nвсього видимого і невидимого;\n\nКуплет 3.\nВ Єдиного Господа  \nІсуса Христа, Сина Божого;\n\nКуплет 4.\nЄдинородного, від Отця народженого,  \nНесотворенного, перше всіх віків;\n\nКуплет 5.\nСвітло від Світла,  \nБога істиного від Бога істиного;\n\nКуплет 6.\nНародженого, несотворенного,  \nодноістот-ного з Отцем, \nЩо через Нього все сталося;\n\nКуплет 7.\nВін для нас, людей  \nі для нашого спасіння з неба зійшов; \nІ тіло прийняв від Духа Святого, \nВід Діви Марії і стався людиною;\n\nКуплет 8.\nРозп''ятий був за нас при Понтії Пилаті,  \nстраждав, помер був похований, \nІ в третій день воскрес, як було написано;\n\nКуплет 9.\nІ вознісся на небо  \nі сидить праворуч Отця \nІ знов прийде у славі судить живих і мертвих, \nЙого же Царству не буде кінця;\n\nКуплет 10.\nІ в Духа Святого,  \nГоспода оживляючого, \nЩо від Отця походить; \nЙому з Отцем і Сином \nоднаковий поклін і однакова слава, \nВін говорив через пророків;\n\nКуплет 11.\nВ Єдиную, Соборную,  \nАпостольськую Церкву;\n\nКуплет 12.\nВизначаю одне хрищення  \nі відпущення гріхів;\n\nКуплет 13.\nЧекаю воскресіння мертвих  \nі життя будучого віку! Амінь.', '', NULL, NULL),
(281, 'Єднає Бог вас у Христі', NULL, 'Куплет 1 \nЄднає Бог вас у Христі, \nце воля є свята, \nЦе воля є свята, \nі ви в майбутньому житті\n\nПрипев: \nПрославте, прославте, \nпрославте, прославте, \nпрославте Господа!\n\nКуплет 2.\nХай в домі вашому царить  \nі згода й тишина, \nі згода й тишина, \nяк християни, в кожну мить', '', NULL, NULL),
(282, 'З Божої ласки ось двоє людей', NULL, 'Куплет 1 \nЗ Божої ласки ось двоє людей \nСтали й бажають, щоб Ти, як дітей, \nБлагословив їх. О, Боже, з''єднай! \nЩастя в родиннім житті їм подай!\n\nПрипев: \nО, поклади, Боже, руку на них, \nВірно триматись доріг дай Твоїх, \nМи, Боже, їх доручаєм Тобі, \nБудь з ними завжди в достатку, в нужді!\n\nКуплет 2.\nРазом життєвий вони шлях пройдуть,  \nБлизько Ти, Боже, до них завжди будь, \nЩоб одружившись, ще краще в сім''ї \nЩиро служили щоденно Тобі.\n\nКуплет 3.\nБоже, даруй, щоб ці юні серця  \nВірні в подружжі були до кінця, \nВ радості, в горі, у праці, в біді \nХай завжди будуть думки в них одні.', '', NULL, NULL),
(283, 'Христос Господь у Галилеї', NULL, 'Куплет 1 \nХристос, Господь, у Галилеї \nу Кану Ти на шлюб ходив, \nСвятою силою Своєю \nТам перше чудо сотворив.\n\nПрипев: \nО, Господи, до нас прийди \nІ славу Свою яви, \nО, Господи, до нас прийди \nі нас благослови.\n\nКуплет 2.\nПрийди до нас, як Гість небесний,  \nІ Сам цей шлюб благослови, \nСкріпи союз любові й честі, \nВ житті щоб вірність зберегли.\n\nКуплет 3.\nСоюз подружжя підкріпляєш  \nВ живій Ти Церкві як Жених, \nНа шлюбі вірних пробуваєш \nПоміж відкуплених Твоїх.\n\nКуплет 4.\nТи кличеш всіх на свято славне,  \nБлагаєм ми, щоб і вони \nЖили для Тебе чесно, вірно, \nВ Твоїй любові усі дні.', '', NULL, NULL),
(284, 'Прийди Ісусе о Боже милий', NULL, 'Куплет 1 \nПрийди, Ісусе, о, Боже милий, \nДітей Своїх благослови. \nНаповни, Боже, любов''ю й миром \nУсе життя їх назавжди.\n\nПрипев: \nБажаєм щастя, лиш тільки щастя, \nХай вас Господь благословить!\n\nКуплет 2.\nЖиви в сімейному їх союзі  \nТи з ними, Отче дорогий; \nна молоде це, нове подружжя \nПролий безмірно Дух Святий.', '', NULL, NULL),
(285, 'Дві руки зєднались нині', NULL, 'Куплет 1 \nДві руки з''єднались нині \nперед Господом святим, \nЩоб у цій земній країні \nразом в радості іти. \nДві руки з''єднались міцно\nдля життя й надій живих; \nТвою руку, Боже вічний, \nпоклади тепер на них.\n\nКуплет 2.\nДвоє уст тепер сказали  \nперед Богом "Так!" святе, \nЖити вірно обіцяли \nдалі все життя своє. \nБоже наш, Тебе благаєм: \nдай їм світла, хай сія; \nІ для щастя їх з''єднає \nХай свята рука Твоя.', '', NULL, NULL),
(286, 'Ось Боже стали дві душі', NULL, 'Куплет 1 \nОсь, Боже, стали дві душі \nз єдиним почуттям, \nНедобре їм у самоті \nщоденного життя.\n\nПрипев: \nО, Боже наш, благослови \nТи душі ці і в них живи, \nПрийми від них Ти молитви, \nу всьому їх благослови!\n\nКуплет 2.\nОдному тяжко в світі жить,  \nзмовкає часто спів, \nА на шляху життя лежить \nвсе більше труднощів.\n\nКуплет 3.\nОдне одного хай вони  \nпідтримують завжди, \nА Ти до неба висоти \nїх, Боже, доведи!', '', NULL, NULL),
(287, 'Дай Боже їм щастя в житті помагай', NULL, 'Куплет 1 \nДай, Боже, їм щастя, в житті помагай, \nВід зла, від нещастя, Ти Сам захищай!\n\nКуплет 2.\nЖиття хай з Тобою вони проживуть  \nІ світло любови всім ближнім несуть.\n\nКуплет 3.\nХай міцно з''єднає їх щира любов,  \nВ час горя втішає серця їхні знов.\n\nКуплет 4.\nДай, Боже, їм мудрість, щоб вірні були  \nДаруй Твою тихість, щоб свято жили.\n\nКуплет 5.\nДай їм пізнавати, що з ними Твій Дух;  \nПовік пам''ятати, що Ти вірний Друг!', '', NULL, NULL),
(288, 'Дай Боже їм щастя в житті помагай', NULL, 'Куплет 1 \nДай, Боже, їм щастя, в житті помагай! \nНа многії літа, на многії літа, на многії літа, \nНа многії літа, на многії літа, на многії літа. \nМногі вам літа, многі вам літа, многі вам літа, \nМногі вам літа, многі вам літа, многі вам літа.\n\nКуплет 2.\nХай міцно з''єднає їх щира любов!  \nНа многії літа, на многії літа, на многії літа, \nНа многії літа, на многії літа, на многії літа. \nМногі вам літа, многі вам літа, многі вам літа, \nМногі вам літа, многі вам літа, многі вам літа.\n\nКуплет 3.\nДай, Боже, їм мудрість, щоб вірні були.  \nНа многії літа, на многії літа, на многії літа, \nНа многії літа, на многії літа, на многії літа.\nМногі вам літа, многі вам літа, многі вам літа, \nМногі вам літа, многі вам літа, многі вам літа.\n\nКуплет 4.\nДай їм пізнавати, що з ними Твій Дух.  \nНа многії літа, на многії літа, на многії літа, \nНа многії літа, на многії літа, на многії літа. \nМногі вам літа, многі вам літа, многі вам літа, \nМногі вам літа, многі вам літа, многі вам літа.', '', NULL, NULL),
(289, 'Браття радійте сестри співайте друзі вітайте', NULL, 'Куплет 1 \nБраття, радійте, сестри, співайте, друзі, вітайте! \nОсь перед нами, ось перед нами спокій і згода. \nСпокій і згода тут поєднались - всі їх вітайте!\nСпокій і згода тут поєднались - всі їх вітайте!\n\nКуплет 2.\nБраття, радійте, сестри, вітайте, всі заспівайте:  \n"Боже великий, ось Твої діти - дай же їм щастя! \nМногії літа, многії літа, дай Твоє щастя!\nМногії літа, многії літа, дай Твоє щастя!', '', NULL, NULL),
(290, 'Многая літа', NULL, 'Куплет 1 \nМногая літа, \nмногая літа, \nМногая літа, \nмногая літа.', '', NULL, NULL),
(291, 'Де згода в сімействі там мир і тишина', NULL, 'Куплет 1 \nДе згода в сімействі, там мир і тишина, \nЩасливі там люди, блаженна сторона. \nЇх Бог благословляє, добро їм посилає, \nІ з ними Він живе і щастя їм дає.\n\nКуплет 2.\nДе згоди немає, там мир не царить,  \nТам Бог не витає, добра їм не дарить. \nРуйнуються пожитки: добро їх, їхні дітки, \nВсе марно пропаде, все марно пропаде.\n\nКуплет 3.\nПошли нам, Боже, згоду і мира Твій покров,  \nІ радість в Господі, і щиру дай любов. \nДай росу щастя, долі і жити в Твоїй волі, \nТи нас благослови Ти нас благослови!', '', NULL, NULL),
(292, 'Бажаю я щоб весь мій дім', NULL, 'Куплет 1 \nБажаю я, щоб весь мій дім, \nТобі, о, Господи, служив;\nТи ж сили дай, щоб в домі цім \nя сам побожно й свято жив.\n\nКуплет 2.\nДопоможи в ділах моїх  \nслужити прикладом для них, \nЗ якими я повинен жить, \nяких повинен я любить.\n\nКуплет 3.\nЄдині мрії маю я,  \nщоб я і вся моя сім''я \nСтворили в душах наших храм \nТвоїм Божественним словам.\n\nКуплет 4.\nТобі я щиро віддаю  \nсебе і всю мою сім''ю; \nПочуй о, Господи, молю, \nі ласку прояви Свою.', '', NULL, NULL),
(293, 'Де Божий Дух в серцях живе', NULL, 'Куплет 1 \nДе Божий Дух в серцях живе, \nтам щастя, там любов, \nНе тільки близьких обійме, \nа також ворогів.\n\nПрипев: \nТвою любов, Господь, пошли, \nЛюбов''ю їх Ти освіти. \nНавчи любить ім''я Твоє \nі прославляти лиш Тебе.\n\nКуплет 2.\nДе Божая любов горить,  \nтам єдність, там спокій, \nТам вірних Бог не залишить, \nВін Пастир дорогий.\n\nКуплет 3.\nДе у любові всі святій,  \nв громаді, чи в рідні, \nТам всім керує Бог живий, \nщасливі там усі.', '', NULL, NULL),
(294, 'Вчуй мене мій милий Боже', NULL, 'Куплет 1 \nВчуй мене, мій милий Боже, \nІ на сон благослови. \nІ у сні будь біля мене, \nІ до ранку стережи. \nСтережи, стережи \nІ до ранку стережи.\n\nКуплет 2.\nЦілий день мене беріг Ти,  \nОдягав і годував. \nЩиро дякую Тобі я \nЗа дари ті, що Ти дав. \nЩо Ти дав, що Ти дав.\nЗа дари ті, що ти дав.\n\nКуплет 3.\nВибачай мої злі вчинки  \nІ на сон благослови. \nЗавтра вранці знов до праці. \nСпасе, Ти мене збуди. \nТи мене, Ти мене, \nСпасе, Ти мене збуди.', '', NULL, NULL),
(295, 'На світанку чи пізньої ночі', NULL, 'Куплет 1 \n"На світанку чи пізньої ночі, \nДе б тобі не прийшлося бувати, \nДо висот підіймай свої очі" – \nГоворила мені моя мати.\n\nПрипев: \n"Не забудь помолитися Богу, \nБо в молитві надія і сила; \nСтане легшою всяка дорога, \nТи з молитвою будеш щасливий."\n\nКуплет 2.\nЦі слова мені в серце запали,  \nЯк весною добірні зернята, \nІ рясні їх дощі поливали, \nБо ж за мене молилася мати.\n\nКуплет 3.\nВ ніжнім смутку твоїм голубинім  \nЯ твою доброту відчуваю, \nТвоє слово, неначе перлина, \nМов би зіронька в небі, що сяє.\n\nКуплет 4.\nСрібло скроні мої покриває,  \nВже і сонце на захід схилилось, \nАле слово твоє пам''ятаю: \n"Сину мій, не забудь помолитись."', '', NULL, NULL),
(296, 'День минає уже наступає ніч', NULL, 'Куплет 1 \nДень минає уже, наступає ніч, \nПокриває пітьма кожну земну річ. \nВже на небі вгорі миготять зірки, \nТихим сном міцно сплять квіти і пташки.\nВже на небі вгорі миготять зірки, \nТихим сном міцно сплять квіти і пташки.\n\nКуплет 2.\nІ людей втомлених переміг вже сон,  \nСтане ангел нехай біля їх вікон. \nНехай з''явиться він нашим діточкам. \nСторожем хай буде всім мандрівникам.\nНехай з''явиться він нашим діточкам. \nСторожем хай буде всім мандрівникам.\n\nКуплет 3.\nВсяку біль в ту нічку, Боже, усмири;  \nІ до вчинку лихого не допусти. \nБоже наш, наглядай над народом всім, \nМир святий і спокій Ти пошли в наш дім.\nБоже наш, наглядай над народом всім, \nМир святий і спокій Ти пошли в наш дім.\n\nКуплет 4.\nЗавтра вранці Ти нас, Боже, пробуди  \nІ до добрих лише вчинків нас веди. \nЩоб ми й завтра могли день почати свій, \nБоже, слава Тобі, Трійці пресвятій!\nЩоб ми й завтра могли день почати свій, \nБоже, слава Тобі, Трійці пресвятій!', '', NULL, NULL),
(297, 'Боже Отче ми до Тебе', NULL, 'Куплет 1 \nБоже, Отче, ми до Тебе \nз вірою йдемо, \nЦю сімейную потребу \nРазом несемо.\n\nПрипев: \nБоже, Боже, ось мале дитя. \nУ Свої візьми Ти руки \nВсе його життя!\n\nКуплет 2.\nЦю, ні в чим не винну душу,  \nБоже, стережи. \nІ від зла, гріха й спокуси \nВ світі збережи!\n\nКуплет 3.\nТак, як Анна Самуїла,  \nЦе дитя батьки \nУ любові захотіли \nпринести Тобі.', '', NULL, NULL),
(298, 'Небесний Отче Всеблагий', NULL, 'Куплет 1 \nНебесний Отче Всеблагий, \nЛаскавий та святий, \nНа наших діточок пролий \nпотоки доброти.\n\nПрипев:\nПролий, пролий потоки доброти, \nПролий, пролий, бо добрий, Боже, Ти.\n\nКуплет 2.\nДо Тебе, любий Боже наш,  \nприносимо ми їх. \nБажаєм їм на всякий час \nблагословінь Твоїх.\n\nКуплет 3.\nНавчи їх слухать голос Твій,  \nнастав на добру путь. \nО, Боже, Боже пресвятий, \nСам з ними завжди будь.\n\nКуплет 4.\nКоли ж від вихору життя  \nвтомляться вони – \nБлагаєм: з ласкою Отця \nїм руки простягни.', '', NULL, NULL),
(299, 'Пташок маленьких любить Бог', NULL, 'Куплет 1 \nПташок маленьких любить Бог, \nїм їжу подає; \nЯкщо пташок Він любить так – \nВін любить і мене.\n\nПрипев: \nТак любить Він, так любить Він; \nЯ знаю: любить Він; \nмаленьких діток любить Він, \nВін любить і мене!\n\nКуплет 2.\nБог любить лілії в полях,  \nде річенька тече; \nЯкщо Він любить квіточки – \nВін любить і мене.\n\nКуплет 3.\nЯкщо пташкам і квіточкам  \nГосподь життя дає – \nВін не забуде діточок, \nВін любить і мене.', '', NULL, NULL),
(300, 'Слава на Сіонігорі –', NULL, 'Куплет 1 \n"Слава на Сіоні-горі!" – \nХор дітей співав тоді, \nЯк в''їзджав у місто Спас,\nЗаспіваймо в цей час.\n\nПрипев: \nТи і я - співаймо для Христа. \nТи і я - співаймо для Христа. \nО, Осанна! Величай Царя царів.\n\nКуплет 2.\nСлів Христових вчили нас,  \nДуха втіхи дав нам Спас. \nМи до неба маєм шлях, \nБог живе у нас в серцях.\n\nКуплет 3.\nСтарші і молоді разом  \nЗаспіваймо всі псалом. \nХай наш спів до хмар злетить, \nВ небесах загомонить.', '', NULL, NULL),
(301, 'З неба Спас у славі', NULL, 'Куплет 1 \nЗ неба Спас у славі \nдивиться на світ \nЙ діточкам ласкавий \nзавжди шле привіт.\n\nКуплет 2.\nМи малі і можем  \nманівцем піти, \nПо небесній стежці, \nСпасе, нас веди.\n\nКуплет 3.\nНам в усіх потребах  \nпоміччю Ти будь \nЙ правдою до неба \nнам освітлюй путь.\n\nКуплет 4.\nМи тобі співаєм,  \nСпасе дорогий, \nМи Тебе благаєм, \nБоже наш Святий.\n\nКуплет 5.\nЯк на квіти роси,  \nласку Ти пролий, \nМи Тебе всі просим, \nСпасе дорогий.\n\nКуплет 6.\nЩоб ми виростали  \nБожими дітьми, \nЙ Тебе шанували \nскрізь поміж людьми.', '', NULL, NULL),
(302, 'Закликає Спас діток', NULL, 'Куплет 1 \nЗакликає Спас діток, \nКличе їх до Себе всіх; \nВін збирає їх в гурток \nяк ягняток дорогих.\n\nПрипев: \nСпас кличе діточок, \nКличе Він, кличе Він; \nУ райський Свій садок \nКличе Божий Син.\n\nКуплет 2.\nМолоді свої серця  \nЗберігайте в чистоті; \nНепорочні хай вуста \nпрославляють лиш Христа.\n\nКуплет 3.\nДітки, всі до одного,  \nзаклик слухайте Його; \nТо Спаситель кличе вас, \nпоспішайте в той же час!', '', NULL, NULL),
(303, 'Вічний радісний край для малих є дітей', NULL, 'Куплет 1 \nВічний, радісний край для малих є дітей, \nСам Спаситель зібрав їх туди, \nТам чудові струмочки живої води \nОсвіжають спасенних людей.\n\nКуплет 2.\nДітки чують там радісний ангельський спів,  \nЩо лунає на славу Христу! \nРазом пісню співають вони цю святу: \n"Сам Христос нас у царство привів!"\n\nКуплет 3.\nВ край небесний Спаситель дітей всіх зібрав,  \nХлібом неба годує їх всіх; \nВін в раю посеред всіх дітей є Своїх, \nДля них щастя навік Він придбав.\n\nКуплет 4.\nДітки в славі Господній зібралися всі,  \nВеселяться у райськім саду, \nВіддають там Творцеві і честь, і хвалу \nУ небесній, чудовій красі.', '', NULL, NULL),
(304, 'Я шукаю мого Спаса', NULL, 'Куплет 1 \nЯ шукаю мого Спаса \nз моїх ранніх літ життя, \nХочу в Нього я учитись, \nмати світле майбуття.\n\nПрипев: \nЛюбить Він мене. Він любить, \nзнаю, любить Він мене: \nНа хресті умер за мене, \nзнаю, любить Він мене.\n\nКуплет 2.\nЯ піду, куди Він скаже,  \nхоч дитя я ще мале; \nПо земній вузькій дорозі \nмене Спас мій проведе.\n\nКуплет 3.\nВін дарує всім спасіння,  \nхоче дати і мені, \nЯ візьму його з благанням, \nбуду в небі вічні дні.', '', NULL, NULL),
(305, 'Пригадаймо браття й сестри', NULL, 'Куплет 1 \nПригадаймо, браття й сестри, \nті минулії часи, \nЯк збирались на вечерю \nу любові вірні всі.\nЯк збирались на вечерю \nу любові вірні всі.\n\nКуплет 2.\nНе щоб тілу догоджати,  \nчас проводили вони, \nА, щоб Бога прославляти \nу любові й від душі.\nА, щоб Бога прославляти \nу любові й від душі.\n\nКуплет 3.\nЗа столом псалми хваління  \nщиро линули з сердець \nЗа дароване спасіння, \nщо у Сині дав Отець.\nЗа дароване спасіння, \nщо у Сині дав Отець.\n\nКуплет 4.\nУ той час любов Христову  \nвідчували вірні всі; \nЦеркви Божої будова \nвиростала у красі.\nЦеркви Божої будова \nвиростала у красі.\n\nКуплет 5.\nІ тепер ми знов зійшлися  \nза братерським цим столом, \nНаші співи знов злилися \nу божественний псалом.\nНаші співи знов злилися \nу божественний псалом.\n\nКуплет 6.\n"О, Спасителю, благаєм,  \nбудь Ти з нами й нас веди; \nДух Святий хай нас навчає \nу любові жить завжди!\nДух Святий хай нас навчає \nу любові жить завжди!"', '', NULL, NULL),
(306, 'Утіху небесну для всіх сердець', NULL, 'Куплет 1 \nУтіху небесну для всіх сердець \nНам послав Отець, нам послав Отець; \nДля радости нині зібрав Він нас, \nЧесть Йому за славний час!\n\nПрипев: \nВсім привіт, всім привіт, \nБраттям, сестрам дорогим!\nБог відкрив світлий край, \nБудем всі радіти в Нім!\n\nКуплет 2.\nДе двоє, чи троє в Його Ім''я,  \nІсус буде там, Ісус буде там; \nВін хоче, щоб вічний наш з Ним союз \nВ благодаті все зростав.\n\nКуплет 3.\nУтіхи цієї не знає світ,  \nщо Господь нам дав, що Господь нам дав; \nМолитись ми будем, щоб Він, Святий, \nВічну радість нам послав.', '', NULL, NULL),
(307, 'Дорогії хвилини Господь нам послав', NULL, 'Куплет 1 \nДорогії хвилини Господь нам послав, \nЛюбі браття і сестри в Христі, \nСам Господь з нами є, як у Слові сказав, \nХай ллється з сердець Йому спів.\nСам Господь з нами є, як у Слові сказав, \nХай ллється з сердець Йому спів.\n\nКуплет 2.\nНам приємно зустріти й побачити вас,  \nА страждання й земну суєту, - \nВсе забути в єднанні святому В цей час, \nі радість відчути святу.\nВсе забути в єднанні святому В цей час, \nі радість відчути святу.\n\nКуплет 3.\nТісно, міцно з''єднаймось навколо Христа,  \nОчі в небо ясне піднесем; \nВ молитвах, в Слові Божім, з любов''ю в серцях \nЗа Господом сміло підем.\nВ молитвах, в Слові Божім, з любов''ю в серцях \nЗа Господом сміло підем.\n\nКуплет 4.\nДо побачення тут, чи в небеснім краю,  \nДо побачення, сестри й брати! \nЦього дня не забудем, - а вічно в раю \nми будем разом завжди.\nЦього дня не забудем, - а вічно в раю \nми будем разом завжди.', '', NULL, NULL),
(308, 'Місце є дороге де бажаю бути ще', NULL, 'Куплет 1 \nМісце є дороге, де бажаю бути ще \nТам з моїми братами в селі; \nДе в неділю ходив, щиро Господу служив \nТам у Церкві з братами в селі.\n\nПрипев: \nОй, як радують думки, \nЯк згадаю ті роки; \nХочеться ще раз мені \nБути в Церкві з братами в селі.\n\nКуплет 2.\nХоч я був молодий, але радий був тоді,  \nЯк молився в тій Церкві в селі, \nМій Спаситель тоді по любові лиш Своїй \nСпас мене там в тій Церкві в селі.\n\nКуплет 3.\nО, якби в наші дні так молились усі,  \nЯк молились колись у селі; \nСпішіть серце відкрить, а Господь благословить, \nЯк бувало колись у селі.', '', NULL, NULL),
(309, 'Блажен союз в Христі', NULL, 'Куплет 1 \nБлажен союз в Христі, \nєднає він серця; \nВ любові Спасовій святій \nми всі одна сім''я.\n\nКуплет 2.\nВ молитвах до Отця  \nприходимо ми всі; \nЗ Христом єдині до кінця \nу прагненнях своїх.\n\nКуплет 3.\nТурботи й тягарі  \nв нас тепер одні, \nЩоб нам єднання берегти \nв любові назавжди.\n\nКуплет 4.\nТяжка розлука нам,  \nта вірим ми, що знов \nЗустрінемось чи тут, чи там, \nде вічний Бог-Любов!\nПРОЩАЛЬНІ', '', NULL, NULL),
(310, 'Бог з тобою до побачення', NULL, 'Куплет 1 \nБог з тобою, до побачення! \nХай твій шлях охороняє, \nНа все добре научає, \nБог з тобою, до побачення!\n\nПрипев: \nДоки ми побачимось, \nпобачимось у ніг Христа; \nДоки ми побачимось \nБог з тобою, до побачення!\n\nКуплет 2.\nБог з тобою, до побачення!  \nСили хай Він укріпляє, \nМанну з неба посилає, \nБог з тобою, до побачення!\n\nКуплет 3.\nБог з тобою, до побачення!  \nЗахистить від зла земного, \nЗнай Його лише Самого, \nБог з тобою, до побачення!\n\nКуплет 4.\nБог з тобою, до побачення!  \nДобрим прикладом будь всюди, \nХай побачать світло люди, \nБог з тобою, до побачення!', '', NULL, NULL),
(311, 'Розлуки час настав для нас', NULL, 'Куплет 1 \nРозлуки час настав для нас, \nІ в час цього призначення \nМи кажем: "До побачення, \nПрощай, щасливо, до побачення!"\n\nКуплет 2.\nСвоїх людей Господь веде,  \nЗавжди рукою сильною \nІ ласкою безмірною, \nПрощай, щасливо, до побачення!\n\nКуплет 3.\nОсь чути клич, слова Христа:  \n"Вже скоро, скоро Я прийду, \nДо неба вірних приведу!" \nПрощай, щасливо, до побачення!\n\nКуплет 4.\nДруже, відкинь зневіри страх!  \nЯкщо ж у цей нелегкий час \nМи бачимось останній раз – \nТоді побачення на небесах!', '', NULL, NULL),
(312, 'Прощайте браття у Христі нам рідні', NULL, 'Куплет 1 \nПрощайте, браття, у Христі нам рідні, \nМоже, ми з вами вже останній раз! \nІ ви прощайте, сестри дорогії, \nМоже, вам більше не бачити нас!\nІ ви прощайте, сестри дорогії, \nМоже, вам більше не бачити нас!\n\nКуплет 2.\nХвилини щастя ми з вами прожили,  \nРазом трудились в той веселий час. \nІ ви прощайте, сестри дорогії, \nМоже, вам більше не бачити нас!\nІ ви прощайте, сестри дорогії, \nМоже, вам більше не бачити нас!\n\nКуплет 3.\nБлизькі і друзі наші всі, прощайте,  \nходіть слідами Ісуса Христа. \nІ нас в молитвах ваших пам''ятайте, \nЗгадка навіки буде хай свята.', '', NULL, NULL),
(313, 'Летить зникає час невпинно', NULL, 'Куплет 1 \nЛетить, зникає час невпинно, \nПройшли вже тисячі років; \nІ так рік нинішній пролине \nслідами зниклих вже родів.\n\nКуплет 2.\nТак в вічність день за днем проходить,  \nне залишаючи слідів; \nЖиття, неначе з вітром сходить, \nпройдуть і наші дні земні.\n\nКуплет 3.\nА наші всі земні діяння,  \nтурботи, праця й марнота \nМигнуть у світі без вертання, \nподібно мрії, що пройшла.\n\nКуплет 4.\nЗа щастям гнався ти роками,  \nвоно ж втікало в далечінь; \nТи жив тут мріями та снами, \nта все минуло, наче тінь.\n\nКуплет 5.\nДля чого ж ти у світ з''явився  \nі переніс тяжке життя? \nЧи лиш для того ти родився, \nщоб долю мати без Христа?\n\nКуплет 6.\nЗа гробом, знай, життя існує,  \nзакінчить вічність наші дні.\nЩо буде, друже, там з тобою? – \nПро це подумав ти, чи ні?', '', NULL, NULL),
(314, 'Як швидко й непомітно дні', NULL, 'Куплет 1 \nЯк швидко й непомітно дні \nжиття людського йдуть, \nЩе не скінчилися одні – \nвже інші настають!\n\nПрипев: \nРік за роком, день за днем \nдо кінця турбот ми йдем. \nОсь останній прийде час, \nі Христос покличе нас.\n\nКуплет 2.\nХто щиро Господа любив  \nі пробував у Нім, \nУ правді перед Ним ходив – \nввійде у вічний дім.\n\nКуплет 3.\nКоли для мене теж прийде  \nостанній час буття, \nГосподь відкрив мені, що жде \nтам вічнеє життя!\n\nКуплет 4.\nВсім серцем вірю, вірю я,  \nщо поклик той Христа \nПочує і душа моя, \nбо я Його слуга.\n\nКуплет 5.\nКоли земний лишити край  \nприйде для мене час, \nО, Боже мій, то пригадай \nтого, кого Ти спас!', '', NULL, NULL),
(315, 'Вже небагато нам', NULL, 'Куплет 1 \nВже небагато нам \nлишилось путі пройти, \nПрийдем до Христа і вже там \nне будем тягар нести.\n\nКуплет 2.\nПоки велить Спас нам  \nІ поки ще сильні ми – \nпрацюймо! З Голгофи вже нам \nне тяжко тягар нести.\n\nКуплет 3.\nВже небагато днів  \nтрудитись лишилось нам; \nУ Царство Христа ми ввійдем, \nу славі ми будем там.', '', NULL, NULL),
(316, 'Боже вічний всемогутній', NULL, 'Куплет 1 \nБоже вічний, всемогутній, \nВсесвіт у Твоїх руках; \nСвітом нашим Ти керуєш \nі зірками в небесах.\n\nПрипев: \nНам незнаний рік майбутній, \nАле все в руках Твоїх; \nПоможи нам, Всемогутній, \nжить з Тобою кожну мить.\n\nКуплет 2.\nТисячі років у Тебе,  \nмов та мить, мов день один. \nТи - володар землі й неба, \nвічності, років, годин.\n\nКуплет 3.\nНаші дні перед Тобою,  \nначе спалахи зірниць. \nДай, щоб вірою святою \nдля Тебе їх прожить.\n\nКуплет 4.\nРік цей, Боже, перед нами,  \nале що він принесе? \nТож, Твоїми хай слідами \nнас рука Твоя веде!', '', NULL, NULL),
(317, 'Сьогодні рік минає', NULL, 'Куплет 1 \nСьогодні рік минає: \nось настає новий. \nТа завжди пробуває \nтут з нами Бог святий; \nВін рік увесь минулий \nусім допомагав, \nБудив серця заснулі, \nбезсилим силу дав.\n\nКуплет 2.\nВсе на землі минає,  \nі слава, і краса; \nЩо швидко так зникають, \nмов ранішня роса. \nА небо відкриває \nлише любов Христа, \nНа нові дні з''єднаєм \nми наше з Ним життя.\n\nКуплет 3.\nВізьми ж нас, милий Боже,  \nВеди в майбутніх днях, \nЗ Тобою переможем \nспокуси, гріх і страх. \nТвою пошли нам силу, \nщоб плід ми принесли,\nДні наші рахували, \nі мудро тут жили.', '', NULL, NULL),
(318, 'Як швидко наші дні пливуть', NULL, 'Куплет 1 \nЯк швидко наші дні пливуть, \nяк тінь вони минають. \nЗ собою нас вони несуть, \nназад вже не вертають.\n\nКуплет 2.\nУ Бога Книга наших дій, -  \nВін наші всі блукання, \nІ наші сльози пише в ній, \nі горе, і страждання.\n\nКуплет 3.\nКоли закінчимо цей шлях  \nдо вічної оселі, \nТоді спочинем в небесах, \nвід горя і недолі.\n\nКуплет 4.\nО, Боже, дай новий нам рік  \nз Тобою розпочати, \nАби днів мудрий перелік \nй розумне серце мати.\n\nКуплет 5.\nНе допусти в дорозі цій  \nнас до спокуси, згуби, \nЛише тримай в руці Твоїй \nдо смерти, Спасе любий!', '', NULL, NULL),
(319, 'Потішайте малодушних', NULL, 'Куплет 1 \nПотішайте малодушних, \nпоки час ще не пройшов, \nСвітлом будьте душам скрушним \nпоки час ще не пройшов, \nЛюдям радість понесіть, \nщо знайшли ми у Христі, \nЩоб спасіння всяк знайшов, \nпоки час ще не пройшов!\n\nПрипев: \nКожен день, кожен день,\nКожен день, кожен день, \nПонесем добро у світ, \nпоки час ще не пройшов!\n\nКуплет 2.\nМарнота хай нас не вабить  \nпоки час ще не пройшов, \nБрат завжди хай з братом ладить, \nпоки час ще не пройшов, \nВ світі стільки сліз і зла, \nдоброти чомусь нема: \nШвидше б ти до Бога йшов, \nпоки час ще не пройшов.\n\nКуплет 3.\nРозірви гріха кайдани,  \nпоки час ще не пройшов, \nЗнай: Христом спасіння дане, \nпоки час ще не пройшов, \nВсе що сієм повсякчас, \nпроросте у певний час. \nЩоб спасіння злак зійшов, \nпоки час ще не пройшов.', '', NULL, NULL),
(320, 'Тут і там поля безкраї', NULL, 'Куплет 1 \nТут і там поля безкраї, \nначе їм нема кінця; \nТак багаті урожаєм \nждуть старанного женця.\n\nПрипев: \nВишли Боже, вишли скоро \nвсіх старанних на поля \nУрожай збирати в пору, \nпоки осінь не прийшла.\n\nКуплет 2.\nШли женців з ранковим часом  \nі обідньої пори; \nШли й надвечір, хай всі разом \nпідберуть полів дари.\n\nКуплет 3.\nБоже, дай з людського поля  \nзняти славний урожай; \nЩоб Твоя здійснилась воля, \nнас усіх благословляй!', '', NULL, NULL),
(321, 'Боже дякуємо ми', NULL, 'Куплет 1 \nБоже, дякуємо ми; \nТи ж подяку цю прийми \nЗа дари рясні землі \nй за цю їжу на столі!\n\nКуплет 2.\nТи благослови дари  \nй нас усякої пори; \nВсіх зміцни та сил нам дай \nі в руках Своїх тримай!', '', NULL, NULL),
(322, 'Ми дякуєм Боже Тобі за ці жнива', NULL, 'Куплет 1 \nМи дякуєм, Боже, Тобі за ці жнива, \nЩо рясно вродили на наших полях,\nЗа сонце, за вітер, за дощ літній з неба, \nЗа спокій, що маєм у наших серцях.\n\nКуплет 2.\nТи все необхідне для нас посилаєш,  \nЗдоров''я для праці Ти нам подаєш, \nЗа руку тримаєш, як батько дитину, \nВ Своє вічне Царство до неба ведеш.\n\nКуплет 3.\nНе можемо, Боже, Тобі відплатити,  \nЗа всі добродійства, що Ти посилав, \nЗа ласки проміння, за вічне спасіння, \nЯке в Своїм Сині Ти нам дарував.\n\nКуплет 4.\nО, Господи, Боже, як часто не ціним  \nУсі добродійства, що Ти нам зробив; \nПрости Ти нам, Боже, зміцни наші сили, \nЩоб більше ніхто з нас Тебе не гнівив.', '', NULL, NULL),
(323, 'Будем розсівати Слово Боже рано', NULL, 'Куплет 1 \nБудем розсівати Слово Боже рано, \nПри заході сонця, і вдень, і вночі; \nБудемо чекати урожаю з лану, \nЗ радощами в серці принесем снопи.\n\nПрипев: \nПринесем снопи, принесем снопи; \nЗ радощами в серці принесем снопи.\nПринесем снопи, принесем снопи; \nЗ радощами в серці принесем снопи.\n\nКуплет 2.\nЧи то в пору добру, чи в час непогоди,  \nНавіть у час бурі, спеки чи дощів, \nМи не занедбаєм доброї нагоди, - \nЗ радощами в серці принесем снопи.\n\nКуплет 3.\nБудем розсівати правду Божу всюди,  \nХоч і перешкоди різні навкруги; \nСкоро час настане, славне свято буде, \nЗ радощами в серці принесем снопи.', '', NULL, NULL),
(324, 'Що ти сіяв Що посіяв', NULL, 'Куплет 1 \nЩо ти сіяв? Що посіяв? \nПри дорозі що посіяв? \nОсь летять на поле птиці, \nЗерна виберуть пшениці, \nЩо ж залишиться тобі? \nЩо ж залишиться тобі?\n\nКуплет 2.\nЩо ти сіяв? Що посіяв?  \nМіж камінням що посіяв? \nМіж камінням грунту мало, \nЩо зійшло - і те зав''яло, \nЩо ж залишиться тобі? \nЩо ж залишиться тобі?\n\nКуплет 3.\nЩо ти сіяв? Що посіяв? \nПоміж терням що посіяв? \nЗнай, марноти та незгоди \nЗавжди глушать добрі сходи, \nЩо ж залишиться тобі? \nЩо ж залишиться тобі?\n\nКуплет 4.\nЩо ти сіяв? Що посіяв?  \nВ добрім грунті що посіяв? \nТі посіви не зів''януть, \nУ чеканні не обмануть, \nА стократно віддадуть, \nа стократно віддадуть.\n\nКуплет 5.\nЩо ти сіяв? Що посіяв?  \nВ цім житті що ти посіяв? \nВсе, що сіяв, бувши в тілі, \nЧи то словом, чи то ділом – \nВсе пожнеш за гробом ти, \nвсе пожнеш за гробом ти.', '', NULL, NULL),
(325, 'Не хотів би я без плоду', NULL, 'Куплет 1 \nНе хотів би я без плоду \nсам до Господа прийти; \nХоч одну хотів би душу, \nдо Ісуса привести.\n\nПрипев: \nНе хотів би я без плоду \nсам до Господа прийти; \nХоч одну хотів би душу \nдо Ісуса привести.\n\nКуплет 2.\nСпас життя дав, - добре знаю  \nі я смерти не боюсь, \nАле сам себе питаю: \n"З чим я перед Ним явлюсь?"\n\nКуплет 3.\nО, коли б літа минулі, \nщо даремно їх прожив, \nЗміг я знову повернути – \nя б лиш Господу служив.\n\nКуплет 4.\nО, працюйте, діти Божі,  \nви у селах та містах \nІ сердечно закликайте \nгрішні душі до Христа!', '', NULL, NULL),
(326, 'Всі до праці спішить', NULL, 'Куплет 1 \nВсі до праці спішить, \nнас Господь кличе Сам, \nВ путь підем, що Спаситель \nпроклав її нам, \nЩоб Дух правди Його \nзавжди нас підкріпляв, \nВіру, силу й життя \nв нас щодня обновляв.\n\nПрипев: \nВсі до праці спішить, всі спішіть \nДружно, разом ідіть, всі ідіть \nУ надії вперед, аж доки Сам Господь прийде!\n\nКуплет 2.\nВсі до праці спішіть,  \nбо багато є справ, \nЗло нехай пропаде, \nбо добра день настав;\n \nІм''я Господа сил \nНехай славиться в нас, \nВін достойний хвали, \nВін навіки нас спас!\n\nКуплет 3.\nВсі до праці спішіть,  \nнам небесний Отець, \nПо закінченню праці \nготує вінець, \nЯк прийдем до небес, \nу місця для святих, \nЗаспіваємо ми: \n"Христос спас нас усіх!"', '', NULL, NULL),
(327, 'Де живуть у злі й без Бога', NULL, 'Куплет 1 \nДе живуть у злі й без Бога, - \nТи життям не називай! \nДля Спасителя Ісуса \nСерце стомлене віддай! \nДруже, глянь, як люди гинуть \nу гріхах і марноті! \nНе знайдеш ти тут спокою, - \nщастя знайдеш лиш в Христі.\n\nКуплет 2.\nО, збирай борців за віру,  \nдо Ісуса закликай: \nДень за днем проходить скоро, -\nне барися, поспішай! \nСкільки душ Христа не знають \nі без Господа живуть... \nРозкажи їм про Ісуса, \nнаверни на добру путь!\n\nКуплет 3.\nСвідком будь ти перед ними,  \nрозкажи, що бачив сам, \nЯк любов Свою Спаситель \nдав покірним всім серцям. \nТи віддай себе Ісусу, - \nвсі літа ще молоді, \nТи віддай Йому і старість, \nбудеш з Богом жить тоді!\n\nКуплет 4.\nО, віддайся ти Ісусу, -  \nІ за тебе Він страждав, \nНа хресті терпів Він муки, \nКров невинну проливав. \nСерце хто віддасть Ісусу, \nВічне в Нім життя знайде; \nТого Сам Христос, Син Божий, \nВ царство радости введе.', '', NULL, NULL),
(328, 'Дружно дружно будем працювати', NULL, 'Куплет 1 \nДружно, дружно будем працювати, \nНа труд той радісно підем; \nЩо для нас тепер Господь призначив – \nЧесно й свято виконати йдем.\n\nПрипев: \nТруд цей для Бога, \nрадісно підем, радісно підем. \nТруд цей для Бога \nв винограднику Його.\n\nКуплет 2.\nСміло, сміло про Христа розкажем,  \nПро любов Його до грішних нас; \nА Спаситель - Божий Син у славі, \nБлагодать безмірну нам подасть.\n\nКуплет 3.\nМи підем услід за Ним покірно,  \nТерпеливо хрест наш понесем; \nІ людей, які живуть без Бога, \nДо Христа Ісуса приведем.', '', NULL, NULL),
(329, 'Браття сестри спільно й радо', NULL, 'Куплет 1 \nБраття, сестри, спільно й радо, \nяк одна рідня, \nХай виходить вся громада \nна поля Христа!\n\nПрипев: \nВсі вперед, хто тільки може, \nнадійшла й для нас пора; \nВсі вперед, на діло Боже, \nвсі на звершення добра!\n\nКуплет 2.\nНива Божа зародила,  \nславний урожай! \nЩиро до святого діла \nкожен поспішай!\n\nКуплет 3.\nНезабаром час настане  \nі прийде наш Спас, \nХай же Він усіх застане \nпри роботі нас!', '', NULL, NULL),
(330, 'Ясне зійшло світило', NULL, 'Куплет 1 \nЯсне зійшло світило \nі правди, і добра, \nНам серце освітила \nРанішня пора. \nСпішіть усі з бажанням \nвідзначить праці час, \nЯк темна ніч настане – \nБог вам спокій дасть!\n\nКуплет 2.\nВже сонце пополудні  \nі спека шкодить нам; \nНадійтесь і в час трудний, \nБог поможе Сам.\nІ дух ваш не пристане \nу трудний праці час, \nЯк темна ніч настане – \nБог вам спокій дасть!\n\nКуплет 3.\nТож, об''єднаймось, браття,  \nна славнії труди, \nСоюзом благодаті \nраз і назавжди.\n \nНіхто хай не відстане, \nБо вже останній час, \nЯк темна ніч настане –\nБог вам спокій дасть!', '', NULL, NULL),
(331, 'Для Господа Христа радісно працюй', NULL, 'Куплет 1 \nДля Господа Христа радісно працюй, \nБільше роби добра, часу не марнуй, \nДні життя земного ти праці присвяти, \nТрудись ти для Ісуса.\n\nПрипев: \nШвидко, невпинно час летить, \nДорогоцінну кожну мить \nНа Господнє діло витрачай сміливо, \nТрудися для Ісуса.\n\nКуплет 2.\nБільше старайся ти ближнім послужить,  \nБідним допомогти, кволих підкріпить. \nДні життя земного ти праці присвяти, \nТрудись ти для Ісуса.\n\nКуплет 3.\nЗавжди думками ти пробувай в Христі,  \nБлагословить тоді Він діла твої. \nДні життя земного ти праці присвяти, \nТрудись ти для Ісуса.', '', NULL, NULL),
(332, 'Людям блукаючим шлях покажіте', NULL, 'Куплет 1 \nЛюдям блукаючим шлях покажіте, \nТих, що зневірились - ви підбодріть! \nВсім погибаючим правду скажіте, \nХто спить душею, ідіть, розбудіть!\n\nПрипев: \nЛюдям блукаючим шлях покажіте, \nХто спить душею, ідіть, розбудіть!\n\nКуплет 2.\nВістку спасіння усім понесіть ви,  \nВсіх до Ісуса благайте прийти, \nЇх научайте як в Господі жити, \nЩоб міг нещасний в Нім щастя знайти.\n\nКуплет 3.\nЛюдям, що в світі тут ходять в темряві,  \nСвітло Христове негайно несіть. \nВ серце утомлене життям гріховним, \nРадість Дух Божий лиш може пролить.', '', NULL, NULL),
(333, 'Не шукай щоб щось велике ти зробити міг', NULL, 'Куплет 1 \nНе шукай, щоб щось велике ти зробити міг,\nА будь вірним в меншім ділі ти; \nІ не думай, щоб далеко ти світити зміг, - \nСвіти в куточку, де ти є.\n\nПрипев: \nСвіти в куточку, де ти є;\nСвіти в куточку, де ти є; \nЩоб усі, хто в темряві, \nДо Господа прийшли, - \nСвіти в куточку, де ти є.\n\nКуплет 2.\nЩе багато хто живе в гріховній темноті,  \nІ потрібне світло їм твоє; \nТи повинен поміч дати хоч одній душі, - \nСвіти в куточку, де ти є.\n\nКуплет 3.\nВсіх людей навколо себе ти щодня люби,  \nРозбуди і в них життя святе; \nВід ранкової зорі їм про Христа кажи – \nСвіти в куточку, де ти є.', '', NULL, NULL),
(334, 'Ми слабкі та помагаєм', NULL, 'Куплет 1 \nМи слабкі, та помагаєм \nБудувати Божий храм; \nМи Ісусу довіряєм, \nДопомогу дасть Він нам. \nПрацю щиру, хоч малу, \nВін приймає, як хвалу.\n\nПрипев: \nО, Осанна, Божий Сину, \nТи безмірно любиш нас! \nМи пильнуєм, як святиню, \nДаний нам святий наказ.\n\nКуплет 2.\nТак людей багато всюди  \nУ гріховному житті; \nЇх Господній голос будить: \n"О, прийдіть, служіть Мені!" \nМи з Христом і тільки з Ним \nТут будуєм вічний дім.\n\nКуплет 3.\nХай скоріше і усюди  \nВиростає Божий храм; \nХай любов Христа, як чудо, \nВідкривається серцям. \nБоже наш, хай заклик Твій \nОбіймає світ людський.', '', NULL, NULL),
(335, 'Я свій час не хочу марно провести', NULL, 'Куплет 1 \nЯ свій час не хочу марно провести, \nВ світлі правди за Христом я буду йти, \nДорогі хвилини всі мого життя \nХочу я віддати для Христа.\n\nПрипев: \nПонесу вість про Христа \nПо землі у всі місця; \nХай про Нього засвідкує хід мого життя: \nЗа Христом іду щоденно я.\n\nКуплет 2.\nДуш багато гине у гріха пітьмі, \nСліз гірких багато пролилось людьми; \nДе недуги мучать душі, де печаль – \nТам звіщати буду про Христа.\n\nКуплет 3.\nДе в домах незгода і тривожно жить,  \nДе дітей молитися ніхто не вчить, \nДе служіння кожен день земним богам – \nПро Христа звістити хочу там.', '', NULL, NULL),
(336, 'О скільки душ страждає без Бога на землі', NULL, 'Куплет 1 \nО, скільки душ страждає без Бога на землі! \nУ темряві гріховній загрожує смерть їм. \nБез Пастиря блукають по грішній тій путі, \nКуди ідуть - не знають, і що чекає їх.\n\nПрипев: \nХодімо шукати грішних, \nПриведем їх до Отця, \nЩоб могли ми Йому того дня сказать: \n"Ось загублена вівця".\n\nКуплет 2.\nХто жертви не боїться, на все готовий йти,  \nЩоб тих овець заблудлих з загибелі спасти? \nХто показать піде їм шлях правди до Отця? \nЛюбов''ю хто потішить розбиті їх серця?\n\nКуплет 3.\nВелика радість буде при зустрічі Творця.  \nНаш добрий Пастир скаже: "Овечка знайдена! \nВ гущавині блукала і змучилась в біді; \nЯ взяв її, безсилу, і прошу: Ти прийми!"', '', NULL, NULL),
(337, 'Люблю розповідати', NULL, 'Куплет 1 \nЛюблю розповідати \nпро давні справи знов: \nЯк нас всіх рятувати \nдо нас з небес зійшов \nЯ хочу, щоб всі чули \nцю вість, потрібну всім, \nТому про все минуле \nоповідаю їм.\n\nПрипев: \nЛюблю розповідати \nВсім людям грішним знов, \nПро Спаса всім казати, \nІ про Його любов.\n\nКуплет 2.\nЛюблю розповідати  \nпро чуда від Отця, \nТа про життя багате \nна ласку без кінця; \nЯк Спас слабих і бідних \nв недолі рятував, \nІ як чужих і рідних \nдо Себе пригортав.\n\nКуплет 3.\nЛюблю розповідати  \nпро все з подій святих \nЙ плоди надіюсь мати \nз оповідань моїх: \nЯ вірю, що народи \nна Божу стануть путь, \nІ я сам в небі буду, \nкуди святі прийдуть.', '', NULL, NULL),
(338, 'Ви всі хочете ходити', NULL, 'Куплет 1 \nВи всі хочете ходити \nшляхом правди до Отця, \nА чому ж це ваші діти \nще не знають про Творця?\n\nПрипев: \nО, батьки, ви своїх діток тих, \nщо Бог вам дарував, \nПриведіте до Ісуса, бо й за них \nВін постраждав.\n\nКуплет 2.\nДе дочка твоя, о, мати,  \nі чому не тут вона? \nТи повинна показати \nїй дорогу до Христа.\n\nКуплет 3.\nБатьку, в зібранні співаєш,  \nу Христі радієш ти, \nА чому твій син не знає \nяк до Господа прийти?\n\nКуплет 4.\nО, батьки розповідайте  \nсвоїм дітям про Христа \nІ завжди Його благайте, \nщоб спасла їх кров свята!', '', NULL, NULL),
(339, 'Свій маяк Господь Всесильний', NULL, 'Куплет 1 \nСвій маяк Господь Всесильний \nвічним світлом засвітив, \nНам же Він вогонь небесний \nзберігати доручив.\n\nПрипев: \nХай же світло наше сяє \nдля людей, що в світі цім, \nОбездолених, нещасних \nнаправляє в вічний дім!\n\nКуплет 2.\nГріх, немов бурхливе море,  \nподорожньому грозить;\nДе лиш темрява і горе, - \nвсюди треба там світить.\n\nКуплет 3.\nПоправляй світильник, брате,  \nщоб і той, хто в темноті, \nМіг те світло розпізнати \nі спастися у Христі.', '', NULL, NULL),
(340, 'Пошли нас Боже сказати', NULL, 'Куплет 1 \nПошли нас, Боже, сказати, \nяк в любові із неба Ти \nзахотів Христа віддати, - \nзнову і знову скажи!\n\nПрипев: \nЗнову і знову скажи! \nЗнову і знову скажи! \nЧудову ту вість про Ісуса \nзнову і знову скажи!\n\nКуплет 2.\nПошли нас, Боже, сказати,  \nяк віддав на страждання Ти \nЗа людей Христа вмирати, - \nзнову і знову скажи!\n\nКуплет 3.\nПошли нас, Боже, сказати,  \nяк страждав Ісус на землі, \nЩоб у небо нас прийняти, - \nзнову і знову скажи!\n\nКуплет 4.\nПошли нас, Боже, сказати,  \nщо бажаєш усіх спасти, \nРадість серцю дарувати, - \nзнову і знову скажи!', '', NULL, NULL),
(341, 'Прийди ти до Ісуса мій друже дорогий', NULL, 'Куплет 1 \nПрийди ти до Ісуса, мій друже дорогий, \nТебе стомив до краю великий гріх тяжкий. \nПрийди і не вагайся, Христос усіх прийма, \nСкажи, що в тебе в серці печаль й гріха зима.\n\nКуплет 2.\nВіддайся ти Ісусу і слухай лиш Його,  \nПоллється пісня щастя із серденька твого. \nВін кров пролив за тебе, вона серця цілить, \nВ ній знайдеш ти спасіння і вічно будеш жить.\n\nКуплет 3.\nІди лиш за Ісусом, як Він, вузьким шляхом,  \nІдучи не журися, борись з гріхом та злом. \nІди і не вагайся, на небі у Христа \nТи ввійдеш в вічну радість небесного життя.', '', NULL, NULL),
(342, 'Прийме грішників Христос', NULL, 'Куплет 1 \nПрийме грішників Христос, - \nхто б до Нього не прийшов, \nХто у тьмі гріха живе \nта в душі тягар несе.\n\nПрипев: \nПро любов всім розкажи, \nПрийме грішників Христос.\nПро любов всім розкажи, \nПрийме грішників Христос.\n\nКуплет 2.\nНам спасіння дарував  \nі за нас життя віддав, \nНас прощає - Він сказав, \nі свободу всім нам дав.\n\nКуплет 3.\nКличе Він, до Нього йди,  \nгріх до ніг Його склади. \nСпокій ти Його прийми \nі в союз із ним вступи.\n\nКуплет 4.\nПрийме грішників Христос,  \nвірю: прийме і мене. \nВсі простить гріхи Христос, \nслав Його, душе, за все.', '', NULL, NULL),
(343, 'Чи тобі все одно що Спаситель страждав', NULL, 'Куплет 1 \nЧи тобі все одно, що Спаситель страждав? \nТи байдуже стоїш, а Він кров проливав! \nПро страждання Його ти забув вже давно. \nЧи тобі все одно, чи тобі все одно?\n\nКуплет 2.\nНа Голгофі за тебе Христос умирав,  \nВсі провини твої Він на Себе узяв; \nТи ж стоїш, весь гріховним охоплений сном \nІ не бачиш нічого, тобі все одно...\n\nКуплет 3.\nВін за кого вмирав? Чи ти думав про те?  \nЩо гріхи Він простив, чи благав ти Його? \nВідкупитель Христос кличе в Царство тебе. \nО, невже в своє серце не приймеш Його?\n\nКуплет 4.\nНаближається вічність, подумай про те!  \nНа суді, знай, ніхто не заступить тебе; \nСтануть всі перед білим престолом Христа, - \nДе ж тоді ти сховаєш гріховні діла?\n\nКуплет 5.\nПоки маєш ще час, навернись до Христа  \nІ віддай Йому, друже, твої всі літа! \nСвоє серце віддай, поки кличе Він Сам: \n"Прийдіть, змучені, вам відпочинок Я дам!"', '', NULL, NULL),
(344, 'Друже мій прийди скоріш', NULL, 'Куплет 1 \nДруже мій, прийди скоріш \nДо Христа тепер, \nВ Нім ти душу освятиш, \nВін за тебе вмер.\n\nПрипев: \nХай прославлять всі вуста Господа Христа, \nВін за грішників страждав І їм вічність дав.\n\nКуплет 2.\nБог престол Свій залишив  \nВ славних небесах, \nІ на землю поспішив \nДо людей в гріхах.\n\nКуплет 3.\nДруже, Спас Себе віддав  \nза життя твоє; \nНа хресті Він Сам сказав, \nщо звершилось все.\n\nКуплет 4.\nНе вагайся, поспішай,  \nскинь тягар душі, \nВсе життя Христу віддай \nі Йому служи!', '', NULL, NULL),
(345, 'Віриш в Слово Боже ти Йди до Ісуса', NULL, 'Куплет 1 \nВіриш в Слово Боже ти? Йди до Ісуса! \nСкинь кайдани марноти! Йди до Ісуса! \nТебе кличе благодать: йди до Ісуса! \nХоче Бог тебе прийнять, йди до Ісуса!\n\nПрипев: \nДруже мій, друже мій! Йди до Ісуса! \nВін Господь, Спаситель твій, йди до Ісуса!\n\nКуплет 2.\nХочеш праведно прожить? Йди до Ісуса!  \nДух без радости скорбить? Йди до Ісуса! \nКаже всім Його любов: Йди до Ісуса, \nВін пролив за тебе кров. Йди до Ісуса!\n\nКуплет 3.\nХочеш бути в небесах? Йди до Ісуса!  \nТи шукаєш правди шлях? Йди до Ісуса! \nТебе кличе Дух Святий: Йди до Ісуса, \nДасть Він радість і спокій. Йди до Ісуса!', '', NULL, NULL),
(346, 'О друже вчуй нині приємний ще час', NULL, 'Куплет 1 \nО, друже, вчуй нині приємний ще час, \nТвої всі провини простить хоче Спас; \nНе будь же байдужим, стань Богу служить, \nБо може Дух Божий затихнути вмить.\n\nКуплет 2.\nХристос закликає усіх до Отця  \nІ сповняє Духом покірні серця; \nВідкрий своє серце, Ісуса прийми, \nІ Духа Святого життям не смути.\n\nКуплет 3.\nТвій жертівник серця вогнем не горить,  \nСпаситель бажає його відновить; \nО, друже, у вірі завжди пробувай, \nДарами від Духа Христа прославляй!', '', NULL, NULL),
(347, 'Брате мій милий чого ти сумуєш', NULL, 'Куплет 1 \nБрате мій милий, чого ти сумуєш, \nВ тебе на серці велика печаль, \nЧом твої очі сумні, як та осінь, \nСерце камінне, тверде, як та сталь?\n\nКуплет 2.\nГоря у світі зазнав ти чимало,  \nЗмучився ти у важкій боротьбі; \nСерце не було любов''ю зігріте, \nЧасто траплялось нещастя тобі.\n\nКуплет 3.\nЩастя було, але швидко минуло,  \nНаче та квітка, що в полі цвіте; \nВітер повіяв - краса облетіла, \nДе ж то поділося гарне, святе?\n\nКуплет 4.\nБрате мій милий, учися робити  \nБільше і більше у світі добра; \nВіруй у Бога, люби свого брата, \nІ в твоїм серці засяє зоря.', '', NULL, NULL),
(348, 'Хай бере хто хоче поки пора', NULL, 'Куплет 1 \nХай бере, хто хоче, поки пора, \nБожий дар спасіння вічного добра; \nСлухайте, ідіть і поспішайте взять \nТе, що Бог всім хоче дать.\n\nПрипев: \nОсь вода жива, всім вона тече; \nТо Ісус-Спаситель даром нам дає. \nХай бере, хто прагне, вічную любов – \nзакликає знов і знов.\n\nКуплет 2.\nО приходь, мій друже, і не зволікай,  \nНині день спасіння ти не зволікай; \nМоже, буде пізно завтра вже благать – \nЗмовкне Божа благодать.\n\nКуплет 3.\nВсі, хто тільки чує Слово це святе,  \nВічний дар спасіння кожний хай прийме; \nВсе по обітниці з ласки Бог дає – \nВбогий духом хай прийде!', '', NULL, NULL),
(349, 'Пробудись заснулий грішник', NULL, 'Куплет 1 \nПробудись, заснулий грішник, \nгоді, годі тобі спать. \nТи страждаєш, безутішний, \nІсус хоче радість дать.\n\nПрипев: \nТи бажаєш оправдання? \nВір, і радість буде у душі твоїй, \nТвій Спаситель кличе, встань.\n\nКуплет 2.\nХто поклав гріхи смиренно  \nдо Голгофського хреста, \nТой знайшов душі прощення \nу Спасителя Христа.\n\nКуплет 3.\nО, прийди скоріш до Бога,  \nти в гріхах, в неправді жив; \nЗа багатих і убогих \nКров Свою Христос пролив.', '', NULL, NULL),
(350, 'Чи є місце для Ісуса', NULL, 'Куплет 1 \nЧи є місце для Ісуса? \nКров''ю Він тебе купив, \nСтукає до твого серця, \nщоб і ти Його впустив.\n\nПрипев: \nДля Ісуса, Його слави, \nсерце нині приготуй; \nГолос той почуй ласкавий \nі прийми Його любов.\n\nКуплет 2.\nМарноти й земним турботам  \nмісце в серці ти даєш; \nО, невже ж перед Ісусом \nсерце ти своє замкнеш?\n\nКуплет 3.\nО, віддайся ти Ісусу!  \nЧуєш, кличе Він тебе. \nМоже, це останній день твій, \nшвидко час земний пройде.\n\nКуплет 4.\nПоспіши ж ти для Ісуса  \nсерце і життя віддать, \nБо не завжди буде ласку \nВін до грішних проявлять.', '', NULL, NULL),
(351, 'О невже ти підеш і не приймеш Христа', NULL, 'Куплет 1 \nО, невже ти підеш і не приймеш Христа, \nЩоб далі в темряві блукать? \nЗагине повік твоя друже, душа, \nвідкинувши ту благодать.\n\nПрипев: \nО, невже ти підеш? О, невже ти підеш? \nО, невже ти підеш і не приймеш Христа? \nО, невже ти підеш?\n\nКуплет 2.\nО, невже ти підеш, не зустрівшись із Ним?  \nСкажи тільки слово "Прости". \nІ стане Він Пастирем добрим твоїм \nі захисником у житті.\n\nКуплет 3.\nО, невже ти підеш, не зустрівшись із Ним?  \nВ Ісусі лиш спокій знайдеш. \nДаремні вагання скоріше відкинь, \nПокайся і душу спасеш!', '', NULL, NULL),
(352, 'Ніжно так Спаситель закликає', NULL, 'Куплет 1 \nНіжно так Спаситель закликає, \nКожну душу хоче Він спасти, \nВсі провини грішникам прощає \nІ веде до вічної мети.\n\nПрипев: \nКлич мене, Спасе мій, \nЯ бажаю за Тобою йти; \nКлич мене, Спасе мій, \nЯ піду, куди вестимеш Ти!\n\nКуплет 2.\nЯ в Христі душі спасіння маю,  \nХоче серце радісно співать, \nТа в гріхах мільйони душ вмирають, \nТреба й їх від згуби рятувать.\n\nКуплет 3.\nБільше днів не хочу марнувати,  \nРятувать піду людей з біди, \nЩоб Спаситель міг мені сказати: \n"Ти був вірний - в царство увійди!"', '', NULL, NULL),
(353, 'О благай Христа мій друже кожним часом дорожи', NULL, 'Куплет 1 \nО, благай Христа, мій друже, кожним часом дорожи, \nВір, молись, не будь байдужим, до Спасителя спіши!\n\nПрипев: \nНаш Христос дає серцям \nтут надію, радість там. \nНаш Христос дає серцям \nтут надію, радість там.\n\nКуплет 2.\nДо Христа прийди покірно,  \nяк дитя, Його проси; \nХоче Він тебе безмірно \nвід загибелі спасти.\n\nКуплет 3.\nПолюби ім''я Христове  \nі Господній заповіт. \nУ Його святій любові \nти новий побачиш світ.\n\nКуплет 4.\nЧас настане й зустрічати  \nбудеш з вірними Христа; \nБілий одяг будуть мати \nвсі спасенні в небесах.', '', NULL, NULL),
(354, 'О друже мій тебе ніхто', NULL, 'Куплет 1 \nО, друже мій, тебе ніхто \nз гріхів спасти не може, \nЗ гріхом до Господа прийди, \nмолись: "Помилуй, Боже!"\n\nКуплет 2.\nЛише Христос нас оправдав  \nСвоїм тяжким стражданням, \nЖиття і спокій нам послав, \nдо Нього йди з благанням.\n\nКуплет 3.\nЧекає Він, скоріш прийди,  \nне гаючи й хвилини. \nМолись: "О, Господи, прости!" – \nСпаситель Він єдиний.\n\nКуплет 4.\nПокинь журбу і сумнів свій,  \nне треба сумувати, \nЙди до Його святих країв. \nВін щастя може дати.', '', NULL, NULL),
(355, 'Любий друже о послухай голос чийсь звучить', NULL, 'Куплет 1 \nЛюбий друже, о, послухай, голос чийсь звучить. \nГолос милий, голос тихий просить відчинить. \nТо не просто перехожий стукає в тиші, \nТо говорить Сам Спаситель: "Відчени Мені".\n\nКуплет 2.\nХоч у серці смерти холод, темрява нічна;  \nЯк відчиниш Йому серце - розцвіте весна. \nРіч свята Його поллється, як ріка вогнів. \nЧуєш, друже, як Він просить: "Відчени Мені"!\n\nКуплет 3.\nО, відкрий Йому ти серце, хоче Він там жить,  \nВ смуток, холод і страждання радість, світ пролить. \nНе вагайся відчинити, не залишся в сні. \nСкоро змовкне голос тихий: "Відчини Мені"\n\nКуплет 4.\nГість пройде і заридаєш на заході днів,  \nБудеш стукати до раю: "Відчиніть Мені!" \nНе відчиняться вже двері, ти підеш в сльозах \nВ муки вічні, де панують сльози, ніч і жах.', '', NULL, NULL),
(356, 'Нині просимо ми всі', NULL, 'Куплет 1 \nНині просимо ми всі, \nнащо гинути в грісі? \nТебе й кличе Дух Святий – \nйди до Спаса, друже мій?\n\nПрипев: \nПоспіши, поспіши нині \nдо Христа прийти!\nПоспіши, поспіши нині \nдо Христа прийти!\n\nКуплет 2.\nТи без Бога довго жив,  \nпроти Нього все грішив; \nСерце ти Йому відкрий – \nдасть Він радість і спокій.\n\nКуплет 3.\nГріх тебе не відпускав,  \nі спокою він не дав; \nДо Христа іди мерщій, - \nтільки в Ньому спокій твій.\n\nКуплет 4.\nПеред Спасом визнай гріх,  \nдасть Він прощення тобі; \nВсе життя віддай Йому, \nдушу Він спасе твою.', '', NULL, NULL),
(357, 'О брате час вже пробудися', NULL, 'Куплет 1 \nО, брате, час вже, пробудися \nВід сну, гріха і марноти! \nХристос зове тебе: "Прокинься!" \nТебе в любові кличе Він.\n\nПрипев: \nНе ухиляйсь, бо Він тепер зове тебе, \nА поспіши скоріш, скоріш до Нього йди.\n\nКуплет 2.\nВін полюбив тебе, мій брате,  \nЗа тебе, Він на хрест пішов, \nЩоб за гріхи твої страждати, \nЩоб в Ньому ти життя знайшов.\n\nКуплет 3.\nІз ран Його свята кров лилась,  \nЛюбов''ю погляд все горів. \nО, брате мій, ми провинились, \nНевинно Він за нас терпів.\n\nКуплет 4.\nПречиста кров нас очищає,  \nЗмиває з серця всякий гріх; \nВона і душу відновляє, \nСпокій дає для вірних всіх.', '', NULL, NULL),
(358, 'За тебе мій друже Христос умирав', NULL, 'Куплет 1 \nЗа тебе, мій друже, Христос умирав, \nСтражданням Своїм Він життя дарував.\n\nКуплет 2.\nЧого ти, мій друже, такий все сумний?  \nСтомився до краю гріхом ти тяжким.\n\nКуплет 3.\nПрийди до Ісуса, Він кличе тебе;  \nВін любить. Він любить, спасе Він тебе.\n\nКуплет 4.\nПрийди, не барися, дай серце Йому.  \nУ Нім знайдеш щастя й життя повноту.\n\nКуплет 5.\nІсус все чекає, коли ти прийдеш?  \nБо завтра, можливо, дочасно помреш.\n\nКуплет 6.\nІсус тебе любить і просить тебе,  \nНе будь же байдужий, дай серце своє.', '', NULL, NULL),
(359, 'Чого ждеш на широкім шляху', NULL, 'Куплет 1 \nЧого ждеш на широкім шляху? \nЧому досі ти служиш гріху? \nО, чому ти не хочеш прийнять, \nДар безцінний - Христа благодать?\n\nПрипев: \nСпіши тепер, спіши тепер, \nДо Христа Ісуса мерщій! \nСпіши тепер, спіши тепер, \nБо в темряві згинеш нічній.\n\nКуплет 2.\nТи поглянь на Ісуса Христа,  \nТо ж за тебе лилась кров свята; \nЧашу горя за тебе він пив \nІ від суду тебе відкупив.\n\nКуплет 3.\nДля Христа все життя присвяти,  \nІ щасливим навік будеш ти; \nКров свята змиє твій тяжкий гріх, \nОдяг білий одягнеш, як сніг.', '', NULL, NULL),
(360, 'Двері ось перед тобою', NULL, 'Куплет 1 \nДвері ось перед тобою, \nдві путі за ними йдуть; \nДруже, виріши душею, \nна яку ти станеш путь?\n\nКуплет 2.\nКрізь одні, широкі двері  \nй путь широку бачиш ти, \nА на ній людей без міри, \nщо шукають марноти.\n\nКуплет 3.\nНа широкій тій дорозі  \nвічна ніч чекає тих, \nЩо не хочуть жити в Бозі, \nчинять тільки зло та гріх.\n\nКуплет 4.\nНа кінці путі вузької  \nнас чекає вічний рай; \nТож, тримайсь мети святої \nі звести себе не дай!', '', NULL, NULL),
(361, 'Хоче всіх людей Господь благословить', NULL, 'Куплет 1 \nХоче всіх людей Господь благословить; \nІ спасіння двері кожному відкрить;\n\nПрипев: \nПоспіши відкрити серця двері ти, \nГоспода Христа впусти! \nГоспода Христа впусти;\nГоспода Христа впусти; \nПоспіши відкрити серця двері ти, \nГоспода Христа впусти!\n\nКуплет 2.\nВін на хрест пішов страждати за наш гріх,  \nВоскресінням славним оправдати всіх;\n\nКуплет 3.\nДовго так стоїш на роздоріжжі ти,  \nЗнай, таких Ісус прийшов знайти й спасти;\n\nКуплет 4.\nМає щастя, хто себе Христу віддасть,  \nСам Христос йому благословіння дасть.', '', NULL, NULL),
(362, 'Ввійдіть двері райські відкрив Сам Христос', NULL, 'Куплет 1 \nВвійдіть, двері райські відкрив Сам Христос, \nВсіх кличе Він в царство Своє. \nСпішіть ви ввійти, ще сьогодні є час! \nХто знає, що завтра вас жде?\n\nПрипев: \nСпіши, друже любий, прийнять \nВелику святу благодать: \nЖиття вічне - Божий дар прийми. \nПрийди до Ісуса, прийди!\n\nКуплет 2.\nСпаситель наш скоро, вже скоро прийде,  \nДе місце знайдеш ти собі? \nСпасенних Він в Царство Своє всіх візьме, \nЗачиняться двері тоді.\n\nКуплет 3.\nПокайся негайно - гріхи Він простить,  \nОбмиє пороки твої, \nІ душу, і тіло твоє оживить, \nНе гайся, до Нього прийди!', '', NULL, NULL),
(363, 'Памятай про Бога завжди', NULL, 'Куплет 1 \nПам''ятай про Бога завжди, \nДруже мій, не забувай; \nІ словами і ділами \nЙого в світі прославляй.\nІ словами і ділами \nЙого в світі прославляй.\n\nКуплет 2.\nТи собі все так говориш:  \n"Молодий - то веселись, \nА коли вже постарієш,\nТоді кайся і молись".\n\nКуплет 3.\nО, нещасний, ти не знаєш,  \nв яку пору ти помреш; \nМоже завтра час настане – \nТи у вічність відійдеш.\n\nКуплет 4.\nМоже завтра побудують  \nгріб сосновий вже тобі \nІ земля навік покриє \nтвоє тіло в глибині.\n\nКуплет 5.\nА душа? - Душа загине,  \nтак, загине назавжди; \nПізно каятися буде, \nпізно, друже, вже тоді.\n\nКуплет 6.\nЧас тепер гріхи лишати, -  \nправду цю запам''ятай, - \nПоспіши Христа прийняти, \nвсе життя Йому віддай.', '', NULL, NULL),
(364, 'О Божих слів не пропускай', NULL, 'Куплет 1 \nО, Божих слів не пропускай, \nспасіння світло в них для нас, \nДля Бога серце відкривай. \nСпасенним будь! - це кличе Спас.\n\nПрипев: \nДень завтра може не прийти, \nІ сонце не освітить нас, \nА зараз час Христа знайти. \nСпасенним будь! - це кличе Спас.\n\nКуплет 2.\nУсюди в світі гріх царить,  \nСпокою він тобі не дасть; \nПочни по-християнські жить. \nСпасенним будь! - це кличе Спас.\n\nКуплет 3.\nХристос до Себе всіх прийняв,  \nХто оцінив спасіння час; \nЯкби Його і ти пізнав. \nСпасенним будь! - це кличе Спас.', '', NULL, NULL),
(365, 'Ви блудите та бєте ноги', NULL, 'Куплет 1 \nВи блудите та б''єте ноги, \nспасіння хочете знайти, \nАле не знаєте дороги; \nвам шляхом іншим треба йти.\nАле не знаєте дороги; \nвам шляхом іншим треба йти.\n\nКуплет 2.\nІдіть ви шляхом правди й віри,  \nдо злих на раду не ходіть; \nЛюбіте ворога ви щиро, \nі в рай обернеться цей світ.\n\nКуплет 3.\nЧого ще мучишся душею,  \nскажи: "О, Боже мій, прости!"\nНе дозволяй, щоб над твоєю \nдушею Каїн міг рости.\n\nКуплет 4.\nЧитайте Книгу Божу ревно,  \nв ній щастя можете знайти: \nВона покаже вам напевно, \nяким вам шляхом треба йти.', '', NULL, NULL),
(366, 'Спасіння нам Христос приніс', NULL, 'Куплет 1 \nСпасіння нам Христос приніс \nвід горя, мук і сліз; \nЗвільнив Він нас від всіх гріхів, \nза те Сам потерпів.\n\nПрипев: \nО, друже, Він за тебе вмер, \nприйми Христа тепер.\nО, друже, Він за тебе вмер, \nприйми Христа тепер.\n\nКуплет 2.\nХристос любов нам показав,  \nза грішних постраждав; \nВін на хресті в останній час \nОтця благав за нас.\n\nКуплет 3.\nЖиття нам, мертвим, дарував,  \nВін тьму із душ прогнав, \nІ Слово Він Своє нам дав, \nщоб кожен спокій мав.\n\nКуплет 4.\nГосподнє Слово - меч святий,  \nВоди струмок живий; \nХриста хто Спасом визнає, \nтой вічно вже живе.', '', NULL, NULL),
(367, 'Боже все життя моє', NULL, 'Куплет 1 \nБоже, все життя моє \nхочу, щоб було Твоє, \nКожен день і кожну мить \nхай Тобі хвала звучить.\n\nПрипев: \nЩоб, з''єднавши сили всі,\nза Твій дар життя, за все, \nСерце сповнене хвали \nІм''я славило Твоє.\n\nКуплет 2.\nРуки Ти візьми мої  \nна святі діла Твої,\nДай ногам ходить лиш там,\nде мені звелиш Ти Сам.\n\nКуплет 3.\nГолос мій візьми, щоб міг  \nутішать дітей Твоїх, \nА вустам дозволь моїм \nговорить про Тебе всім.\n\nКуплет 4.\nВсю візьми любов мою,  \nз нею все Тобі даю; \nІ благаю, Спасе мій, \nхай увесь я буду Твій.', '', NULL, NULL),
(368, 'Кращі літа молодії', NULL, 'Куплет 1 \nКращі літа молодії, \nсили юначі в ці дні весни, \nМи присвятім їх Ісусу, \nв дар наш Йому дорогий. \nЩо може бути ще кращим, \nяк для Ісуса служить, \nТут у житті цім дочаснім \nсерце Йому присвятить.\n\nКуплет 2.\nЧуєш, як Він закликає?  \nЧас благодатний для нас настав. \nБільше вагатись не можем, \nСпас нам життя дарував!\n \nСестри, підемо в надії \nз ім''ям Ісуса Христа! \nПромінь небесний зігріє \nвіру й любов у серцях.\n\nКуплет 3.\nСміло за ім''я Ісуса,  \nбраття, вперед на борню з гріхом! \nТисячі гинуть в темряві, \nсвітло ми їм понесем.\nХоч нас зустрінуть гоніння, \nсмерть за Христа не страшна! \nЗ вірою все переможем \nдля слави Спаса Христа.', '', NULL, NULL),
(369, 'Жити для Спаса з Ним умирать', NULL, 'Куплет 1 \nЖити для Спаса, з Ним умирать, \nЩо можна в світі краще бажать? \nВарто смирятись, варто боротись, \nВарто життя для Нього віддать.\n\nКуплет 2.\nЖити для Спаса вірно всяк час,  \nХоч би лякала тінь смерти нас; \nВсе ж без вагання, без нарікання, \nЩиро працюймо, поки є час.\n\nКуплет 3.\nЖити для Спаса - гріх умертвить,  \nХрест свій зневаги радо носить.\nШлях свій закінчим, щоб в небі вічнім \nВ славі безсмертя з Ісусом жить.', '', NULL, NULL),
(370, 'Я не свій  Христом спасенний', NULL, 'Куплет 1 \nЯ не свій, - Христом спасенний \nі належу вже Йому; \nВін навік придбав мене Сам, \nсерцем я Йому служу.\n\nПрипев: \nЯ Твій, я Твій, \nя належу вже Тобі, \nВсе, що маю і бажаю – \nвсе кладу до ніг Твоїх.\n\nКуплет 2.\nЯ не свій, - Христос Спаситель  \nмій Порадник для душі, \nВін спасіння Довершитель, \nдар життя в Його руці.\n\nКуплет 3.\nЯ не свій, - Христу Ісусу  \nвіддаю віднині я \nРозум, час мій і всі сили, \nсерце, волю і життя.\n\nКуплет 4.\nЯ не свій, - Бог милосердний  \nСам мене Своїм назвав, \nВ царство вічне і щасливе \nмене взяти обіцяв.', '', NULL, NULL),
(371, 'Вірний Спасителю мій', NULL, 'Куплет 1 \nВірний Спасителю мій, \nТи є найкращий мій Друг. \nЯ все Тобі віддаю: (даю) \nсерце, любов і красу.\nЯ все Тобі віддаю: (даю) \nсерце, любов і красу.\n\nКуплет 2.\nВ світі далеко я був,  \nгрішний, неправдою жив, \nТи ж мене, Боже, любив, (любив), \nКров''ю гріхи всі обмив.\nТи ж мене, Боже, любив, (любив), \nКров''ю гріхи всі обмив.\n\nКуплет 3.\nПісню про ласку Твою  \nВ серце моє Ти всели! \nДай сили хрест свій нести, (нести), \nВірним Тобі будь завжди!\nДай сили хрест свій нести, (нести), \nВірним Тобі будь завжди!', '', NULL, NULL),
(372, 'Хай Ісуса краса у житті весь час', NULL, 'Куплет 1 \nХай Ісуса краса у житті весь час \nОсвятить чистотою й любов''ю нас. \nДух любви Святий силу в дух мій послав, \nЩоб Спасителя образ в мені сіяв.\n\nКуплет 2.\nХай в душі моїй сяє краса Христа,  \nВся Його чистота і любов свята, \nЯк, Дух Божий ввійде, все в мені оживе, \nВсі побачать у серці красу Христа.\n\nКуплет 3.\nДух Святий утішає мене в житті;  \nБлагодать я знаходжу лише в Христі, \nЩоб я плід приносив, Щоб Тобі я служив, \nЩоб вечерю зі мною Ти розділив.\n\nКуплет 4.\nХай врочисто душа гімн хвали співа,  \nБо в Ісусі моє джерело життя. \nХай Ісуса Христа Прославляють уста, \nІ співає повік гімн хвали душа.', '', NULL, NULL),
(373, 'Все віддам я для Ісуса', NULL, 'Куплет 1 \nВсе віддам я для Ісуса, \nсерце все Йому віддам; \nХочу я Йому служити, \nяк Він Сам служив всім нам.\n\nПрипев: \nВсе Тобі даю, все Тобі даю, \nВсе для Тебе, мій Ісусе, нині віддаю!\n\nКуплет 2.\nВін поможе це зробити,  \nсилу духа дасть мені; \nЗ Ним я вічно буду жити \nтам, в небесній стороні.\n\nКуплет 3.\nЛиш з Ісусом я зумію  \nв світі хрест тяжкий нести, \nБо на Нього я надіюсь, \nщо Він може помогти.\n\nКуплет 4.\nСлава, честь Тобі, Ісусе,  \nза діла Твої святі, \nЩо відкрив для мене ясне \nСвітло правди в цім житті.', '', NULL, NULL),
(374, 'Як овечку Пастир сильний', NULL, 'Куплет 1 \nЯк овечку, Пастир сильний, \nТи вперед мене веди, \nНа Твої луги розкішні \nІ до тихої води. \nО Ісусе, о, Ісусе \nТи за мене кров пролив.\nО Ісусе, о, Ісусе \nТи за мене кров пролив.\n\nКуплет 2.\nНа землі будь мені Другом, \nВ світі цьому збережи; \nНас веди небесним лугом, \nА хто стомлений, держи. \nО, Ісусе, о, Ісусе, \nБудь зі мною Ти навік.\nО, Ісусе, о, Ісусе, \nБудь зі мною Ти навік.\n\nКуплет 3.\nДай, щоб серцем міг я вірно  \nЗаповіт лиш Твій любить; \nБлижнім всім служити щиро; \nО, Навчи в любові жить. \nО, Ісусе, о, Ісусе, \nБудь зі мною Ти навік.\nО, Ісусе, о, Ісусе, \nБудь зі мною Ти навік.', '', NULL, NULL),
(375, 'Дай що найкраще для Бога', NULL, 'Куплет 1 \nДай що найкраще для Бога, - \nсилу для Нього віддай; \nЙому віддай всі спромоги \nі за Христом вслід ступай. \nВін приклад для нас оставив, \nсміло за правду стояв, \nІ тяжко за нас страждав Він, \nу жертву життя віддав.\n\nПрипев: \nДай що найкраще для Бога, \nСилу для Нього віддай; \nЗ радістю йди на служення, \nВсім про спасіння звіщай.\n\nКуплет 2.\nДай що найкраще для Бога;  \nв серце Його ти впусти, \nІ для служення святого \nЙому усе присвяти. \nВесь на служення віддайся; \nВін за нас Сина віддав; \nЖити для Нього старайся, \nвсе, що найкраще віддай!\n\nКуплет 3.\nДай що найкраще для Бога,  \nВін тобі більше вже дав: \nВ небі оставив всю славу, \nв жертву Себе Він віддав. \nСтраждав за нас Він безвинно, \nЩоб від гріхів всіх спасти; \nДай Йому честь і хваління, \nвсе, що найкраще віддай!', '', NULL, NULL),
(376, 'Пастир добрий стережи нас', NULL, 'Куплет 1 \nПастир добрий, стережи нас, \nнаше щастя лиш в Тобі; \nДоглядай і підкріпляй нас, \nбо без Тебе ми слабі.\n\nПрипев: \nО, Ісусе, о, Ісусе, \nТи купив нас, ми Твої.\nО, Ісусе, о, Ісусе, \nТи купив нас, ми Твої.\n\nКуплет 2.\nМи бажаєм за Тобою,  \nТільки за Тобою йти; \nСам дорогою вузькою \nв Царство вічне нас веди.\n\nКуплет 3.\nВсіх прийняти Ти бажаєш,  \nКличеш кожного: прийди! \nВсі провини Ти прощаєш, \nхто довіриться Тобі.', '', NULL, NULL),
(377, 'Не дайся спокусі бо впадеш у гріх', NULL, 'Куплет 1 \nНе дайся спокусі, бо впадеш у гріх, \nУ Христі Ісусі будь взірцем для всіх. \nПроти зла борися, гніватись не смій, \nНа Христа дивися, Він Порадник є твій.\n\nПрипев: \nСпаса поклич на поміч, \nВін є щирий Друг твій; \nНе залишить в дорозі \nВін помічник є твій.\n\nКуплет 2.\nНе гріши у слові, не гріши в ділах;  \nА молися Богу, май Господній страх. \nСвято, чесно, мудро ти завжди живи, \nНа Христа дивися, Він Порадник є твій.\n\nКуплет 3.\nТому, хто воює вірою з гріхом,  \nБог вінець дарує і життя з Христом.\nБрате мій, бодрися і у вірі стій; \nНа Христа дивися, Він Порадник є твій.', '', NULL, NULL),
(378, 'Любо вірити в Ісуса', NULL, 'Куплет 1 \nЛюбо вірити в Ісуса, \nІ святим Його словам; \nЯ душею підношуся \nв край небесний, де Він Сам.\n\nПрипев: \nМій Спасителю, Ісусе, \nТи є добрий Пастир мій. \nМій Спасителю, Ісусе, \nЯ вже вічно буду Твій.\n\nКуплет 2.\nЯ надіюсь на Ісуса,  \nНа Його святу любов; \nЯ Йому служу й молюся, \nВін пролив за мене кров.\n\nКуплет 3.\nЯк приємно знати Бога,  \nДухом пробувати в Ним; \nПідкріплятись Його Словом \nі ходити завжди з Ним!', '', NULL, NULL),
(379, 'В долині паслася отара овець', NULL, 'Куплет 1 \nВ долині паслася отара овець, \nїх в Пастиря всіх було сто.\nїх в Пастиря всіх було сто. \nІ добрий їх Пастир стеріг, як Отець, \nале заблудилась одна;\nале заблудилась одна; \nВід Пастиря свого далеко зайшла, \nДо Нього вернутись сама не могла.\nДо Нього вернутись сама не могла.\n\nКуплет 2.\nДев''яносто дев''ять пасуться в гурті,  \nблукає одна в самоті.\nблукає одна в самоті. \nІ Пастир промовив: "А де ж та одна? \nлюблю всіх і люба вона.\nлюблю всіх і люба вона. \nПіду Сам за Нею по горах крутих, \nБажаю одну я привести до них.\nБажаю одну я привести до них.\n\nКуплет 3.\nІ Пастир ласкавий за нею пішов,  \nвсі гори й поля обійшов.\nвсі гори й поля обійшов. \nНад прірвою, бачить, овечка стоїть, \nПастир до неї спішить.\nПастир до неї спішить. \nКаміння і терен Його не здержав,\nВівцю погибаючу Він врятував.\nВівцю погибаючу Він врятував.\n\nКуплет 4.\nНа плечі спасенну овечку Він взяв,  \nз любов''ю її пригортав.\nз любов''ю її пригортав. \nНа пашу зелену її Він пустив, \nжиттям її Пастир зрадів.\nжиттям її Пастир зрадів. \nРадіють всі ангели, співи звучать, \nЇм любо за неї Творця прославлять.\nЇм любо за неї Творця прославлять.', '', NULL, NULL),
(380, 'Веди нас Месіє по стежці вузенькій', NULL, 'Куплет 1 \nВеди нас, Месіє, по стежці вузенькій, \nНе дай нам упасти на цьому шляху, \nЗміцни нашу віру до Тебе, Учителю, \nЩоб більше ми не служили гріху.\nЗміцни нашу віру до Тебе, Учителю, \nЩоб більше ми не служили гріху.\n\nКуплет 2.\nЯк тяжко тим людям, що Бога не знають,  \nЖиття безталанне, гірке, як полинь. \nЩасливі ті люди, що Бога шанують \nІ люблять Закон тільки Божий один.\nЩасливі ті люди, що Бога шанують \nІ люблять Закон тільки Божий один.\n\nКуплет 3.\nВеди нас, Месіє, до краю святого,  \nБо там ми побачимо славу Твою, \nВ молитві ми схилимо наші коліна, \nВіддавши сердечну пошану Творцю.\nВ молитві ми схилимо наші коліна, \nВіддавши сердечну пошану Творцю.\n\nКуплет 4.\nТам перед престолом Отця заспіваєм,  \nСплетемо вінок із пісень тих святих, \nСкладем на вівтар нашу жертву хваління \nЗа безліч Господніх дарів дорогих.\nСкладем на вівтар нашу жертву хваління \nЗа безліч Господніх дарів дорогих.', '', NULL, NULL),
(381, 'За євангельськую віру', NULL, 'Куплет 1 \nЗа євангельськую віру, \nза Христа ми стоїмо; \nЗло панує через міру, \nми з Ісусом підемо.\n\nПрипев: \nВсі єдиною сім''єю, \nна устах з святим псалмом, \nОдним серцем і душею \nза Спасителем Христом!\n\nКуплет 2.\nЧас прийшов палкого бою,  \nпанувати хоче гріх; \nБраття, з вірою святою \nповедем до Бога всіх!\n\nКуплет 3.\nЛюди Господа забули,  \nвідступили від Христа; \nЗвістимо їм, щоб почули: \n"Він є Правда і Життя!"\n\nКуплет 4.\nБудем сміло захищати  \nПравди Божий Заповіт \nІ Христа усім звіщати, \nхай Його приймає світ.', '', NULL, NULL),
(382, 'Могутня в нас твердиня  Бог', NULL, 'Куплет 1 \nМогутня в нас твердиня - Бог, \nВін понад всі твердині! \nВін захист є від всіх тривог \nв тяжку для нас годину. \nХай ворог повсякчас \nзгубити хоче нас; \nНе зможе подолать: \nСпас буде захищать, \nбо наша Він твердиня!\n\nКуплет 2.\nКоли б ми, браття, у борні  \nздались на власні сили, \nНапевно б сили зла страшні \nв змаганні нас зломили! \nЛиш Бог-Месія Сам \nє певна поміч нам: \nВін наш незмінний Спас, \nВін кров пролив за нас \nі знищив сили пекла.\n\nКуплет 3.\nІ хоч би цілий грізний світ  \nна нас піднявсь сьогодні, \nБог захистить нас, - Він наш щит; \nхвалім ім''я Господнє! \nГосподь твердиня нам! \nВін нас провадить Сам. \nБезсилля чи пітьма, - \nта з Ним страху нема: \nми з Ним - непереможні!', '', NULL, NULL),
(383, 'Непереможне знамено ми маєм', NULL, 'Куплет 1 \nНепереможне знамено ми маєм, \nВгору високо його піднесем! \nБог нам гріхи всі простив, - це ми знаєм, \nВ небо Він прийме, коли ми прийдем.\n\nПрипев: \nВслід за Ісусом, вслід за Ісусом \nРадісно в бій всі підем. \nЗ Ним переможем гріх і спокусу; \nВсі за Ісусом підем!\n\nКуплет 2.\nВсі ми покликані тут працювати,  \nТож закликаймо Христа всіх любить, \nТреба боротися й часом страждати, \nВ небо ж підем навік відпочить.\n\nКуплет 3.\nБог надає нам Свою допомогу,  \nВін поведе нас в обіцяний край, \nПевну одержим над злом перемогу, \nБогом спасеннеє серце, співай!', '', NULL, NULL),
(384, 'Я в безсмертя іду наступаю на зло', NULL, 'Куплет 1 \nЯ в безсмертя іду, наступаю на зло, - \nХоч скорботна і важка дорога. \nВ моїм серці тепер благодать і тепло, \nЦе тому, що я вірую в Бога.\nВ моїм серці тепер благодать і тепло, \nЦе тому, що я вірую в Бога.\n\nКуплет 2.\nЗнаю, де моя воля і в чому нема,  \nЗнаю доброго міру і злого; \nЗнаю, що я живу на землі не дарма; \nЦе тому, що я вірую в Бога.\nЗнаю, що я живу на землі не дарма; \nЦе тому, що я вірую в Бога.\n\nКуплет 3.\nПроти істини військо веде сатана,  \nДухи зла повстають у двобої. \nІ чекає мене неземна сторона, \nЦе тому, що я вірую в Бога.\nІ чекає мене неземна сторона, \nЦе тому, що я вірую в Бога.\n\nКуплет 4.\nІ, коли навіть бачу сліди катастроф,  \nХоч з''являється в серці тривога, \nЯк подумаю я, що є люблячий Бог – \nЯ спокійний, бо вірую в Бога.\nЯк подумаю я, що є люблячий Бог – \nЯ спокійний, бо вірую в Бога.\n\nКуплет 5.\nТішить радість без слів: Бог до щастя привів,  \nМною знайдена в небо дорога. \nГріє душу мою благодатне тепло, \nЦе тому, що я вірую в Бога.\nГріє душу мою благодатне тепло, \nЦе тому, що я вірую в Бога.', '', NULL, NULL),
(385, 'Боже милий я благаю', NULL, 'Куплет 1 \nБоже милий, я благаю: \nне забудь мене, згадай! \nВід страждань земного краю \nмені захист, поміч дай.\n\nПрипев: \nПевно знаю, що з Тобою \nв цьому світі я пройду; \nХоч з тяжкою боротьбою, \nале в світлий рай ввійду.\n\nКуплет 2.\nТемна ніч панує всюди,  \nчасом серце так болить \nІ нема рятунку в людях, \nБоже, тяжко в світі жить!\n\nКуплет 3.\nГрішний в світі я блукаю,  \nв серці радости нема. \nЯ з Тобою жить бажаю, \nбо без Тебе горе й тьма.\n\nКуплет 4.\nБоже, Боже, покладаюсь  \nя на Тебе, - Ти спасеш; \nВід гріха, плачу й відчаю \nв світлий рай мене візьмеш.', '', NULL, NULL),
(386, 'За Ним піду усюди я', NULL, 'Куплет 1 \nЗа Ним піду усюди я, \nбо вірить вся душа моя,\nЩо то за гріх мій у житті \nВін був розп''ятий на хресті.\n\nПрипев: \nХристос зо мною завжди є, \nкерує Він життям моїм; \nОхороняє кожен час, \nвід вічних мук мене Він спас!\n\nКуплет 2.\nЙого любов''ю я живу,  \nпроклав Він путь мені нову, \nХоч часом тяжко йти мені – \nджерела сили у Христі.\n\nКуплет 3.\nЯ йду вперед і не боюсь,  \nЙому я вірю і молюсь; \nі Слово Боже вчить мене – \nдо раю віра приведе.', '', NULL, NULL),
(387, 'Я Ісуса голос чую', NULL, 'Куплет 1 \nЯ Ісуса голос чую,\nЯ Ісуса голос чую, \nЯ Ісуса голос чую, \nТи візьми хреста й за Мною йди!\n\nКуплет 2.\nЯ піду за Ним усюди, \nЯ піду за Ним усюди, \nЯ піду за Ним усюди, \nКуди тільки Він Сам поведе.\n\nКуплет 3.\nДай мені Твоїх сил, Христе, \nДай мені Твоїх сил, Христе,\nДай мені Твоїх сил, Христе, \nЩоб з Тобою завжди міг іти.\n\nКуплет 4.\nПоборю всі перешкоди, \nПоборю всі перешкоди, \nПоборю всі перешкоди, \nІ ввійду за Ним я в дім Отця.\n\nКуплет 5.\nТам вінця хвали прийму я, \nТам вінця хвали прийму я, \nТам вінця хвали прийму я, \nЗ рук Ісуса, Спаса, в вічності.\n\nКуплет 6.\nО, душе моя, будь мужня! \nО, душе моя, будь мужня! \nО, душе моя, будь мужня! \nВже твій Спас, Христос, по тебе йде.', '', NULL, NULL),
(388, 'За Христом іду я о мій милий Боже', NULL, 'Куплет 1 \nЗа Христом іду я, о мій милий Боже, \nХто ж мені в тяжкій дорозі допоможе? \nЗміцнюй моє серце й духа боязкого, \nСам навчи ходити по слідах Святого.\n\nКуплет 2.\nЗа Христом іду я, голос Його любий  \nКличе в Нім спастися від гріха та згуби, \nСлово це цінніше скарбу золотого, \nРадить йти за Спасом, геть від світу злого.\n\nКуплет 3.\nЗа Христом іду я, Божий Син для мене те,  \nЩо в часи спеки дерево зелене: \nВ Нім знайду я захист, тінь і прохолоду. \nТож піду за Спасом до свого народу.\n\nКуплет 4.\nЗа Христом іду я, Ним я від геєни  \nКров''ю на Голгофі на хресті спасений. \nСмерть Його з страшної вирвала безодні, \nТо ж піду за Спасом любим вже сьогодні.\n\nКуплет 5.\nЗа Христом іду я, жодна в світі сила  \nЗ Його рук не вирве мене до могили. \nХай на цій дорозі Дух Святий Твій Боже, \nЙти Його слідами мені допоможе.', '', NULL, NULL),
(389, 'На Христа дивися Він взірець тобі', NULL, 'Куплет 1 \nНа Христа дивися, Він взірець тобі. \nВіруй і молися, - поміч Він в журбі. \nВін помер за тебе, взяв твій гріх Він Сам, \nУ твоїй потребі вір Його словам.\n\nКуплет 2.\nНа Христа дивися, йди за Ним услід,  \nГаряче молися й принеси свій плід; \nТи хоч і безсилий в боротьбі з гріхом, \nСпас є твоя сила, йди Його шляхом.\n\nКуплет 3.\nНа Христа дивися, й твердо в вірі стій,  \nПеред Ним смирися, Він Спаситель твій. \nПоки день ясніє, й ніч ще не прийшла, - \nВіра хай міцніє в Господі твоя.\n\nКуплет 4.\nНа Христа дивися, вірним Йому будь,  \nІ коли скінчиться ця скорботна путь, \nЦя важка дорога прийде до кінця, \nВід Святого Бога матимеш вінця.', '', NULL, NULL),
(390, 'Ти знаєш шлях хоч я його не знаю', NULL, 'Куплет 1 \nТи знаєш шлях, хоч я його не знаю, \nПанує спокій у душі моїй; \nЧому ж мені тривожитись, боятись, \nКоли я певно знаю: Ти Бог мій!\n\nКуплет 2.\nТи знаєш все: коли і звідки вітер,  \nЯк можна бурю в тишу привести. \nХоч не знайомий шлях, яким іду я, \nТа я спокійний - шлях мій знаєш Ти.\n\nКуплет 3.\nТи знаєш шлях, майбутнє все Ти знаєш,  \nТи план давно приготував мені; \nСердечно я люблю Тебе і славлю \nЗа ласку, за турботи всі Твої!', '', NULL, NULL),
(391, 'Не знаю що чекає мене на цій землі', NULL, 'Куплет 1 \nНе знаю, що чекає мене на цій землі, \nЖиття моє злітає, мов в вирій журавлі. \nГосподь накреслив шлях життя до вічного буття.\nГосподь накреслив шлях життя до вічного буття.\n\nПрипев: \nКуди Господь провадить, \nЯ скрізь за Ним піду, \nНіколи Він не зрадить, \nЯкщо я з Ним іду.\n\nКуплет 2.\nСвіт темрява вкриває, вперед так тяжко йти;  \nБог світло розливає в долині марноти. \nВ час бурі Сам зі мною йде, підтримує й веде.\nВ час бурі Сам зі мною йде, підтримує й веде.\n\nКуплет 3.\nВперед іду й не знаю майбутніх днів моїх;  \nТворцеві довіряю у всіх путях земних. \nЗ Ним легко долом смерті йти у край небес святих.\nЗ Ним легко долом смерті йти у край небес святих.', '', NULL, NULL),
(392, 'Будем браття жити свято', NULL, 'Куплет 1 \nБудем, браття, жити свято, \nдалі все від марноти; \nІ в єднанні, як брат з братом, \nбудем за Христом іти. \nНас Христос прийняв з любов''ю, \nстанем тішитися ми, \nІ обмиті Його кров''ю – \nбудем світлом між людьми.\n\nКуплет 2.\nЯк незрячі ми блукали,  \nсмерть за нами всюди йшла, \nА любов Христа шукала \nі, знайшовши, нас спасла. \nДухом ми були убогі, \nа Христос багатства дав, \nНам відкрив святу дорогу, \nвічний рай приготував.\n\nКуплет 3.\nСеред горя і страждання  \nне відійдем від мети, \nПідем далі без вагання \nдо святої висоти.\n \nІ ніхто на всьому світі \nнас не може подолать, \nБо Христос, по Заповіту, \nбуде нас охоронять.', '', NULL, NULL),
(393, 'Ой куди піду ще я', NULL, 'Куплет 1 \nОй, куди піду ще я? \nДе мені шукать спасіння? \nДе знайде душа моя \nспокій для свого сумління?\n\nКуплет 2.\nСкрізь по світі я ходив,  \nсерце радості шукало; \nЩастя світ не подарив, \nсерцю ще сумніше стало.\n\nКуплет 3.\nДо людей більш не піду  \nправди, щастя в них шукати; \nБоже мій, до Тебе йду, \nщоб з Тобою пробувати.\n\nКуплет 4.\nЛиш у Тебе Одного,  \nмоя сила для терпіння \nІ від горя я свого \nзнайду втіху і спасіння.\n\nКуплет 5.\nО, прийми, прийми мене,  \nБоже правди і любови; \nХай гріховне все мине, \nдай життя почати нове.', '', NULL, NULL),
(394, 'Як приємно йти з Ісусом', NULL, 'Куплет 1 \nЯк приємно йти з Ісусом, \nДобрим Господом моїм; \nПо Його слідах ступати \nі ходити лиш за Ним.\n\nПрипев: \nТож піду за Спасом всюди, \nде лиш тільки поведе; \nЗ Ним ідуть спасенні люди, \nВін їх в небо приведе.\n\nКуплет 2.\nЯк безпечно йти з Ісусом  \nта при помочі Його; \nЙти усюди, де веде Він, \nдо кінця життя мого.\n\nКуплет 3.\nЯ крокую за Ісусом,  \nкожен день усе за Ним; \nХоч я немічний, безсилий, \nале силу маю в Нім.\n\nКуплет 4.\nО, тримай мене, мій Спасе,  \nу Твоїй руці святій, \nЩоб усюди й завжди бачив \nя прекрасний образ Твій!', '', NULL, NULL),
(395, 'Куди піду куди від Тебе', NULL, 'Куплет 1 \nКуди піду, куди від Тебе, \nХристе, Христе, куди іти? \nДе зможу я навік для себе \nСпокій і мир душі знайти.\nДе зможу я навік для себе \nСпокій і мир душі знайти.\n\nКуплет 2.\nХто мені скаже правди слово?  \nВ розбите серце силу дасть? \nЩоб я тонув в святій любові \nІ міг її братам подать?\nЩоб я тонув в святій любові \nІ міг її братам подать?\n\nКуплет 3.\nХіба піду, де розлилися  \nБезжурний сміх та п''яний спів? \nЯ там вже був, там я томився, \nТам чорна хмара темних днів.\nЯ там вже був, там я томився, \nТам чорна хмара темних днів.\n\nКуплет 4.\nЯк цвіт на квітці засихає,  \nЯк лист пожовкне, облетить. \nТакий кінець їх всіх чекає. \nО, ні, не можу це любить.\nТакий кінець їх всіх чекає. \nО, ні, не можу це любить.\n\nКуплет 5.\nКуди піду, куди від Тебе,  \nХристе, Христе, куди піду? \nЗ Тобою буду, бо без Тебе \nНіде я щастя не знайду.\nЗ Тобою буду, бо без Тебе \nНіде я щастя не знайду.', '', NULL, NULL),
(396, 'Я люблю з Христом ходити', NULL, 'Куплет 1 \nЯ люблю з Христом ходити \nяк апостоли колись, \nЩо неначе добрі діти \nбатька слухати зійшлись. \nЗавжди чути я готовий, \nбез утоми, без кінця, \nЙого любе дивне Слово \nпро небесного Отця.\n\nПрипев: \nЯ піду за Спасом всюди; \nЯ там буду, де Він буде; \nЗ Ним піду, де поведе Він, \nСкрізь, куди піде лиш Божий Син.\n\nКуплет 2.\nЯ люблю в моїй уяві  \nна Голгофі бути ще \nЙ споглядати на святії \nруки, ноги і лице; \nУ стражданні співчувати, \nяк Він тяжко умирав. \nЩоб мені спасіння дати, \nВін на Себе кару взяв.\n\nКуплет 3.\nПрийде час, і в небі тихім  \nя побачу вічний дім; \nІ, забувши горе й лихо, \nза Христом піду моїм \nОглядати буду вічно \nвсю красу небесних див; \nЙ розкажу Йому, як сильно \nна землі Його любив.', '', NULL, NULL),
(397, 'За Христом готовий всюди завжди іти', NULL, 'Куплет 1 \nЗа Христом готовий всюди завжди іти, \nДе жива вода, там де запашні квітки. \nБуду скрізь ходити завжди тільки лиш за Ним, \nРадісно ступати по слідах святих.\n\nПрипев: \nЗа Христом піду завжди всюди, \nСкрізь піду за Ним, за моїм Ісусом, \nЗа Христом піду, за Христом піду, \nДе б мене Він не повів, я піду за Ним.\n\nКуплет 2.\nЗа Христом готовий всюди завжди іти,  \nХоч потоки грізнії і шумлять вітри; \nПід Його рукою я нічого не боюсь, \nВін – мій вірний захист, бурі не страшусь.\n\nКуплет 3.\nЗа Христом готовий всюди завжди іти,  \nПо долинах чи по горах буде Він нести; \nЗнаю, проведе мене Він по Своїх слідах \nВ радість вічну, де святі всі в небесах.', '', NULL, NULL),
(398, 'Не падай духом а борись', NULL, 'Куплет 1 \nНе падай духом, а борись, \nБог не забув тебе, \nІ завжди ти Йому молись, \nБог захистить тебе.\n\nПрипев: \nБог захистить тебе \nв руках Своїх, в путях твоїх. \nБог захистить тебе. \nБог захистить й спасе, (й спасе).\n\nКуплет 2.\nСеред земних твоїх трудів  \nБог не забув тебе, \nІ небезпека як прийде, \nБог захистить тебе.\n\nКуплет 3.\nПотреби знає Він твої,  \nБог не забув тебе; \nВін кращу долю дав тобі, \nБог захистить тебе.\n\nКуплет 4.\nНе бачиш світла у житті,  \nБог не забув тебе; \nСпіши знайти спокій в Христі, \nБог захистить тебе.', '', NULL, NULL),
(399, 'Спокійна будь душе з тобою Бог', NULL, 'Куплет 1 \nСпокійна будь, душе, з тобою Бог, \nБез нарікань неси хреста в житті. \nВін вірним є у час журби, тривог. \nПоможе Він у боротьбі. \nСпокійна будь, душе, бо всюди йде \nз тобою Він, і в радість приведе.\n\nКуплет 2.\nСпокійна будь, душе, з тобою Він,  \nІ проведе, як дотепер провів. \nВ надії певна будь, що Божий Син \nВідкриє тайни вічности віків. \nСпокійна будь, бо навіть буревій \nЗатихне вмить від Його вічних слів.\n\nКуплет 3.\nСпокійна будь, душе, надходить час,  \nІ скоро ти підеш у вічний край. \nВсе горе, сум і страх залишить нас. \nНастане щастя, радість, вічний рай. \nСпокійна будь, душе моя, в цю мить, \nГосподь тебе від болів всіх звільнить.', '', NULL, NULL),
(400, 'Коли життя тихо тече мов ріка', NULL, 'Куплет 1 \nКоли життя тихо тече мов ріка, \nАбо навістить буревій: \nДовірившись Богу, в Його я руках \nМаю захист, спасіння, спокій.\n\nПрипев: \nВін завжди мій Господь, \nЯ у Ньому знаходжу спокій.\n\nКуплет 2.\nО, що за любов, що у ній я придбав  \nСпасіння і вічне життя! \nІ з ласки Його я наслідником став, \nДарував Він нетлінне буття.\n\nКуплет 3.\nО, Боже, чекаю я славного дня:  \nКоли Ти вже вдруге прийдеш, \nЗодягнеш спасенних в нетлінне буття, \nВ свою славу безсмертя введеш.\n\nПрипев: \nВін завжди мій Господь,\nВічно буду я з Ним в небесах!', '', NULL, NULL),
(401, 'Промінь сонця за горою спалахнув і згас', NULL, 'Куплет 1 \nПромінь сонця за горою спалахнув і згас. \nБоже наш, зостанься з нами в цей вечірній час. \nНічка темна покриває зло та гріх землі. \nБіля Спаса спочивають душі вірні всі.\n\nКуплет 2.\nВівчарі спішать поїти перед сном овець. \nМоже Бог задовільнити спрагу всіх сердець. \nВін, як Пастир, їх потреби знає в кожну мить, \nНіжно пригорне до Себе, від зла захистить.\n\nКуплет 3.\nЗемлю всюди покриває безпросвітна мла,  \nЧорну справу починає ворог-сатана, \nТа коли до нас він прийде хитро спокушать, \nВірю: Бог назустріч вийде - буде захищать!\n\nКуплет 4.\nПромінь сонця за горою спалахнув і згас...  \nЗалишайся, Боже, з нами в цей вечірній час, \nКоли смерти ніч настане, в темряві світи;\nВід земного мандрування Ти нас в рай візьми.', '', NULL, NULL),
(402, 'О тяжко дуже тяжко у грішнім світі жить', NULL, 'Куплет 1 \nО, тяжко, дуже тяжко у грішнім світі жить; \nХто душу заспокоїть, утішить, захистить?\n\nПрипев: \nХристос, тільки Він,\nХристос, тільки Він, \nХристос, тільки Він \nТебе потішить тут Один!\n\nКуплет 2.\nЯ в горі і печалі, недоля навкруги;  \nХто витре мої сльози і поміч дасть мені?\n\nКуплет 3.\nГріхи мене лякають, на суд боюсь прийти;  \nРятунку я чекаю і втіхи назавжди.', '', NULL, NULL),
(403, 'Часто буря грізна у твоїм житті', NULL, 'Куплет 1 \nЧасто буря грізна у твоїм житті, \nНиє серце стомлене; тривожні дні, \nМилість і любов Господню пригадай, \nСміло далі йди, надії не втрачай.\n\nПрипев: \nМилість і любов Господню пригадай, \nСміло далі йди, надії не втрачай, \nПригадай, як Він грішних полюбив, \nДивуватись будеш, що Він Сам звершив.\n\nКуплет 2.\nЧасом тяжке горе на душі лежить,  \nСерце сум сповив глибокий, тяжко жить, \nМилість і любов Господню пригадай, \nСерце просвітліє, зникне сум, відчай.\n\nКуплет 3.\nНа Христа дивися і Його благай,  \nПісля сліз і горя ввійдеш в Божий край. \nМилість і любов Господню не забудь, \nБурі і страждання наші всі минуть.', '', NULL, NULL),
(404, 'Мій Бог є скеля в Ньому я', NULL, 'Куплет 1 \nМій Бог є скеля, в Ньому я \nсховаюсь під час бурі; \nУ спокій свій введе мене – \nзі мною завжди буде.\n\nПрипев: \nІсус джерелом є в землі сухій,\nв землі сухій, в землі сухій; \nІсус джерелом є в землі сухій \nі захистом в час бурі.\n\nКуплет 2.\nІ ворог хоч мене страшить –  \nмене Спаситель захистить. \nЯк гори стануть на путі, \n"Не бійся!" - чую я тоді.\n\nКуплет 3.\nМій Бог - Отець небесний мій  \nі захист під час бурі; \nНадійний, вічний і святий \nмій захист під час бурі.', '', NULL, NULL),
(405, 'Страшно бушує життєвеє море', NULL, 'Куплет 1 \nСтрашно бушує життєвеє море, \nХвилі мій човен так нещадно б''ють; \nВ смертній тривозі, в великому горі, \nБоже, молюся: не дай потонуть!\nВ смертній тривозі, в великому горі, \nБоже, молюся: не дай потонуть!\n\nКуплет 2.\nЗглянься, о, Боже спаси і помилуй,  \nЗ днів моїх ранніх в житті я борюсь; \nБільше боротись не маю вже сили, \nБоже помилуй! - до Тебе молюсь!\nБільше боротись не маю вже сили, \nБоже помилуй! - до Тебе молюсь!\n\nКуплет 3.\nНе залишай мій човен в хвилях моря,  \nБоже мій милий, о, Боже благий! \nБлизько вже берег небесний, І скоро \nТам лиш знайду для душі я спокій.\nБлизько вже берег небесний, І скоро \nТам лиш знайду для душі я спокій.', '', NULL, NULL),
(406, 'Не зупиняйся хоч темрява й зло', NULL, 'Куплет 1 \nНе зупиняйся, хоч темрява й зло, \nдні невідомі твої, \nСерце в недолі тяжкій знемогло, - \nБог допоможе тоді.\n\nКуплет 2.\nЗнай, по стежині з тобою іде  \nТой, Хто весь світ полюбив, \nЧерез темряву Він Сам проведе, \nщоби у небі з Ним жив.\n\nКуплет 3.\nНе зупиняйся, хоч темрява й зло,  \nсилу в молитві знайди, \nВ ній є спокій, життєдайне тепло, \nв небо сміливо іди.', '', NULL, NULL),
(407, 'На шляху життя сміліше ми підем', NULL, 'Куплет 1 \nНа шляху життя сміліше ми підем, \nЯкщо будем довірять Ісусу; \nСилу Божу для роботи ми знайдем, \nЯкщо будем довірять Ісусу.\n\nПрипев: \nПроясніє тоді шлях, \nРадість буде нам в серцях, \nСпіви слави на устах, \nЯкщо будем довірять Ісусу.\n\nКуплет 2.\nОбітниці Божі стануть нам ясні,  \nЯкщо будем довірять Ісусу; \nЛаска Господа наповнить нас в житті, \nЯкщо будем довірять Ісусу.\n\nКуплет 3.\nВолю Божу ми научимось чинить,  \nЯкщо будем довірять Ісусу; \nЗ Ним у вічній славі будемо ми жить, \nЯкщо будем довірять Ісусу.', '', NULL, NULL),
(408, 'О душе бодрися Я  Спаситель Твій', NULL, 'Куплет 1 \n"О, душе, бодрися! Я - Спаситель Твій! \nЗавжди лиш дивися на світильник Мій. \nНа шляху тернистім руку Я подам, \nЯ з тобою всюди, - Вір, що уже ти не сам".\n\nПрипев: \nНі, я не один. Ні, я не один. \nМій Бог мене не залишить.\nНі, не залишусь один!\nНі, я не один. Ні, я не один. \nМій Бог мене не залишить.\nНі, не залишусь один!\n\nКуплет 2.\nЛілії пов''януть, сонце теж зайде, \nАле пісня слави Господу живе. \nХоч бушує буря уночі чи вдень, - \nВсюди Спас зі мною, з Ним тепер не один.\n\nКуплет 3.\nХоч мені і важко йти шляхом життя,  \nЧую Божий голос: "Ти - Моє дитя!"\nВірю, що Спаситель вірних захистить, \nІ спасенні душі будуть у небі з Ним жить.', '', NULL, NULL),
(409, 'Всі обітниці Господні будуть', NULL, 'Куплет 1 \nВсі обітниці Господні будуть, \nНам Слово Боже це запевняє; \nІ хоч би сгасла в житті надія, \nЩо обіцяв Бог - те дасть.\n\nПрипев: \nЩо обіцяв Бог - того не змінить, \nХоч би на світі змінилось все,\nХоч би зірки всі погасли в небі – \nБог обітниці збереже.\n\nКуплет 2.\nВ часи страждання, коли темніє,  \nНадія гасне, росте зневіра, \nЛиш обітниці дають утіху: \nЩо обіцяв Бог - те дасть.\n\nКуплет 3.\nКоли спокуси мене тривожать –  \nГосподня сила зміцняє душу; \nІ я радію в святій надії: \nЩо обіцяв Бог - те дасть.\n\nКуплет 4.\nКоли воскреснуть всі діти Божі  \nІ ангели нас зустрінуть в небі, \nВсіх переможців вінці чекають: \nЩо обіцяв Бог - те дасть.', '', NULL, NULL),
(410, 'Вірю я в обітниці Христа Царя', NULL, 'Куплет 1 \nВірю я в обітниці Христа Царя! \nВ серці вже моїм зійшла нова зоря. \nХай Йому звучить в мені хвала свята, \nВірю я в обітниці Христа!\n\nПрипев: \nВірю, вірю, вірю я \nВ обітниці Христа!\nВірю, вірю, вірю я \nВ обітниці Христа!\n\nКуплет 2.\nВірю я в обітниці, Йому хвала!  \nНе боюся я скорбот, гріха та зла. \nБез Ісуса в світі цім все марнота, \nВірю я в обітниці Христа!\n\nКуплет 3.\nВірю я в обітниці, живу з Христом,  \nВизнаю Його моїм усім єством, \nІ співаю пісню слави з торжеством, \nВірю я в обітниці Христа!\n\nКуплет 4.\nВірю я в обітниці, бо в них кріплюсь,  \nЛаскою Спасителя завжди хвалюсь, \nПеред Його троном в небі поклонюсь, \nВірю я в обітниці Христа!', '', NULL, NULL),
(411, 'Не покину Я вас не забуду –', NULL, 'Куплет 1 \n"Не покину Я вас, не забуду!" – \nТак Бог каже тобі і мені. \n"Я про вас турбуватися буду \nУ стражданнях тяжких на землі.\n\nКуплет 2.\nБуду в праці Я вам помагати,  \nБуду силу і міць подавать, \nІ в годину сердечної втрати \nБуду в душу бадьорість вливать.\n\nКуплет 3.\nНе покину Я вас, не забуду;  \nКоли батько, і мати, й рідня \nВідречуться від вас, то Я буду\nРідним батьком для вас з того дня.\n\nКуплет 4.\nНіжно буду Я вас доглядати,  \nТак, як мати маленьке дитя, \nВід усякого зла захищати \nІ провадить у вічне життя.\n\nКуплет 5.\nЯ самотнєє серце розважу,  \nСумні думи Я геть віджену, \nІ розбите життя Я поладжу, \nДух засмучений в вас підкріплю".', '', NULL, NULL),
(412, 'Коли в темряві буревій', NULL, 'Куплет 1 \nКоли в темряві буревій \nопівночі завиє, \nСльоза гірка спаде із вій,\nта серденько заниє,\n\nПрипев: \nІди скоріш, Спаситель твій \nтебе давно чекає; \nУтре Він сльози із очей, \nвведе тебе до раю.\n\nКуплет 2.\nКоли минуть юначі дні  \nі тяжко їх забути, \nІ в грудях збудять жаль вони \nза тим, що не вернути,\n\nКуплет 3.\nКоли життя ти змарнував,  \nі мрії повтікали, \nЙ тепер лиш згадок час настав, \nй надії позникали,\n\nКуплет 4.\nКоли не можеш йти туди,  \nкуди лиш глянуть очі, \nДруже, до Господа іди, \nтебе спасти Він хоче.', '', NULL, NULL),
(413, 'Коли втомлений в дорозі', NULL, 'Куплет 1 \nКоли втомлений в дорозі \nти спіткнешся, друже мій, \nТільки завжди будь у Бозі, \nВін тягар нестиме твій.\n\nКуплет 2.\nТільки Він у дні тяжкії  \nдопоможе й сили дасть; \nДо грудей Своїх пригорне \nй віджене усю напасть.\n\nКуплет 3.\nТільки Він, Творець Всесвіту,  \nможе зняти твій тягар \nІ в Своїй крові обмити, \nі найкращий дати дар.\n\nКуплет 4.\nТільки Той, Хто Сам з могили  \nвстав і світло всім приніс, \nМоже дати людям сили \nподолати всякий гріх.', '', NULL, NULL),
(414, 'Не сумуй ти душе дорогая', NULL, 'Куплет 1 \nНе сумуй ти, душе дорогая, \nНе журися, а радісна будь; \nНезабаром ввійдеш ти до раю, \nСпас нас любить - про це не забудь.\n\nКуплет 2.\nУповай ти на Господа Бога  \nІ частіше молися в тиші – \nІ затихне на серці тривога, \nІ настане спокій для душі.\n\nКуплет 3.\nХоч бушує життя, наче морє,  \nЧути всюди страшний буревій, \nАле глянь ти з надією в гору, \nЯк пильнує з любов''ю Бог твій.\n\nКуплет 4.\nНе забудь, що Христос задля тебе  \nПостраждав і помер на хресті; \nВін з любов''ю веде тебе в небо, \nВін з тобою і тут на землі.\n\nКуплет 5.\nВже не довго нам тут сумувати,  \nВсім тривогам настане кінець; \nМи підем до Христа спочивати \nІ одержимо славний вінець.\n\nКуплет 6.\nНе сумуй ти, душе дорогая,  \nНе журися, не плач, не зітхай, - \nВ небесах нас блаженство чекає, \nЖиття вічне, і радість, і рай.', '', NULL, NULL),
(415, 'Чому твої очі сльозами блищать', NULL, 'Куплет 1 \nЧому твої очі сльозами блищать, \nЧому рани серця болять і болять? \nІ сумніви, й смутки пригнобили враз, \nІ вогник молитви святої погас.\n\nКуплет 2.\nЧи віри забракло у серці твоїм,  \nЧи втратив надію на Бога зовсім? \nТвій Бог так великий, Всесильний, згадай, \nДо Нього з молитвою ти поспішай.\n\nКуплет 3.\nЯк тільки до Спаса в молитві прийдеш –  \nТоді ти і радість і спокій знайдеш.\nЗагояться рани, твій дух оживе \nІ радісна пісня з душі попливе.', '', NULL, NULL),
(416, 'Коли горе нам на серце ляже', NULL, 'Куплет 1 \nКоли горе нам на серце ляже, \nСкажем Ісусу, скажем Ісусу; \nКоли душу смуток дуже зв''яже, \nСкажем Ісусу про все.\n\nПрипев: \nСкажем Ісусу, скажем Ісусу, \nВін є Друг, що знає все; \nНема брата кращого в цім світі, \nЯк наш Спаситель Христос.\n\nКуплет 2.\nКоли сльози спокій наш порушать,  \nСкажем Ісусу, скажем Ісусу; \nКоли тайні гріхи душу мучать, \nСкажем Ісусу про все.\n\nКуплет 3.\nКоли бачим, що біда приходить,  \nСкажем Ісусу, скажем Ісусу; \nКоли горе або смерть надходить, \nСкажем Ісусу про все.\n\nКуплет 4.\nКоли важко в світі цьому жити,  \nСкажем Ісусу, скажем Ісусу; \nКоли в Божім Царстві хочем бути, \nСкажем Ісусу про все.', '', NULL, NULL),
(417, 'Як сумно буває мені', NULL, 'Куплет 1 \nЯк сумно буває мені, \nколи я не бачу Христа, \nСпокою не має тоді, \nзмовкають, неміють вуста.\n\nКуплет 2.\nІ ніби все спить навкруги,  \nі місяць, і зорі смутні, \nНе тішать ні гай, ні луги, \nскорботно на серці в ті дні.\n\nКуплет 3.\nВ Ісусі все щастя моє,  \nз Ним радісно в світі іду; \nКоли Він зі мною живе, \nспіваю Йому я хвалу.', '', NULL, NULL),
(418, 'Коли твоє серце від мук заболить', NULL, 'Куплет 1 \nКоли твоє серце від мук заболить, \nІ тяжко, і скорбно тобі буде жить, \nІди до Ісуса, скажи все Йому; \nВін в горі поможе, розвіє всю тьму.\n\nКуплет 2.\nВін бачить і знає всі сльози твої,  \nІ хоче згори дати сили тобі. \nПізнаєш ти знову спасіння Христа, \nІ пісня хваління поллється свята.\n\nКуплет 3.\nНещасних багато, блукають вони;  \nВтомились, страждають в дорозі земній. \nСкоріше скажи їм про Спаса Христа, \nЩо вмер Він за грішних і дав їм життя.', '', NULL, NULL),
(419, 'Коли ти знеможений будеш в безсиллі', NULL, 'Куплет 1 \nКоли ти знеможений, будеш в безсиллі, \nОслабнеш в нерівній, тяжкій боротьбі, \nІ краплю по краплі із чаші страждання \nПить будеш з докором ти долі своїй, \nДушею не падай, вперед іди знов; \nЄ віра, надія, любов.\n\nКуплет 2.\nКоли твоє серце заниє порою  \nІ прийдуть сумні та безрадісні дні, \nДуша не почує ні слова спокою, \nніхто їй не скаже: "Іди, відпочинь!" \nЗгадай, що зігріє і душу, і кров, - \nЦе віра, надія, любов.\n\nКуплет 3.\nКоли у твоєму житті буде втрата –  \nНе плач безутішно, в журбу не впадай;\nЗнай: доля така є від Бога, мій брате, \nПризначення всяке від Нього приймай. \nТоді твою душу порадує знов \nІ віра, й надія, й любов.\n\nКуплет 4.\nНе стане терпіння, ослабнуть всі сили, \nУ сумнівах буде тонути душа – \nОдну бережи в серці ціль до могили, \nБо навіть в стражданнях нам любе життя. \nНайбільше нам щастя у тому лежить – \nНадіятись, вірить, любить.', '', NULL, NULL),
(420, 'Сховай своє горе від людських очей', NULL, 'Куплет 1 \nСховай своє горе від людських очей, \nЙ без тебе сліз досить і горя в людей; \nМолися до Того, Хто поміч дає: \nСкажи ти Христові про горе твоє.\n\nКуплет 2.\nХристос усе знає та бачить усе, \nй твого Він хреста на Собі понесе; \nВін гірко страждав тут в тяжкій боротьбі,\nВідкрий все Йому, Він поможе тобі.\n\nКуплет 3.\nКоли твоє горе Він з тебе здійме,  \nТоді твоїм ближнім вчини те саме: \nДо всіх ти з любов''ю та ласкою йди \nІ їх визволяй від нещастя й біди.', '', NULL, NULL),
(421, 'В Божім спасінні укрийся', NULL, 'Куплет 1 \nВ Божім спасінні укрийся, \nЗмучений горем - трудом; \nКров''ю Ісуса обмийся, \nСтомлений друже, гріхом. \nДушу тривожить спокуса? – \nПоміч чекай від Ісуса, \nВ Ньому знайдеш відпочинок \nО, стомлений друже, гріхом!\nО, стомлений друже, гріхом!\n\nКуплет 2.\nІсус тебе не забуде, \nВін твій тягар понесе, \nСилою й захистом буде, \nСльози з очей Сам зітре. \nБачить твої Він страждання, \nВсі заспокоїть зітхання, \nПлач віддалить і ридання, \nВсі сльози з очей Сам зітре.\nВсі сльози з очей Сам зітре.', '', NULL, NULL),
(422, 'Коли б я мав крила орлині', NULL, 'Куплет 1 \nКоли б я мав крила орлині, \nпіднятися в небо умів, - \nСпішив би в простори святії \nІ Божою б силою жив.\n\nКуплет 2.\nУ світлі небесні блакиті,  \nде радість і спокій царить, \nСкоріше бажаю летіти, \nвід горя земного спочить.\n\nКуплет 3.\nУ межі тієї країни, \nде Спас мій у славі сія, \nУ місто, де ясписні стіни, \nщодня лине думка моя.\n\nКуплет 4.\nО, Боже, дай віри міцної  \nі сили свій хрест пронести; \nТи можеш Своєю рукою \nдо неба мене провести.', '', NULL, NULL),
(423, 'Тільки в Бозі душі є спокій', NULL, 'Куплет 1 \nТільки в Бозі душі є спокій; \nБо у Нього спасіння моє! \nБо твердиня Він моя, \nСкеля Він моя міцна, \nО, душе, тільки в Бозі Тобі є спокій.\n\nКуплет 2.\nТільки в Бозі душі є спокій,  \nБо у Ньому надія моя! \nВін втішає кожен час, \nЙого сила й слава в нас, \nО, душе, тільки в Бозі Тобі є спокій.\n\nКуплет 3.\nТільки в Бозі душі є спокій, \nТи на Нього надійся всяк час! \nВиливай лиш перед Ним \nСерце ти своє завжди; \nО, душе, тільки в Бозі Тобі є спокій.\n\nКуплет 4.\nТільки в Тобі, душі є спокій,  \nБо це милість Твоя, Царю мій! \nОдин раз бо Ти сказав, \nДвічі чув від Тебе я;\nЩо сила у Бога Ісуса Христа.', '', NULL, NULL),
(424, 'Не знаю я чому мені', NULL, 'Куплет 1 \nНе знаю я, чому мені \nспасіння Бог відкрив; \nЧому мене в тяжкій борні \nвід смерти захистив.\n\nПрипев: \nАле знаю, Кому я вірю, \nніщо мене з Христом не розлучить; \nМене Він безмежно любить \nі в небесний край візьме.\n\nКуплет 2.\nНе знаю, як Господь дає,  \nщоб вірив я Йому, \nЯк радість віри в душу ллє, \nі мир, і тишину.\n\nКуплет 3.\nНе знаю я, як Дух Святий  \nвід зла мене звільнив, \nІ як усякий гріх тяжкий \nХристос мені простив.\n\nКуплет 4.\nНе знаю ночі я, ні дня,  \nколи Господь прийде, \nПо смерті, чи ще за життя \nмене Він забере.', '', NULL, NULL),
(425, 'Браття всі радійте славний день настав', NULL, 'Куплет 1 \nБраття, всі радійте: славний день настав; \nСестри, торжествуйте: Бог нам радість дав. \nМи були далекі, а тепер брати, \nЧерез Кров Ісуса стали близькі ми.\n\nПрипев: \nВсі співайте: Алилуя! \nБог нас спас і оправдав; \nНаші імена навіки \nВ вічну Книгу записав.\n\nКуплет 2.\nМи не приступили до Синай-гори  \nВже нас не лякають блискавки й громи; \nСлово благодати чуємо з хреста, \nМи спаслись від гніву через кров Христа.\n\nКуплет 3.\nВірою й любов''ю ми тепер живем,  \nІ обмиті кров''ю, до небес ідем; \nВіра і надія веселять серця, \nБудем жить навіки, славлячи Христа.', '', NULL, NULL),
(426, 'Радійте співайте і славте', NULL, 'Куплет 1 \nРадійте, співайте і славте, \nОбмитії кров''ю Христа! \nВи пісню нову заспівайте \nТому, Хто нас спас від гріха.\n\nПрипев: \nСпівайте, радійте \nІ славте Ісуса Христа!\nСпівайте, радійте \nІ славте Ісуса Христа!\n\nКуплет 2.\nПрославте Того, Хто на землю  \nЗійшов, щоб і нас оправдать, \nСпасти і обмити нас кров''ю \nІ щастя навіки нам дать.\n\nКуплет 3.\nВін силу нам дасть й перемогу,  \nЗ гріхом в боротьбі підкріпить, \nЛюбов''ю зігріє від Бога \nІ Духом Святим нас зміцнить.\n\nКуплет 4.\nВсі радісним серцем співайте,  \nВіддайте подяку Тому, \nХто Сам заплатив за нас кров''ю, \nО, слава навіки Йому!', '', NULL, NULL),
(427, 'Всім серцем прагну я хвалить', NULL, 'Куплет 1 \nВсім серцем прагну я хвалить \nНебесного Отця, \nБажаю Господу служить \nв житті цім до кінця. \nХристос за мене постраждав, \nбо так мене любив; \nСебе на хресну смерть віддав \nі двері в рай відкрив.\n\nКуплет 2.\nХристу на славу і хвалу  \nспіваю я пісні; \nВін кров пролив Свою святу \nй простив гріхи мені. \nІ ти, о друже любий мій, \nХриста не забувай, \nБо Він, лиш є Спаситель твій, \nтебе веде в Свій рай.', '', NULL, NULL),
(428, 'З Ісусом жити радісно', NULL, 'Куплет 1 \nЗ Ісусом жити радісно, \nрадісно, радісно, \nВін нас веде в небесний край, \nв чудовий, світлий рай.\n\nПрипев: \nО, Ісус Спаситель! Ти вічно мій; \nТи вічно будеш мій найкращий Друг!\n\nКуплет 2.\nМене від смерти відкупив,  \nвідкупив, відкупив \nІ Словом правди відродив, \nмене Він відродив.\n\nКуплет 3.\nЯ буду Бога прославлять,  \nпрославлять, прославлять \nЗа радість ту великую \nі милість вічную.\n\nКуплет 4.\nЙого всім серцем я люблю,  \nя люблю, я люблю, \nЖиття своє я віддаю, \nЙому я віддаю.', '', NULL, NULL),
(429, 'Радість у Христі я знайшов', NULL, 'Куплет 1 \nРадість у Христі я знайшов, - \nВін моє життя і спокій, \nКоли я до Нього прийшов – \nЗ того часу Батько Він мій.\n\nПрипев: \nЗ того часу я Його син. \nІ радію, що Він прийняв \nМене до святих тих країн, \nЩоб Його я там прославляв.\n\nКуплет 2.\nЯ приніс до Нього все зло, -  \nВін дав радість в серце моє. \nВсе гріховне геть відійшло, \nБо Отець спасіння дає.\n\nКуплет 3.\nІ тепер радію всі дні,  \nЩо мене мій Батько знайшов, \nВін подав прощення мені, \nКоли я до Нього прийшов.', '', NULL, NULL),
(430, 'Лине пісня про Ісуса', NULL, 'Куплет 1 \nЛине пісня про Ісуса, \nпро діла Його святі. \nЯ до Нього пригорнуся \nщирим серцем у житті.\n\nПрипев: \nВсе віддам я для Ісуса: \nсерце, душу і життя; \nІ навіки з Ним зіллюся \nв Царстві вічного буття.\n\nКуплет 2.\nПро любов Його велику  \nлине пісня серед нас, \nБуду я для Нього вірним \nкожен день і кожен час.\n\nКуплет 3.\nХай світ, як море грізне,  \nнепокоїться й шумить – \nВ небесах моя Вітчизна, \nБогу слава там звучить.\n\nКуплет 4.\nДаль небесна проясніла  \nсеред горя і тривог, \nДав мені надії крила \nмій Спаситель і мій Бог.', '', NULL, NULL),
(431, 'Як чудесно змінилося моє все життя', NULL, 'Куплет 1 \nЯк чудесно змінилося моє все життя \nЗ того дня, як Христа я пізнав; \nЯ спокою не мав, а Христос мені дав \nЗ того дня, як Христа я пізнав.\n\nПрипев: \nЗ того дня, як Христа я пізнав, \nЗ того дня, як Христа я пізнав, \nСтруми радости в душу мою все пливуть, \nЗ того дня, як Христа я пізнав.\n\nКуплет 2.\nМандрівки і блукання я всі залишив  \nЗ того дня, як Христа я пізнав; \nІ гріхи всі мої Він навіки простив \nЗ того дня, як Христа я пізнав.\n\nКуплет 3.\nЯ одержав у серці надію святу  \nЗ того дня, як Христа я пізнав; \nІ не маю я вже ні вагань, ні страху \nЗ того дня, як Христа я пізнав.\n\nКуплет 4.\nУ житті все нове і в душі все нове  \nЗ того дня, як Христа я пізнав; \nТак, я впевнений, що Він у серці живе \nЗ того дня, як Христа я пізнав.\n\nКуплет 5.\nЯ небесну оселю навік полюбив  \nЗ того дня, як Христа я пізнав; \nТам зустрінуся з Тим, Кому вірно служив \nЗ того дня, як Христа я пізнав.', '', NULL, NULL),
(432, 'Радість радість що від Бога', NULL, 'Куплет 1 \nРадість, радість, що від Бога, \nсерце наше веселить, \nПромінь щастя й віри в Ньго \nв нас ніщо не погасить.\n\nПрипев: \nРадість, радість, що від Бога, \nсерце наше веселить, \nПромінь щастя й віри в Нього \nв нас ніщо вже не вгасить.\n\nКуплет 2.\nНас Христос веде за руки,  \nпідкріпляє в боротьбі, \nЗберігає нас від муки \nй утішає у журбі.\n\nКуплет 3.\nПо слідах підем Господніх  \nми під захистом святим, \nЯк учора, так сьогодні \nі навіки будем з Ним.\n\nКуплет 4.\nВічна радість хай в нас сяє,  \nхай не буде смутку в нас, \nБо нас Бог в руках тримає, \nВін є наш Отець і Спас.', '', NULL, NULL),
(433, 'Я не соромлюсь визнавать', NULL, 'Куплет 1 \nЯ не соромлюсь визнавать \nВоскреслого Христа, \nЙого веління сповіщать \nі міць Його хреста.\n\nПрипев: \nУ Христі, у Христі я душею ожив, \nУ Христі навіки я прозрів, \nУ Христі спасіння вічне придбав, \nВіднині щасливий я вже став.\n\nКуплет 2.\nЯ не соромлюсь визнавать  \nв Нім Господа мого, \nВін спас мене, дав благодать \nі Духа дав Свого.\n\nКуплет 3.\nЯ не соромлюся нести  \nзневагу за Христа; \nБлагаю: Боже, всім прости, \nто їхня біднота.\n\nКуплет 4.\nНе дасть Він сумніву мені  \nпри виді зла всього, \nІ не залишить на землі \nмене Він одного.', '', NULL, NULL),
(434, 'Любить мене мій Бог завжди вірно', NULL, 'Куплет 1 \nЛюбить мене мій Бог завжди вірно, \nДержить в Своїх руках мене сильно, \nВін заплатив за душу мою, \nНалежу я Йому.\n\nПрипев: \nНалежу я Христові, \nВін Богом є моїм, \nВін всі гріхи мої простив, \nНавіки всиновив.\n\nКуплет 2.\nБув я у світі, в темряві гинув,  \nТа задля мене Бог послав Сина, \nГріх та неправду Він з мене зняв, \nІ я спасенним став.\n\nКуплет 3.\nСерце моє радіє без краю,  \nСмутку та горя більш я не маю. \nВін заплатив за гріх мій ціну, \nНалежу я Йому.', '', NULL, NULL),
(435, 'Христос за гріх наш викуп дав', NULL, 'Куплет 1 \nХристос за гріх наш викуп дав; \nо, чудовий Спаситель! \nВін нас від смерти врятував; \nо, чудовий Спаситель!\n\nПрипев: \nО, чудовий Спаситель \nІсус мій, Ісус мій, \nО, чудовий Спаситель, \nГосподь мій Ісус...\n\nКуплет 2.\nВін кров Свою за нас пролив,  \nо, чудовий Спаситель! \nІ з Богом нас Він примирив, \nо, чудовий Спаситель!\n\nКуплет 3.\nІз серця мого гріх Він стер, \nо, чудовий Спаситель! \nІ Сам панує в нім тепер, \nо, чудовий Спаситель!\n\nКуплет 4.\nВ дорозі йде зі мною Він,  \nо, чудовий Спаситель! \nІ до святих веде країн, \nо, чудовий Спаситель!\n\nКуплет 5.\nДає для перемоги сил,  \nо, чудовий Спаситель! \nВін воскрешає із могил, \nо, чудовий Спаситель!', '', NULL, NULL),
(436, 'У гріхах я потопав про Спаса я не знав', NULL, 'Куплет 1 \nУ гріхах я потопав, про Спаса я не знав, \nНа шляху життя страждав, поранений лежав. \nТа Господь мене любив, почув Він стогін мій \nІ гріхи мої обмив в крові Своїй.\n\nПрипев: \nЛюбов Христа! Любов Христа! \nМене з гріхів спасла любов Христа.\n\nКуплет 2.\nДушу всю я віддаю, серце і розум мій, \nВ Ньому прощення знайду, Він є Спаситель мій. \nЗа безмірную любов Йому віддам хвалу, \nВже не хочу більше знов служити злу.\n\nКуплет 3.\nДобре бути у Христі - Він є життя моє,  \nВсіх приймає в простоті, радість і мир дає. \nГріх цілком перемогти зможу я тільки з Ним, \nВ горі може помогти лиш Божий Син.', '', NULL, NULL),
(437, 'Коли почую про Христа  я духом веселюсь', NULL, 'Куплет 1 \nКоли почую про Христа - я духом веселюсь; \nТоді співаю в простоті: "Спаситель мій - Ісус!" \nКоли на тьму гріха і зла, де гинув, подивлюсь, \nТоді звучить моя хвала: "Спаситель мій - Ісус!"\n\nПрипев: \nДуші моїй Ти радість дав, \nі я тепер молюсь, \nЩоб цілий світ, як я, співав: \n"Спаситель мій - Ісус!"\n\nКуплет 2.\nВ якій безодні потопав - згадати я боюсь;  \nМене і звідти врятував Спаситель мій, Ісус. \nУ світі я без Бога жив, тепер же я учусь \nПрощати, як мене простив Спаситель мій, Ісус.\n\nКуплет 3.\nПеред Тобою мертвим був - тепер же я учусь \nУ Тебе, як Творця любить, Спаситель мій, Ісус. \nПеред Тобою мертвим був - тепер я веселюсь. \nМій дух від смерти оживив, Спаситель мій, Ісус.', '', NULL, NULL),
(438, 'В часи тривоги сумніву й зневіри', NULL, 'Куплет 1 \nВ часи тривоги, сумніву й зневіри, \nНадія часом гасне у пітьмі, \nДуша болить, останні в''януть сили, \nТоді спішу до Тебе, Боже мій!\n\nПрипев: \nЩасливий я, що я Ісуса маю, \nЩасливий я, що в серці Він моїм.\nЖиву я з Ним і в Ньому пробуваю, \nВін став найкращим Другом дорогим!\n\nКуплет 2.\nО, Образ дивний, лагідний, смиренний,  \nІсусе, будь взірцем в моїй душі, \nЩоб, поміч відчуваючи щоденно, \nНе знемогтись під тягарем мені.\n\nКуплет 3.\nКуди піду в тривозі я сердечній,  \nУ горі хто розрадив би мене?\nЛиш Ти Один в любові безконечній \nМене простив і дав життя нове.\n\nКуплет 4.\nМені порою тяжко тут буває,  \nЗдається, вже сам Бог лишив мене, \nТоді в душі слова Твої лунають: \n"Я не покину, Я люблю тебе!"', '', NULL, NULL),
(439, 'Довго радість я між людьми шукав', NULL, 'Куплет 1 \nДовго радість я між людьми шукав; \nРадість повну у Христі лиш я пізнав.\n\nКуплет 2.\nТільки в Нім Однім благодать горить  \nІ не можу я без Нього в світі жить.\n\nКуплет 3.\nБуду вічно з Ним, з Господом моїм,  \nВін мене стражданням відкупив Своїм.\n\nКуплет 4.\nІ всіх кличе Він, щоб скоріш прийшли  \nІ спасіння радість для сердець знайшли.\n\nКуплет 5.\nО, мій друже, встань, до Христа прийди  \nІ шляхами грішних більше не ходи!', '', NULL, NULL),
(440, 'О як радісно з Богом йти Своїм', NULL, 'Куплет 1 \nО, як радісно з Богом йти Своїм, \nПрославляючи Його ім''я! \nВін введе мене в Свій небесний дім, \nІ вже буду з Ним навіки я.\n\nПрипев: \nЛюбо й мило, \nЯк Він за руки нас веде. \nВ Нього сила! \nВін нас в царство вічне доведе.\n\nКуплет 2.\nО, як радісно відчуваю я,  \nЩо могутнє є Його плече; \nДобре йти з Ним так через все життя, \nЯк зі мною Він, то зло втече.\n\nКуплет 3.\nТож, нікого я більше не боюсь,  \nЯк веде мене Його рука \nІ спокійно я Богові молюсь, \nХоч і часом доля є тяжка.', '', NULL, NULL),
(441, 'Немає більше втіхи', NULL, 'Куплет 1 \nНемає більше втіхи \nі радости в житті, \nЯк пробувать навіки \nдушею у Христі.\n\nПрипев: \nО, як дивно завжди жити спільно з Ним; \nО, як дивно жити спільно з Ним!\n\nКуплет 2.\nУ спільності постійній  \nз Учителем моїм \nЯ краще володію \nзнанням Його святим.\n\nКуплет 3.\nЯ з Ним, всесильним Богом,  \nі в радості й в журбі, \nТут маю перемогу \nв життєвій боротьбі.\n\nКуплет 4.\nЯ з Ним, не просто з Богом,  \nа як з Отцем моїм; \nОтцівська допомога \nведе в небесний дім.\n\nКуплет 5.\nРадіє і сьогодні  \nусе єство моє: \nУ милості Господній \nблагословіння є.', '', NULL, NULL),
(442, 'Довго довго я скитався без Ісуса в темноті', NULL, 'Куплет 1 \nДовго, довго я скитався, без Ісуса в темноті \nІ життям розчарувався, не знаходячи мети. \nЯ шукав: хто допоможе, моїм другом стане хто? \nІ почув я голос Божий: "Я люблю тебе давно".\n\nПрипев: \n"Так давно, так давно, Я люблю тебе давно!" \nЯк приємний голос Божий: "Я люблю тебе давно".\n\nКуплет 2.\nБог мене прийняв з любов''ю, від гріха звільнив мене;  \nБлагодать Його знайшов я і подяку склав за все. \nІ тепер завжди покоюсь я в присутності Його, \nПовсякчасно чую голос: "Я люблю тебе давно".\n\nКуплет 3.\nЯ щасливий і радію, що Христу я не чужий;  \nВін мій спокій і надія, Він є Друг незмінний мій. \nЦе велике щастя наше, коли маємо Того, \nХто життя дає і каже: "Я люблю тебе давно".\n\nКуплет 4.\nО, засмучений мій друже, до Ісуса ти прийди;  \nВін до тебе не байдужий, стане Другом назавжди. \nЯк покаєшся ти щиро, приймеш вірою Його, \nТо почуєш голос милий: "Я люблю тебе давно".', '', NULL, NULL),
(443, 'Без Бога жив я безнадійно спокою не мав', NULL, 'Куплет 1 \nБез Бога жив я безнадійно, спокою не мав, \nЛише Спаситель в Своїй крові спокій мені дав.\n\nПрипев: \nДивний спокій Христос дарував, \nНа хресті дар спасіння придбав. \nХоч ще гріх навкруги так бушує, кипить; \nАле Бог нас хранить.\n\nКуплет 2.\nЯкщо марноти налягають на життя моє,  \nТоді Христос наш для спасіння руку подає.\n\nКуплет 3.\nНезмінне щастя, милість Божу серцем я пізнав:  \nХристос за наші всі провини на хресті вмирав.\n\nКуплет 4.\nХоч ви знеможені й безсилі на путі земній,  \nСпішіть ви до Христа, Він дасть вам спокій неземний.\n\nКуплет 5.\nСердечні двері ви відкрийте і прийміть Христа,  \nВін ваші душі Сам очистить, дасть нове життя.', '', NULL, NULL),
(444, 'Я спасенний з гріха Вже я Божий слуга', NULL, 'Куплет 1 \nЯ спасенний з гріха, Вже я Божий слуга, \nСерцем вірю в Христа Ісуса; \nСпокій Він дав мені, всі гріхи з душі зняв, \nВ Сина Божого вірую я!\n\nПрипев: \nВірю я (вірю я), вірю я (вірю я), \nСерцем вірю я, вірю в Ісуса!\nВірю я (вірю я), вірю я (вірю я),\nВ Сина Божого вірую я!\n\nКуплет 2.\nВін мене оправдав, я це щиро прийняв,  \nСерцем вірю в Христа Ісуса; \nВін - незмінна любов, Він - надійний покров, \nВ Сина Божого вірую я!\n\nКуплет 3.\nВ Нім я радість знайшов, як до Нього прийшов,  \nСерцем вірю в Христа Ісуса; \nЯ Його лиш хвалю, і Йому лиш служу, \nВ Сина Божого вірую я!', '', NULL, NULL),
(445, 'О Ісус достойний Ти', NULL, 'Куплет 1 \nО, Ісус, достойний Ти \nслави й чести на землі, \nСлави й чести на землі від нас. \nІ від серця повноти \nми співаємо Тобі, \nБудем всюди славити Тебе.\n\nПрипев: \nЗбережи у світі нас, \nДай з Тобою пробувать, \nПідкріпляй нас в кожний час, \nЩоб Тебе лиш прославлять.\n\nКуплет 2.\nНаші Ти гріхи простив,  \nСвою милість Проявив, \nСвою милість проявив до нас. \nБережеш у кожний час, \nутішаєш Духом нас, \nДухом правди утішаєш нас.\n\nКуплет 3.\nТи життя нам дарував,  \nсвітлом правди осіяв, \nМир небесний у серця послав. \nКров Свою за нас пролив, \nнаші всі гріхи простив, \nНаші всі гріхи Ти нам простив.', '', NULL, NULL),
(446, 'На серці є пісня одна', NULL, 'Куплет 1 \nНа серці є пісня одна, \nІ в радості ллється вона, \nЯк чиста джерельна вода: \nМир, мир, святий Божий мир!\n\nКуплет 2.\nКоли я Ісуса пізнав,  \nВін мир мені в серце послав,\nЙого я любов відчував: \nМир, мир, святий Божий мир!\n\nКуплет 3.\nВ Христі я душею живий,  \nДо Нього лиш прагне дух мій,\nУ Ньому знаходжу спокій: \nМир, мир, святий Божий мир!\n\nКуплет 4.\nЗа Богом іти - є мета,  \nНайкраща в житті та свята; \nБез неї ж тут все марнота: \nМир, мир! Святий Божий мир!', '', NULL, NULL),
(447, 'Мир повний мир  і там де суєта', NULL, 'Куплет 1 \nМир, повний мир! - і там, де суєта? \nНебесний мир дає лиш Кров Христа. \nМир, повний мир Сам Бог нам подає, \nНадія на Христа нам мир дає.\n\nПрипев: \nМир, повний мир! Хоч зло кругом кипить, \nТільки в Христі Однім, В Нім мир царить, \nтак, мир царить!\n\nКуплет 2.\nМир, повний мир, далеко від рідні?  \nБог збереже нас на путях земних. \nМир, повний мир! Хоч світ наш у пітьмі, \nХристос - наш Цар, і сила наша в Нім!\n\nКуплет 3.\nМир, повний мир, хоч смерть навколо нас,  \nЇї вже подолав Спаситель наш. \nКоли кінець земній борні прийде, - \nХристос в небесний дім всіх нас візьме.', '', NULL, NULL),
(448, 'Хай моїм серцем Ісус володіє', NULL, 'Куплет 1 \nХай моїм серцем Ісус володіє, \nУ почуттях і в думках хай живе; \nКраще любити ніхто не зуміє, \nРадість і спокій Один Він дає.\n\nПрипев: \nДосить томитися, досить страждати, \nПоруч зі мною Спаситель Ісус. \nВін обіцяв в горі не залишати, \nЗ Ним я нічого повік не страшусь.\nВін обіцяв в горі не залишати, \nЗ Ним я нічого повік не страшусь.\n\nКуплет 2.\nДав мені дивну Христос перемогу –  \nСилою Бога гріхи віддалив, \nІ, показавши до неба дорогу, \nМир Свій святий мені в душу пролив.\n\nКуплет 3.\nМоже, з гріхом в боротьбі постраждаю –  \nДух мій слабий тільки Він підкріпить; \nВ Нім джерело я очищення маю, \nСилу і радість душі Він дарить.\n\nКуплет 4.\nПраця скінчиться - в оселі небесні,  \nВірю, покличе мене мій Ісус; \nМир не порушать страждання тілесні, \nВ Отчих обіймах навік з Ним зіллюсь.', '', NULL, NULL),
(449, 'Дорожчим за все є для мене Христос', NULL, 'Куплет 1 \nДорожчим за все є для мене Христос, \nЗнайшов у Христі я багатство моє, \nЩасливий я з Ним над усе.\n\nПрипев: \nЩасливий я всюди з Христом, \nЩасливий я всюди з Христом, \nЗневажений в світі, я можу сказать: \nЩасливий я завжди з Христом!\n\nКуплет 2.\nКоли я був грішник, спокою не мав, \n Без Божого слова блукав, \nСпаситель прийшов і мене оправдав, \nВічності спадщину дав.\n\nКуплет 3.\nЛиш жертва одна мала змогу спасти  \nІ з Богом мене примирить \nІсус за мій гріх дав Себе розп''ясти,\nЩоб я з Ним навіки міг жить.\n\nКуплет 4.\nЗакликав, навчив, правди путь показав  \nІ в серце спокій мені дав. \nМолитись Він учить і в світлі ходить, \nЗавіт Його в серці носить.\n\nКуплет 5.\nХоч навіть і рідні покинуть мене,  \nІ втрачу я все на землі, \nХристові довірюсь, Він любить мене, \nНавік я укриюся в Нім.', '', NULL, NULL),
(450, 'Хочу всім я розказати', NULL, 'Куплет 1 \nХочу всім я розказати, \nяк Христос мій постраждав, \nЗ тягарем гріхів розп''ятий \nна хресті Він помирав.\n\nКуплет 2.\nХочу всім я розказати,  \nщо Христос за нас вмирав. \nХто до Нього навернувся – \nмир і радість дарував.\n\nКуплет 3.\nЧасом поклику не чую  \nі блукаю, як вівця, \nВін знайде - я знов відчую \nбатьківську любов Отця.\n\nКуплет 4.\nГріх мені наносив рани,  \nя втомився і знеміг; \nПогляд в горі мов в тумані – \nВін мені лиш допоміг.\n\nКуплет 5.\nМимо смерти я проходжу.  \nСкільки лиха на шляху! \nАле все я переможу, \nсилу в Бозі я знайду.\n\nКуплет 6.\nСпас бере мене за руки  \nза Собою вслід веде, \nВ край без горя, без розлуки \nСам мене Він приведе.', '', NULL, NULL),
(451, 'Коли я до Христа в гріхах прийшов', NULL, 'Куплет 1 \nКоли я до Христа в гріхах прийшов,\nВін взяв мої гріхи, \nВін взяв мої гріхи; \nІ замість смутку, радість я знайшов: \nВін взяв мої гріхи.\n\nПрипев: \nМої гріхи Він взяв,\nМої гріхи Він взяв \nІ серцю радість дарував. \nЯ рад, що мої гріхи Він взяв \nІ радість дарував.\n\nКуплет 2.\nТягар гріхів для мене був тяжким,  \nВін взяв мої гріхи, \nВін взяв мої гріхи; \nІ я на Нього мій тягар зложив: \nВін взяв мої гріхи.\n\nКуплет 3.\nОсуждення для мене вже нема,  \nВін взяв мої гріхи, \nВін взяв мої гріхи; \nІ звершений спокій Він мені дав: \nВін взяв мої гріхи.\n\nКуплет 4.\nКоли й ти прийдеш до Христа тепер,  \nТвої гріхи візьме, \nтвої гріхи візьме; \nВін і тобі у серце радість дасть, \nТвої візьме гріхи.', '', NULL, NULL),
(452, 'Ми у Христі вже  не під законом', NULL, 'Куплет 1 \nМи у Христі вже, - не під законом: \nПрощені всі ми навіки Богом, - \nЗа нас Спаситель Сам постраждав, \nРаз і назавжди нас оправдав.\n\nПрипев: \nХристос страждав! О, грішнику знай! \nЗа нас вмирав, подяку віддай! \nТягар гріховний Син Божий зняв з нас, \nРаз і назавжди від смерти спас.\n\nКуплет 2.\nТепер ми вільні - нема осуду,  \nХристом спасенні, з Ним жити будем. \n"Прийдіть до Мене!" - звучать слова: \n"Я відкупив вас кров''ю Христа".\n\nКуплет 3.\nБожі ми діти, - то наша слава!  \nВся честь Христові, хвала й держава!\nВ життя від смерти ми перейшли: \nНаше спасіння в Христі знайшли.', '', NULL, NULL),
(453, 'Хоч вирують люті хвилі', NULL, 'Куплет 1 \nХоч вирують люті хвилі \nі лякаюсь дуже я, \nХоч я немічний, безсилий – \nсила в Господа моя.\n\nПрипев: \nТак, мене Він захищає \nі дає душі спокій, \nБлагодаттю оживляє, \nВін, Господь, Спаситель мій.\n\nКуплет 2.\nХоч недоля наступає,  \nсила зла мене гнітить, \nМій Господь мене спасає. \nВін мого спасіння щит.\n\nКуплет 3.\nХоч не бачу я Ісуса,  \nзнаю: любить Він мене; \nЧасто, навіть у спокусах, \nвипробовує, й веде.\n\nКуплет 4.\nХоч прийде біда та горе, \nмій Ісус мене спасе. \nДопоможе мені скоро, \nтягарі всі понесе.', '', NULL, NULL),
(454, 'Славте Бога піснями хваління', NULL, 'Куплет 1 \nСлавте Бога піснями хваління, \nСлавте, славте всім життям своїм; \nДружним співом славте за спасіння \nСеред мук і сліз у світі цім.\n\nПрипев: \nСлавте Бога, славте від душі, \nВін вас спас в Христі, \nславте Бога, славте Господа повік.\n\nКуплет 2.\nСлавте Бога кожної хвилини  \nВ почуттях, думках, святих ділах \nЗа терпіння Господа донині, \nЩо чекає каяття в гріхах.\n\nКуплет 3.\nСлавте Бога щирою душею  \nЗа Його безмірную любов, \nВін спас людство ласкою Своєю, \nНа хресті святу проливши кров.\n\nКуплет 4.\nСлавте Бога, славте повсякчасно:  \nСкоро Він у славі Сам прийде, \nВ вишній Свій Єрусалим прекрасний \nВін спасенних з піснею введе.', '', NULL, NULL),
(455, 'Любить грішників Спаситель', NULL, 'Куплет 1 \nЛюбить грішників Спаситель \nВін прощає людям всім. \nЗакликає всіх до Себе \nЙ хоче дать спасіння їм.\n\nПрипев: \nВін відкрив у небо брами \nвсім, Його хто полюбив. \nВічно буде жити з нами. \nКров''ю Він нас відкупив.\n\nКуплет 2.\nЙшов колись і я в загибель,  \nв темряві ходив щодня: \nБез надії в цьому світі, \nта Христос мене прийняв.\n\nКуплет 3.\nВін простив мої провини,  \nвсі гріхи мої обмив; \nІ тепер Його я славлю, \nВін мене усиновив.\n\nКуплет 4.\nІ коли скінчиться шлях мій,  \nй відійде душа моя; \nПрийме в рай мене Спаситель, \nвічно з Ним там буду я.', '', NULL, NULL),
(456, 'Радій радій спасенний', NULL, 'Куплет 1 \nРадій, радій, спасенний, \nхай буде завжди радістю тобі \nСпаситель, що смиренно \nза всі твої гріхи вмер на хресті.\n\nПрипев: \nРадій, (радій) спасенний, \nСпівай (співай) про те, \nЩо твій Христос Спаситель \nНавіки спас тебе!\n\nКуплет 2.\nРадій, радій, спасенний, \nна небесах дім вічний тебе жде \nІ у величній славі \nСпаситель твій тебе туди введе.\n\nКуплет 3.\nРадій, радій, спасенний,  \nспокійний ти під захистом Його, \nНіякий дух пекельний \nіз серця миру не візьме твого.\n\nКуплет 4.\nРадій, радій, спасенний,  \nспіши тепер до радісних святих \nІ, торжеством натхненний, \nСпасителю співай пісень твоїх.', '', NULL, NULL),
(457, 'Жить знову без Бога світ кличе мене', NULL, 'Куплет 1 \nЖить знову без Бога світ кличе мене \nІ щастя дочасне мені він дає; \nАле на землі, де одна марнота, \nНема більше щастя, як вірить в Христа.\n\nКуплет 2.\nШироким шляхом люди світу ідуть;  \nЗ вузенької стежки мені не звернуть; \nХай буде терниста й тяжка моя путь, \nЯ в рай, вони в пекло навіки підуть.\n\nКуплет 3.\nУсюди у світі зневажений я  \nЗа те, що про Господа пісня моя; \nТа серце підноситься вірою знов \nДо Того, Хто має незмінну любов.\n\nКуплет 4.\nВін ніжний і сильний мій Друг і Творець,  \nЗа вірність мою в нагороду вінець \nГотує Він в райських оселях Своїх, \nДе сліз і страждань вже не буде земних.\n\nКуплет 5.\nЙому присвятив я життя все своє  \nІ знаю: щасливе майбуднє моє; \nВже тут, на землі, з Ним проводжу я дні, \nІ більшого щастя не треба мені.', '', NULL, NULL),
(458, 'У гріхах я довго жив блукав', NULL, 'Куплет 1 \nУ гріхах я довго жив, блукав, \nпро Голгофську жертву ще не знав. \nІ не знав, що за то мене \nв муках вмер Христос.\n\nПрипев: \nЛаску проявив безмірну Він, \nдарував спасіння Божий Син. \nЗняв з душі мої гріхи усі \nВін на хресті.\n\nКуплет 2.\nБог відкрив для мене весь мій гріх,  \nбільш спокійно жити я не міг, \nПоки не схиливсь до Його ніг\nя під хрестом.\n\nКуплет 3.\nВсе тепер віддав я для Христа,  \nВін моїм Царем і Спасом став. \nСлавлять від тоді мої уста \nлише Христа.\n\nКуплет 4.\nО, яка Його любов до всіх,  \nй ласка, що прощає всякий гріх. \nВін з''єднав з Отцем людей Своїх \nтам на хресті.', '', NULL, NULL),
(459, 'Не знаючи Спаса  життя я не знав', NULL, 'Куплет 1 \nНе знаючи Спаса, - життя я не знав, \nГріху та неправді себе віддавав;\nПочув раптом дивні слова новини: \n"Христос тебе любить, з Ним жити почни!"\n\nПрипев: \nХриста я не знав, та голос сказав: \n"Він любить, Він любить!" – \nЙого я впізнав.\n\nКуплет 2.\nКоли я томився в тяжкій боротьбі  \nБлаженства, спокою не мав я в собі; \nТоді, чую, - голос Господій звучить: \n"Христос тебе любить, на поміч спішить!"\n\nКуплет 3.\nХристові віддавшись, я в Ньому живу,  \nВін дав мені щастя і долю нову; \nЯ впевнено, з радістю слухаю знов: \n"Христос тебе любить, бо Він є Любов!"', '', NULL, NULL),
(460, 'Твердо я вірю мій любий Спас', NULL, 'Куплет 1 \nТвердо я вірю, мій любий Спас, \nНим я радію, бо Він мене спас; \nНебо в дарунок хоче Він дать, \nЯк же приємно з Ним пробувать.\n\nПрипев: \nСпасу щоденно моя хвала, \nБо Його ласка мене спасла; \nВічно я буду славить Його, \nдивного Друга, Спаса мого!\n\nКуплет 2.\nТвердо я вірю: з часу того,  \nЯк я повірив, дитя я Його; \nСповнює спокій за майбуття, \nВ Нім я знаходжу все для життя.\n\nКуплет 3.\nТвердо я вірю в Спаса мого,  \nСкрізь відчуваю турботу Його; \nЩоб нам не сталось - радісний дух: \nВічно зі мною вірний мій Друг.\n\nКуплет 4.\nСпокій чудесний, спокій святий,  \nДух мій знаходить в любові Твоїй; \nДай, щоб Тобі я серце відав, \nЯ б умалявся, Ти б виростав.', '', NULL, NULL),
(461, 'Спасенний О дивна це радість', NULL, 'Куплет 1 \nСпасенний! О, дивна це радість, \nспасенний я кров''ю Христа; \nСпасенний по милості Божій, \nтепер я вже Боже дитя.\n\nПрипев: \nСпасен, спасен, \nспасенний я кров''ю Христа; \nСпасен, спасен, \nтепер я вже Боже дитя.\n\nКуплет 2.\nСпасенний: щасливий в Ісусі,  \nне маю від радості слів; \nВін в серці моїм поселився \nі любо мені жити з Ним.\n\nКуплет 3.\nЯ думаю завжди про Спаса  \nі безперестанку, весь день, \nПро ласку Його я співаю, \nщо сталася змістом пісень.\n\nКуплет 4.\nВже скоро побачу у славі  \nХриста, в Ньому слава моя; \nВін кроки мої направляє \nдо неба, у вічне життя.', '', NULL, NULL),
(462, 'Радіснії співи линьте в небесах', NULL, 'Куплет 1 \nРадіснії співи, линьте в небесах! \nБлудний син, одумавшись, прийшов; \nЗ Богом примирився в радісних сльозах, \nВ рідний дім Отця він увійшов.\n\nПрипев: \nСлава, слава Богу в небесах! \nВсі прославте на землі Творця! \nНе змовкайте співи стомлених гріхом, \nВикуплених Господом Христом!\n\nКуплет 2.\nРадіснії співи, линьте в небесах!  \nБо знайшлась загублена вівця. \nГрішник був далеко, мертвий у гріхах, \nА тепер прийшов він до Отця.\n\nКуплет 3.\nРадіснії співи линьте в небесах!  \nПрославляйте всі любов Христа! \nХай звучить подяка в радісних серцях, \nХай Христа прославлять всі уста!', '', NULL, NULL),
(463, 'Глибша від морів та океанів', NULL, 'Куплет 1 \nГлибша від морів та океанів, \nВічна, неосяжна і свята, \nВища від усіх світил небесних \nБлагодатная любов Христа.\n\nПрипев: \nЯ блукав на чужині, \nВін всі гріхи простив мені, \nДар Святого Духа мені дав, \nСвоїм дитям мене назвав.\n\nКуплет 2.\nЩастя маю у Христі Ісусі,  \nНе боюся суду більше я, \nМоїм серцем гріх не володіє, \nВ нім оселя Господа Христа.\n\nКуплет 3.\nЖив я довго в темряві без світла,  \nПробував далеко від Христа, \nГинув я, знеможений, нещасний, \nТа Ісус щасливе дав життя.', '', NULL, NULL),
(464, 'Спасе мій я торжествую', NULL, 'Куплет 1 \nСпасе мій, я торжествую, \nбо почув Ти голос мій, \nТому вічно буду славить \nя Голгофський подвиг Твій.\n\nПрипев: \nВідкупителю величний, \nТи гріхи мої простив; \nВід страждання і від муки \nТи мене навік звільнив.\n\nКуплет 2.\nШлях мій був тяжкий і темний,  \nжурно йти було мені, \nТа до Тебе я звернувся, \nу хвилини ці сумні.\n\nКуплет 3.\nСлавити Тебе лиш буду,  \nо, Ісусе, Спасе мій, \nЯ щасливим став навіки \nчерез хрест Голгофський Твій.', '', NULL, NULL),
(465, 'Благодатна Скеля ця', NULL, 'Куплет 1 \nБлагодатна Скеля ця, \nПоміч скрізь мені дає; \nВід гріха, пороків, зла, \nВже навік спасла мене; \nЗ тої Скелі, із Христа, \nЛлється всім жива вода.\n\nКуплет 2.\nЯ закону не сповняв  \nІ засудження чекав, \nДовго гріх мене тримав \nІ спокою не давав, - \nЛиш знайшов я спокій свій \nВ Скелі Господа святій.\n\nКуплет 3.\nЯ прийшов, Христос прийняв,  \nОдяг білий мені дав, \nЯ збіднів, а Він мені \nСвітлий рай подарував, \nПолюбив мене й придбав, \nВ Скелі правди заховав.\n\nКуплет 4.\nБлагодатне Світло це  \nБереже від бід мене, \nВоно смутку не несе, \nТільки сили додає, \nЯ нічого не боюсь, \nБо це Світло - Сам Ісус!', '', NULL, NULL),
(466, 'Спасе джерело утіхи', NULL, 'Куплет 1 \nСпасе, джерело утіхи, \nсерце звесели моє.\nДай співать мені ту пісню, \nщо святить ім''я Твоє. \nХай полине спів чудовий \nпро небесну благодать, \nІ про те, як Ти в любові \nмир святий всім хочеш дать.\n\nКуплет 2.\nМи в темряві не блукаєм,  \nТи освітлюєш наш шлях. \nТи простив наші провини, \nце ми чуємо в серцях. \nБув і я, мов син той блудний, \nта мене Ти відшукав, \nБо життя Своє за мене \nна хресті, Святий, віддав.\n\nКуплет 3.\nЯк Твою любов велику  \nлюдський розум мій збагне! \nО, яку віддам подяку, \nщо з гріхів Ти спас мене? \nНе бажаєм більше, Спасе, \nвідійти від Тебе знов; \nБо й за мене на Голгофі \nТи своє життя віддав.', '', NULL, NULL),
(467, 'Душе утішайся в Ісусі', NULL, 'Куплет 1 \nДуше, утішайся в Ісусі, \nгріхи твої всі Він простив; \nВін в серце спокій посилає, \nнавіки тебе полюбив. \nЩасливий я вічно з Ісусом, - \nспочинок в Христі я знайшов, \nВін серцю моєму дав радість, \nколи я до Нього прийшов.\n\nКуплет 2.\nЯк радісно бути з Ісусом,  \nВін Духа Святого послав, \nЗасмучену душу потішив \nі місце з Собою їй дав.\n \nТепер я щасливий з Ісусом, \nне мучить вже душу журба. \nЯ щастя знайшов і блаженство \nв любові Ісуса Христа.\n\nКуплет 3.\nЯк радісно бути з Ісусом,  \nхоч шлях мій тернистий, вузький, \nМене до мети доведе Він, \nде вічний знайду я спокій. \nНавіки я буду з Ісусом, \nу вічній любові там з Ним; \nМені дав багатства небесні, \nя тішусь Ісусом моїм.', '', NULL, NULL),
(468, 'Радійте браття і в піснях духовних', NULL, 'Куплет 1 \nРадійте, браття, і в піснях духовних \nСлаву і честь віддавайте Христу. \nВін нас знайшов всіх в неволі гріховній, \nВін нам любови явив повноту.\n\nКуплет 2.\nО, як безмірно нас любить Спаситель,  \nОхороняє в житті нас земнім, \nВін приготовив нам святі оселі \nІ нагородить вінцем золотим.\n\nКуплет 3.\nЗ радістю, браття, за Слово Господнє,  \nБіль і зневагу покірно знесем. \nБог підкріпить нас на вузькій дорозі, \nВ славу введе нас у Царство Святе.', '', NULL, NULL),
(469, 'Я хочу співати в кожний час', NULL, 'Куплет 1 \nЯ хочу співати в кожний час, \nжурби в мені нема; \nХристос мене від смерті спас, \nщасливий я без кінця.\n\nПрипев: \nСпівай, співай, \nдля Господа співай, \nСпівай, співай, \nсумний мій брате, співай!\n\nКуплет 2.\nСпівай тоді, коли в душі  \nтягар наляжеться, \nСпівай від серця, від душі \nі легше зробиться.\n\nКуплет 3.\nЯ буду співать завжди в житті  \nпро Божу благодать, \nБо хочу я, щоб люди всі \nзі мною стали співать.', '', NULL, NULL),
(470, 'Христос любови повний', NULL, 'Куплет 1 \nХристос любови повний, \nу Ньому ласки дар, \nВін - манна, хліб духовний, \nВін - наш всесильний Цар. \nВ Нім наше воскресіння, \nжиття в Нім без кінця, \nІ вічне багатіння, \nй спочинок для борця.\n\nПрипев: \nЛиш в Нім (Однім),\nЛиш в Нім (Однім), \nТак, благословіння повнота лиш в Нім, \nЛиш в Нім (Однім),\nЛиш в Нім (Однім),\nТак, повнота лиш в Нім (Однім).\n\nКуплет 2.\nЯ з Ним відпочиваю, не вимовлять уста,  \nЯкий я спокій маю і радісне життя. \nЙому пісні складаю, бо Він моя хвала; \nЙого я величаю за всі Його діла.\n\nКуплет 3.\nКоли побачу, Боже, усе що в небі є, -  \nПрийде кінець тривогам, бо я дитя Твоє.\nТоді в святім єднанні Тобі віддам хвалу \nЗа те, що від страждання Ти душу спас мою!', '', NULL, NULL),
(471, 'В земній долині задоволений я', NULL, 'Куплет 1 \nВ земній долині задоволений я, \nХоч і хатина небагата моя, \nАле в тім місці, де спасенні живуть, \nМене багаті оселі там ждуть.\n\nПрипев: \nЯ маю місце там у славній країні, \nДе не старіють, де вічна весна, \nІ вічно буду з Ісусом там жити \nКоли ввійду вже у небеса.\n\nКуплет 2.\nНе раз буває, що дорога моя  \nВже не під силу й знемагаюся я, \nЩе небагато і мети досягну, \nШляхом спасіння я в небо ввійду.\n\nКуплет 3.\nХоч зустрічаю горе я і недуги,  \nТа добре знаю, що до неба іду, \nЛише дочасно я з''явився сюди – \nУ небі буду я з Богом завжди.', '', NULL, NULL),
(472, 'Я для Тебе гімн співаю', NULL, 'Куплет 1 \nЯ для Тебе гімн співаю, \nСпасе любий, дорогий. \nТи введеш мене до раю, \nяк скінчу цей шлях земний.\n\nПрипев: \nВ пісні тій - моє натхнення, \nпоклик вічної краси, \nІ сердечне поклоніння; \nмоя пісня, Спасе, Ти!\n\nКуплет 2.\nШлях важкий, але я знаю,  \nщо мене так любиш Ти, \nПісня душу окриляє, \nз нею легше далі йти.\n\nКуплет 3.\nІ коли прийду в край вічний –  \nзаспіваю там в раю \nГімн достойний і величний \nпро святу любов Твою.', '', NULL, NULL),
(473, 'Шлях до спасіння вічний живий', NULL, 'Куплет 1 \nШлях до спасіння вічний, живий \nСловом відкрив Христос дорогий. \nСпокій Він Сам дарує тобі, \nКличе тепер: "Прийди!"\n\nПрипев: \nРадість, радість буде в небесах, \nЗустріч в райських славних тих місцях. \nБуде навіки в наших серцях \nДивна Його любов.\n\nКуплет 2.\n"Будьте, як діти!" - Христос сказав,  \nРадість небесну Він дарував, \nгрішним усім спасіння придбав, \nДруже, тепер прийди!\n\nКуплет 3.\nЗнай, і тебе Він кличе "Прийди!",  \nСумнів відкинь і з вірою йди, \nТобі дарує мир неземний, \nСам кличе Він: "Прийди!"', '', NULL, NULL),
(474, 'До Господа прийдіть', NULL, 'Куплет 1 \nДо Господа прийдіть, \nусі Йому служіть, \nЗа нас Спаситель постраждав \nі всім спасіння дав.\nЗа нас Спаситель постраждав \nі всім спасіння дав.\nПрисіпв: \nІдем ми з хвалінням в небо, \nде Господа трон; \nІдемо ми в дім нетлінний \nі будем там вічно з Христом.\n\nКуплет 2.\nСпасенні всі ідуть,  \nусюди спів їх чуть; \nЗа Господом вони пішли \nі в Нім життя знайшли.\nЗа Господом вони пішли \nі в Нім життя знайшли.\n\nКуплет 3.\nО, грішники, спішіть  \nі за Христом ідіть: \nПрийміть Його в свої серця, \nзнайдете в Нім життя.\nПрийміть Його в свої серця, \nзнайдете в Нім життя.', '', NULL, NULL),
(475, 'Далеко від земних марнот', NULL, 'Куплет 1 \nДалеко від земних марнот \nі всіх людських турбот \nЄ край, де вічно ясний день, \nде лине звук пісень.\n\nПрипев: \nВ той край, в той край, \nвсім серцем лину я; \nДе вічне щастя - Божий рай, \nде вічне світло дня.\n\nКуплет 2.\nПанує там любов свята  \nу славі, у Христа, \nЖиття там вічного весна, \nкраса там неземна.\n\nКуплет 3.\nНове там небо і земля,  \nнове святе життя, \nХристом відкуплені серця \nрадіють без кінця.', '', NULL, NULL),
(476, 'О радість радість буде', NULL, 'Куплет 1 \nО, радість, радість буде \nтам Відкупленим серцям, \nКоли пройдемо путь свою \nі будемо в раю.\nРосте там дерево життя, \nнавколо неземна краса, \nВ любові вічній неземній, \nцарює Бог живий.\n\nПрипев: \nО, що за радість там, \nрадість там, радість там; \nО, що за радість там \nспасенним буде нам,\nДе всі святії без числа \nХвалу приносять для Христа;\nі ми співати там почнем, \nколи туди прийдем.\n\nКуплет 2.\nВузька дорога лиш одна  \nпризначена всім нам; \nЯкщо ми нею не підем – \nнавіки ми помрем.\n \nКоли ж по ній смиренно йдем, \nто, хоч сумуєм, сльози ллєм – \nВ любові будемо Творця \nщасливі без кінця.\n\nКуплет 3.\nХристос воскрес, розвіяв страх,  \nі ось, в величний час – \nВ чудових, світлих небесах \nзустріти хоче нас. \nО, любий друже, пам''ятай \nщо є блаженства вічний край! \nХоч тяжко, трудно в світі нам – \nвся радість буде там.', '', NULL, NULL),
(477, 'Я знаю є небесний край', NULL, 'Куплет 1 \nЯ знаю, є небесний край, \nдивний край, вічний край; \nВідсутній сум там і відчай – \nдивний край, вічний край. \nСпівають там святі пісні, \nтам ангели живуть святі; \nНіхто не знає там гріха – \nкрай святий, край святий.\n\nКуплет 2.\nБлакитне небо там без хмар –  \nсвітлий край, світлий край; \nЖиття не має там примар – \nБожий рай, Божий рай. \nІ радощі там без кінця \nперед ясним лицем Творця, \nТам скрізь нев''януча краса – \nдивний край, дивний край.\n\nКуплет 3.\nЗгрішили ми всі перед Ним –  \nБог нас спас; Бог нас спас; \nХоч світ пройнятий весь гріхом – \nБог нас спас, Бог нас спас. \nХристос прийшов за нас страждать, \nі може з нас провини знять \nІ в край блаженства привести, \nВін нас спас, Він нас спас.\n\nКуплет 4.\nЗа Господом усі ідіть,  \nвслід за Ним, вслід за Ним; \nЗ Ним будемо там вічно жить – \nвічно з Ним, вічно з Ним. \nНе гайтесь: скоро час прийде; \nчи в вірі вас Господь знайде, \nКоли за вірними прийде? – \nВін прийде, Він прийде!', '', NULL, NULL),
(478, 'До небес мій дух злітає', NULL, 'Куплет 1 \nДо небес мій дух злітає, \nдо Всевишнього Отця; \nВін любов Свою зливає \nна утомлені серця.\nВін любов Свою зливає \nна утомлені серця.\n\nКуплет 2.\nТам святі відпочивають  \nу небесній висоті, \nВічно Бога прославляють, \nя ж томлюся в цім житті.\nВічно Бога прославляють, \nя ж томлюся в цім житті.\n\nКуплет 3.\nГоря там ніхто не знає,  \nтам блаженна сторона, \nТам в любові розквітає \nвічнорадісна весна.\nТам в любові розквітає \nвічнорадісна весна.\n\nКуплет 4.\nСліз ніхто не проливає  \nі немає там журби, \nЯсне сонце там сіяє \nу блаженній стороні.\nЯсне сонце там сіяє \nу блаженній стороні.\n\nКуплет 5.\nДо небес і я бажаю, \nтам Христос Спаситель мій; \nМоє щастя, добре знаю,\nу Вітчизні неземній.\nМоє щастя, добре знаю,\nу Вітчизні неземній.\n\nКуплет 6.\nСкоро прийде та хвилина,  \nБог мене благословить: \nЯ піду в свою Вітчизну \nі в ній вічно буду жить.\nЯ піду в свою Вітчизну \nі в ній вічно буду жить.', '', NULL, NULL),
(479, 'Де знайде душа у країні якій', NULL, 'Куплет 1 \nДе знайде душа, у країні якій, \nдля серденька свого і ласку, й спокій? \nХто міг би журливу її утішать, \nбо люди не можуть рятунку їй дать? \nНі-ні, ні-ні! Світ нам чужий, \nЛиш в Царстві Христовім є повний спокій.\n\nКуплет 2.\nУсім, хто Христа від душі покохав,  \nВін місто на небі святе збудував, \nІ місто те сяє, як дивний вінець, \nЧи ж рідний то дім для спочинку сердець? \nТак-так, так-так - дім дорогий, \nЙ мені там з святими є вічний спокій.\n\nКуплет 3.\nВізьми, мій Спасителю, Ти і мене,  \nде хори святих величають Тебе; \nДуша моя хоче в тім сонмі стоять, \nза кров, за страждання Тебе прославлять. \nЖди, жди! Скоро час твій прийде, \nУ славу небесну тебе Він введе.\n\nКуплет 4.\nНадійся душе, недалеко той край;  \nнедовго - і скажуть: "Іди спочивай!" \nБорися, не падай в тяжкій боротьбі, \nтам буде і слава, і спокій тобі. \nРадість, радість там у Отця \nусім, хто терпить на землі до кінця.', '', NULL, NULL),
(480, 'О Боже мій Боже як швидко в цім світі', NULL, 'Куплет 1 \nО, Боже мій, Боже, як швидко в цім світі, \nМов хвиля, пройшли мої дні; \nПриходить година, зближається хвиля \nЙ відійду з цієї землі.\n\nКуплет 2.\nКоли я піду вже у вічну країну,  \nТам Спас буде світлом мені. \nЛиш там я спочину, лиш там я забуду \nНещасні гіркі свої дні.\n\nКуплет 3.\nУ небі спочину, і там я забуду  \nВсю долю земного життя, \nРазом зі святими і рідними буду \nУ сяєві вічного дня.\n\nКуплет 4.\nО, друже, не гайся, скоріше покайся;  \nСпаситель простить все тобі, \nБо прийде година, і там, в домовині, \nВже пізно благати тоді.', '', NULL, NULL),
(481, 'В небі є моя свята Вітчизна', NULL, 'Куплет 1 \nВ небі є моя свята Вітчизна, \nде нема страждання і спокус; \nМісце те для мене приготовив \nМій Спаситель, мій Ісус.\n\nПрипев: \nСкоро, скоро в небі буду я, \nде Христос у славі мене жде; \nБог не залишить тут мене, \nв небо приведе.\n\nКуплет 2.\nДім мій там, за хмарами високо,  \nде спокійно всі святі живуть. \nСлавлять Бога за любов велику \nі мене вони там ждуть.\n\nКуплет 3.\nО, небесна, Божая Країно,  \nвсім своїм єством тебе люблю; \nХоч в дорозі часто знемагаю, \nвсе ж до Тебе, Боже, йду.', '', NULL, NULL),
(482, 'Куди тепер іти нам', NULL, 'Куплет 1 \nКуди тепер іти нам, \nкуди шлях направлять? \nБез Тебе, любий Боже, \nде можна спочивать?\n\nПрипев: \nЛиш там я знайду спокій, \nлиш там кінець сльозам, \nЛиш там забуду горе, \nде Бог царює Сам.\n\nКуплет 2.\nО, як би поспішити  \nввійти в небесний край? \nТо ж там моя Вітчизна, \nблаженний, світлий рай.\n\nКуплет 3.\nНе знаю, що зі мною  \nзробилося в цю мить, \nЩо серце, мов на крилах, \nу край святий летить?', '', NULL, NULL),
(483, 'Заспіваймо всі пісню радісну для нас', NULL, 'Куплет 1 \nЗаспіваймо всі пісню, радісну для нас! \nСкоро ми ввійдем у вічний дім; \nНіч гріха минає - йде блаженний час, \nСкоро ми ввійдем у вічний дім.\n\nПрипев: \nСкоро ми ввійдем, скоро ми ввійдем, \nНедалеко дивний край; \nІ ввійдем туди, у небесний Божий рай, \nСкоро ми ввійдем у вічний дім.\n\nКуплет 2.\nМи для Бога всі будем разом працювать,  \nСкоро ми ввійдем у вічний дім; \nБлагодатну поміч дасть Христос всім нам, \nСкоро ми ввійдем у вічний дім.\n\nКуплет 3.\nПокажімо всім правду в нашому житті,  \nСкоро ми ввійдем у вічний дім; \nА Христос спасіння нам Своє дає, \nСкоро ми ввійдем у вічний дім.\n\nКуплет 4.\nНі недуг, ні смерти нема в краю святім,  \nСкоро ми ввійдем у вічний дім; \nСпокій ми знайдем там в місті золотім, \nСкоро ми ввійдем у вічний дім.', '', NULL, NULL),
(484, 'О день бажаний день предивний', NULL, 'Куплет 1 \nО, день бажаний, день предивний, \nдень радости для вірних всіх, \nКоли Господь, наш Бог Всесильний, \nнавік візьме з землі Своїх! \nТам Богу співи понесуться, \nвсі будуть славить: Свят! Свят! Свят! \nЗемні скорботи там минуться, \nтам нас зігріє благодать.\n\nКуплет 2.\nО, радість - Бога прославляти,  \nз Христом тепер і вічно жить. \nХто любить Слово виповняти, \nтого Христос нагородить. \nТам в Царстві Божім із святими \nвсі заспіваєм: Свят! Свят! Свят! \nВоскреснуть мертві, і ми з ними \nТворцеві будем честь складать.\n\nКуплет 3.\nПоки живемо в смертнім тілі,  \nзвучать скорботи і в піснях. \nКоли ж, прийде Господь наш в силі,\nвоскресне радість у серцях. \nТоді всі вірні в силі Духа \nвраз заспівають: Свят! Свят! Свят! \nВ піснях небесних, дивних звуках \nТворця всі будуть величать.', '', NULL, NULL),
(485, 'Співаймо і славмо Творця', NULL, 'Куплет 1 \nСпіваймо і славмо Творця, \nхоч хрест несемо на землі; \nХристос прийде в славі Отця, - \nо, як же нам буде тоді!\n\nПрипев: \nО, як, о, як, о, як же нам буде тоді! \nХристос прийде в славі Отця, - \nо, як же нам буде тоді!\n\nКуплет 2.\nОбмиті ми кров''ю Христа,  \nтепер же готуймось туди, \nДе в Божій любові життя, \nо, як же нам буде тоді!\n\nКуплет 3.\nУ Агнця весілля для нас  \nі радо йдемо ми туди. \nХоч сумно буває не раз – \nо, як же нам буде тоді!\n\nКуплет 4.\nУ Божому Слові біжить  \nструмочок живої води, \nІ з нього ми можемо пить, \nо, як же нам буде тоді!\n\nКуплет 5.\nХристос нас усіх відкупив  \nі наших чекає плодів; \nВін нам царство правди відкрив, - \nо, як же нам буде тоді!\n\nКуплет 6.\nУ вічному царстві Христа \nне буде ні сліз, ні біди; \nМинеться земна марнота, \nо, як же нам буде тоді!', '', NULL, NULL),
(486, 'У край небесний я іду', NULL, 'Куплет 1 \nУ край небесний я іду, \nде всі багатства у Христа; \nТам відпочинок я знайду \nй блаженство вічного життя.\n\nПрипев: \nО, дивний край, небесний рай, \nтуди душею лину я, \nБо маю вічне там життя \nв ясних оселях у Христа; \nВже бачу берег неземний, \nчудовий, вічний край святий.\n\nКуплет 2.\nКоли прийду я в дім святий,  \nзустріне там мене Ісус, \nНавік прославлений, живий, \nу сонмі всіх спасенних душ.\n\nКуплет 3.\nДерева в тім краю цвітуть,  \nі квіти аромати ллють, \nВоди живої джерело \nтече спасенним на добро.\n\nКуплет 4.\nТам, у присутності Творця,  \nсіяють радістю серця \nІ співи ангелів святих \nлунають у просторах тих.', '', NULL, NULL),
(487, 'Ближче о Боже мій до Тебе йду', NULL, 'Куплет 1 \nБлижче, о, Боже мій, до Тебе йду, \nХоч і страждання тут часто несу. \nТа в боротьбі земній \nБлижче о, Боже мій,\nБлижче о, Боже мій,\nдо Тебе йду!\n\nКуплет 2.\nЯ подорожній тут, на цій землі,  \nІ відпочинок лиш знайду в Тобі! \nВдень і в порі нічній, \nБлижче о, Боже мій,\nБлижче о, Боже мій,\nдо Тебе йду!\n\nКуплет 3.\nЯк лиш настане день, славлю Тебе,  \nЩо піснею хвали сповнив мене. \nЧую я голос Твій; \nБлижче о, Боже мій,\nБлижче о, Боже мій,\nдо Тебе йду!\n\nКуплет 4.\nКоли ж земне життя Ти перервеш,  \nТоді у славу Сам мене введеш, \nРадість в країні тій; \nБлижче о, Боже мій,\nБлижче о, Боже мій, \nдо Тебе йду!', '', NULL, NULL),
(488, 'Я вірою вперед дивлюсь', NULL, 'Куплет 1 \nЯ вірою вперед дивлюсь, \nтуди, де вічний край, \nВвесь час до Господа молюсь,\nщоб Він мене взяв в рай.\n\nПрипев: \nНам Господь відпочинок дасть Свій там, \nУ раю, де немає зими. \nПісню Агнця ми всі заспіваємо там, \nЗ Христом навіки будем ми.\n\nКуплет 2.\nОзнаки всі свідкують нам,  \nщо надійде той час, \nКоли Спаситель прийде Сам, \nщоб взяти в Царство нас.\n\nКуплет 3.\nЯ лину у моїх думках  \nв святий Єрусалим, \nТуди, до Бога в небесах, \nщоб вічно жити з Ним.', '', NULL, NULL),
(489, 'Не ради почести і слави', NULL, 'Куплет 1 \nНе ради почести і слави \nдо неба, Боже, лину я; \nХоч край той пишний, величавий, \nі ним живе душа моя, \nАле Ти й тут, в земній долині, \nОтець мені, я - син Тобі... \nНе треба почести віднині\nі слави іншої мені.\n\nКуплет 2.\nНе ради вічного спокою  \nдо неба, Боже, лину я; \nХоч часто тут в житті буває, \nтомлять мене скорботи дня; \nАле Твій труд - це насолода, \nв труді натхнення і любов, \nІ боротьба, і нагорода... \nІ в цьому спокій я знайшов.\n\nКуплет 3.\nНе ради вічного достатку  \nдо Тебе, Боже, лину я; \nТи дав мені спасіння частку \nі ожила душа моя; \nВ нове життя мій дух покликав, \nйого любов''ю осінив... \nО, ласка ця велика! – \nПро це я й думати не смів.\n\nКуплет 4.\nНе ради тих блаженних далей  \nдо неба, Боже, лину я; \nЯ хочу в пісні досконалій \nспівать яка любов Твоя; \nАле не можу, бо я знаю: \nнеповна пісня на землі, \nВона лиш в небі залунає \nу досконалості хвали.', '', NULL, NULL),
(490, 'За днями линуть дні', NULL, 'Куплет 1 \nЗа днями линуть дні, \nвсе ближче край! \nІ думка вся моя – \nвсе ближче край! \nВже скоро буду я \nу рідній стороні.\n\nПрипев: \nВсе ближче рідний край, \nВсе ближче рідний край!\n\nКуплет 2.\nМинають мої дні,  \nвсе ближче край! \nДо Господа я йду, \nвсе ближче край! \nЗвучать святих пісні, \nі я туди прийду.\n\nКуплет 3.\nСкінчу я шлях земний,  \nвсе ближче край! \nВсе горе там мине, \nвсе ближче край! \nВід суму і плачу \nпіду я в край святий.', '', NULL, NULL),
(491, 'Хто в небесах у мене є', NULL, 'Куплет 1 \nХто в небесах у мене є? \nТільки Ти, тільки Ти! \nІ пісня на землі моя: \nМій Христос, мій Христос! \nЗа мене тяжко Ти страждав, \nмені спасіння даром дав \nІ з Богом повний мир послав \nтільки Ти, тільки Ти!\n\nКуплет 2.\nНе хочу я багатств земних, -  \nтільки Ти, тільки Ти! \nНемає щастя, знаю, в них, \nмій Христос, мій Христос! \nЦей світ нам щастя не дає,\nза добре злом він віддає; \nУсе найкраще, що моє, - \nмій Христос, мій Христос!\n\nКуплет 3.\nКоли покину землю я, -  \nтільки Ти, тільки Ти! \nПіде в Твій край душа моя, \nмій Христос, мій Христос! \nКоли тяжкі настануть дні \nі скорбно зробиться мені, \nЯ все ж співатиму Тобі, \nмій Христос, мій Христос!', '', NULL, NULL),
(492, 'Небесний краю мій', NULL, 'Куплет 1 \nНебесний краю мій, \nдо тебе лину я, \nУгору, в дім святий \nлетить душа моя.\n\nПрипев: \nО, краю мій, \nсердечних мрій, \nДо тебе рвуся я, \nВітчизно ти моя!\n\nКуплет 2.\nЯ прагну бути там,  \nв Отця на висоті, \nДе славний Божий храм \nзасяє у красі.\n\nКуплет 3.\nВже скоро ввійду  \nз землі в небесний край,\nДе щастя я знайду, \nдуші безсмертний рай.', '', NULL, NULL),
(493, 'Не багатства бажаю і не скарбів земних', NULL, 'Куплет 1 \nНе багатства бажаю і не скарбів земних, \nА небесного раю і насліддя святих. \nБути в царстві спасенних славна мрія моя; \nО, скажи, Боже милий, чи записаний я?\n\nПрипев: \nО, скажи, Боже мій, чи записаний я? \nВ вічній Книзі спасенних чи записаний я?\n\nКуплет 2.\nБога довго не знав я, у гріхах проживав,  \nІ спасіння не мав я, і Христа не шукав. \nТільки вічний Спаситель мене Сам відшукав, \nІ ласкаво покликав, і той клич я прийняв.\n\nКуплет 3.\nМісто вічне для вірних в небі Бог збудував  \nІ оселі Син Божий для спасенних придбав. \nТам гріха вже немає, ні темряви, ні зла, \nСонце правди там сяє і лунає хвала.', '', NULL, NULL),
(494, 'О небесна Країно до тебе я йду', NULL, 'Куплет 1 \nО, небесна Країно, до тебе я йду \nТа про тебе усім розкажу. \nЛиш у тебе царює небесний спокій, \nО, прийми мене, Спасе, Ти мій.\n\nПрипев: \nВслід за Спасом ми підем \nІ в небесний край ввійдем, \nТам життя нове ми розпочнем.\n\nКуплет 2.\nСвіт про тебе не знає, не може пізнать,  \nБо нам треба піти розказать, \nЩоб пізнали про Тебе також люди всі, \nЩо вмирав Ти за них на хресті.\n\nКуплет 3.\nО, не раз я сльозами так гірко заллюсь,  \nЯк на грішний цей світ подивлюсь; \nЩо він так у гріхах та неправді живе, \nЙого кара за гріх не мине.', '', NULL, NULL),
(495, 'Я знаю край де горя вже не буде', NULL, 'Куплет 1 \nЯ знаю край, де горя вже не буде. \nДе більш не буде литись братня кров; \nДе в згоді житимуть щасливі люди. \nТам запанує правда і любов.\n\nКуплет 2.\nВ цей рідний край веде моя дорога,  \nЦей край святий я змалку полюбив; \nІду туди і славлю мого Бога, \nЩо Він мені цю путь святу відкрив.\n\nКуплет 3.\nІду, і всіх, кого лиш зустрічаю,  \nЯ кличу за собою в рідний край. \nТуди, де сонце правди вічно сяє, \nНе відцвітає там ніколи май.\n\nКуплет 4.\nІдіть туди, усі скорботні люди,  \nБо там уже не ллється братня кров, \nТам горя й сліз ніколи вже не буде. \nБо там панує правда і любов.', '', NULL, NULL),
(496, 'Було сказано нам про чудовий той край', NULL, 'Куплет 1 \nБуло сказано нам про чудовий той край, \nПро який нас учить Біблія. \nДе турбот вже нема, ні тяжкого труда, \nІ нема вже насильства там.\n\nПрипев: \nВ тім прекраснім краю, у небеснім раю, \nВже грізних хмар не буде там. \nПройшла смерти тінь, настав вічний день, \nІ повік сонце не зайде!\n\nКуплет 2.\nТам у райськім саду плоди золоті,  \nВсе цвіте там, немов лілія. \nТам спасенні серця прославляють Творця, \nДе немає насильства вже.\n\nКуплет 3.\nТам оселі для нас приготовив Христос,  \nТак прикрашені, як скінія. \nДжерело там життя, пісня ллється свята, \nІ нема там насильства вже.', '', NULL, NULL),
(497, 'Оселя моя біля тої ріки', NULL, 'Куплет 1 \nОселя моя біля тої ріки, \nДе квіти ніколи не в''януть, \nЛічби де не знатимуть більше роки, \nЩасливі часи там настануть.\n\nКуплет 2.\nДушею щоденно я лину туди.  \nДе сліз вже не буде, ні болю; \nВ країну цю, Господи, Сам проведи, \nКрізь темряву зла і недолю.\n\nКуплет 3.\nТут часто терниста стежина моя,  \nА мало так маю я сили. \nПідтримати може рука лиш Твоя, \nВітри щоб з дороги не збили.\n\nКуплет 4.\nТе місце для мене дорожче життя,  \nБо там від страждань я спочину, \nІ хрест мій щоденний, що ніс все життя, \nНазавжди із себе вже скину.\n\nКуплет 5.\nПобачу там друзів, що смерть на землі  \nІз ними мене розлучила, \nА зараз на небі у Божій хвалі, \nПечаль їхню радість змінила.\n\nКуплет 6.\nТам разом прославимо Бога небес,  \nЩо людям приніс Він спасіння,\nБув мертвим, та з гробу у славі воскрес \nІ вірним дарує нетління.', '', NULL, NULL),
(498, 'Радісно я вирушаю в ту путь', NULL, 'Куплет 1 \nРадісно я вирушаю в ту путь,\nщо нею праведні в небо ідуть. \nАнгельських хорів доноситься спів,\n кличуть мене, щоб я з ними там жив. \nВже незабаром прийду до кінця, \nтам відпочину навік у Отця.\nТам я забуду мандрівки, труди; \nрадісно, радісно йду я туди.\n\nКуплет 2.\nВ небі чекають мене всі святі,  \nщо своє щастя знайшли у Христі; \nСпіви безжурні звучать ніч і день, \nваблять до себе ті звуки пісень; \nЯк невимовне солодкі вони! \nТягнуть додому мене з чужини. \nВ сяйві співають ті хори святих; \nрадісно, радісно йду я до них.\n\nКуплет 3.\nСмерти жахливої я не боюсь,  \nз смерти в життя вічне переселюсь. \nЗнаю: за гробом воскресну я знов, \nмене чекає там вічна любов. \nРанок ясний, сходить сонце вже там; \nв сяйві Христос зустрічатиме Сам.\nВсе там забуду: і горе, й тугу... \nРадісно, радісно в небо я йду.', '', NULL, NULL),
(499, 'На небі мій Отцівський дім', NULL, 'Куплет 1 \nНа небі мій Отцівський дім, \nя хочу до Ісуса; \nНі сліз, ні горя в домі тім, \nя хочу до Ісуса.\n\nПрипев: \nТа з часом щастя промине, \nа спадщина на небі є, \nА спадщина ж на небі є, \nя хочу до Ісуса.\n\nКуплет 2.\nЛюдина мріє мати дім –  \nя хочу до Ісуса; \nВона будує щастя в нім – \nя хочу до Ісуса.\n\nПрипев: \nПрощай, о, земле, в дім святий \nіду туди, де спокій мій, \nІду туди, де спокій мій, \nіду я до Ісуса.\n\nКуплет 3.\nДодому хочу я весь час  \nя хочу до Ісуса; \nБо Він мене навіки спас, \nя хочу до Ісуса.', '', NULL, NULL),
(500, 'При Божім троні в небесах', NULL, 'Куплет 1 \nПри Божім троні, в небесах, \nзібрались діточки. \nСпівають радісні пісні,\nясніють, як зірки.\n\nПрипев: \nІ там, і там радіють у Христі, \nІ там, і там співають Йому всі: \nСлава Господу повік.\n\nКуплет 2.\nЩо їх у небо привело,  \nв світ Божої краси? \nІ як туди, де вічний мир, \nвони, малі, ввійшли?\n\nКуплет 3.\nЛюбили Господа вони  \nв свої дитячі дні, \nТа щоб сильніш любить могли, - \nВін взяв їх від землі.', '', NULL, NULL),
(501, 'Чи зустрінемось з тобою', NULL, 'Куплет 1 \nЧи зустрінемось з тобою, \nде святі усі живуть? \nДе спокійною рікою \nводи чистії течуть?\n\nПрипев: \nТак, зустрінемось з тобою \nнад чистою, чудовою рікою; \nТам усі з достойною хвалою \nми Ісусові будем служить.\n\nКуплет 2.\nНам до вічного спокою  \nперехід не існував, \nБожий Син ціною крові \nпуть спасіння нам поклав.\n\nКуплет 3.\nТам над світлою рікою  \nми Христа побачим всі, \nЗалунає спів хвалою \nв вічній радості, красі.\n\nКуплет 4.\nТам зустрінемось з тобою  \nде і мир, і благодать; \nТам ми будем над рікою \nвічно Бога прославлять.', '', NULL, NULL),
(502, 'Несем ми тіло на спокій', NULL, 'Куплет 1 \nНесем ми тіло на спокій, \nСхоронимо його в землі; \nУсі помруть, так Бог звелів, \nУ гріх упавших осудив.\n\nКуплет 2.\nО, браття й сестри, всі туди  \nВ свій час ми маєм відійти; \nТурботам всім прийде кінець, - \nПокличе в вічність нас Творець.\n\nКуплет 3.\nЯк скоро день, за днем летить!  \nЖиття, мов хвиля, пробіжить; \nЧи близько, чи далеко час; \nЩо в вічності чекає нас?\n\nКуплет 4.\nТворець обмежив тут наш вік,  \nДе смертний кожний чоловік. \nХристос смерть смертю подолав, \nЖиття нам вічне дарував.', '', NULL, NULL),
(503, 'Недалеко за рікою', NULL, 'Куплет 1 \nНедалеко за рікою \nберег вічного життя; \nЙдемо ми туди з хвалою \nдо Спасителя Христа.\n\nПрипев: \nБудем з вірою чекати, \nпоки Сам Христос прийде; \nБуде Він нас проводжати, \nв місто слави всіх введе.\n\nКуплет 2.\nЗа рікою сонце сяє,  \nмісто дивне в вишині. \nСпіви радісні лунають, \nспіви дивні, неземні.\n\nКуплет 3.\nНіч холодна над рікою,  \nале далі світло дня; \nТо - край неба, край спокою, \nтам з Христом нове життя.\n\nКуплет 4.\nЯк багато дітей Божих  \nперейшли в той дивний край; \nСкоро й ми, хто ще в дорозі, \nувійдемо в Божий рай.', '', NULL, NULL),
(504, 'Гора Сіон гора святая', NULL, 'Куплет 1 \nГора Сіон, гора святая, \nпрестол Господній там стоїть; \nТуди щодня всім серцем лину,\nде сонце вічнеє горить.\n\nКуплет 2.\nДе зла нема, в краю спокою,  \nде радість вічна, дивний спів, \nДе все в красі, у сяйві щастя, \nде вже нема похмурих днів.\n\nКуплет 3.\nУ славі там Господь сіяє  \nпоміж відкуплених Своїх; \nВін сльози витер їм навіки \nі втішив щастям вічним їх.\n\nКуплет 4.\nХваління ллється з уст спасенних  \nі співи радости звучать;\nТого ніяка людська мова \nне може в слові передать.\n\nКуплет 5.\nО, скоро, скоро я там буду  \nз Христом на тій горі святій; \nВін спас мене Своєю кров''ю, \nВін - Відкупитель, Пастир мій.', '', NULL, NULL),
(505, 'В рідний край в рідний край серцем лину я', NULL, 'Куплет 1 \nВ рідний край, в рідний край серцем лину я, \nТам щастя, радість вся моя, забуду мук відчай. \nЦей світ чужий душі моїй, не рідний він мені, \nЗнайду я спокій неземний в небесній стороні.\n\nКуплет 2.\nВ небесах, в небесах здійснення надій.  \nО, скільки любих в тих краях! І там Спаситель мій. \nУ цьому світі тяжко жить, стомивсь я в боротьбі; \nТак хочу дні земні прожить, щоб пробувать в Тобі.\n\nКуплет 3.\nСкоро я, скоро я в рідній край ввійду;  \nВстає зоря нового дня, святі часи ідуть. \nЧого ніколи на землі не бачив я й не знав, \nГосподь спасенним і мені навік приготував.', '', NULL, NULL),
(506, 'Ідуть подорожні додому ідуть', NULL, 'Куплет 1 \nІдуть подорожні, додому ідуть, \nВ край вічний, де спокій святий; \nНі горя, ні сліз вони там не знайдуть, \nЇх прийме Христос дорогий.\n\nПрипев: \nТам нема вже зла, \nБоротьба пройшла, \nКраще сонця Христос там сія, \nКраще сонця Христос там сія.\n\nКуплет 2.\nНемає там смерти, немає страждань,  \nНеправди і гніву нема, \nНі голосу злого, ні грішних бажань – \nТам світло Господнє сія.\n\nКуплет 3.\nІдуть подорожні... Вже близько той край,  \nДе праведні душі усі; \nТуди їх Спаситель зібрав в дивний рай, \nТам сяє все в Божій красі.', '', NULL, NULL),
(507, 'Я подорожую тут на цій землі', NULL, 'Куплет 1 \nЯ подорожую тут на цій землі, \nшвидко наближаюсь я до вічності, \nХрест несу щоденно, часом сльози й жах,\nйду я до Вітчизни в святих небесах. \nА, коли прийду я в небеса святі, \nСпас мене зустріне там на висоті, \nБуде Він стрічати і мене вітати в радісних словах; \nХрест Він з мене зніме і до Себе прийме там у небесах.\n\nКуплет 2.\nОй, яка, дорога тяжкая моя,  \nначе густим терням пробираюсь я, \nІ каміння гостре на путі лежить, \nсерце ранить сумнів і душа болить.\nА коли прийду я в небеса святі, \nСпас мене зустріне там на висоті, \nБуде Він стрічати і мене вітати в радісних словах; \nРани Він загоїть, душу заспокоїть там у небесах.\n\nКуплет 3.\nГоре та недолю зустрічаю я,  \nі сльозами часто заливаюсь я; \nТа одна надія веселить мене, \nщо в мою Країну горе не ввійде. \nА коли прийду я в небеса святі, \nСпас мене зустріне там на висоті, \nБуде Він стрічати і мене вітати в радісних словах; \nЗітре мої сльози, змінить в радість горе там у небесах.\n\nКуплет 4.\nБачу я навколо всяких ворогів  \nі від них я чую неповагу й гнів; \nВся моя дорога повна небезпек, \nмушу пильнувати, щоб мій зір не змерк. \nА коли прийду я в небеса святі, \nСпас мене зустріне там на висоті, \nБуде Він стрічати і мене вітати в радісних словах; \nІ пісні хваління з уст моїх полинуть там у небесах.', '', NULL, NULL),
(508, 'Я  подорожній тут на землі', NULL, 'Куплет 1 \nЯ - подорожній тут на землі, \nДовго мандрую, як в чужині.\n\nПрипев: \nТам в небі дім мого Отця, \nО, як туди бажає душа!\n\nКуплет 2.\nТяжко і тісно, й сумно мені,  \nЯк то, зви-чайно, на чужині.\n\nКуплет 3.\nЯк перейду долину земну,  \nДо Батьків-щини в небо ввійду.\n\nКуплет 4.\nХочу життя скоріше пройти, \nЩоб уже в царство Боже ввійти.\n\nКуплет 5.\nПрийме мене мій Бог, мій Отець  \nІ всім стражданням прийде кінець.', '', NULL, NULL),
(509, 'В долині гріховній земній', NULL, 'Куплет 1 \nВ долині гріховній, земній, \nДе незгоди, нещастя, обман, \nВ рідний край я іду неземний \nПо скорботних слідах християн.\n\nПрипев: \nВ рідний край неземний, \nДе нема зла й не ллється вже кров, \nЯ іду і прийду \nДе царює святая любов.\n\nКуплет 2.\nХоч як небезпечно кругом  \nІ важка є мандрівка моя, \nЯ надіюсь і йду за Христом \nВ рідний край, де спочину з Ним я.\n\nКуплет 3.\nСміливо вперед я іду,  \nІ неспокій мені не страшний; \nЯ долину земну перейду \nІ ввійду в дім небесний святий.', '', NULL, NULL),
(510, 'Вітчизна моя в небесах', NULL, 'Куплет 1 \nВітчизна моя в небесах, \nТуди рветься і лине душа; \nТам святії в спокійних місцях \nСлавлять вічно в любові Христа.\n\nПрипев: \nВ небесах, в небесах, \nВітчизна моя в небесах;\nВ небесах, в небесах, \nВітчизна моя в небесах;\n\nКуплет 2.\nГосподь жде мене в небесах,  \nВін готує оселю Свою; \nВідпочинок навік для святих \nВ Його світлім, блаженнім раю.\n\nКуплет 3.\nВже скоро прийду в небеса,  \nСкоро скінчиться шлях мій земний; \nТам зустріну я в славі Отця \nТих, що в вірі святій тут жили.', '', NULL, NULL),
(511, 'О як радісно стремитись', NULL, 'Куплет 1 \nО, як радісно стремитись \nв Царство Боже на Сіон! \nВсі повинні ми дивитись \nна Христа, де Божий трон. \nТам Спаситель наш царює, \nбудем всі Йому служить. \nСпів небесний: "Алилуя!" – \nз уст відкуплених звучить.\n\nКуплет 2.\nТут, в долинах Вавилону,  \nзаставляють нас мовчать, \nвисоти гори Сіону \nбудем Бога величать. \nТам нічної тьми не буде, \nсум, журба навік пройде. \nВічно з нами Бог там буде, \nнаші сльози Він зітре.\n\nКуплет 3.\nТут земні завжди тривоги,  \nхрест терпіння ми несем, \nМи там станем перед Богом, \nВседержителем Творцем. \nБраття, сестри! Не лякайтесь, \nвсе вперед, вперед підем! \nНа Христа лиш покладайтесь: \nв небі будем вічно з Ним.', '', NULL, NULL),
(512, 'Я небо нове й нову землю', NULL, 'Куплет 1 \nЯ небо нове й нову землю \nпобачу за словом Творця; \nІ славу від Бога одержу, \nя житиму там без кінця!\n\nПрипев: \nТам усі в небесах \nв славі Божій чекають мене.\nЗ мене хрест зніме Спас \nі в небесную радість прийме.\n\nКуплет 2.\nПобачу я місто чудесне,  \nде всі прославляють Творця; \nУ світлій оселі небесній \nя житиму там без кінця!\n\nКуплет 3.\nТам вулиці золотом вкриті,  \nтам слава Господня сія; \nІ кров''ю Ісуса обмитий, \nя житиму там без кінця!\n\nКуплет 4.\nТам будуть спасенні народи  \nу славі небесній Творця; \nДалеко від зла і незгоди \nя житиму там без кінця!\n\nКуплет 5.\nВ небесному царстві Христовім  \nзіллються спасенних серця: \nХвалу віддадуть усі Богу, \nя житиму там без кінця!', '', NULL, NULL),
(513, 'Ми життєвим океаном у небесний край пливем', NULL, 'Куплет 1 \nМи життєвим океаном у небесний край пливем; \nСкоро, скоро час настане - в радість вічну ми ввійдем. \nНезабаром стихне море, ми на берег вийдем скоро, \nМи життєвим океаном у небесний край пливем; \nСкоро, скоро час настане - в радість вічну ми ввійдем.\n\nКуплет 2.\nСкільки душ уже добралось до бажаних берегів  \nІ тепер у вічну радість ждуть ще інших моряків. \nНезабаром стихне море, ми на берег вийдем скоро, \nСкільки душ уже добралось до бажаних берегів. \nІ тепер у вічну радість ждуть ще інших моряків.\n\nКуплет 3.\nОсь видніє берег ясний, де кінець журбі, сльозам;  \nУвійдемо в край прекрасний, будем вічно жити там. \nНезабаром стихне море, ми на берег вийдем скоро, \nОсь видніє берег ясний, де кінець журбі, сльозам; \nУвійдемо в край прекрасний, будем вічно жити там.', '', NULL, NULL),
(514, 'Нам здалека вже видно той край', NULL, 'Куплет 1 \nНам здалека вже видно той край, \nДе нема вже ніяких турбот; \nСам Спаситель веде в Божий рай \nСвій відкуплений, вірний народ.\n\nПрипев: \nСкоро Він нас введе \nу блаженний той край дорогий.\nСкоро Він нас введе \nу блаженний той край дорогий.\n\nКуплет 2.\nТам, забувши недолю земну,  \nДе Країна чудова, свята, \nВсі співають від серця хвалу, \nПрославляючи Спаса Христа.\n\nКуплет 3.\nТам зібрання спасенних усіх,  \nЩо втішаються Духом Святим,\nВеличають Христову любов \nПеред троном Його пресвятим.', '', NULL, NULL),
(515, 'Я пришлець в земній долині', NULL, 'Куплет 1 \nЯ пришлець в земній долині, \nа навколо чужина, \nВище зір небесних нині \nмоя рідна сторона.\n\nПрипев: \nТам країна свята, там Вітчизна моя, \nТам побачу Христа, де родина уся. \nВсі вони в рідній стороні, \nА я блукаю по чужині.\n\nКуплет 2.\nТут ненавість, гріх, нещастя:  \nне приймають тут Христа, \nАле там край, повний щастя, \nтам любов живе свята.\n\nКуплет 3.\nТут мене всі зневажають, \nненавидять тут мене, \nАле там мене чекають, \nколи смерті ніч мине.\n\nКуплет 4.\nТут загрожує смерть-згуба,  \nв цій похмурній чужині, \nТам життя та вічність люба \nв моїй рідній стороні.', '', NULL, NULL),
(516, 'Вперед дружніше браття', NULL, 'Куплет 1 \nВперед, дружніше, браття, \nдо вишніх нагород; \nТам буде славить Бога \nвідкуплений народ. \nГотує Бог нам спокій, \nтой славний час іде, \nТа хто Христа не прийме – \nу спокій не ввійде.\n\nПрипев: \nВ небі жде спокій нас, \nв небі жде спокій нас, \nВ небі жде нас, в небі жде нас, \nВ небі жде спокій нас.\n\nКуплет 2.\nХристос є наше Світло,  \nВін попереду йде, \nОсвітлює дорогу, \nдо Царства нас веде. \nХто серцем і душею \nдовіриться Йому, \nТой радісно й спокійно \nжить буде у раю.\n\nКуплет 3.\nДітей багато Божих  \nвже спочивають там, \nДе горе не тривожить, \nБог спокій дав серцям. \nМи незабаром будем \nу небі вічно жить... \nЧому ж у цьому світі \nнам плакать і тужить?', '', NULL, NULL),
(517, 'Ще трохи трохи днів', NULL, 'Куплет 1 \nЩе трохи, трохи днів \nсеред турбот, страждань. \nЩе трохи серця мрійних снів, \nмолитв, надій, ридань.\n\nКуплет 2.\nЩе трохи боротьби  \nй змагань, а далі там – \nПрийде кінець трудам, журбі \nі смуткові, й сльозам.\n\nКуплет 3.\nА потім - вічний день,  \nі вічний, дивний край, \nДе звук Божественних пісень, \nспокій, Христос і рай.', '', NULL, NULL),
(518, 'Ми знаємо край де царює Спаситель', NULL, 'Куплет 1 \nМи знаємо край, де царює Спаситель \nІ місто, збудоване Богом для нас; \nХристос там готує нам вічні оселі, \nДе щастям наділить відкуплених Спас.\n\nПрипев: \nРайське нам щастя\nРайське нам щастя \n(Голгофа дає), \nРайська нам радість\nРайська нам радість \n(з Голгофи тече) \nКров''ю святою Христос нас придбав. \n(Куплені кров''ю Ісуса, \nПриносим подяку Йому ми за все). \nАлилуя! \nВін нам відкрив двері раю! \nСлава Христу, (Слава навіки Ісусу Христу), \nВін від смерти нас спас!\n\nКуплет 2.\nАпостоли вірні й святії пророки  \nУсі там спасенні з Ним вічно живуть; \nІ ми перейдемо в те місто величне, \nДе душі в спокої, де сліз вже не ллють.\n\nКуплет 3.\nУ світі немало для нас горювання,  \nА наша душа прагне щастя й життя; \nО, браття і сестри, вперед без вагання, \nГотуймось до вічного царства Христа!', '', NULL, NULL),
(519, 'Я прагну все на небеса', NULL, 'Куплет 1 \nЯ прагну все на небеса, \nде сяє Божая краса, \nДе сум навіки мій мине – \nтуди Господь веде мене.\n\nПрипев: \nО, Господи, мене сильніш, \nв Своїй любові Ти зігрій, \nВід темноти, гріха й біди, \nу світлий край небес веди.\n\nКуплет 2.\nЯ хочу там постійно жить,  \nі Відкупителю служить, \nДе хори дивні без кінця, \nспівають славу для Творця.\n\nКуплет 3.\nЯка там славна сторона,  \nі вабить так мене вона, \nЧерез усе життя земне, \nтуди, Господь, провадь мене.', '', NULL, NULL),
(520, 'Люблю я мріяти про край', NULL, 'Куплет 1 \nЛюблю я мріяти про край, \nде ангели святі \nНаповнюють піснями рай \nдля Господа в хвалі.\n\nПрипев: \nНочі не буде,\nНочі не буде, \nНочі не буде,\nгріха не буде там.\n\nКуплет 2.\nЯ мрію про той край святих,  \nде Бог царює наш, \nЯк запах лілій весняних \nтам радість буде нам.\n\nПрипев: \nГоря не буде,\nГоря не буде,\nГоря не буде,\nгріха не буде там.\n\nКуплет 3.\nЛюблю оселі ті святі;  \nтам Бог приготував \nВінці для тих, хто в боротьбі \nз гріхом перемагав.\n\nПрипев: \nСмерти не буде,\nСмерти не буде,\nСмерти не буде,\nГріха не буде там.\n\nКуплет 4.\nЛюблю я мріяти про край,  \nде скінчу шлях земний, \nМені відчинять двері в рай, \nі там знайду спокій.\n\nПрипев: \nНочі не буде, \nГоря не буде, \nСмерти не буде, \nГріха не буде там.', '', NULL, NULL),
(521, 'Буду співати славу складати', NULL, 'Куплет 1 \nБуду співати, славу складати, \nславу Тому, за нас Хто вмирав. \nДивний Учитель, Христос Спаситель, \nВін нам спасіння всім дарував. \nСлавити вічно буду Христа, \nв Ньому знайшов я світла й життя. \nСили ворожі з Ним переможу \nв земній тут боротьбі.\n\nКуплет 2.\nЯ на Ісуса завжди дивлюся,  \nНим лиш Одним на світі живу; \nВін мій Спаситель, Пастир Учитель, \nдасть мені місце, в небі, в раю. \nДе в цьому світі щастя знайду? \nІ від Ісуса куди піду? \nЗ Ним лиш іду я і в неземную \nрадість Його ввійду.\n\nКуплет 3.\nТут все минає, там, в Божім раю,  \nстомленим душам вічний спокій. \nКоли ввійду я в славу святую, \nтам мене прийме Спас любий мій. \nТам залунає пісня свята, \nславить спасені будуть Христа, \nПісню спасіння, пісню хваління \nбуду співати я.', '', NULL, NULL),
(522, 'Отче Небесний, Боже Могутній', NULL, 'Куплет 1\nОтче Небесний, Боже Могутній,\nТи Утішитель, Дух Правди Ти,\nВсюди присутній і всеведучий,\nБудь тут між нами, нас просвіти!\n(2р.)\nКуплет 2\nОтче Небесний, Боже ласкавий,\nНас, дітей Своїх, не забувай;\nПрийди, вселися в серцях убогих,\nБлагослови нас, щастя нам дай\n(2р.)\nКуплет 3\nОтче Небесний, змий всі провини\nІ чистотою душу вкраси;\nХай Твоя ласка радість нам верне,\nНас у недолі, Боже, спаси.\n(2р.)', '', NULL, NULL),
(523, 'Всесильний, нездоланний ', NULL, 'Куплет 1\nВсесильний, нездоланний \nХто збагне великого Творця?\nМи безсилі, безпорадні\nХто зійде явити нам життя?\n\nКуплет Перед Приспів \nСвіту що сидить у темноті світло засяяло\n\nКуплет Приспів\nБог з нами Цар всього творіння\nПрийняв на Себе тління долю всіх людей\nБог з нами Він зняв небесні шати\nЩоб зодягнути в славу усіх Своїх дітей\n\nКуплет 3\nСлава Богу ввисоті\nМир людям на землі радійте! Бог з нами!\nСлава Богу ввисоті\nМир людям на землі радійте! Бог з нами!', '', NULL, NULL),
(524, 'Свят, Свят Господь Саваоф', NULL, 'Куплет 1\nСвят, Свят Господь Саваоф\nІ вся земля повна слави Господньої\nСвят, Свят Господь Саваоф\nРука Твоя не скоротилася сьогодні\n\nПриспів\nСвят Господь Саваоф\n\nКуплет 2\n\nТи нас збираєш, як птах пташенят\nТи нас захищаєш від вражих атак\nТвоє царство є незмінним навіки віків\nСвят, Свят Господь Саваоф', '', NULL, NULL);